C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterab
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ab
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION a2ab
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION lamda, disc, sqdr, thrshhi, thrshlo
      DOUBLE PRECISION discab, sqdrab
      DOUBLE PRECISION ncon, qcon, ucon, uconold
      DOUBLE PRECISION qconab, uconab
      DOUBLE PRECISION w2, w3
      DOUBLE PRECISION w2ab, w3ab
      LOGICAL tst, tst2
      INTEGER i
      DOUBLE PRECISION aa
      DOUBLE PRECISION aaab
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbab
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccab
      DOUBLE PRECISION rt1
      DOUBLE PRECISION rt1ab
      DOUBLE PRECISION rt2
      DOUBLE PRECISION rt2ab
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1ab0
      DOUBLE PRECISION temp0ab
      DOUBLE PRECISION temp1ab
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_ab/ gnh3ab
      COMMON /ions_ab/ molalab, gamaab, waterab
      COMMON /inpt_ab/ wab
C
C *** SETUP PARAMETERS ************************************************
C
      tst = .true.
      tst2 = .true.
C INITIAL AMOUNT OF (NH4)2SO4 IN SOLUTION
      w2 = w(2)
      w3 = w(3)
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ucon = 0.d0
      ad_count = 0
      DO WHILE (i .LE. 14 .AND. tst .AND. tst2)
C      DO I=1,14 !NSWEEP
        uconold = ucon
        CALL PUSHREAL8(a2)
        a2 = xk2*r*temp/xkw*(gama(8)/gama(9))**2.
        CALL PUSHREAL8(aa)
C
        aa = -a2
        CALL PUSHREAL8(bb)
        bb = a2*w3 - 2.d0*a2*w2 + 1
        cc = 2.d0*w2
        disc = bb*bb - 4.d0*aa*cc
        CALL PUSHREAL8(sqdr)
        sqdr = SQRT(disc)
C
        rt1 = (-bb+sqdr)/2.d0/aa
        rt2 = (-bb-sqdr)/2.d0/aa
C         WRITE(*,*) 'ROOTS', RT1, RT2
C
        IF (rt1 .LT. zero .AND. rt2 .GE. zero) THEN
          ucon = rt1
          CALL PUSHCONTROL2B(0)
        ELSE IF (rt2 .LT. zero .AND. rt1 .GE. zero) THEN
          ucon = rt2
          CALL PUSHCONTROL2B(1)
        ELSE
          tst2 = .false.
          CALL PUSHCONTROL2B(2)
        END IF
C
        qcon = -ucon
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = qcon
C         MOLAL (3) = MAX(W(3)/(ONE/A2/OMEGI + ONE), 2.*MOLAL(5)) ! NH4I
C         MOLAL (3) = MAX(2.D0*W2 + UCON, TINY)   ! NH4I
        IF (tiny .GT. 2.d0*w2 + ucon) THEN
          CALL PUSHREAL8(molal(3))
          molal(3) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(3))
          molal(3) = 2.d0*w2 + ucon
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = w2
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = zero
C         GNH3      = MAX(W(3)-MOLAL(3), TINY)   ! NH3GI
        IF (tiny .GT. w(3) - molal(3)) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C OHI
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P()
        thrshlo = uconold - uconold*1.0d-15
        thrshhi = uconold + uconold*1.0d-15
        IF (ucon .LE. thrshlo .AND. ucon .GE. thrshhi) THEN
          tst = .false.
        ELSE
          tst = .true.
        END IF
C         CALL CALCACT     
C         ELSE
C            GOTO 20
C         ENDIF
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      DO ii1=1,ncomp
        wab(ii1) = 0.D0
      ENDDO
      uconab = 0.D0
      w2ab = 0.D0
      w3ab = 0.D0
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3P_AB()
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          wab(3) = wab(3) + gnh3ab
          molalab(3) = molalab(3) - gnh3ab
        END IF
        CALL POPREAL8(molal(6))
        molalab(6) = 0.D0
        CALL POPREAL8(molal(5))
        w2ab = w2ab + molalab(5)
        molalab(5) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(3))
          molalab(3) = 0.D0
        ELSE
          CALL POPREAL8(molal(3))
          w2ab = w2ab + 2.d0*molalab(3)
          uconab = uconab + molalab(3)
          molalab(3) = 0.D0
        END IF
        CALL POPREAL8(molal(1))
        qconab = molalab(1)
        molalab(1) = 0.D0
        uconab = uconab - qconab
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          rt1ab = uconab
          rt2ab = 0.D0
          uconab = 0.D0
        ELSE
          IF (branch .EQ. 1) THEN
            rt2ab = uconab
            uconab = 0.D0
          ELSE
            rt2ab = 0.D0
          END IF
          rt1ab = 0.D0
        END IF
        temp1ab0 = rt1ab/(2.d0*aa)
        temp1ab = rt2ab/(2.d0*aa)
        sqdrab = temp1ab0 - temp1ab
        cc = 2.d0*w2
        disc = bb*bb - 4.d0*aa*cc
        IF (disc .EQ. 0.0) THEN
          discab = 0.0
        ELSE
          discab = sqdrab/(2.0*SQRT(disc))
        END IF
        bbab = 2*bb*discab - temp1ab0 - temp1ab
        aaab = -((sqdr-bb)*temp1ab0/aa) - 4.d0*cc*discab - (-bb-sqdr)*
     +    temp1ab/aa
        CALL POPREAL8(sqdr)
        ccab = -(4.d0*aa*discab)
        w2ab = w2ab + 2.d0*ccab - 2.d0*a2*bbab
        CALL POPREAL8(bb)
        a2ab = (w3-2.d0*w2)*bbab - aaab
        w3ab = w3ab + a2*bbab
        CALL POPREAL8(aa)
        CALL POPREAL8(a2)
        temp0 = gama(8)/gama(9)
        temp0ab = 2.*temp0*xk2*r*temp*a2ab/(xkw*gama(9))
        gamaab(8) = gamaab(8) + temp0ab
        gamaab(9) = gamaab(9) - temp0*temp0ab
        gnh3ab = 0.D0
      ENDDO
      wab(3) = wab(3) + w3ab
      wab(2) = wab(2) + w2ab
      END

C  Differentiation of calchs4 in reverse (adjoint) mode:
C   gradient     of useful results: hi so4i delta
C   with respect to varying inputs: gama water hi so4i
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHS4
C *** THIS SUBROUTINE CALCULATES THE HSO4 GENERATED FROM (H,SO4).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHS4_AB(hi, hiab, so4i, so4iab, hso4i, delta, 
     +                      deltaab)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHS4 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterab
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ab
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION a8ab
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION hiab, so4iab, deltaab, bbab, ccab, ddab, sqddab, 
     +                 delta1ab, delta2ab
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0ab
      DOUBLE PRECISION temp1ab
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_ab/ gnh3ab
      COMMON /ions_ab/ molalab, gamaab, waterab
      COMMON /inpt_ab/ wab
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .LE. 1d1*tiny) THEN
        DO ii1=1,npair
          gamaab(ii1) = 0.D0
        ENDDO
        waterab = 0.D0
      ELSE
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2ab = deltaab
            delta1ab = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2ab = deltaab
            delta1ab = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1ab = deltaab
            ELSE
              delta1ab = 0.D0
            END IF
            delta2ab = 0.D0
          END IF
          bbab = -(0.5*delta1ab) - 0.5*delta2ab
          sqddab = 0.5*delta1ab - 0.5*delta2ab
          IF (dd .EQ. 0.0) THEN
            ddab = 0.0
          ELSE
            ddab = sqddab/(2.0*SQRT(dd))
          END IF
        ELSE
          ddab = 0.D0
          bbab = 0.D0
        END IF
        bbab = bbab + 2*bb*ddab
        ccab = -(4.d0*ddab)
        hiab = hiab + so4i*ccab - bbab
        so4iab = so4iab + hi*ccab - bbab
        a8ab = -bbab - hso4i*ccab
        DO ii1=1,npair
          gamaab(ii1) = 0.D0
        ENDDO
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1ab = 2.*temp1*temp0*xk1*a8ab/gama(7)
        temp0ab = temp1**2.*xk1*a8ab/gama(7)
        gamaab(8) = gamaab(8) + temp1ab
        gamaab(7) = gamaab(7) - temp0*temp0ab - temp1*temp1ab
        waterab = temp0ab
      END IF
      END

C  Differentiation of calcact3p in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3P_AB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicab
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterab
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ab
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0ab(6, 4), sionab, hab, chab, f1ab(3), f2ab(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplab, xijab, yjiab
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01ab
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02ab
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03ab
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04ab
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05ab
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06ab
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07ab
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08ab
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09ab
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10ab
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11ab
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12ab
      INTEGER j
      INTEGER branch
      DOUBLE PRECISION temp0ab0
      INTRINSIC MAX
      DOUBLE PRECISION x2ab
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0ab
      INTRINSIC MIN
      DOUBLE PRECISION x1ab
      DOUBLE PRECISION temp0ab13
      DOUBLE PRECISION temp0ab12
      INTEGER ii2
      INTEGER ii1
      DOUBLE PRECISION temp0ab11
      INTRINSIC SQRT
      DOUBLE PRECISION temp0ab9
      DOUBLE PRECISION temp0ab10
      DOUBLE PRECISION temp0ab8
      DOUBLE PRECISION temp0ab7
      DOUBLE PRECISION temp0ab6
      DOUBLE PRECISION temp0ab5
      DOUBLE PRECISION temp0ab4
      DOUBLE PRECISION temp0ab3
      DOUBLE PRECISION temp0ab2
      DOUBLE PRECISION temp0ab1
      COMMON /gas_ab/ gnh3ab
      COMMON /ions_ab/ molalab, gamaab, waterab
      COMMON /inpt_ab/ wab
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamaab(i) = 10.d0**gama(i)*LOG(10.d0)*gamaab(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamaab(i) = 0.D0
          x2ab = 0.D0
        ELSE
          x2ab = gamaab(i)
          gamaab(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamaab(i) = gamaab(i) + x2ab
      ENDDO
      CALL POPREAL8(gama(13))
      gamaab(4) = gamaab(4) + 0.2d0*3.d0*gamaab(13)
      gamaab(9) = gamaab(9) + 0.2d0*2.d0*gamaab(13)
      gamaab(13) = 0.D0
      DO ii1=1,3
        f1ab(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2ab(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0ab2 = zz(12)*gamaab(12)/(z(2)+z(6))
      f1ab(2) = f1ab(2) + temp0ab2/z(2)
      f2ab(3) = f2ab(3) + temp0ab2/z(6)
      hab = -(zz(12)*gamaab(12))
      gamaab(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0ab3 = zz(11)*gamaab(11)/(z(1)+z(4))
      f2ab(1) = f2ab(1) + temp0ab3/z(4)
      hab = hab - zz(11)*gamaab(11)
      gamaab(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0ab4 = zz(10)*gamaab(10)/(z(1)+z(7))
      f1ab(1) = f1ab(1) + temp0ab4/z(1) + temp0ab3/z(1)
      f2ab(4) = f2ab(4) + temp0ab4/z(7)
      hab = hab - zz(10)*gamaab(10)
      gamaab(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0ab5 = zz(9)*gamaab(9)/(z(3)+z(6))
      f1ab(3) = f1ab(3) + temp0ab5/z(3)
      hab = hab - zz(9)*gamaab(9)
      gamaab(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0ab6 = zz(8)*gamaab(8)/(z(1)+z(6))
      f2ab(3) = f2ab(3) + temp0ab6/z(6) + temp0ab5/z(6)
      hab = hab - zz(8)*gamaab(8)
      gamaab(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0ab7 = zz(7)*gamaab(7)/(z(1)+z(5))
      f1ab(1) = f1ab(1) + temp0ab7/z(1) + temp0ab6/z(1)
      f2ab(2) = f2ab(2) + temp0ab7/z(5)
      hab = hab - zz(7)*gamaab(7)
      gamaab(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0ab8 = zz(6)*gamaab(6)/(z(3)+z(4))
      f2ab(1) = f2ab(1) + temp0ab8/z(4)
      hab = hab - zz(6)*gamaab(6)
      gamaab(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0ab9 = zz(5)*gamaab(5)/(z(3)+z(7))
      f2ab(4) = f2ab(4) + temp0ab9/z(7)
      hab = hab - zz(5)*gamaab(5)
      gamaab(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0ab10 = zz(4)*gamaab(4)/(z(3)+z(5))
      f1ab(3) = f1ab(3) + temp0ab9/z(3) + temp0ab10/z(3) + temp0ab8/z(3)
      f2ab(2) = f2ab(2) + temp0ab10/z(5)
      hab = hab - zz(4)*gamaab(4)
      gamaab(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0ab11 = zz(3)*gamaab(3)/(z(2)+z(7))
      f2ab(4) = f2ab(4) + temp0ab11/z(7)
      hab = hab - zz(3)*gamaab(3)
      gamaab(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0ab12 = zz(2)*gamaab(2)/(z(2)+z(5))
      f2ab(2) = f2ab(2) + temp0ab12/z(5)
      hab = hab - zz(2)*gamaab(2)
      gamaab(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0ab13 = zz(1)*gamaab(1)/(z(2)+z(4))
      f1ab(2) = f1ab(2) + temp0ab12/z(2) + temp0ab13/z(2) + temp0ab11/z(
     +  2)
      f2ab(1) = f2ab(1) + temp0ab13/z(4)
      hab = hab - zz(1)*gamaab(1)
      gamaab(1) = 0.D0
      ionicab = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0ab(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mplab = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijab = (g0(i, j)+zpl*zmi*h)*f2ab(j)
          yji = ch*molal(j+3)/water
          g0ab(i, j) = g0ab(i, j) + yji*f1ab(i) + xij*f2ab(j)
          hab = hab + yji*zpl*zmi*f1ab(i) + xij*zpl*zmi*f2ab(j)
          yjiab = (g0(i, j)+zpl*zmi*h)*f1ab(i)
          temp0ab1 = molal(j+3)*yjiab/water
          molalab(j+3) = molalab(j+3) + ch*yjiab/water
          chab = mpl*xijab + temp0ab1
          waterab = waterab - ch*temp0ab1/water
          mplab = mplab + ch*xijab
          ionicab = ionicab - (zpl+zmi)**2*0.25d0*chab/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalab(i) = molalab(i) + mplab/water
        waterab = waterab - molal(i)*mplab/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0ab0 = agama*hab/(sion+1.d0)
      sionab = (1.D0-sion/(sion+1.d0))*temp0ab0
      IF (.NOT.ionic .EQ. 0.0) ionicab = ionicab + sionab/(2.0*SQRT(
     +    ionic))
      g05ab = g0ab(3, 4)
      g0ab(3, 4) = 0.D0
      g09ab = g0ab(3, 3)
      g0ab(3, 3) = 0.D0
      g04ab = g0ab(3, 2)
      g0ab(3, 2) = 0.D0
      g06ab = g0ab(3, 1)
      g0ab(3, 1) = 0.D0
      g03ab = g0ab(2, 4)
      g0ab(2, 4) = 0.D0
      g12ab = g0ab(2, 3)
      g0ab(2, 3) = 0.D0
      g02ab = g0ab(2, 2)
      g0ab(2, 2) = 0.D0
      g01ab = g0ab(2, 1)
      g0ab(2, 1) = 0.D0
      g10ab = g0ab(1, 4)
      g0ab(1, 4) = 0.D0
      g08ab = g0ab(1, 3)
      g0ab(1, 3) = 0.D0
      g07ab = g0ab(1, 2)
      g0ab(1, 2) = 0.D0
      g11ab = g0ab(1, 1)
      CALL KMFUL3_AB(ionic, ionicab, temp, g01, g01ab, g02, g02ab, g03, 
     +               g03ab, g04, g04ab, g05, g05ab, g06, g06ab, g07, 
     +               g07ab, g08, g08ab, g09, g09ab, g10, g10ab, g11, 
     +               g11ab, g12, g12ab)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1ab = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1ab = ionicab
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicab = 0.D0
      ELSE
        temp0ab = 0.5d0*x1ab/water
        ionicab = temp0ab
        waterab = waterab - ionic*temp0ab/water
      END IF
      DO i=7,1,-1
        molalab(i) = molalab(i) + z(i)**2*ionicab
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_AB(ionic, ionicab, temp, g01, g01ab, g02, g02ab
     +                     , g03, g03ab, g04, g04ab, g05, g05ab, g06, 
     +                     g06ab, g07, g07ab, g08, g08ab, g09, g09ab, 
     +                     g10, g10ab, g11, g11ab, g12, g12ab)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicab, sionab, cf2ab
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01ab, g02ab, g03ab, g04ab, g05ab, g06ab, g07ab, 
     +                 g08ab, g09ab, g10ab, g11ab, g12ab
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0ab0
      INTRINSIC ABS
      DOUBLE PRECISION temp0ab
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01ab = g01ab + g12ab
      g08ab = g08ab + g09ab + g12ab
      g11ab = g11ab - g09ab - g12ab
      g06ab = g06ab + g09ab
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2ab = -(z10*g10ab) - z07*g07ab - z05*g05ab - z03*g03ab - z01*
     +    g01ab - z02*g02ab - z04*g04ab - z06*g06ab - z08*g08ab - z11*
     +    g11ab
        g11ab = cf1*g11ab
        g10ab = cf1*g10ab
        g08ab = cf1*g08ab
        g07ab = cf1*g07ab
        g06ab = cf1*g06ab
        g05ab = cf1*g05ab
        g04ab = cf1*g04ab
        g03ab = cf1*g03ab
        g02ab = cf1*g02ab
        g01ab = cf1*g01ab
        temp0ab = (0.125d0-ti*0.005d0)*cf2ab
        temp0ab0 = -(0.41d0*temp0ab/(sion+1.d0))
        ionicab = ionicab + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0ab
        sionab = (1.D0-sion/(sion+1.d0))*temp0ab0
      ELSE
        sionab = 0.D0
      END IF
      CALL MKBI_AB(q11, ionic, ionicab, sion, sionab, z11, g11, g11ab)
      CALL MKBI_AB(q10, ionic, ionicab, sion, sionab, z10, g10, g10ab)
      CALL MKBI_AB(q8, ionic, ionicab, sion, sionab, z08, g08, g08ab)
      CALL MKBI_AB(q7, ionic, ionicab, sion, sionab, z07, g07, g07ab)
      CALL MKBI_AB(q6, ionic, ionicab, sion, sionab, z06, g06, g06ab)
      CALL MKBI_AB(q5, ionic, ionicab, sion, sionab, z05, g05, g05ab)
      CALL MKBI_AB(q4, ionic, ionicab, sion, sionab, z04, g04, g04ab)
      CALL MKBI_AB(q3, ionic, ionicab, sion, sionab, z03, g03, g03ab)
      CALL MKBI_AB(q2, ionic, ionicab, sion, sionab, z02, g02, g02ab)
      CALL MKBI_AB(q1, ionic, ionicab, sion, sionab, z01, g01, g01ab)
      IF (.NOT.ionic .EQ. 0.0) ionicab = ionicab + sionab/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_AB(q, ionic, ionicab, sion, sionab, zip, bi, biab)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicab, sionab, biab
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cab, xxab
      DOUBLE PRECISION tempab
      INTRINSIC EXP
      DOUBLE PRECISION tempab0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxab = zip*biab
      biab = zip*biab/(bi*LOG(10.0))
      tempab = -(0.5107d0*xxab/(c*sion+1.d0))
      tempab0 = -(sion*tempab/(c*sion+1.d0))
      sionab = sionab + c*tempab0 + tempab
      cab = sion*tempab0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicab = ionicab - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cab
      ELSE
        ionicab = ionicab + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*biab - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cab
      END IF
      END

