          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = w(2) - molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = x2
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ak1*molal(6)/molal(5) .GT. w(2)) THEN
          x3 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x3 = ak1*molal(6)/molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x3 .LT. tiny) THEN
          CALL PUSHREAL8(molal(1))
          molal(1) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(1))
          molal(1) = x3
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR                                           ! Water content
C
C CORRECT FOR HSO4 DISSOCIATION 
        so4i = molal(5) - molal(1)
        hso4i = molal(6) + molal(1)
        IF (so4i .LT. hso4i) THEN
C [LC] = [SO4]       
          molalr(13) = so4i
          IF (hso4i - so4i .LT. zero) THEN
            molalr(9) = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            molalr(9) = hso4i - so4i
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
C [LC] = [HSO4]
          molalr(13) = hso4i
          IF (so4i - hso4i .LT. zero) THEN
            molalr(4) = zero
            CALL PUSHCONTROL2B(3)
          ELSE
            molalr(4) = so4i - hso4i
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C         IF (.NOT.CALAIN) GOTO 30
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
C*** slc.11.2009 moved to beginning of loop
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCB4')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      DO ii1=1,nions
        molalbb(ii1) = 0.D0
      ENDDO
      DO i=nions,1,-1
        molalbb(i) = molalbb(i) + aerliqbb(i)
        aerliqbb(i) = 0.D0
      ENDDO
      gasbb(3) = 0.D0
      gasbb(2) = 0.D0
      gnh3bb = gasbb(1)
      gasbb(1) = 0.D0
      CALL CALCNH3_BB()
      DO ii1=1,ncomp
        wbb(ii1) = 0.D0
      ENDDO
      DO ii1=1,npair
        molalrbb(ii1) = 0.D0
      ENDDO
      waterbb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_BB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterbb = 0.D0
        DO j=npair,1,-1
          molalrbb(j) = molalrbb(j) + waterbb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            hso4ibb = molalrbb(9)
            so4ibb = -molalrbb(9)
            molalrbb(9) = 0.D0
          ELSE
            molalrbb(9) = 0.D0
            hso4ibb = 0.D0
            so4ibb = 0.D0
          END IF
          so4ibb = so4ibb + molalrbb(13)
          molalrbb(13) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            so4ibb = molalrbb(4)
            hso4ibb = -molalrbb(4)
            molalrbb(4) = 0.D0
          ELSE
            molalrbb(4) = 0.D0
            hso4ibb = 0.D0
            so4ibb = 0.D0
          END IF
          hso4ibb = hso4ibb + molalrbb(13)
          molalrbb(13) = 0.D0
        END IF
        molalbb(6) = molalbb(6) + hso4ibb
        molalbb(1) = molalbb(1) + hso4ibb
        molalbb(5) = molalbb(5) + so4ibb
        molalbb(1) = molalbb(1) - so4ibb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(1))
          molalbb(1) = 0.D0
          x3bb = 0.D0
        ELSE
          CALL POPREAL8(molal(1))
          x3bb = molalbb(1)
          molalbb(1) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbb(2) = wbb(2) + x3bb
          ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
          ak1bb = 0.D0
        ELSE
          temp2bb = x3bb/molal(5)
          ak1bb = molal(6)*temp2bb
          molalbb(6) = molalbb(6) + ak1*temp2bb
          molalbb(5) = molalbb(5) - ak1*molal(6)*temp2bb/molal(5)
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalbb(6) = 0.D0
          x2bb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          x2bb = molalbb(6)
          molalbb(6) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbb(2) = wbb(2) + x2bb
        ELSE
          wbb(2) = wbb(2) + x2bb
          molalbb(5) = molalbb(5) - x2bb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          molalbb(5) = 0.D0
          x1bb = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          x1bb = molalbb(5)
          molalbb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbb(2) = wbb(2) + x1bb
          x4bb = 0.D0
        ELSE
          x4bb = x1bb
        END IF
        bet = w(2)
        gam = molal(3)
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddbb = 0.0
        ELSE
          ddbb = 0.5*x4bb/(2.0*SQRT(dd))
        END IF
        bbbb = 2*bb*ddbb - 0.5*x4bb
        ccbb = -(4.d0*ddbb)
        ak1bb = ak1bb + bbbb - bet*ccbb
        betbb = bbbb - ak1*ccbb
        CALL POPREAL8(bb)
        gambb = -bbbb
        molalbb(3) = molalbb(3) + gambb
        wbb(2) = wbb(2) + betbb
        CALL POPREAL8(ak1)
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1bb = 2.*temp1*temp0*xk1*ak1bb/gama(7)
        temp0bb = temp1**2.*xk1*ak1bb/gama(7)
        gamabb(8) = gamabb(8) + temp1bb
        gamabb(7) = gamabb(7) - temp0*temp0bb - temp1*temp1bb
        waterbb = temp0bb
      ENDDO
      wbb(3) = wbb(3) + molalbb(3)
      molalrbb(13) = molalrbb(13) + waterbb/m0(13)
      molalrbb(9) = molalrbb(9) + waterbb/m0(9)
      molalrbb(4) = molalrbb(4) + waterbb/m0(4)
      cnh42s4bb = molalrbb(4)
      molalrbb(4) = 0.D0
      cnh4hs4bb = molalrbb(9)
      molalrbb(9) = 0.D0
      clcbb = molalrbb(13)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        wbb(3) = wbb(3) + 2.d0*cnh42s4bb
        wbb(2) = wbb(2) + 2.d0*clcbb - 3.d0*cnh42s4bb
        wbb(3) = wbb(3) - clcbb
      ELSE
        wbb(2) = wbb(2) + 3.d0*cnh4hs4bb
        wbb(3) = wbb(3) + clcbb - 2.d0*cnh4hs4bb
        wbb(2) = wbb(2) - clcbb
      END IF
C      DO ii1=1,ncomp
C        wpbb(ii1) = 0.D0
C      ENDDO
      wpbb = wbb
C
C      ncase = 2
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) w,rh,temp,wpbb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
      END

C  Differentiation of calcnh3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA IN THE GAS PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE AEROSOL EQUILIBRIUM. 
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE DIRECT PROBLEM
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3_BB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterbb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3bb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1bb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1bb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2bb
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION bb, cc, diak, psi
      DOUBLE PRECISION bbbb, ccbb, diakbb, psibb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0bb
      INTRINSIC MAX
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp1bb
      DOUBLE PRECISION x1bb
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_bb/ gnh3bb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamabb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 SUBLIMATION *****************************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        chi1 = molal(3)
        chi2 = molal(1)
C
C a=1; b!=1; c!=1 
        bb = chi2 + one/a1
        cc = -(chi1/a1)
C Always > 0
        diak = SQRT(bb*bb - 4.d0*cc)
C One positive root
        psi = 0.5*(-bb+diak)
        IF (psi .GT. chi1) THEN
          x1 = chi1
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = psi
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        chi2bb = molalbb(1)
        psibb = molalbb(1)
        molalbb(1) = 0.D0
        chi1bb = molalbb(3)
        psibb = psibb + gnh3bb - molalbb(3)
        molalbb(3) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          x1bb = 0.D0
        ELSE
          x1bb = psibb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi1bb = chi1bb + x1bb
          psibb = 0.D0
        ELSE
          psibb = x1bb
        END IF
        diakbb = 0.5*psibb
        IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
          temp1bb = 0.0
        ELSE
          temp1bb = diakbb/(2.0*SQRT(bb**2-4.d0*cc))
        END IF
        bbbb = 2*bb*temp1bb - 0.5*psibb
        ccbb = -(4.d0*temp1bb)
        chi1bb = chi1bb - ccbb/a1
        a1bb = chi1*ccbb/a1**2 - one*bbbb/a1**2
        chi2bb = chi2bb + bbbb
        molalbb(1) = molalbb(1) + chi2bb
        molalbb(3) = molalbb(3) + chi1bb
        DO ii1=1,npair
          gamabb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0bb = 2.0*temp0*xk2*r*temp*a1bb/(xkw*gama(5))
        gamabb(10) = gamabb(10) + temp0bb
        gamabb(5) = gamabb(5) - temp0*temp0bb
      END IF
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_BB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicbb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterbb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3bb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0bb(6, 4), sionbb, hbb, chbb, f1bb(3), f2bb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplbb, xijbb, yjibb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01bb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02bb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03bb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04bb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05bb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06bb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07bb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08bb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09bb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10bb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11bb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12bb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0bb10
      DOUBLE PRECISION temp0bb
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0bb9
      DOUBLE PRECISION temp0bb8
      DOUBLE PRECISION temp0bb7
      DOUBLE PRECISION temp0bb6
      DOUBLE PRECISION temp0bb5
      DOUBLE PRECISION temp0bb4
      DOUBLE PRECISION temp0bb3
      DOUBLE PRECISION temp0bb2
      DOUBLE PRECISION temp0bb1
      DOUBLE PRECISION temp0bb0
      DOUBLE PRECISION x1bb
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION x2bb
      DOUBLE PRECISION temp0bb13
      DOUBLE PRECISION temp0bb12
      DOUBLE PRECISION y1
      DOUBLE PRECISION temp0bb11
      COMMON /gas_bb/ gnh3bb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamabb(i) = 10.d0**gama(i)*LOG(10.d0)*gamabb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamabb(i) = 0.D0
          x2bb = 0.D0
        ELSE
          x2bb = gamabb(i)
          gamabb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamabb(i) = gamabb(i) + x2bb
      ENDDO
      CALL POPREAL8(gama(13))
      gamabb(4) = gamabb(4) + 0.2d0*3.d0*gamabb(13)
      gamabb(9) = gamabb(9) + 0.2d0*2.d0*gamabb(13)
      gamabb(13) = 0.D0
      DO ii1=1,3
        f1bb(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2bb(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0bb2 = zz(12)*gamabb(12)/(z(2)+z(6))
      f1bb(2) = f1bb(2) + temp0bb2/z(2)
      f2bb(3) = f2bb(3) + temp0bb2/z(6)
      hbb = -(zz(12)*gamabb(12))
      gamabb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0bb3 = zz(11)*gamabb(11)/(z(1)+z(4))
      f2bb(1) = f2bb(1) + temp0bb3/z(4)
      hbb = hbb - zz(11)*gamabb(11)
      gamabb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0bb4 = zz(10)*gamabb(10)/(z(1)+z(7))
      f1bb(1) = f1bb(1) + temp0bb4/z(1) + temp0bb3/z(1)
      f2bb(4) = f2bb(4) + temp0bb4/z(7)
      hbb = hbb - zz(10)*gamabb(10)
      gamabb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0bb5 = zz(9)*gamabb(9)/(z(3)+z(6))
      f1bb(3) = f1bb(3) + temp0bb5/z(3)
      hbb = hbb - zz(9)*gamabb(9)
      gamabb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0bb6 = zz(8)*gamabb(8)/(z(1)+z(6))
      f2bb(3) = f2bb(3) + temp0bb6/z(6) + temp0bb5/z(6)
      hbb = hbb - zz(8)*gamabb(8)
      gamabb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0bb7 = zz(7)*gamabb(7)/(z(1)+z(5))
      f1bb(1) = f1bb(1) + temp0bb7/z(1) + temp0bb6/z(1)
      f2bb(2) = f2bb(2) + temp0bb7/z(5)
      hbb = hbb - zz(7)*gamabb(7)
      gamabb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0bb8 = zz(6)*gamabb(6)/(z(3)+z(4))
      f2bb(1) = f2bb(1) + temp0bb8/z(4)
      hbb = hbb - zz(6)*gamabb(6)
      gamabb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0bb9 = zz(5)*gamabb(5)/(z(3)+z(7))
      f2bb(4) = f2bb(4) + temp0bb9/z(7)
      hbb = hbb - zz(5)*gamabb(5)
      gamabb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0bb10 = zz(4)*gamabb(4)/(z(3)+z(5))
      f1bb(3) = f1bb(3) + temp0bb9/z(3) + temp0bb10/z(3) + temp0bb8/z(3)
      f2bb(2) = f2bb(2) + temp0bb10/z(5)
      hbb = hbb - zz(4)*gamabb(4)
      gamabb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0bb11 = zz(3)*gamabb(3)/(z(2)+z(7))
      f2bb(4) = f2bb(4) + temp0bb11/z(7)
      hbb = hbb - zz(3)*gamabb(3)
      gamabb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0bb12 = zz(2)*gamabb(2)/(z(2)+z(5))
      f2bb(2) = f2bb(2) + temp0bb12/z(5)
      hbb = hbb - zz(2)*gamabb(2)
      gamabb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0bb13 = zz(1)*gamabb(1)/(z(2)+z(4))
      f1bb(2) = f1bb(2) + temp0bb12/z(2) + temp0bb13/z(2) + temp0bb11/z(
     +  2)
      f2bb(1) = f2bb(1) + temp0bb13/z(4)
      hbb = hbb - zz(1)*gamabb(1)
      gamabb(1) = 0.D0
      ionicbb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0bb(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mplbb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijbb = (g0(i, j)+zpl*zmi*h)*f2bb(j)
          yji = ch*molal(j+3)/water
          g0bb(i, j) = g0bb(i, j) + yji*f1bb(i) + xij*f2bb(j)
          hbb = hbb + yji*zpl*zmi*f1bb(i) + xij*zpl*zmi*f2bb(j)
          yjibb = (g0(i, j)+zpl*zmi*h)*f1bb(i)
          temp0bb1 = molal(j+3)*yjibb/water
          molalbb(j+3) = molalbb(j+3) + ch*yjibb/water
          chbb = mpl*xijbb + temp0bb1
          waterbb = waterbb - ch*temp0bb1/water
          mplbb = mplbb + ch*xijbb
          ionicbb = ionicbb - (zpl+zmi)**2*0.25d0*chbb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalbb(i) = molalbb(i) + mplbb/water
        waterbb = waterbb - molal(i)*mplbb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0bb0 = agama*hbb/(sion+1.d0)
      sionbb = (1.D0-sion/(sion+1.d0))*temp0bb0
      IF (.NOT.ionic .EQ. 0.0) ionicbb = ionicbb + sionbb/(2.0*SQRT(
     +    ionic))
      g05bb = g0bb(3, 4)
      g0bb(3, 4) = 0.D0
      g09bb = g0bb(3, 3)
      g0bb(3, 3) = 0.D0
      g04bb = g0bb(3, 2)
      g0bb(3, 2) = 0.D0
      g06bb = g0bb(3, 1)
      g0bb(3, 1) = 0.D0
      g03bb = g0bb(2, 4)
      g0bb(2, 4) = 0.D0
      g12bb = g0bb(2, 3)
      g0bb(2, 3) = 0.D0
      g02bb = g0bb(2, 2)
      g0bb(2, 2) = 0.D0
      g01bb = g0bb(2, 1)
      g0bb(2, 1) = 0.D0
      g10bb = g0bb(1, 4)
      g0bb(1, 4) = 0.D0
      g08bb = g0bb(1, 3)
      g0bb(1, 3) = 0.D0
      g07bb = g0bb(1, 2)
      g0bb(1, 2) = 0.D0
      g11bb = g0bb(1, 1)
      CALL KMFUL3_BB(ionic, ionicbb, temp, g01, g01bb, g02, g02bb, g03, 
     +               g03bb, g04, g04bb, g05, g05bb, g06, g06bb, g07, 
     +               g07bb, g08, g08bb, g09, g09bb, g10, g10bb, g11, 
     +               g11bb, g12, g12bb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1bb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1bb = ionicbb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicbb = 0.D0
      ELSE
        temp0bb = 0.5d0*x1bb/water
        ionicbb = temp0bb
        waterbb = waterbb - ionic*temp0bb/water
      END IF
      DO i=7,1,-1
        molalbb(i) = molalbb(i) + z(i)**2*ionicbb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
