C *** CALCULATE COMPOSITION *******************************************
C
      IF (x .LE. y) THEN
C LC is the MIN(x,y)
CX        ! NH4HSO4 >= (NH4)2S04
        clc = 2.d0*w(2) - w(3)
        cnh4hs4 = zero
CY-X
        cnh42s4 = 2.d0*w(3) - 3.d0*w(2)
        CALL PUSHCONTROL1B(0)
      ELSE
CY        ! NH4HSO4 <  (NH4)2S04
        clc = w(3) - w(2)
CX-Y
        cnh4hs4 = 3.d0*w(2) - 2.d0*w(3)
        cnh42s4 = zero
        CALL PUSHCONTROL1B(1)
      END IF
C
      molalr(13) = clc
      molalr(9) = cnh4hs4
      molalr(4) = cnh42s4
      water = molalr(13)/m0(13) + molalr(9)/m0(9) + molalr(4)/m0(4)
C
C NH4I
      molal(3) = w(3)
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. calain)
        CALL PUSHREAL8(ak1)
C         IF (I.GT.1) CALL CALCACT3
        ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
        bet = w(2)
        gam = molal(3)
        CALL PUSHREAL8(bb)
C
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        x4 = 0.5d0*(-bb+SQRT(dd))
        IF (x4 .GT. w(2)) THEN
          x1 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = x4
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHREAL8(molal(5))
          molal(5) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(5))
          molal(5) = x1
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(2) - molal(5) .GT. w(2)) THEN
          x2 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = w(2) - molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = x2
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ak1*molal(6)/molal(5) .GT. w(2)) THEN
          x3 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x3 = ak1*molal(6)/molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x3 .LT. tiny) THEN
          CALL PUSHREAL8(molal(1))
          molal(1) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(1))
          molal(1) = x3
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR                                           ! Water content
C
C CORRECT FOR HSO4 DISSOCIATION 
        so4i = molal(5) - molal(1)
        hso4i = molal(6) + molal(1)
        IF (so4i .LT. hso4i) THEN
C [LC] = [SO4]       
          molalr(13) = so4i
          IF (hso4i - so4i .LT. zero) THEN
            molalr(9) = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            molalr(9) = hso4i - so4i
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
C [LC] = [HSO4]
          molalr(13) = hso4i
          IF (so4i - hso4i .LT. zero) THEN
            molalr(4) = zero
            CALL PUSHCONTROL2B(3)
          ELSE
            molalr(4) = so4i - hso4i
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C*** slc.11.2009 moved to beginning of loop
        CALL CALCACT3()
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCB4R')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      aerliqpbrb(nions+ngasaq+2) = 0.D0
      waterbrb = 1.0d3*aerliqpbrb(nions+1)/18.0d0
      aerliqpbrb(nions+1) = 0.D0
      DO i=ngasaq,1,-1
        aerliqpbrb(nions+1+i) = 0.D0
      ENDDO
      molalbrb = 0.D0
      DO i=nions,1,-1
        molalbrb(i) = molalbrb(i) + aerliqpbrb(i)
        aerliqpbrb(i) = 0.D0
      ENDDO
      gaspbrb(3) = 0.D0
      gaspbrb(2) = 0.D0
      gnh3brb = gaspbrb(1)
      gaspbrb(1) = 0.D0
      CALL CALCNH3P_BRB()
      wbrb = 0.D0
      molalrbrb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_BRB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterbrb = 0.D0
        DO j=npair,1,-1
          molalrbrb(j) = molalrbrb(j) + waterbrb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            hso4ibrb = molalrbrb(9)
            so4ibrb = -molalrbrb(9)
            molalrbrb(9) = 0.D0
          ELSE
            molalrbrb(9) = 0.D0
            hso4ibrb = 0.D0
            so4ibrb = 0.D0
          END IF
          so4ibrb = so4ibrb + molalrbrb(13)
          molalrbrb(13) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            so4ibrb = molalrbrb(4)
            hso4ibrb = -molalrbrb(4)
            molalrbrb(4) = 0.D0
          ELSE
            molalrbrb(4) = 0.D0
            hso4ibrb = 0.D0
            so4ibrb = 0.D0
          END IF
          hso4ibrb = hso4ibrb + molalrbrb(13)
          molalrbrb(13) = 0.D0
        END IF
        molalbrb(6) = molalbrb(6) + hso4ibrb
        molalbrb(1) = molalbrb(1) + hso4ibrb
        molalbrb(5) = molalbrb(5) + so4ibrb
        molalbrb(1) = molalbrb(1) - so4ibrb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(1))
          molalbrb(1) = 0.D0
          x3brb = 0.D0
        ELSE
          CALL POPREAL8(molal(1))
          x3brb = molalbrb(1)
          molalbrb(1) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbrb(2) = wbrb(2) + x3brb
          ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
          ak1brb = 0.D0
        ELSE
          temp2brb = x3brb/molal(5)
          ak1brb = molal(6)*temp2brb
          molalbrb(6) = molalbrb(6) + ak1*temp2brb
          molalbrb(5) = molalbrb(5) - ak1*molal(6)*temp2brb/molal(5)
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalbrb(6) = 0.D0
          x2brb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          x2brb = molalbrb(6)
          molalbrb(6) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbrb(2) = wbrb(2) + x2brb
        ELSE
          wbrb(2) = wbrb(2) + x2brb
          molalbrb(5) = molalbrb(5) - x2brb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          molalbrb(5) = 0.D0
          x1brb = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          x1brb = molalbrb(5)
          molalbrb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wbrb(2) = wbrb(2) + x1brb
          x4brb = 0.D0
        ELSE
          x4brb = x1brb
        END IF
        bet = w(2)
        gam = molal(3)
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddbrb = 0.0
        ELSE
          ddbrb = 0.5d0*x4brb/(2.0*SQRT(dd))
        END IF
        bbbrb = 2*bb*ddbrb - 0.5d0*x4brb
        ccbrb = -(4.d0*ddbrb)
        ak1brb = ak1brb + bbbrb - bet*ccbrb
        betbrb = bbbrb - ak1*ccbrb
        CALL POPREAL8(bb)
        gambrb = -bbbrb
        molalbrb(3) = molalbrb(3) + gambrb
        wbrb(2) = wbrb(2) + betbrb
        CALL POPREAL8(ak1)
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0brb = 2.*temp0*temp1*xk1*ak1brb/gama(7)
        temp1brb = temp0**2.*xk1*ak1brb/gama(7)
        gamabrb(8) = gamabrb(8) + temp0brb
        gamabrb(7) = gamabrb(7) - temp1*temp1brb - temp0*temp0brb
        waterbrb = temp1brb
      ENDDO
      wbrb(3) = wbrb(3) + molalbrb(3)
      molalrbrb(13) = molalrbrb(13) + waterbrb/m0(13)
      molalrbrb(9) = molalrbrb(9) + waterbrb/m0(9)
      molalrbrb(4) = molalrbrb(4) + waterbrb/m0(4)
      cnh42s4brb = molalrbrb(4)
      molalrbrb(4) = 0.D0
      cnh4hs4brb = molalrbrb(9)
      molalrbrb(9) = 0.D0
      clcbrb = molalrbrb(13)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        wbrb(3) = wbrb(3) + 2.d0*cnh42s4brb
        wbrb(2) = wbrb(2) + 2.d0*clcbrb - 3.d0*cnh42s4brb
        wbrb(3) = wbrb(3) - clcbrb
      ELSE
        wbrb(2) = wbrb(2) + 3.d0*cnh4hs4brb
        wbrb(3) = wbrb(3) + clcbrb - 2.d0*cnh4hs4brb
        wbrb(2) = wbrb(2) - clcbrb
      END IF
      waerbrb = 0.D0
      waerbrb(3) = waerbrb(3) + wbrb(3)
      wbrb(3) = 0.D0
      waerbrb(2) = waerbrb(2) + wbrb(2)
      waerpbrb = 0.D0
      waerpbrb = waerbrb
C
C *** adjoint development **********************************************
C
C      ncase = 12
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpbrb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END


C  Differentiation of calcnh3p in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3P
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE INVERSE PROBLEM SOLVER
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3P_BRB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3P ****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalbrb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamabrb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterbrb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3brb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1brb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION wb(ncomp)
      COMMON /inpt_b/ wb
C
C *** Case A adjoint ***************************************************
C
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION waterab
      COMMON /ions_ab/ molalab, gamaab, waterab
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt_ab/ wab
      DOUBLE PRECISION gnh3ab
      COMMON /gas_ab/ gnh3ab
CC
CC *** Case B adjoint ***************************************************
CC
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION waterbb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
      DOUBLE PRECISION gnh3bb
      COMMON /gas_bb/ gnh3bb
CC
CC *** Case C adjoint ***************************************************
CC
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION watercb
      COMMON /ions_cb/ molalcb, gamacb, watercb
      DOUBLE PRECISION gnh3cb
      COMMON /gas_cb/ gnh3cb
CC
CC *** Case D adjoint ***************************************************
CC
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2db
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas_db/ gnh3db, ghno3db
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION waterdb
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
CC
CC *** Case E adjoint ***************************************************
CC
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION watereb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt_eb/ web
      DOUBLE PRECISION ghno3eb
      COMMON /gas_eb/ ghno3eb
CC
CC *** Case F adjoint ***************************************************
CC
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION waterfb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt_fb/ wfb
      DOUBLE PRECISION ghno3fb
      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION temp1brb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1brb0
      INTEGER ii1
      DOUBLE PRECISION temp0brb
      COMMON /gas_brb/ gnh3brb
      COMMON /ions_brb/ molalbrb, gamabrb, waterbrb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamabrb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 GAS PHASE CONCENTRATION *****************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
C 
        temp1brb = gnh3brb/(molal(1)*a1)
        temp1brb0 = -(molal(3)*temp1brb/(molal(1)*a1))
        molalbrb(3) = molalbrb(3) + temp1brb
        molalbrb(1) = molalbrb(1) + a1*temp1brb0
        a1brb = molal(1)*temp1brb0
        DO ii1=1,npair
          gamabrb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0brb = 2.0*temp0*xk2*r*temp*a1brb/(xkw*gama(5))
        gamabrb(10) = gamabrb(10) + temp0brb
        gamabrb(5) = gamabrb(5) - temp0*temp0brb
      END IF
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_BRB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalbrb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicbrb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamabrb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterbrb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
