     +             )
      CALL MKBI_BRB(q1, ionic, ionicbrb, sion, sionbrb, z01, g01, g01brb
     +             )
      IF (.NOT.ionic .EQ. 0.0) ionicbrb = ionicbrb + sionbrb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_BRB(q, ionic, ionicbrb, sion, sionbrb, zip, bi, 
     +                    bibrb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicbrb, sionbrb, bibrb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cbrb, xxbrb
      INTRINSIC EXP
      DOUBLE PRECISION tempbrb0
      DOUBLE PRECISION tempbrb
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxbrb = zip*bibrb
      bibrb = zip*bibrb/(bi*LOG(10.0))
      tempbrb = -(0.5107d0*xxbrb/(c*sion+1.d0))
      tempbrb0 = -(sion*tempbrb/(c*sion+1.d0))
      sionbrb = sionbrb + c*tempbrb0 + tempbrb
      cbrb = sion*tempbrb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicbrb = ionicbrb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cbrb
      ELSE
        ionicbrb = ionicbrb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bibrb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cbrb
      END IF
      END

