      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrcb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watercb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3cb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION lamda, kapa, psi, parm
      DOUBLE PRECISION lamdacb, kapacb, psicb, parmcb
      DOUBLE PRECISION bb, cc
      DOUBLE PRECISION bbcb, cccb
      DOUBLE PRECISION wp(ncomp), gas(3), aerliq(7)
      DOUBLE PRECISION wpcb(ncomp), gascb(3), aerliqcb(7)
      INTEGER i
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1cb
      INTRINSIC MAX
      DOUBLE PRECISION temp2cb
      DOUBLE PRECISION temp0cb
      INTEGER ii1, npflag, ncase
      INTRINSIC SQRT
      COMMON /gas_cb/ gnh3cb
      COMMON /ions_cb/ molalcb, gamacb, watercb
C
C      w = wp
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS **************************************************
C
C NH4HSO4 INITIALLY IN SOLUTION
      lamda = w(3)
C H2SO4 IN SOLUTION
      psi = w(2) - w(3)
      i = 1
      ad_count = 0
C      NSWEEP = 50
      DO WHILE (i .LE. nsweep .AND. calain)
C         IF (I.GT.1) CALL CALCACT3 
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        kapa = 0.5*(-bb+SQRT(bb*bb-4.0*cc))
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = psi + kapa
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = lamda
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = kapa
        IF (lamda + psi - kapa .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = lamda + psi - kapa
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR                                       ! Water content
C
C         MOLALR(9) = MOLAL(3)                     ! NH4HSO4  *** As in ISORROPIA 1.7
C NH4HSO4
        molalr(4) = molal(3)
        IF (w(2) - w(3) .LT. zero) THEN
          molalr(7) = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          molalr(7) = w(2) - w(3)
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C         IF (.NOT.CALAIN) GOTO 30
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
C*** slc.11.2009 moved to beginning of loop
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCC2')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      DO ii1=1,nions
        molalcb(ii1) = 0.D0
      ENDDO
      DO i=nions,1,-1
        molalcb(i) = molalcb(i) + aerliqcb(i)
        aerliqcb(i) = 0.D0
      ENDDO
      gascb(3) = 0.D0
      gascb(2) = 0.D0
      gnh3cb = gascb(1)
      gascb(1) = 0.D0
      CALL CALCNH3_CB()
      DO ii1=1,ncomp
        wcb(ii1) = 0.D0
      ENDDO
      DO ii1=1,npair
        molalrcb(ii1) = 0.D0
      ENDDO
      watercb = 0.D0
      psicb = 0.D0
      lamdacb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_CB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) watercb = 0.D0
        DO j=npair,1,-1
          molalrcb(j) = molalrcb(j) + watercb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          molalrcb(7) = 0.D0
        ELSE
          wcb(2) = wcb(2) + molalrcb(7)
          wcb(3) = wcb(3) - molalrcb(7)
          molalrcb(7) = 0.D0
        END IF
        molalcb(3) = molalcb(3) + molalrcb(4)
        molalrcb(4) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalcb(6) = 0.D0
          kapacb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          lamdacb = lamdacb + molalcb(6)
          psicb = psicb + molalcb(6)
          kapacb = -molalcb(6)
          molalcb(6) = 0.D0
        END IF
        CALL POPREAL8(molal(5))
        kapacb = kapacb + molalcb(5)
        molalcb(5) = 0.D0
        CALL POPREAL8(molal(3))
        lamdacb = lamdacb + molalcb(3)
        molalcb(3) = 0.D0
        CALL POPREAL8(molal(1))
        kapacb = kapacb + molalcb(1)
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        IF (bb**2 - 4.0*cc .EQ. 0.0) THEN
          temp2cb = 0.0
        ELSE
          temp2cb = 0.5*kapacb/(2.0*SQRT(bb**2-4.0*cc))
        END IF
        bbcb = 2*bb*temp2cb - 0.5*kapacb
        cccb = -(4.0*temp2cb)
        psicb = psicb + bbcb - parm*cccb + molalcb(1)
        molalcb(1) = 0.D0
        parmcb = bbcb - (lamda+psi)*cccb
        lamdacb = lamdacb - parm*cccb
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1cb = 2.*temp1*temp0*xk1*parmcb/gama(7)
        temp0cb = temp1**2.*xk1*parmcb/gama(7)
        gamacb(8) = gamacb(8) + temp1cb
        gamacb(7) = gamacb(7) - temp0*temp0cb - temp1*temp1cb
        watercb = temp0cb
      ENDDO
      wcb(2) = wcb(2) + psicb
      wcb(3) = wcb(3) + lamdacb - psicb
C      DO ii1=1,ncomp
C        wpcb(ii1) = 0.D0
C      ENDDO
      wpcb = wcb
C
C      ncase = 3
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) w,rh,temp,wpcb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
      END
C
C
C  Differentiation of calcnh3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA IN THE GAS PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE AEROSOL EQUILIBRIUM. 
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE DIRECT PROBLEM
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3_CB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watercb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3cb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1cb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1cb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2cb
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION bb, cc, diak, psi
      DOUBLE PRECISION bbcb, cccb, diakcb, psicb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1cb
      INTRINSIC MAX
      DOUBLE PRECISION x1cb
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0cb
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_cb/ gnh3cb
      COMMON /ions_cb/ molalcb, gamacb, watercb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamacb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 SUBLIMATION *****************************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        chi1 = molal(3)
        chi2 = molal(1)
C
C a=1; b!=1; c!=1 
        bb = chi2 + one/a1
        cc = -(chi1/a1)
C Always > 0
        diak = SQRT(bb*bb - 4.d0*cc)
C One positive root
        psi = 0.5*(-bb+diak)
        IF (psi .GT. chi1) THEN
          x1 = chi1
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = psi
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        chi2cb = molalcb(1)
        psicb = molalcb(1)
        molalcb(1) = 0.D0
        chi1cb = molalcb(3)
        psicb = psicb + gnh3cb - molalcb(3)
        molalcb(3) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          x1cb = 0.D0
        ELSE
          x1cb = psicb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi1cb = chi1cb + x1cb
          psicb = 0.D0
        ELSE
          psicb = x1cb
        END IF
        diakcb = 0.5*psicb
        IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
          temp1cb = 0.0
        ELSE
          temp1cb = diakcb/(2.0*SQRT(bb**2-4.d0*cc))
        END IF
        bbcb = 2*bb*temp1cb - 0.5*psicb
        cccb = -(4.d0*temp1cb)
        chi1cb = chi1cb - cccb/a1
        a1cb = chi1*cccb/a1**2 - one*bbcb/a1**2
        chi2cb = chi2cb + bbcb
        molalcb(1) = molalcb(1) + chi2cb
        molalcb(3) = molalcb(3) + chi1cb
        DO ii1=1,npair
          gamacb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0cb = 2.0*temp0*xk2*r*temp*a1cb/(xkw*gama(5))
        gamacb(10) = gamacb(10) + temp0cb
        gamacb(5) = gamacb(5) - temp0*temp0cb
      END IF
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_CB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ioniccb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watercb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3cb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0cb(6, 4), sioncb, hcb, chcb, f1cb(3), f2cb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplcb, xijcb, yjicb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01cb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02cb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03cb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04cb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05cb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06cb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07cb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08cb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09cb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10cb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11cb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12cb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0cb13
      DOUBLE PRECISION temp0cb12
      DOUBLE PRECISION temp0cb11
      DOUBLE PRECISION temp0cb10
      INTRINSIC MAX
      DOUBLE PRECISION x1cb
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2cb
      DOUBLE PRECISION temp0cb9
      DOUBLE PRECISION temp0cb8
      DOUBLE PRECISION temp0cb7
      DOUBLE PRECISION temp0cb6
      DOUBLE PRECISION temp0cb5
      DOUBLE PRECISION temp0cb4
      DOUBLE PRECISION temp0cb3
      DOUBLE PRECISION temp0cb
      DOUBLE PRECISION temp0cb2
      DOUBLE PRECISION temp0cb1
      DOUBLE PRECISION temp0cb0
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION y1
      COMMON /gas_cb/ gnh3cb
      COMMON /ions_cb/ molalcb, gamacb, watercb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamacb(i) = 10.d0**gama(i)*LOG(10.d0)*gamacb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamacb(i) = 0.D0
          x2cb = 0.D0
        ELSE
          x2cb = gamacb(i)
          gamacb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamacb(i) = gamacb(i) + x2cb
      ENDDO
      CALL POPREAL8(gama(13))
      gamacb(4) = gamacb(4) + 0.2d0*3.d0*gamacb(13)
      gamacb(9) = gamacb(9) + 0.2d0*2.d0*gamacb(13)
      gamacb(13) = 0.D0
      DO ii1=1,3
        f1cb(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2cb(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0cb2 = zz(12)*gamacb(12)/(z(2)+z(6))
      f1cb(2) = f1cb(2) + temp0cb2/z(2)
      f2cb(3) = f2cb(3) + temp0cb2/z(6)
      hcb = -(zz(12)*gamacb(12))
      gamacb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0cb3 = zz(11)*gamacb(11)/(z(1)+z(4))
      f2cb(1) = f2cb(1) + temp0cb3/z(4)
      hcb = hcb - zz(11)*gamacb(11)
      gamacb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0cb4 = zz(10)*gamacb(10)/(z(1)+z(7))
      f1cb(1) = f1cb(1) + temp0cb4/z(1) + temp0cb3/z(1)
      f2cb(4) = f2cb(4) + temp0cb4/z(7)
      hcb = hcb - zz(10)*gamacb(10)
      gamacb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0cb5 = zz(9)*gamacb(9)/(z(3)+z(6))
      f1cb(3) = f1cb(3) + temp0cb5/z(3)
      hcb = hcb - zz(9)*gamacb(9)
      gamacb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0cb6 = zz(8)*gamacb(8)/(z(1)+z(6))
      f2cb(3) = f2cb(3) + temp0cb6/z(6) + temp0cb5/z(6)
      hcb = hcb - zz(8)*gamacb(8)
      gamacb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0cb7 = zz(7)*gamacb(7)/(z(1)+z(5))
      f1cb(1) = f1cb(1) + temp0cb7/z(1) + temp0cb6/z(1)
      f2cb(2) = f2cb(2) + temp0cb7/z(5)
      hcb = hcb - zz(7)*gamacb(7)
      gamacb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0cb8 = zz(6)*gamacb(6)/(z(3)+z(4))
      f2cb(1) = f2cb(1) + temp0cb8/z(4)
      hcb = hcb - zz(6)*gamacb(6)
      gamacb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0cb9 = zz(5)*gamacb(5)/(z(3)+z(7))
      f2cb(4) = f2cb(4) + temp0cb9/z(7)
      hcb = hcb - zz(5)*gamacb(5)
      gamacb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0cb10 = zz(4)*gamacb(4)/(z(3)+z(5))
      f1cb(3) = f1cb(3) + temp0cb9/z(3) + temp0cb10/z(3) + temp0cb8/z(3)
      f2cb(2) = f2cb(2) + temp0cb10/z(5)
      hcb = hcb - zz(4)*gamacb(4)
      gamacb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0cb11 = zz(3)*gamacb(3)/(z(2)+z(7))
      f2cb(4) = f2cb(4) + temp0cb11/z(7)
      hcb = hcb - zz(3)*gamacb(3)
      gamacb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0cb12 = zz(2)*gamacb(2)/(z(2)+z(5))
      f2cb(2) = f2cb(2) + temp0cb12/z(5)
      hcb = hcb - zz(2)*gamacb(2)
      gamacb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0cb13 = zz(1)*gamacb(1)/(z(2)+z(4))
      f1cb(2) = f1cb(2) + temp0cb12/z(2) + temp0cb13/z(2) + temp0cb11/z(
     +  2)
      f2cb(1) = f2cb(1) + temp0cb13/z(4)
      hcb = hcb - zz(1)*gamacb(1)
      gamacb(1) = 0.D0
      ioniccb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0cb(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mplcb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijcb = (g0(i, j)+zpl*zmi*h)*f2cb(j)
          yji = ch*molal(j+3)/water
          g0cb(i, j) = g0cb(i, j) + yji*f1cb(i) + xij*f2cb(j)
          hcb = hcb + yji*zpl*zmi*f1cb(i) + xij*zpl*zmi*f2cb(j)
          yjicb = (g0(i, j)+zpl*zmi*h)*f1cb(i)
          temp0cb1 = molal(j+3)*yjicb/water
          molalcb(j+3) = molalcb(j+3) + ch*yjicb/water
          chcb = mpl*xijcb + temp0cb1
          watercb = watercb - ch*temp0cb1/water
          mplcb = mplcb + ch*xijcb
          ioniccb = ioniccb - (zpl+zmi)**2*0.25d0*chcb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalcb(i) = molalcb(i) + mplcb/water
        watercb = watercb - molal(i)*mplcb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0cb0 = agama*hcb/(sion+1.d0)
      sioncb = (1.D0-sion/(sion+1.d0))*temp0cb0
      IF (.NOT.ionic .EQ. 0.0) ioniccb = ioniccb + sioncb/(2.0*SQRT(
     +    ionic))
      g05cb = g0cb(3, 4)
      g0cb(3, 4) = 0.D0
      g09cb = g0cb(3, 3)
      g0cb(3, 3) = 0.D0
      g04cb = g0cb(3, 2)
      g0cb(3, 2) = 0.D0
      g06cb = g0cb(3, 1)
      g0cb(3, 1) = 0.D0
      g03cb = g0cb(2, 4)
      g0cb(2, 4) = 0.D0
      g12cb = g0cb(2, 3)
      g0cb(2, 3) = 0.D0
      g02cb = g0cb(2, 2)
      g0cb(2, 2) = 0.D0
      g01cb = g0cb(2, 1)
      g0cb(2, 1) = 0.D0
      g10cb = g0cb(1, 4)
      g0cb(1, 4) = 0.D0
      g08cb = g0cb(1, 3)
      g0cb(1, 3) = 0.D0
      g07cb = g0cb(1, 2)
      g0cb(1, 2) = 0.D0
      g11cb = g0cb(1, 1)
      CALL KMFUL3_CB(ionic, ioniccb, temp, g01, g01cb, g02, g02cb, g03, 
     +               g03cb, g04, g04cb, g05, g05cb, g06, g06cb, g07, 
     +               g07cb, g08, g08cb, g09, g09cb, g10, g10cb, g11, 
     +               g11cb, g12, g12cb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1cb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1cb = ioniccb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ioniccb = 0.D0
      ELSE
        temp0cb = 0.5d0*x1cb/water
        ioniccb = temp0cb
        watercb = watercb - ionic*temp0cb/water
      END IF
      DO i=7,1,-1
        molalcb(i) = molalcb(i) + z(i)**2*ioniccb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_CB(ionic, ioniccb, temp, g01, g01cb, g02, g02cb
     +                     , g03, g03cb, g04, g04cb, g05, g05cb, g06, 
     +                     g06cb, g07, g07cb, g08, g08cb, g09, g09cb, 
     +                     g10, g10cb, g11, g11cb, g12, g12cb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ioniccb, sioncb, cf2cb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01cb, g02cb, g03cb, g04cb, g05cb, g06cb, g07cb, 
     +                 g08cb, g09cb, g10cb, g11cb, g12cb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      INTRINSIC ABS
      DOUBLE PRECISION temp0cb
      DOUBLE PRECISION temp0cb0
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01cb = g01cb + g12cb
      g08cb = g08cb + g09cb + g12cb
      g11cb = g11cb - g09cb - g12cb
      g06cb = g06cb + g09cb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2cb = -(z10*g10cb) - z07*g07cb - z05*g05cb - z03*g03cb - z01*
     +    g01cb - z02*g02cb - z04*g04cb - z06*g06cb - z08*g08cb - z11*
     +    g11cb
        g11cb = cf1*g11cb
        g10cb = cf1*g10cb
        g08cb = cf1*g08cb
        g07cb = cf1*g07cb
        g06cb = cf1*g06cb
        g05cb = cf1*g05cb
        g04cb = cf1*g04cb
        g03cb = cf1*g03cb
        g02cb = cf1*g02cb
        g01cb = cf1*g01cb
        temp0cb = (0.125d0-ti*0.005d0)*cf2cb
        temp0cb0 = -(0.41d0*temp0cb/(sion+1.d0))
        ioniccb = ioniccb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0cb
        sioncb = (1.D0-sion/(sion+1.d0))*temp0cb0
      ELSE
        sioncb = 0.D0
      END IF
      CALL MKBI_CB(q11, ionic, ioniccb, sion, sioncb, z11, g11, g11cb)
      CALL MKBI_CB(q10, ionic, ioniccb, sion, sioncb, z10, g10, g10cb)
      CALL MKBI_CB(q8, ionic, ioniccb, sion, sioncb, z08, g08, g08cb)
      CALL MKBI_CB(q7, ionic, ioniccb, sion, sioncb, z07, g07, g07cb)
      CALL MKBI_CB(q6, ionic, ioniccb, sion, sioncb, z06, g06, g06cb)
      CALL MKBI_CB(q5, ionic, ioniccb, sion, sioncb, z05, g05, g05cb)
      CALL MKBI_CB(q4, ionic, ioniccb, sion, sioncb, z04, g04, g04cb)
      CALL MKBI_CB(q3, ionic, ioniccb, sion, sioncb, z03, g03, g03cb)
      CALL MKBI_CB(q2, ionic, ioniccb, sion, sioncb, z02, g02, g02cb)
      CALL MKBI_CB(q1, ionic, ioniccb, sion, sioncb, z01, g01, g01cb)
      IF (.NOT.ionic .EQ. 0.0) ioniccb = ioniccb + sioncb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_CB(q, ionic, ioniccb, sion, sioncb, zip, bi, bicb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ioniccb, sioncb, bicb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION ccb, xxcb
      INTRINSIC EXP
      DOUBLE PRECISION tempcb
      DOUBLE PRECISION tempcb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxcb = zip*bicb
      bicb = zip*bicb/(bi*LOG(10.0))
      tempcb = -(0.5107d0*xxcb/(c*sion+1.d0))
      tempcb0 = -(sion*tempcb/(c*sion+1.d0))
      sioncb = sioncb + c*tempcb0 + tempcb
      ccb = sion*tempcb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ioniccb = ioniccb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*ccb
      ELSE
        ioniccb = ioniccb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bicb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*ccb
      END IF
      END

