      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION lamda, kapa, psi, parm
      DOUBLE PRECISION lamdacrb, kapacrb, psicrb, parmcrb
      DOUBLE PRECISION bb, cc
      DOUBLE PRECISION bbcrb, cccrb
      DOUBLE PRECISION wp, gas(3), aerliq(7)
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3), waerp(ncomp)
      DOUBLE PRECISION aerliqpcrb(nions+ngasaq+2), gaspcrb(3), waerpcrb(
     +                 ncomp)
      DOUBLE PRECISION wi
      DIMENSION wi(ncomp)
      INTEGER i
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp0crb
      DOUBLE PRECISION temp1crb
      DOUBLE PRECISION temp2crb
      INTRINSIC SQRT
      COMMON /gas_crb/ gnh3crb
      COMMON /ions_crb/ molalcrb, gamacrb, watercrb
      INTEGER npflag, ncase
C
C      waer = waerp
C
      w(2) = waer(2)
      w(3) = waer(3)
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS **************************************************
C
C NH4HSO4 INITIALLY IN SOLUTION
      lamda = w(3)
C H2SO4 IN SOLUTION
      psi = w(2) - w(3)
      i = 1
      ad_count = 0
C      NSWEEP = 50
      DO WHILE (i .LE. nsweep .AND. calain)
C         IF (I.GT.1) CALL CALCACT3 
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        kapa = 0.5*(-bb+SQRT(bb*bb-4.0*cc))
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = psi + kapa
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = lamda
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = kapa
        IF (lamda + psi - kapa .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = lamda + psi - kapa
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR                                       ! Water content
C
C NH4HSO4  *** As in ISORROPIA 1.7
        molalr(9) = molal(3)
        IF (w(2) - w(3) .LT. zero) THEN
          molalr(7) = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          molalr(7) = w(2) - w(3)
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C         IF (.NOT.CALAIN) GOTO 30
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
C*** slc.11.2009 Moved to beginning of loop     
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCC2R')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      aerliqpcrb(nions+ngasaq+2) = 0.D0
      watercrb = 1.0d3*aerliqpcrb(nions+1)/18.0d0
      aerliqpcrb(nions+1) = 0.D0
      DO i=ngasaq,1,-1
        aerliqpcrb(nions+1+i) = 0.D0
      ENDDO
      molalcrb = 0.D0
      DO i=nions,1,-1
        molalcrb(i) = molalcrb(i) + aerliqpcrb(i)
        aerliqpcrb(i) = 0.D0
      ENDDO
      gaspcrb(3) = 0.D0
      gaspcrb(2) = 0.D0
      gnh3crb = gaspcrb(1)
      gaspcrb(1) = 0.D0
      CALL CALCNH3P_CRB()
      wcrb = 0.D0
      molalrcrb = 0.D0
      psicrb = 0.D0
      lamdacrb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_CRB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) watercrb = 0.D0
        DO j=npair,1,-1
          molalrcrb(j) = molalrcrb(j) + watercrb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          molalrcrb(7) = 0.D0
        ELSE
          wcrb(2) = wcrb(2) + molalrcrb(7)
          wcrb(3) = wcrb(3) - molalrcrb(7)
          molalrcrb(7) = 0.D0
        END IF
        molalcrb(3) = molalcrb(3) + molalrcrb(9)
        molalrcrb(9) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalcrb(6) = 0.D0
          kapacrb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          lamdacrb = lamdacrb + molalcrb(6)
          psicrb = psicrb + molalcrb(6)
          kapacrb = -molalcrb(6)
          molalcrb(6) = 0.D0
        END IF
        CALL POPREAL8(molal(5))
        kapacrb = kapacrb + molalcrb(5)
        molalcrb(5) = 0.D0
        CALL POPREAL8(molal(3))
        lamdacrb = lamdacrb + molalcrb(3)
        molalcrb(3) = 0.D0
        CALL POPREAL8(molal(1))
        kapacrb = kapacrb + molalcrb(1)
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        IF (bb**2 - 4.0*cc .EQ. 0.0) THEN
          temp2crb = 0.0
        ELSE
          temp2crb = 0.5*kapacrb/(2.0*SQRT(bb**2-4.0*cc))
        END IF
        bbcrb = 2*bb*temp2crb - 0.5*kapacrb
        cccrb = -(4.0*temp2crb)
        psicrb = psicrb + bbcrb - parm*cccrb + molalcrb(1)
        molalcrb(1) = 0.D0
        parmcrb = bbcrb - (lamda+psi)*cccrb
        lamdacrb = lamdacrb - parm*cccrb
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0crb = 2.*temp0*temp1*xk1*parmcrb/gama(7)
        temp1crb = temp0**2.*xk1*parmcrb/gama(7)
        gamacrb(8) = gamacrb(8) + temp0crb
        gamacrb(7) = gamacrb(7) - temp1*temp1crb - temp0*temp0crb
        watercrb = temp1crb
      ENDDO
      wcrb(2) = wcrb(2) + psicrb
      wcrb(3) = wcrb(3) + lamdacrb - psicrb
      waercrb = 0.D0
      waercrb(3) = waercrb(3) + wcrb(3)
      wcrb(3) = 0.D0
      waercrb(2) = waercrb(2) + wcrb(2)
      waerpcrb = 0.D0
      waerpcrb = waercrb
C
C *** adjoint development **********************************************
C
C      ncase = 13
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpcrb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END

C

C  Differentiation of calcnh3p in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3P
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE INVERSE PROBLEM SOLVER
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3P_CRB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3P ****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalcrb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamacrb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watercrb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3crb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1crb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION wb(ncomp)
      COMMON /inpt_b/ wb
C
C *** Case A adjoint ***************************************************
C
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION waterab
      COMMON /ions_ab/ molalab, gamaab, waterab
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt_ab/ wab
      DOUBLE PRECISION gnh3ab
      COMMON /gas_ab/ gnh3ab
CC
CC *** Case B adjoint ***************************************************
CC
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION waterbb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
      DOUBLE PRECISION gnh3bb
      COMMON /gas_bb/ gnh3bb
CC
CC *** Case C adjoint ***************************************************
CC
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION watercb
      COMMON /ions_cb/ molalcb, gamacb, watercb
      DOUBLE PRECISION gnh3cb
      COMMON /gas_cb/ gnh3cb
CC
CC *** Case D adjoint ***************************************************
CC
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2db
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas_db/ gnh3db, ghno3db
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION waterdb
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
CC
CC *** Case E adjoint ***************************************************
CC
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION watereb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt_eb/ web
      DOUBLE PRECISION ghno3eb
      COMMON /gas_eb/ ghno3eb
CC
CC *** Case F adjoint ***************************************************
CC
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION waterfb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt_fb/ wfb
      DOUBLE PRECISION ghno3fb
      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0crb
      DOUBLE PRECISION temp1crb
      INTEGER ii1
      DOUBLE PRECISION temp1crb0
      COMMON /gas_crb/ gnh3crb
      COMMON /ions_crb/ molalcrb, gamacrb, watercrb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamacrb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 GAS PHASE CONCENTRATION *****************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
C 
        temp1crb = gnh3crb/(molal(1)*a1)
        temp1crb0 = -(molal(3)*temp1crb/(molal(1)*a1))
        molalcrb(3) = molalcrb(3) + temp1crb
        molalcrb(1) = molalcrb(1) + a1*temp1crb0
        a1crb = molal(1)*temp1crb0
        DO ii1=1,npair
          gamacrb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0crb = 2.0*temp0*xk2*r*temp*a1crb/(xkw*gama(5))
        gamacrb(10) = gamacrb(10) + temp0crb
        gamacrb(5) = gamacrb(5) - temp0*temp0crb
      END IF
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_CRB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalcrb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ioniccrb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamacrb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watercrb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3crb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION wb(ncomp)
      COMMON /inpt_b/ wb
C
C *** Case A adjoint ***************************************************
C
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION waterab
      COMMON /ions_ab/ molalab, gamaab, waterab
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt_ab/ wab
      DOUBLE PRECISION gnh3ab
      COMMON /gas_ab/ gnh3ab
CC
CC *** Case B adjoint ***************************************************
CC
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION waterbb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
      DOUBLE PRECISION gnh3bb
      COMMON /gas_bb/ gnh3bb
CC
CC *** Case C adjoint ***************************************************
CC
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION watercb
      COMMON /ions_cb/ molalcb, gamacb, watercb
      DOUBLE PRECISION gnh3cb
      COMMON /gas_cb/ gnh3cb
CC
CC *** Case D adjoint ***************************************************
CC
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2db
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas_db/ gnh3db, ghno3db
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION waterdb
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
CC
CC *** Case E adjoint ***************************************************
CC
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION watereb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt_eb/ web
      DOUBLE PRECISION ghno3eb
      COMMON /gas_eb/ ghno3eb
CC
CC *** Case F adjoint ***************************************************
CC
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION waterfb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt_fb/ wfb
      DOUBLE PRECISION ghno3fb
      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0crb(6, 4), sioncrb, hcrb, chcrb, f1crb(3), 
     +                 f2crb(4)
      DOUBLE PRECISION mpl, xij, yji, check
      DOUBLE PRECISION mplcrb, xijcrb, yjicrb
      CHARACTER*40 errinf
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01crb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02crb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03crb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04crb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05crb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06crb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07crb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08crb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09crb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10crb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11crb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12crb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0crb9
      DOUBLE PRECISION temp0crb8
      DOUBLE PRECISION temp0crb7
      DOUBLE PRECISION temp0crb6
      DOUBLE PRECISION temp0crb5
      DOUBLE PRECISION temp0crb4
      DOUBLE PRECISION temp0crb3
      DOUBLE PRECISION temp0crb2
      DOUBLE PRECISION temp0crb1
      DOUBLE PRECISION temp0crb0
      INTRINSIC MAX
      DOUBLE PRECISION temp0crb13
      DOUBLE PRECISION temp0crb12
      DOUBLE PRECISION temp0crb11
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION temp0crb10
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0crb
      DOUBLE PRECISION x1crb
      DOUBLE PRECISION x2crb
      INTRINSIC MIN
      INTRINSIC SQRT
      DOUBLE PRECISION y1
      COMMON /gas_crb/ gnh3crb
      COMMON /ions_crb/ molalcrb, gamacrb, watercrb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 200.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
