C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_CRB(q, ionic, ioniccrb, sion, sioncrb, zip, bi, 
     +                    bicrb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ioniccrb, sioncrb, bicrb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION ccrb, xxcrb
      DOUBLE PRECISION tempcrb
      INTRINSIC EXP
      DOUBLE PRECISION tempcrb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxcrb = zip*bicrb
      bicrb = zip*bicrb/(bi*LOG(10.0))
      tempcrb = -(0.5107d0*xxcrb/(c*sion+1.d0))
      tempcrb0 = -(sion*tempcrb/(c*sion+1.d0))
      sioncrb = sioncrb + c*tempcrb0 + tempcrb
      ccrb = sion*tempcrb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ioniccrb = ioniccrb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*ccrb
      ELSE
        ioniccrb = ioniccrb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bicrb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*ccrb
      END IF
      END


