      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2db
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2db
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrd
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION wp(ncomp), gas(3), aerliq(7)
      DOUBLE PRECISION wpdb(ncomp), gasdb(3), aerliqdb(7)
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               PSI1, PSI2, PSI3, PSI4, PSI5, PSI6, PSI7, PSI8,
C     &               A1,   A2,   A3,   A4,   A5,   A6,   A7,   A8
      DOUBLE PRECISION p4, y1, parm, x
      DOUBLE PRECISION y1db, xdb
      DOUBLE PRECISION x1, x2, xt, y1d, y2, xtd
      DOUBLE PRECISION x2db, y1ddb
      DOUBLE PRECISION ps, om, omps, diak, ze, delta
      DOUBLE PRECISION psdb, omdb, ompsdb, diakdb, zedb, deltadb
      CHARACTER*40 errinf
      INTEGER errstki(25)
      LOGICAL dexs, iexs, eof
      DOUBLE PRECISION absire, feps
      CHARACTER*40 errmsgi(25)
      COMMON /cd1a/ om, ps, ze
      INTEGER i
      INTEGER branch, npflag, ncase
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION abs1
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      COMMON /gas_db/ gnh3db, ghno3db
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
C
C *** SETUP PARAMETERS ************************************************
C
C      w = wp
C
C *** SETUP PARAMETERS ************************************************
C
C      WRITE(*,*) 'Within FUNCD3P_DB'
      feps = 1.d-5
      parm = xk10/(r*temp)/(r*temp)
C
C *** CALCULATE NH4NO3 THAT VOLATIZES *********************************
C
      cnh42s4 = w(2)
      IF (w(3) - 2.d0*w(2) .GT. w(4)) THEN
        x = w(4)
        CALL PUSHCONTROL1B(0)
      ELSE
        x = w(3) - 2.d0*w(2)
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x .GT. zero) THEN
        IF (w(3) - 2.0*w(2) .LT. w(4)) THEN
          ps = zero
          om = w(4) - w(3) + 2.0*w(2)
          IF (om .LT. tiny) THEN
            om = zero
            CALL PUSHCONTROL3B(4)
          ELSE
            CALL PUSHCONTROL3B(3)
          END IF
        ELSE
          ps = w(3) - w(4) - 2.0*w(2)
          IF (ps .LT. tiny) THEN
            ps = zero
            CALL PUSHCONTROL3B(1)
          ELSE
            CALL PUSHCONTROL3B(2)
          END IF
          om = zero
        END IF
      ELSE
        x = zero
        IF (w(3) - 2.d0*w(2) .LT. zero) THEN
          CALL PUSHCONTROL1B(0)
          ps = zero
        ELSE
          ps = w(3) - 2.d0*w(2)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ps .LT. tiny) THEN
          ps = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        om = w(4)
        CALL PUSHCONTROL3B(0)
      END IF
C
      omps = om + ps
C DIAKRINOUSA
      diak = SQRT(omps*omps + 4.0*parm)
      IF (x .GT. 0.5*(-omps+diak)) THEN
        ze = 0.5*(-omps+diak)
        CALL PUSHCONTROL1B(0)
      ELSE
        ze = x
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** SPECIATION *******************************************************
C
C Solid NH4NO3
      cnh4no3 = x - ze
C Gas NH3
      gnh3 = ps + ze
C Gas HNO3
      ghno3 = om + ze
C
C Save from CALCD1 run
      chi2 = cnh42s4
      chi3 = ghno3
      chi4 = gnh3
C
C ASSIGN INITIAL PSI's
      psi1 = cnh4no3
      psi2 = chi2
      psi4 = p4
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
C
C *** NEWTON-RAPHSON DETERMINATION OF ROOT **********************
C
C      WRITE(*,*) 'Before FUNCD3B_DNRD, xt: ',PSI4
      xt = psi4
      xtd = 1.d0
      CALL PUSHREAL8ARRAY(gamadnrd, npair)
      CALL PUSHREAL8ARRAY(molaldnrd, nions)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
C      WRITE(*,*) 'PSI4 ',PSI4
C      CALL FUNCD3B(XT,Y1)
      CALL FUNCD3B_DNRD(xt, xtd, y1, y1d)
      x2 = xt - y1/(y1d*1.d0)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
      CALL FUNCD3B(x2, y2)
C      WRITE(*,*) 'x2 ', x2, ' y2 ',y2
      IF (y2 .GE. 0.) THEN
        abs1 = y2
      ELSE
        abs1 = -y2
      END IF
      IF (abs1 .GT. feps) THEN
C        WRITE(*,*) 'abs1 .GT. feps', abs1
        WRITE(ERRINF, '(A,E12.5,A)') 'CALCD3 (',(abs1),')'
        CALL PUSHERR (0104, ERRINF)    ! WARNING ERROR: NO CONVERGENCE
        DO ii1=1,nions
          molaldb(ii1) = 0.D0
        ENDDO
        DO ii1=1,npair
          gamadb(ii1) = 0.D0
        ENDDO
        waterdb = 0.D0
        gnh3db = 0.D0
        ghno3db = 0.D0
      ELSE
C      WRITE(*,*) '********** Testing Newton in CVM *******************'
C      WRITE(*,*) 'XT ',XT
C      WRITE(*,*) 'Y1 ', Y1
C      WRITE(*,*) 'Y1D ', Y1D
C      WRITE(*,*) 'X2 ',X2
C      WRITE(*,*) 'Y2 ',Y2
C      WRITE(*,*) '******** End of testing Newton in CVM ***************'
C
        IF (molal(1) .GT. tiny .AND. molal(5) .GT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        DO ii1=1,nions
          molaldb(ii1) = 0.D0
        ENDDO
        DO i=nions,1,-1
          molaldb(i) = molaldb(i) + aerliqdb(i)
          aerliqdb(i) = 0.D0
        ENDDO
C        WRITE(*,*) 'molaldb',molaldb
        gasdb(3) = 0.D0
        ghno3db = gasdb(2)
        gasdb(2) = 0.D0
        gnh3db = gasdb(1)
        gasdb(1) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          deltadb = molaldb(6)
          molaldb(6) = 0.D0
          deltadb = deltadb - molaldb(1) - molaldb(5)
          CALL CALCHS4_DB(molal(1), molaldb(1), molal(5), molaldb(5), 
     +                    zero, delta, deltadb)
        ELSE
          DO ii1=1,npair
            gamadb(ii1) = 0.D0
          ENDDO
          waterdb = 0.D0
        END IF
      END IF
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL FUNCD3B_DB(x2, x2db, y2)
      y1db = -(x2db/y1d)
      y1ddb = y1*x2db/y1d**2
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL POPREAL8ARRAY(molaldnrd, nions)
      CALL POPREAL8ARRAY(gamadnrd, npair)
      CALL FUNCD3B_DNRD_DB(xt, xtd, y1, y1db, y1d, y1ddb)
      chi2db = psi2db
      cnh4no3db = psi1db
      gnh3db = gnh3db + chi4db
      ghno3db = ghno3db + chi3db
      cnh42s4db = chi2db
      omdb = ghno3db
      zedb = gnh3db - cnh4no3db + ghno3db
      psdb = gnh3db
      xdb = cnh4no3db
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        diakdb = 0.5*zedb
        ompsdb = -(0.5*zedb)
      ELSE
        xdb = xdb + zedb
        diakdb = 0.D0
        ompsdb = 0.D0
      END IF
      IF (.NOT.parm*4.0 + omps**2 .EQ. 0.0) ompsdb = ompsdb + 2*omps*
     +    diakdb/(2.0*SQRT(parm*4.0+omps**2))
      omdb = omdb + ompsdb
      psdb = psdb + ompsdb
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          DO ii1=1,ncomp
            wdb(ii1) = 0.D0
          ENDDO
          wdb(4) = wdb(4) + omdb
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) psdb = 0.D0
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            wdb(3) = wdb(3) + psdb
            wdb(2) = wdb(2) - 2.d0*psdb
          END IF
          xdb = 0.D0
          GOTO 100
        ELSE
          psdb = 0.D0
        END IF
      ELSE IF (branch .NE. 2) THEN
        IF (branch .NE. 3) omdb = 0.D0
        DO ii1=1,ncomp
          wdb(ii1) = 0.D0
        ENDDO
        wdb(4) = wdb(4) + omdb
        wdb(3) = wdb(3) - omdb
        wdb(2) = wdb(2) + 2.0*omdb
        GOTO 100
      END IF
      DO ii1=1,ncomp
        wdb(ii1) = 0.D0
      ENDDO
      wdb(3) = wdb(3) + psdb
      wdb(4) = wdb(4) - psdb
      wdb(2) = wdb(2) - 2.0*psdb
 100  CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        wdb(4) = wdb(4) + xdb
      ELSE
        wdb(3) = wdb(3) + xdb
        wdb(2) = wdb(2) - 2.d0*xdb
      END IF
      wdb(2) = wdb(2) + cnh42s4db
C      DO ii1=1,5
C        wpdb(ii1) = 0.D0
C      ENDDO
      wpdb = wdb
      END

C  Differentiation of funcd3b in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water gnh3 ghno3
C   with respect to varying inputs: molal molalr gama water gnh3
C                ghno3 chi3 chi4 psi1 psi2 p4
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** FUNCTION FUNCD3
C *** CASE D3 
C     FUNCTION THAT SOLVES THE SYSTEM OF EQUATIONS FOR CASE D3 ; 
C     AND RETURNS THE VALUE OF THE ZEROED FUNCTION IN FUNCD3.
C
C=======================================================================
C
      SUBROUTINE FUNCD3B_DB(p4, p4db, fd3b)
      IMPLICIT NONE
C
C *** END OF FUNCTION FUNCD3P *******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterdb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2db
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi3db
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi4db
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION a3db
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4db
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION a7db
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrd
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               PSI1, PSI2, PSI3, PSI4, PSI5, PSI6, PSI7, PSI8,
C     &               A1,   A2,   A3,   A4,   A5,   A6,   A7,   A8
C      DOUBLE PRECISION wp(5), molalp(7)
      DOUBLE PRECISION p4, bb, denm, ahi, aml5, fd3b
      DOUBLE PRECISION p4db, bbdb, denmdb, ahidb, aml5db
      CHARACTER*40 errinf
      INTEGER errstki(25), k, j
      LOGICAL dexs, iexs, eof
      CHARACTER*40 errmsgi(25)
      LOGICAL tst
      INTEGER i
      DOUBLE PRECISION abb
      DOUBLE PRECISION abbdb
      INTEGER branch
      DOUBLE PRECISION temp3
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp4db
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp2db
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2db
      DOUBLE PRECISION temp2db3
      DOUBLE PRECISION temp2db2
      DOUBLE PRECISION temp2db1
      DOUBLE PRECISION temp2db0
      DOUBLE PRECISION temp3db0
      DOUBLE PRECISION temp0db
      DOUBLE PRECISION temp4db0
      DOUBLE PRECISION temp3db
      DOUBLE PRECISION temp1db
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION x1db
      DOUBLE PRECISION max1
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      COMMON /gas_db/ gnh3db, ghno3db
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
C
C *** SETUP PARAMETERS ************************************************
C
      psi4 = p4
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      DO i=1,3
C
        a3 = xk4*r*temp*(water/gama(10))**2.0
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        CALL PUSHREAL8(a7)
        a7 = xkw*rh*water*water
C
        psi3 = a3*a4*chi3*(chi4-psi4) - psi1*(2.d0*psi2+psi1+psi4)
        CALL PUSHREAL8(psi3)
        psi3 = psi3/(a3*a4*(chi4-psi4)+2.d0*psi2+psi1+psi4)
        IF (psi3 .LT. zero) THEN
          x1 = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = psi3
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .GT. chi3) THEN
          psi3 = chi3
          CALL PUSHCONTROL1B(0)
        ELSE
          psi3 = x1
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(bb)
C
        bb = psi4 - psi3
        CALL PUSHREAL8(denm)
        denm = bb + SQRT(bb*bb + 4.d0*a7)
        IF (denm .LE. tiny) THEN
          IF (bb .GE. 0.) THEN
            CALL PUSHREAL8(abb)
            abb = bb
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(abb)
            abb = -bb
            CALL PUSHCONTROL1B(1)
          END IF
C Taylor expansion of SQRT
          denm = bb + abb + 2.0*a7/abb - 2.0*a7*a7/abb**3.0
C            WRITE(*,*) 'TS approx. of DENM: ',DENM
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        ahi = 2.0*a7/denm
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = ahi
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = psi1 + psi4 + 2.d0*psi2
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = psi2
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = zero
        CALL PUSHREAL8(molal(7))
C NO3I
        molal(7) = psi3 + psi1
C Solid (NH4)2SO4
C Solid NH4NO3
C Gas HNO3
C Gas NH3
C
C         CALL CALCMR                                ! Water content
C
C (NH4)2SO4
        molalr(4) = molal(5) + molal(6)
C "free" NH4
        aml5 = molal(3) - 2.d0*molalr(4)
        IF (aml5 .GT. molal(7)) THEN
          x2 = molal(7)
          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = aml5
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. zero) THEN
          molalr(5) = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          molalr(5) = x2
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
C
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
        CALL CALCACT3P()
      ENDDO
      DO ii1=1,npair
        molalrdb(ii1) = 0.D0
      ENDDO
      chi3db = 0.D0
      chi4db = 0.D0
      psi1db = 0.D0
      psi2db = 0.D0
      psi4db = 0.D0
      DO i=3,1,-1
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3P_DB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterdb = 0.D0
        DO j=npair,1,-1
          molalrdb(j) = molalrdb(j) + waterdb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          molalrdb(5) = 0.D0
          x2db = 0.D0
        ELSE
          x2db = molalrdb(5)
          molalrdb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          molaldb(7) = molaldb(7) + x2db
          aml5db = 0.D0
        ELSE
          aml5db = x2db
        END IF
        molaldb(3) = molaldb(3) + aml5db
        molalrdb(4) = molalrdb(4) - 2.d0*aml5db
        molaldb(5) = molaldb(5) + molalrdb(4)
        molaldb(6) = molaldb(6) + molalrdb(4)
        molalrdb(4) = 0.D0
        chi4db = chi4db + gnh3db
        chi3db = chi3db + ghno3db
        psi3db = molaldb(7) - ghno3db
        CALL POPREAL8(molal(7))
        psi1db = psi1db + molaldb(7)
        molaldb(7) = 0.D0
        CALL POPREAL8(molal(6))
        molaldb(6) = 0.D0
        CALL POPREAL8(molal(5))
        psi2db = psi2db + molaldb(5)
        molaldb(5) = 0.D0
        psi4db = psi4db + molaldb(3) - gnh3db
        CALL POPREAL8(molal(3))
        psi1db = psi1db + molaldb(3)
        psi2db = psi2db + 2.d0*molaldb(3)
        molaldb(3) = 0.D0
        CALL POPREAL8(molal(1))
        ahidb = molaldb(1)
        molaldb(1) = 0.D0
        temp4db0 = 2.0*ahidb/denm
        a7db = temp4db0
        denmdb = -(a7*temp4db0/denm)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          bbdb = 0.D0
        ELSE
          temp4db = 2.0*denmdb/abb
          temp3 = abb**3.0
          temp3db0 = -(2.0*denmdb/temp3)
          bbdb = denmdb
          abbdb = denmdb - a7*temp4db/abb - a7**2*3.0*abb**2.0*temp3db0/
     +      temp3
          a7db = a7db + 2*a7*temp3db0 + temp4db
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(abb)
            bbdb = bbdb + abbdb
          ELSE
            CALL POPREAL8(abb)
            bbdb = bbdb - abbdb
          END IF
          denmdb = 0.D0
        END IF
        CALL POPREAL8(denm)
        IF (bb**2 + 4.d0*a7 .EQ. 0.0) THEN
          temp3db = 0.0
        ELSE
          temp3db = denmdb/(2.0*SQRT(bb**2+4.d0*a7))
        END IF
        bbdb = bbdb + 2*bb*temp3db + denmdb
        a7db = a7db + 4.d0*temp3db
        CALL POPREAL8(bb)
        psi4db = psi4db + bbdb
        psi3db = psi3db - bbdb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi3db = chi3db + psi3db
          x1db = 0.D0
        ELSE
          x1db = psi3db
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          psi3db = 0.D0
        ELSE
          psi3db = x1db
        END IF
        a3 = xk4*r*temp*(water/gama(10))**2.0
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        CALL POPREAL8(psi3)
        temp2 = a3*a4*(chi4-psi4) + 2.d0*psi2 + psi1 + psi4
        temp2db = -(psi3*psi3db/temp2**2)
        temp2db0 = a3*a4*temp2db
        psi3db = psi3db/temp2
        temp2db1 = chi3*(chi4-psi4)*psi3db
        a3db = a4*temp2db1 + (chi4-psi4)*a4*temp2db
        a4db = a3*temp2db1 + (chi4-psi4)*a3*temp2db
        temp2db2 = a3*a4*psi3db
        chi4db = chi4db + chi3*temp2db2 + temp2db0
        temp2db3 = -(psi1*psi3db)
        psi4db = psi4db + temp2db3 - chi3*temp2db2 + temp2db - temp2db0
        psi2db = psi2db + 2.d0*temp2db3 + 2.d0*temp2db
        psi1db = psi1db + temp2db3 - (2.d0*psi2+psi1+psi4)*psi3db + 
     +    temp2db
        chi3db = chi3db + (chi4-psi4)*temp2db2
        CALL POPREAL8(a7)
        temp1 = gama(10)/gama(5)
        temp1db = 2.0*temp1*xk2*r*temp*a4db/(xkw*gama(5))
        gamadb(10) = gamadb(10) + temp1db
        gamadb(5) = gamadb(5) - temp1*temp1db
        temp0 = water/gama(10)
        temp0db = 2.0*temp0*xk4*r*temp*a3db/gama(10)
        waterdb = temp0db + xkw*rh*2*water*a7db
        gamadb(10) = gamadb(10) - temp0*temp0db
        gnh3db = 0.D0
        ghno3db = 0.D0
      ENDDO
      p4db = psi4db
      END

C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHS4
C *** THIS SUBROUTINE CALCULATES THE HSO4 GENERATED FROM (H,SO4).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHS4_DB(hi, hidb, so4i, so4idb, hso4i, delta, 
     +                      deltadb)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHS4 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterdb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2db
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION a8db
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrd
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION hidb, so4idb, deltadb, bbdb, ccdb, dddb, sqdddb, 
     +                 delta1db, delta2db
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0db
      DOUBLE PRECISION temp1db
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      COMMON /gas_db/ gnh3db, ghno3db
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .LE. 1d1*tiny) THEN
        DO ii1=1,npair
          gamadb(ii1) = 0.D0
        ENDDO
        waterdb = 0.D0
      ELSE
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2db = deltadb
            delta1db = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2db = deltadb
            delta1db = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1db = deltadb
            ELSE
              delta1db = 0.D0
            END IF
            delta2db = 0.D0
          END IF
          bbdb = -(0.5*delta1db) - 0.5*delta2db
          sqdddb = 0.5*delta1db - 0.5*delta2db
          IF (dd .EQ. 0.0) THEN
            dddb = 0.0
          ELSE
            dddb = sqdddb/(2.0*SQRT(dd))
          END IF
        ELSE
          dddb = 0.D0
          bbdb = 0.D0
        END IF
        bbdb = bbdb + 2*bb*dddb
        ccdb = -(4.d0*dddb)
        hidb = hidb + so4i*ccdb - bbdb
        so4idb = so4idb + hi*ccdb - bbdb
        a8db = -bbdb - hso4i*ccdb
        DO ii1=1,npair
          gamadb(ii1) = 0.D0
        ENDDO
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1db = 2.*temp1*temp0*xk1*a8db/gama(7)
        temp0db = temp1**2.*xk1*a8db/gama(7)
        gamadb(8) = gamadb(8) + temp1db
        gamadb(7) = gamadb(7) - temp0*temp0db - temp1*temp1db
        waterdb = temp0db
      END IF
      END

C  Differentiation of calcact3p in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3P_DB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicdb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterdb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2db
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrd
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0db(6, 4), siondb, hdb, chdb, f1db(3), f2db(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mpldb, xijdb, yjidb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01db
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02db
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03db
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04db
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05db
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06db
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07db
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08db
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09db
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10db
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11db
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12db
      INTEGER j
      INTEGER branch
      DOUBLE PRECISION temp0db9
      DOUBLE PRECISION temp0db8
      DOUBLE PRECISION temp0db7
      DOUBLE PRECISION temp0db6
      DOUBLE PRECISION temp0db5
      DOUBLE PRECISION temp0db4
      DOUBLE PRECISION temp0db3
      DOUBLE PRECISION temp0db2
      DOUBLE PRECISION temp0db13
      DOUBLE PRECISION temp0db1
      DOUBLE PRECISION temp0db12
      DOUBLE PRECISION temp0db0
      DOUBLE PRECISION temp0db11
      DOUBLE PRECISION temp0db10
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2db
      DOUBLE PRECISION temp0db
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION x1db
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      COMMON /gas_db/ gnh3db, ghno3db
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamadb(i) = 10.d0**gama(i)*LOG(10.d0)*gamadb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamadb(i) = 0.D0
          x2db = 0.D0
        ELSE
          x2db = gamadb(i)
          gamadb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamadb(i) = gamadb(i) + x2db
      ENDDO
      CALL POPREAL8(gama(13))
      gamadb(4) = gamadb(4) + 0.2d0*3.d0*gamadb(13)
      gamadb(9) = gamadb(9) + 0.2d0*2.d0*gamadb(13)
      gamadb(13) = 0.D0
      DO ii1=1,3
        f1db(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2db(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0db2 = zz(12)*gamadb(12)/(z(2)+z(6))
      f1db(2) = f1db(2) + temp0db2/z(2)
      f2db(3) = f2db(3) + temp0db2/z(6)
      hdb = -(zz(12)*gamadb(12))
      gamadb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0db3 = zz(11)*gamadb(11)/(z(1)+z(4))
      f2db(1) = f2db(1) + temp0db3/z(4)
      hdb = hdb - zz(11)*gamadb(11)
      gamadb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0db4 = zz(10)*gamadb(10)/(z(1)+z(7))
      f1db(1) = f1db(1) + temp0db4/z(1) + temp0db3/z(1)
      f2db(4) = f2db(4) + temp0db4/z(7)
      hdb = hdb - zz(10)*gamadb(10)
      gamadb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0db5 = zz(9)*gamadb(9)/(z(3)+z(6))
      f1db(3) = f1db(3) + temp0db5/z(3)
      hdb = hdb - zz(9)*gamadb(9)
      gamadb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0db6 = zz(8)*gamadb(8)/(z(1)+z(6))
      f2db(3) = f2db(3) + temp0db6/z(6) + temp0db5/z(6)
      hdb = hdb - zz(8)*gamadb(8)
      gamadb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0db7 = zz(7)*gamadb(7)/(z(1)+z(5))
      f1db(1) = f1db(1) + temp0db7/z(1) + temp0db6/z(1)
      f2db(2) = f2db(2) + temp0db7/z(5)
      hdb = hdb - zz(7)*gamadb(7)
      gamadb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0db8 = zz(6)*gamadb(6)/(z(3)+z(4))
      f2db(1) = f2db(1) + temp0db8/z(4)
      hdb = hdb - zz(6)*gamadb(6)
      gamadb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0db9 = zz(5)*gamadb(5)/(z(3)+z(7))
      f2db(4) = f2db(4) + temp0db9/z(7)
      hdb = hdb - zz(5)*gamadb(5)
      gamadb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0db10 = zz(4)*gamadb(4)/(z(3)+z(5))
      f1db(3) = f1db(3) + temp0db9/z(3) + temp0db10/z(3) + temp0db8/z(3)
      f2db(2) = f2db(2) + temp0db10/z(5)
      hdb = hdb - zz(4)*gamadb(4)
      gamadb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0db11 = zz(3)*gamadb(3)/(z(2)+z(7))
      f2db(4) = f2db(4) + temp0db11/z(7)
      hdb = hdb - zz(3)*gamadb(3)
      gamadb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0db12 = zz(2)*gamadb(2)/(z(2)+z(5))
      f2db(2) = f2db(2) + temp0db12/z(5)
      hdb = hdb - zz(2)*gamadb(2)
      gamadb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0db13 = zz(1)*gamadb(1)/(z(2)+z(4))
      f1db(2) = f1db(2) + temp0db12/z(2) + temp0db13/z(2) + temp0db11/z(
     +  2)
      f2db(1) = f2db(1) + temp0db13/z(4)
      hdb = hdb - zz(1)*gamadb(1)
      gamadb(1) = 0.D0
      ionicdb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0db(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mpldb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijdb = (g0(i, j)+zpl*zmi*h)*f2db(j)
          yji = ch*molal(j+3)/water
          g0db(i, j) = g0db(i, j) + yji*f1db(i) + xij*f2db(j)
          hdb = hdb + yji*zpl*zmi*f1db(i) + xij*zpl*zmi*f2db(j)
          yjidb = (g0(i, j)+zpl*zmi*h)*f1db(i)
          temp0db1 = molal(j+3)*yjidb/water
          molaldb(j+3) = molaldb(j+3) + ch*yjidb/water
          chdb = mpl*xijdb + temp0db1
          waterdb = waterdb - ch*temp0db1/water
          mpldb = mpldb + ch*xijdb
          ionicdb = ionicdb - (zpl+zmi)**2*0.25d0*chdb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molaldb(i) = molaldb(i) + mpldb/water
        waterdb = waterdb - molal(i)*mpldb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0db0 = agama*hdb/(sion+1.d0)
      siondb = (1.D0-sion/(sion+1.d0))*temp0db0
      IF (.NOT.ionic .EQ. 0.0) ionicdb = ionicdb + siondb/(2.0*SQRT(
     +    ionic))
      g05db = g0db(3, 4)
      g0db(3, 4) = 0.D0
      g09db = g0db(3, 3)
      g0db(3, 3) = 0.D0
      g04db = g0db(3, 2)
      g0db(3, 2) = 0.D0
      g06db = g0db(3, 1)
      g0db(3, 1) = 0.D0
      g03db = g0db(2, 4)
      g0db(2, 4) = 0.D0
      g12db = g0db(2, 3)
      g0db(2, 3) = 0.D0
      g02db = g0db(2, 2)
      g0db(2, 2) = 0.D0
      g01db = g0db(2, 1)
      g0db(2, 1) = 0.D0
      g10db = g0db(1, 4)
      g0db(1, 4) = 0.D0
      g08db = g0db(1, 3)
      g0db(1, 3) = 0.D0
      g07db = g0db(1, 2)
      g0db(1, 2) = 0.D0
      g11db = g0db(1, 1)
      CALL KMFUL3_DB(ionic, ionicdb, temp, g01, g01db, g02, g02db, g03, 
     +               g03db, g04, g04db, g05, g05db, g06, g06db, g07, 
     +               g07db, g08, g08db, g09, g09db, g10, g10db, g11, 
     +               g11db, g12, g12db)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1db = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1db = ionicdb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicdb = 0.D0
      ELSE
        temp0db = 0.5d0*x1db/water
        ionicdb = temp0db
        waterdb = waterdb - ionic*temp0db/water
      END IF
      DO i=7,1,-1
        molaldb(i) = molaldb(i) + z(i)**2*ionicdb
      ENDDO
      END

C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_DB(ionic, ionicdb, temp, g01, g01db, g02, g02db
     +                     , g03, g03db, g04, g04db, g05, g05db, g06, 
     +                     g06db, g07, g07db, g08, g08db, g09, g09db, 
     +                     g10, g10db, g11, g11db, g12, g12db)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicdb, siondb, cf2db
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01db, g02db, g03db, g04db, g05db, g06db, g07db, 
     +                 g08db, g09db, g10db, g11db, g12db
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0db0
      INTRINSIC ABS
      DOUBLE PRECISION temp0db
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01db = g01db + g12db
      g08db = g08db + g09db + g12db
      g11db = g11db - g09db - g12db
      g06db = g06db + g09db
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2db = -(z10*g10db) - z07*g07db - z05*g05db - z03*g03db - z01*
     +    g01db - z02*g02db - z04*g04db - z06*g06db - z08*g08db - z11*
     +    g11db
        g11db = cf1*g11db
        g10db = cf1*g10db
        g08db = cf1*g08db
        g07db = cf1*g07db
        g06db = cf1*g06db
        g05db = cf1*g05db
        g04db = cf1*g04db
        g03db = cf1*g03db
        g02db = cf1*g02db
        g01db = cf1*g01db
        temp0db = (0.125d0-ti*0.005d0)*cf2db
        temp0db0 = -(0.41d0*temp0db/(sion+1.d0))
        ionicdb = ionicdb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0db
        siondb = (1.D0-sion/(sion+1.d0))*temp0db0
      ELSE
        siondb = 0.D0
      END IF
      CALL MKBI_DB(q11, ionic, ionicdb, sion, siondb, z11, g11, g11db)
      CALL MKBI_DB(q10, ionic, ionicdb, sion, siondb, z10, g10, g10db)
      CALL MKBI_DB(q8, ionic, ionicdb, sion, siondb, z08, g08, g08db)
      CALL MKBI_DB(q7, ionic, ionicdb, sion, siondb, z07, g07, g07db)
      CALL MKBI_DB(q6, ionic, ionicdb, sion, siondb, z06, g06, g06db)
      CALL MKBI_DB(q5, ionic, ionicdb, sion, siondb, z05, g05, g05db)
      CALL MKBI_DB(q4, ionic, ionicdb, sion, siondb, z04, g04, g04db)
      CALL MKBI_DB(q3, ionic, ionicdb, sion, siondb, z03, g03, g03db)
      CALL MKBI_DB(q2, ionic, ionicdb, sion, siondb, z02, g02, g02db)
      CALL MKBI_DB(q1, ionic, ionicdb, sion, siondb, z01, g01, g01db)
      IF (.NOT.ionic .EQ. 0.0) ionicdb = ionicdb + siondb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_DB(q, ionic, ionicdb, sion, siondb, zip, bi, bidb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicdb, siondb, bidb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cdb, xxdb
      INTRINSIC EXP
      DOUBLE PRECISION tempdb
      INTRINSIC LOG10
      DOUBLE PRECISION tempdb0
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxdb = zip*bidb
      bidb = zip*bidb/(bi*LOG(10.0))
      tempdb = -(0.5107d0*xxdb/(c*sion+1.d0))
      tempdb0 = -(sion*tempdb/(c*sion+1.d0))
      siondb = siondb + c*tempdb0 + tempdb
      cdb = sion*tempdb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicdb = ionicdb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cdb
      ELSE
        ionicdb = ionicdb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bidb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cdb
      END IF
      END


