C=======================================================================
C
      SUBROUTINE MKBI_DNRD_DB(q, ionic, ionicdb, ionicdnrd, ionicdnrddb
     +                        , sion, siondb, siondnrd, siondnrddb, zip
     +                        , bi, bidb, bidnrd, bidnrddb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicdb, siondb, bidb
      DOUBLE PRECISION ionicdnrd, siondnrd, bidnrd
      DOUBLE PRECISION ionicdnrddb, siondnrddb, bidnrddb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cdb, xxdb
      DOUBLE PRECISION cdnrd, xxdnrd
      DOUBLE PRECISION cdnrddb, xxdnrddb
