      DOUBLE PRECISION pwx1db
      DOUBLE PRECISION pwx1dnrd
      DOUBLE PRECISION pwx1dnrddb
      DOUBLE PRECISION pwr1
      DOUBLE PRECISION pwr1db
      DOUBLE PRECISION pwr1dnrd
      DOUBLE PRECISION pwr1dnrddb
      INTRINSIC EXP
      INTRINSIC LOG10
      DOUBLE PRECISION tiny
      INTEGER branch
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION tempdb
      DOUBLE PRECISION temp1db3
      DOUBLE PRECISION temp1db2
      DOUBLE PRECISION temp1db1
      DOUBLE PRECISION temp1db0
      INTRINSIC ABS
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0db
      INTRINSIC LOG
      INTRINSIC INT
