      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION a3dnrd
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4dnrd
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION a7dnrd
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               PSI1, PSI2, PSI3, PSI4, PSI5, PSI6, PSI7, PSI8,
C     &               A1,   A2,   A3,   A4,   A5,   A6,   A7,   A8
C      DOUBLE PRECISION wp(5), molalp(7)
      DOUBLE PRECISION p4, bb, denm, ahi, aml5, fd3b
      DOUBLE PRECISION p4dnrd, bbdnrd, denmdnrd, ahidnrd, aml5dnrd, 
     +                 fd3bdnrd
      CHARACTER*40 errinf
      INTEGER errstki(25), k, j
      LOGICAL dexs, iexs, eof
      CHARACTER*40 errmsgi(25)
      LOGICAL tst
      INTEGER i
      DOUBLE PRECISION abb
      DOUBLE PRECISION abbdnrd
      DOUBLE PRECISION arg1
      DOUBLE PRECISION arg1dnrd
      DOUBLE PRECISION result1
      DOUBLE PRECISION result1dnrd
      DOUBLE PRECISION x1dnrd
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION max1dnrd
      DOUBLE PRECISION x2dnrd
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION max1
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
C *** SETUP PARAMETERS ************************************************
C
C      WRITE(*,*) 'Within FUNCD3B_DNRD: ',p4,p4dnrd
      psi4dnrd = p4dnrd
      psi4 = p4
      DO ii1=1,nions
        molaldnrd(ii1) = 0.D0
      ENDDO
      DO ii1=1,npair
        molalrdnrd(ii1) = 0.D0
      ENDDO
      DO ii1=1,npair
        gamadnrd(ii1) = 0.D0
      ENDDO
      waterdnrd = 0.D0
      gnh3dnrd = 0.D0
      a4dnrd = 0.D0
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      DO i=1,3
C
        a2 = xk7*(water/gama(4))**3.0
        a3dnrd = xk4*r*temp*2.0*water*(waterdnrd*gama(10)-water*gamadnrd
     +    (10))/gama(10)**3
        a3 = xk4*r*temp*(water/gama(10))**2.0
        a4dnrd = xk2*r*temp*2.0*gama(10)*(gamadnrd(10)*gama(5)-gama(10)*
     +    gamadnrd(5))/(xkw*gama(5)**3)
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        a7dnrd = xkw*rh*(waterdnrd*water+water*waterdnrd)
        a7 = xkw*rh*water*water
C
        psi3dnrd = chi3*((a3dnrd*a4+a3*a4dnrd)*(chi4-psi4)-a3*a4*
     +    psi4dnrd) - psi1*psi4dnrd
        psi3 = a3*a4*chi3*(chi4-psi4) - psi1*(2.d0*psi2+psi1+psi4)
        psi3dnrd = (psi3dnrd*(a3*a4*(chi4-psi4)+2.d0*psi2+psi1+psi4)-
     +    psi3*((a3dnrd*a4+a3*a4dnrd)*(chi4-psi4)-a3*a4*psi4dnrd+
     +    psi4dnrd))/(a3*a4*(chi4-psi4)+2.d0*psi2+psi1+psi4)**2
        psi3 = psi3/(a3*a4*(chi4-psi4)+2.d0*psi2+psi1+psi4)
        IF (psi3 .LT. zero) THEN
          x1 = zero
          x1dnrd = 0.D0
        ELSE
          x1dnrd = psi3dnrd
          x1 = psi3
        END IF
        IF (x1 .GT. chi3) THEN
          psi3 = chi3
          psi3dnrd = 0.D0
        ELSE
          psi3dnrd = x1dnrd
          psi3 = x1
        END IF
C
        bbdnrd = psi4dnrd - psi3dnrd
        bb = psi4 - psi3
        arg1dnrd = bbdnrd*bb + bb*bbdnrd + 4.d0*a7dnrd
        arg1 = bb*bb + 4.d0*a7
        IF (abs(arg1) .LT. tiny) THEN
          result1dnrd = 0.D0
        ELSE
          result1dnrd = arg1dnrd/(2.0*SQRT(arg1))
        END IF
        result1 = SQRT(arg1)
        denmdnrd = bbdnrd + result1dnrd
        denm = bb + result1
        IF (denm .LE. tiny) THEN
          IF (bb .GE. 0.D0) THEN
            abbdnrd = bbdnrd
            abb = bb
          ELSE
            abbdnrd = -bbdnrd
            abb = -bb
          END IF
C Taylor expansion of SQRT
          denmdnrd = bbdnrd + abbdnrd + (2.0*a7dnrd*abb-2.0*a7*abbdnrd)/
     +      abb**2 - (2.0*(a7dnrd*a7+a7*a7dnrd)*abb**3.0-2.0*a7**2*3.0*
     +      abb**2.0*abbdnrd)/(abb**3.0)**2
          denm = bb + abb + 2.0*a7/abb - 2.0*a7*a7/abb**3.0
C            WRITE(*,*) 'TS approx. of DENM: ',DENM
        END IF
        ahidnrd = (2.D0*a7dnrd*denm-2.D0*a7*denmdnrd)/denm**2
        ahi = 2.D0*a7/denm
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molaldnrd(1) = ahidnrd
        molal(1) = ahi
C NH4I
        molaldnrd(3) = psi4dnrd
        molal(3) = psi1 + psi4 + 2.d0*psi2
C SO4I
        molaldnrd(5) = 0.D0
        molal(5) = psi2
C HSO4I
        molaldnrd(6) = 0.D0
        molal(6) = zero
C NO3I
        molaldnrd(7) = psi3dnrd
        molal(7) = psi3 + psi1
C Solid (NH4)2SO4
        cnh42s4 = chi2 - psi2
C Solid NH4NO3
        cnh4no3 = zero
C Gas HNO3
        ghno3 = chi3 - psi3
C Gas NH3
        gnh3dnrd = -psi4dnrd
        gnh3 = chi4 - psi4
C
C         CALL CALCMR                                ! Water content
C
C (NH4)2SO4
        molalrdnrd(4) = molaldnrd(5) + molaldnrd(6)
        molalr(4) = molal(5) + molal(6)
C "free" NH4
        aml5dnrd = molaldnrd(3) - 2.d0*molalrdnrd(4)
        aml5 = molal(3) - 2.d0*molalr(4)
        IF (aml5 .GT. molal(7)) THEN
          x2dnrd = molaldnrd(7)
          x2 = molal(7)
        ELSE
          x2dnrd = aml5dnrd
          x2 = aml5
        END IF
        IF (x2 .LT. zero) THEN
          molalrdnrd(5) = 0.D0
          molalr(5) = zero
        ELSE
          molalrdnrd(5) = x2dnrd
          molalr(5) = x2
        END IF
C
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        waterdnrd = 0.D0
        DO j=1,npair
          waterdnrd = waterdnrd + molalrdnrd(j)/m0(j)
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          waterdnrd = 0.D0
        ELSE
          water = water
        END IF
C
        CALL CALCACT3P_DNRD()
      ENDDO
      IF (gnh3 .LT. tiny) THEN
        max1 = tiny
        max1dnrd = 0.D0
      ELSE
        max1dnrd = gnh3dnrd
        max1 = gnh3
      END IF
C
C *** CALCULATE OBJECTIVE FUNCTION ************************************
C
CCC      FUNCD3= NH4I/HI/MAXCOMP(GNH3,TINY)/A4 - ONE 
      fd3bdnrd = (((molaldnrd(3)*molal(1)-molal(3)*molaldnrd(1))*max1/
     +  molal(1)**2-molal(3)*max1dnrd/molal(1))*a4/max1**2-molal(3)*
     +  a4dnrd/(molal(1)*max1))/a4**2
      fd3b = molal(3)/molal(1)/max1/a4 - one
C      WRITE(*,*) 'fd3b ',fd3b, 'fd3bdnrd ',fd3bdnrd 
      RETURN
      END
C
C  Differentiation of calcact3p in forward (tangent) mode:
C   variations   of useful results: gama
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3P_DNRD()
      IMPLICIT NONE
C
C      DOUBLE PRECISION molaldnrd(nions)
C      DOUBLE PRECISION gamadnrd(npair)
C      DOUBLE PRECISION waterdnrd
C      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicdnrd
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterdnrd
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0dnrd(6, 4), siondnrd, hdnrd, chdnrd, f1dnrd(3)
     +                 , f2dnrd(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mpldnrd, xijdnrd, yjidnrd
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01dnrd
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02dnrd
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03dnrd
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04dnrd
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05dnrd
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06dnrd
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07dnrd
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08dnrd
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09dnrd
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10dnrd
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11dnrd
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12dnrd
      INTEGER j
      DOUBLE PRECISION x1dnrd
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2dnrd
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      ionicdnrd = 0.D0
      DO i=1,7
        ionicdnrd = ionicdnrd + z(i)**2*molaldnrd(i)
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        x1dnrd = 0.D0
      ELSE
        x1dnrd = (0.5d0*ionicdnrd*water-0.5d0*ionic*waterdnrd)/water**2
        x1 = 0.5d0*ionic/water
      END IF
      IF (x1 .LT. tiny) THEN
        ionic = tiny
        ionicdnrd = 0.D0
      ELSE
        ionicdnrd = x1dnrd
        ionic = x1
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3_DNRD(ionic, ionicdnrd, temp, g01, g01dnrd, g02, 
     +                 g02dnrd, g03, g03dnrd, g04, g04dnrd, g05, g05dnrd
     +                 , g06, g06dnrd, g07, g07dnrd, g08, g08dnrd, g09, 
     +                 g09dnrd, g10, g10dnrd, g11, g11dnrd, g12, g12dnrd
     +                )
      DO ii1=1,4
        DO ii2=1,6
          g0dnrd(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
C
      g0dnrd(1, 1) = g11dnrd
      g0(1, 1) = g11
      g0dnrd(1, 2) = g07dnrd
      g0(1, 2) = g07
      g0dnrd(1, 3) = g08dnrd
      g0(1, 3) = g08
      g0dnrd(1, 4) = g10dnrd
      g0(1, 4) = g10
      g0dnrd(2, 1) = g01dnrd
      g0(2, 1) = g01
      g0dnrd(2, 2) = g02dnrd
      g0(2, 2) = g02
      g0dnrd(2, 3) = g12dnrd
      g0(2, 3) = g12
      g0dnrd(2, 4) = g03dnrd
      g0(2, 4) = g03
      g0dnrd(3, 1) = g06dnrd
      g0(3, 1) = g06
      g0dnrd(3, 2) = g04dnrd
      g0(3, 2) = g04
      g0dnrd(3, 3) = g09dnrd
      g0(3, 3) = g09
      g0dnrd(3, 4) = g05dnrd
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      IF (abs(ionic) .LT. tiny) THEN
        siondnrd = 0.D0
      ELSE
        siondnrd = ionicdnrd/(2.0*SQRT(ionic))
      END IF
      sion = SQRT(ionic)
      hdnrd = (agama*siondnrd*(1.d0+sion)-agama*sion*siondnrd)/(1.d0+
     +  sion)**2
      h = agama*sion/(1.d0+sion)
C
      DO i=1,3
        f1dnrd(i) = 0.D0
        f1(i) = 0.d0
        f2dnrd(i) = 0.D0
        f2(i) = 0.d0
      ENDDO
      f2dnrd(4) = 0.D0
      f2(4) = 0.d0
      DO ii1=1,3
        f1dnrd(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2dnrd(ii1) = 0.D0
      ENDDO
C
      DO i=1,3
        zpl = z(i)
        mpldnrd = (molaldnrd(i)*water-molal(i)*waterdnrd)/water**2
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          chdnrd = -(0.25d0*(zpl+zmi)**2*ionicdnrd/ionic**2)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xijdnrd = chdnrd*mpl + ch*mpldnrd
          xij = ch*mpl
          yjidnrd = ((chdnrd*molal(j+3)+ch*molaldnrd(j+3))*water-ch*
     +      molal(j+3)*waterdnrd)/water**2
          yji = ch*molal(j+3)/water
          f1dnrd(i) = f1dnrd(i) + yjidnrd*(g0(i, j)+zpl*zmi*h) + yji*(
     +      g0dnrd(i, j)+zpl*zmi*hdnrd)
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2dnrd(j) = f2dnrd(j) + xijdnrd*(g0(i, j)+zpl*zmi*h) + xij*(
     +      g0dnrd(i, j)+zpl*zmi*hdnrd)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gamadnrd(1) = zz(1)*((f1dnrd(2)/z(2)+f2dnrd(1)/z(4))/(z(2)+z(4))-
     +  hdnrd)
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gamadnrd(2) = zz(2)*((f1dnrd(2)/z(2)+f2dnrd(2)/z(5))/(z(2)+z(5))-
     +  hdnrd)
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gamadnrd(3) = zz(3)*((f1dnrd(2)/z(2)+f2dnrd(4)/z(7))/(z(2)+z(7))-
     +  hdnrd)
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gamadnrd(4) = zz(4)*((f1dnrd(3)/z(3)+f2dnrd(2)/z(5))/(z(3)+z(5))-
     +  hdnrd)
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gamadnrd(5) = zz(5)*((f1dnrd(3)/z(3)+f2dnrd(4)/z(7))/(z(3)+z(7))-
     +  hdnrd)
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gamadnrd(6) = zz(6)*((f1dnrd(3)/z(3)+f2dnrd(1)/z(4))/(z(3)+z(4))-
     +  hdnrd)
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gamadnrd(7) = zz(7)*((f1dnrd(1)/z(1)+f2dnrd(2)/z(5))/(z(1)+z(5))-
     +  hdnrd)
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gamadnrd(8) = zz(8)*((f1dnrd(1)/z(1)+f2dnrd(3)/z(6))/(z(1)+z(6))-
     +  hdnrd)
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gamadnrd(9) = zz(9)*((f1dnrd(3)/z(3)+f2dnrd(3)/z(6))/(z(3)+z(6))-
     +  hdnrd)
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gamadnrd(10) = zz(10)*((f1dnrd(1)/z(1)+f2dnrd(4)/z(7))/(z(1)+z(7))
     +  -hdnrd)
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gamadnrd(11) = zz(11)*((f1dnrd(1)/z(1)+f2dnrd(1)/z(4))/(z(1)+z(4))
     +  -hdnrd)
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gamadnrd(12) = zz(12)*((f1dnrd(2)/z(2)+f2dnrd(3)/z(6))/(z(2)+z(6))
     +  -hdnrd)
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
C LC ; SCAPE
      gamadnrd(13) = 0.2d0*(3.d0*gamadnrd(4)+2.d0*gamadnrd(9))
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          x2 = 5.0d0
          x2dnrd = 0.D0
        ELSE
          x2dnrd = gamadnrd(i)
          x2 = gama(i)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          gamadnrd(i) = 0.D0
          gama(i) = -5.0d0
        ELSE
          gamadnrd(i) = x2dnrd
          gama(i) = x2
        END IF
        gamadnrd(i) = 10.d0**gama(i)*LOG(10.d0)*gamadnrd(i)
        gama(i) = 10.d0**gama(i)
      ENDDO
C
C Increment ACTIVITY call counter
      iclact = iclact + 1
C
C *** END OF SUBROUTINE ACTIVITY ****************************************
C
      RETURN
      END

C  Differentiation of kmful3 in forward (tangent) mode:
C   variations   of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_DNRD(ionic, ionicdnrd, temp, g01, g01dnrd, g02, 
     +                       g02dnrd, g03, g03dnrd, g04, g04dnrd, g05, 
     +                       g05dnrd, g06, g06dnrd, g07, g07dnrd, g08, 
     +                       g08dnrd, g09, g09dnrd, g10, g10dnrd, g11, 
     +                       g11dnrd, g12, g12dnrd)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicdnrd, siondnrd, cf2dnrd
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01dnrd, g02dnrd, g03dnrd, g04dnrd, g05dnrd, 
     +                 g06dnrd, g07dnrd, g08dnrd, g09dnrd, g10dnrd, 
     +                 g11dnrd, g12dnrd
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTRINSIC ABS
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
      DOUBLE PRECISION tiny
      tiny = 1.d-20
C
      IF (abs(ionic) .LT. tiny) THEN
        siondnrd = 0.D0
      ELSE
        siondnrd = ionicdnrd/(2.0*SQRT(ionic))
      END IF
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
      CALL MKBI_DNRD(q1, ionic, ionicdnrd, sion, siondnrd, z01, g01, 
     +               g01dnrd)
      CALL MKBI_DNRD(q2, ionic, ionicdnrd, sion, siondnrd, z02, g02, 
     +               g02dnrd)
      CALL MKBI_DNRD(q3, ionic, ionicdnrd, sion, siondnrd, z03, g03, 
     +               g03dnrd)
      CALL MKBI_DNRD(q4, ionic, ionicdnrd, sion, siondnrd, z04, g04, 
     +               g04dnrd)
      CALL MKBI_DNRD(q5, ionic, ionicdnrd, sion, siondnrd, z05, g05, 
     +               g05dnrd)
      CALL MKBI_DNRD(q6, ionic, ionicdnrd, sion, siondnrd, z06, g06, 
     +               g06dnrd)
      CALL MKBI_DNRD(q7, ionic, ionicdnrd, sion, siondnrd, z07, g07, 
     +               g07dnrd)
      CALL MKBI_DNRD(q8, ionic, ionicdnrd, sion, siondnrd, z08, g08, 
     +               g08dnrd)
      CALL MKBI_DNRD(q10, ionic, ionicdnrd, sion, siondnrd, z10, g10, 
     +               g10dnrd)
      CALL MKBI_DNRD(q11, ionic, ionicdnrd, sion, siondnrd, z11, g11, 
     +               g11dnrd)
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.D0) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        cf2dnrd = (0.125d0-0.005d0*ti)*(0.039d0*0.92d0*ionic**(-0.8D0)*
     +    ionicdnrd-(0.41d0*siondnrd*(1.d0+sion)-0.41d0*sion*siondnrd)/(
     +    1.d0+sion)**2)
        cf2 = (0.125d0-0.005d0*ti)*(0.039d0*ionic**0.92d0-0.41d0*sion/(
     +    1.d0+sion))
        g01dnrd = cf1*g01dnrd - z01*cf2dnrd
        g01 = cf1*g01 - cf2*z01
        g02dnrd = cf1*g02dnrd - z02*cf2dnrd
        g02 = cf1*g02 - cf2*z02
        g03dnrd = cf1*g03dnrd - z03*cf2dnrd
        g03 = cf1*g03 - cf2*z03
        g04dnrd = cf1*g04dnrd - z04*cf2dnrd
        g04 = cf1*g04 - cf2*z04
        g05dnrd = cf1*g05dnrd - z05*cf2dnrd
        g05 = cf1*g05 - cf2*z05
        g06dnrd = cf1*g06dnrd - z06*cf2dnrd
        g06 = cf1*g06 - cf2*z06
        g07dnrd = cf1*g07dnrd - z07*cf2dnrd
        g07 = cf1*g07 - cf2*z07
        g08dnrd = cf1*g08dnrd - z08*cf2dnrd
        g08 = cf1*g08 - cf2*z08
        g10dnrd = cf1*g10dnrd - z10*cf2dnrd
        g10 = cf1*g10 - cf2*z10
        g11dnrd = cf1*g11dnrd - z11*cf2dnrd
        g11 = cf1*g11 - cf2*z11
      END IF
C
      g09dnrd = g06dnrd + g08dnrd - g11dnrd
      g09 = g06 + g08 - g11
      g12dnrd = g01dnrd + g08dnrd - g11dnrd
      g12 = g01 + g08 - g11
C
C *** Return point ; End of subroutine
C
      RETURN
      END

C  Differentiation of mkbi in forward (tangent) mode:
C   variations   of useful results: bi
C   with respect to varying inputs: sion ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_DNRD(q, ionic, ionicdnrd, sion, siondnrd, zip, bi
     +                     , bidnrd)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicdnrd, siondnrd, bidnrd
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cdnrd, xxdnrd
      DOUBLE PRECISION arg1
      DOUBLE PRECISION arg1dnrd
      DOUBLE PRECISION pwx1
      DOUBLE PRECISION pwx1dnrd
      DOUBLE PRECISION pwr1
      DOUBLE PRECISION pwr1dnrd
      INTRINSIC EXP
      INTRINSIC LOG10
      DOUBLE PRECISION tiny
      tiny = 1.d-20
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      arg1dnrd = -(.023d0*((ionicdnrd*ionic+ionic*ionicdnrd)*ionic+ionic
     +  **2*ionicdnrd))
      arg1 = -(.023d0*ionic*ionic*ionic)
      cdnrd = .055d0*q*arg1dnrd*EXP(arg1)
      c = 1. + .055d0*q*EXP(arg1)
      xxdnrd = -((0.5107d0*siondnrd*(1.d0+c*sion)-0.5107d0*sion*(cdnrd*
     +  sion+c*siondnrd))/(1.d0+c*sion)**2)
      xx = -(0.5107d0*sion/(1.d0+c*sion))
      pwx1dnrd = .1d0*ionicdnrd
      pwx1 = 1.d0 + .1d0*ionic
      IF (pwx1 .GT. 0.d0 .OR. (pwx1 .LT. 0.d0 .AND. 
     &       abs(q-INT(q)) .LT. tiny)) THEN
        pwr1dnrd = q*pwx1**(q-1)*pwx1dnrd
      ELSE IF (abs(pwx1) .LT. tiny .AND. abs(q-1.D0) .LT. tiny) THEN
        pwr1dnrd = pwx1dnrd
      ELSE
        pwr1dnrd = 0.0
      END IF
      pwr1 = pwx1**q
      bidnrd = b*pwr1dnrd
      bi = 1.d0 + b*pwr1 - b
      bidnrd = zip*bidnrd/(bi*LOG(10.D0)) + zip*xxdnrd
      bi = zip*LOG10(bi) + zip*xx
C
      RETURN
      END


