      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION x, y, so4i, hso4i, bb, cc, dd
      DOUBLE PRECISION so4ieb, hso4ieb, bbeb, cceb, ddeb
      DOUBLE PRECISION wp(ncomp), gas(3), aerliq(7)
      DOUBLE PRECISION wpeb(ncomp), gaseb(3), aerliqeb(7)
      INTEGER i
      DOUBLE PRECISION ak1
      DOUBLE PRECISION ak1eb
      DOUBLE PRECISION bet
      DOUBLE PRECISION beteb
      DOUBLE PRECISION gam
      DOUBLE PRECISION gameb
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION x2eb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0eb
      INTRINSIC MAX
      DOUBLE PRECISION x4
      DOUBLE PRECISION x3
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x3eb
      DOUBLE PRECISION temp1eb
      DOUBLE PRECISION x1eb
      DOUBLE PRECISION x4eb
      INTRINSIC MIN
      INTEGER ii1, npflag, ncase
      INTRINSIC SQRT
      DOUBLE PRECISION temp2eb
      COMMON /gas_eb/ ghno3eb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      COMMON /inpt_eb/ web
C
C *** SOLVE EQUATIONS **************************************************
C
C      w = wp
C
      frst = .true.
      calain = .true.
C
C *** CALCULATE WATER CONTENT ******************************************
C
C
C      CALL CALCB1A         ! GET DRY SALT CONTENT, AND USE FOR WATER.
C
C *** SETUP PARAMETERS ************************************************
C
C Equivalent NH4HSO4
      x = 2.d0*w(2) - w(3)
C Equivalent (NH4)2SO4
      y = w(3) - w(2)
C
C *** CALCULATE COMPOSITION *******************************************
C
      IF (x .LE. y) THEN
C LC is the MIN(x,y)
C         CLC     = X        ! NH4HSO4 >= (NH4)2S04
        clc = 2.d0*w(2) - w(3)
        cnh4hs4 = zero
C         CNH42S4 = Y-X
        cnh42s4 = 2.d0*w(3) - 3.d0*w(2)
        CALL PUSHCONTROL1B(0)
      ELSE
C         CLC     = Y        ! NH4HSO4 <  (NH4)2S04
        clc = w(3) - w(2)
C         CNH4HS4 = X-Y
        cnh4hs4 = 3.d0*w(2) - 2.d0*w(3)
        cnh42s4 = zero
        CALL PUSHCONTROL1B(1)
      END IF
C
      molalr(13) = clc
      molalr(9) = cnh4hs4
      molalr(4) = cnh42s4
      water = molalr(13)/m0(13) + molalr(9)/m0(9) + molalr(4)/m0(4)
C
C NH4I
      molal(3) = w(3)
C
      i = 1
      ad_count = 0
C      NSWEEP = 50
      DO WHILE (i .LE. nsweep .AND. calain)
        CALL PUSHREAL8(ak1)
C         IF (I.GT.1) CALL CALCACT3
        ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
        bet = w(2)
        gam = molal(3)
        CALL PUSHREAL8(bb)
C
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        x4 = 0.5d0*(-bb+SQRT(dd))
        IF (x4 .GT. w(2)) THEN
          x1 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = x4
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHREAL8(molal(5))
          molal(5) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(5))
          molal(5) = x1
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(2) - molal(5) .GT. w(2)) THEN
          x2 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = w(2) - molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = x2
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ak1*molal(6)/molal(5) .GT. w(2)) THEN
          x3 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x3 = ak1*molal(6)/molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x3 .LT. tiny) THEN
          CALL PUSHREAL8(molal(1))
          molal(1) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(1))
          molal(1) = x3
          CALL PUSHCONTROL1B(1)
        END IF
C         WRITE(*,*) 'MOLAL(5, 6) ', MOLAL(5), MOLAL(6)
C
C         CALL CALCMR                                           ! Water content
C      slc.1.2011 - calling CALCMR for case E rather than B
C
C CORRECT FOR HSO4 DISSOCIATION  as from B4
        so4i = molal(5) - molal(1)
C         SO4I  = MAX(MOLAL(5)-MOLAL(1),ZERO)      ! FROM HSO4 DISSOCIATION 
        hso4i = molal(6) + molal(1)
        IF (so4i .LT. hso4i) THEN
C [LC] = [SO4] 
          molalr(13) = so4i
          IF (hso4i - so4i .LT. zero) THEN
            molalr(9) = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            molalr(9) = hso4i - so4i
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
C [LC] = [HSO4]
          molalr(13) = hso4i
          IF (so4i - hso4i .LT. zero) THEN
            molalr(4) = zero
            CALL PUSHCONTROL2B(3)
          ELSE
            molalr(4) = so4i - hso4i
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C         IF (.NOT.CALAIN) GOTO 30
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
C*** slc.11.2009 moved to beginning of loop
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCB4E')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      DO ii1=1,nions
        molaleb(ii1) = 0.D0
      ENDDO
      DO i=nions,1,-1
        molaleb(i) = molaleb(i) + aerliqeb(i)
        aerliqeb(i) = 0.D0
      ENDDO
      gaseb(3) = 0.D0
      ghno3eb = gaseb(2)
      gaseb(2) = 0.D0
      gaseb(1) = 0.D0
      CALL CALCNA_EB()
      DO ii1=1,npair
        molalreb(ii1) = 0.D0
      ENDDO
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_EB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) watereb = 0.D0
        DO j=npair,1,-1
          molalreb(j) = molalreb(j) + watereb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            hso4ieb = molalreb(9)
            so4ieb = -molalreb(9)
            molalreb(9) = 0.D0
          ELSE
            molalreb(9) = 0.D0
            hso4ieb = 0.D0
            so4ieb = 0.D0
          END IF
          so4ieb = so4ieb + molalreb(13)
          molalreb(13) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            so4ieb = molalreb(4)
            hso4ieb = -molalreb(4)
            molalreb(4) = 0.D0
          ELSE
            molalreb(4) = 0.D0
            hso4ieb = 0.D0
            so4ieb = 0.D0
          END IF
          hso4ieb = hso4ieb + molalreb(13)
          molalreb(13) = 0.D0
        END IF
        molaleb(6) = molaleb(6) + hso4ieb
        molaleb(1) = molaleb(1) + hso4ieb
        molaleb(5) = molaleb(5) + so4ieb
        molaleb(1) = molaleb(1) - so4ieb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(1))
          molaleb(1) = 0.D0
          x3eb = 0.D0
        ELSE
          CALL POPREAL8(molal(1))
          x3eb = molaleb(1)
          molaleb(1) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          web(2) = web(2) + x3eb
          ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
          ak1eb = 0.D0
        ELSE
          temp2eb = x3eb/molal(5)
          ak1eb = molal(6)*temp2eb
          molaleb(6) = molaleb(6) + ak1*temp2eb
          molaleb(5) = molaleb(5) - ak1*molal(6)*temp2eb/molal(5)
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molaleb(6) = 0.D0
          x2eb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          x2eb = molaleb(6)
          molaleb(6) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          web(2) = web(2) + x2eb
        ELSE
          web(2) = web(2) + x2eb
          molaleb(5) = molaleb(5) - x2eb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          molaleb(5) = 0.D0
          x1eb = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          x1eb = molaleb(5)
          molaleb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          web(2) = web(2) + x1eb
          x4eb = 0.D0
        ELSE
          x4eb = x1eb
        END IF
        bet = w(2)
        gam = molal(3)
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddeb = 0.0
        ELSE
          ddeb = 0.5d0*x4eb/(2.0*SQRT(dd))
        END IF
        bbeb = 2*bb*ddeb - 0.5d0*x4eb
        cceb = -(4.d0*ddeb)
        ak1eb = ak1eb + bbeb - bet*cceb
        beteb = bbeb - ak1*cceb
        CALL POPREAL8(bb)
        gameb = -bbeb
        molaleb(3) = molaleb(3) + gameb
        web(2) = web(2) + beteb
        CALL POPREAL8(ak1)
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1eb = 2.*temp1*temp0*xk1*ak1eb/gama(7)
        temp0eb = temp1**2.*xk1*ak1eb/gama(7)
        gamaeb(8) = gamaeb(8) + temp1eb
        gamaeb(7) = gamaeb(7) - temp0*temp0eb - temp1*temp1eb
        watereb = temp0eb
      ENDDO
      web(3) = web(3) + molaleb(3)
      molalreb(13) = molalreb(13) + watereb/m0(13)
      molalreb(9) = molalreb(9) + watereb/m0(9)
      molalreb(4) = molalreb(4) + watereb/m0(4)
      cnh42s4eb = molalreb(4)
      molalreb(4) = 0.D0
      cnh4hs4eb = molalreb(9)
      molalreb(9) = 0.D0
      clceb = molalreb(13)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        web(3) = web(3) + 2*cnh42s4eb
        web(2) = web(2) + 2*clceb - 3*cnh42s4eb
        web(3) = web(3) - clceb
      ELSE
        web(2) = web(2) + 3*cnh4hs4eb
        web(3) = web(3) + clceb - 2*cnh4hs4eb
        web(2) = web(2) - clceb
      END IF
C      DO ii1=1,ncomp
C        wpeb(ii1) = 0.D0
C      ENDDO
      wpeb = web

C      ncase = 5
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) w,rh,temp,wpeb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
      END

C  Differentiation of calcna in reverse (adjoint) mode:
C   gradient     of useful results: molal ghno3
C   with respect to varying inputs: w molal gama water
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNA
C *** CALCULATES NITRATES SPECIATION
C
C     NITRIC ACID IN THE LIQUID PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE HSO4-SO4 EQUILIBRIUM. THE NITRIC
C     ACID DISSOLVED IS CALCULATED FROM THE HNO3(G) -> (H+) + (NO3-) 
C     EQUILIBRIUM, USING THE (H+) FROM THE SULFATES.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNA_EB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNA ******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watereb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION ghno3eb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION alfa, delt, kapa, diak
      DOUBLE PRECISION alfaeb, delteb, kapaeb, diakeb
      DOUBLE PRECISION x
      DOUBLE PRECISION xeb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0eb
      INTRINSIC MAX
      DOUBLE PRECISION temp1eb
      DOUBLE PRECISION temp1eb1
      DOUBLE PRECISION temp1eb0
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_eb/ ghno3eb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      COMMON /inpt_eb/ web
CC      CHARACTER*40 errinf
C
C *** CALCULATE HNO3 DISSOLUTION ****************************************
C
      x = w(4)
      delt = 0.0d0
      IF (water .GT. tiny) THEN
        kapa = molal(1)
        alfa = xk4*r*temp*(water/gama(10))**2.0
        diak = SQRT((kapa+alfa)**2.0 + 4.0*alfa*x)
        delt = 0.5*(-(kapa+alfa)+diak)
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      IF (x - delt .LT. 0.0d0) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      delteb = molaleb(7) + molaleb(1)
      molaleb(7) = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        xeb = 0.D0
      ELSE
        xeb = ghno3eb
        delteb = delteb - ghno3eb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        DO ii1=1,npair
          gamaeb(ii1) = 0.D0
        ENDDO
        watereb = 0.D0
      ELSE
        temp1eb = 0.5*delteb
        diakeb = temp1eb
        IF ((kapa+alfa)**2.0 + 4.0*(alfa*x) .EQ. 0.0) THEN
          temp1eb1 = 0.0
        ELSE
          temp1eb1 = diakeb/(2.0*SQRT((kapa+alfa)**2.0+4.0*(alfa*x)))
        END IF
        temp1eb0 = 2.0*(kapa+alfa)*temp1eb1
        alfaeb = temp1eb0 + 4.0*x*temp1eb1 - temp1eb
        kapaeb = temp1eb0 - temp1eb
        xeb = xeb + 4.0*alfa*temp1eb1
        DO ii1=1,npair
          gamaeb(ii1) = 0.D0
        ENDDO
        temp0 = water/gama(10)
        temp0eb = 2.0*temp0*xk4*r*temp*alfaeb/gama(10)
        watereb = temp0eb
        gamaeb(10) = gamaeb(10) - temp0*temp0eb
        molaleb(1) = molaleb(1) + kapaeb
      END IF
      DO ii1=1,ncomp
        web(ii1) = 0.D0
      ENDDO
      web(4) = web(4) + xeb
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_EB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ioniceb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watereb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION ghno3eb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0eb(6, 4), sioneb, heb, cheb, f1eb(3), f2eb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mpleb, xijeb, yjieb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01eb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02eb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03eb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04eb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05eb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06eb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07eb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08eb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09eb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10eb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11eb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12eb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION x2eb
      DOUBLE PRECISION temp0eb
      INTRINSIC MAX
      DOUBLE PRECISION temp0eb13
      DOUBLE PRECISION temp0eb12
      DOUBLE PRECISION temp0eb11
      DOUBLE PRECISION temp0eb10
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0eb9
      DOUBLE PRECISION temp0eb8
      DOUBLE PRECISION temp0eb7
      DOUBLE PRECISION temp0eb6
      DOUBLE PRECISION temp0eb5
      DOUBLE PRECISION temp0eb4
      DOUBLE PRECISION temp0eb3
      DOUBLE PRECISION temp0eb2
      DOUBLE PRECISION temp0eb1
      DOUBLE PRECISION temp0eb0
      DOUBLE PRECISION x1eb
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION y1
      COMMON /gas_eb/ ghno3eb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      COMMON /inpt_eb/ web
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamaeb(i) = 10.d0**gama(i)*LOG(10.d0)*gamaeb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamaeb(i) = 0.D0
          x2eb = 0.D0
        ELSE
          x2eb = gamaeb(i)
          gamaeb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamaeb(i) = gamaeb(i) + x2eb
      ENDDO
      CALL POPREAL8(gama(13))
      gamaeb(4) = gamaeb(4) + 0.2d0*3.d0*gamaeb(13)
      gamaeb(9) = gamaeb(9) + 0.2d0*2.d0*gamaeb(13)
      gamaeb(13) = 0.D0
      DO ii1=1,3
        f1eb(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2eb(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0eb2 = zz(12)*gamaeb(12)/(z(2)+z(6))
      f1eb(2) = f1eb(2) + temp0eb2/z(2)
      f2eb(3) = f2eb(3) + temp0eb2/z(6)
      heb = -(zz(12)*gamaeb(12))
      gamaeb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0eb3 = zz(11)*gamaeb(11)/(z(1)+z(4))
      f2eb(1) = f2eb(1) + temp0eb3/z(4)
      heb = heb - zz(11)*gamaeb(11)
      gamaeb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0eb4 = zz(10)*gamaeb(10)/(z(1)+z(7))
      f1eb(1) = f1eb(1) + temp0eb4/z(1) + temp0eb3/z(1)
      f2eb(4) = f2eb(4) + temp0eb4/z(7)
      heb = heb - zz(10)*gamaeb(10)
      gamaeb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0eb5 = zz(9)*gamaeb(9)/(z(3)+z(6))
      f1eb(3) = f1eb(3) + temp0eb5/z(3)
      heb = heb - zz(9)*gamaeb(9)
      gamaeb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0eb6 = zz(8)*gamaeb(8)/(z(1)+z(6))
      f2eb(3) = f2eb(3) + temp0eb6/z(6) + temp0eb5/z(6)
      heb = heb - zz(8)*gamaeb(8)
      gamaeb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0eb7 = zz(7)*gamaeb(7)/(z(1)+z(5))
      f1eb(1) = f1eb(1) + temp0eb7/z(1) + temp0eb6/z(1)
      f2eb(2) = f2eb(2) + temp0eb7/z(5)
      heb = heb - zz(7)*gamaeb(7)
      gamaeb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0eb8 = zz(6)*gamaeb(6)/(z(3)+z(4))
      f2eb(1) = f2eb(1) + temp0eb8/z(4)
      heb = heb - zz(6)*gamaeb(6)
      gamaeb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0eb9 = zz(5)*gamaeb(5)/(z(3)+z(7))
      f2eb(4) = f2eb(4) + temp0eb9/z(7)
      heb = heb - zz(5)*gamaeb(5)
      gamaeb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0eb10 = zz(4)*gamaeb(4)/(z(3)+z(5))
      f1eb(3) = f1eb(3) + temp0eb9/z(3) + temp0eb10/z(3) + temp0eb8/z(3)
      f2eb(2) = f2eb(2) + temp0eb10/z(5)
      heb = heb - zz(4)*gamaeb(4)
      gamaeb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0eb11 = zz(3)*gamaeb(3)/(z(2)+z(7))
      f2eb(4) = f2eb(4) + temp0eb11/z(7)
      heb = heb - zz(3)*gamaeb(3)
      gamaeb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0eb12 = zz(2)*gamaeb(2)/(z(2)+z(5))
      f2eb(2) = f2eb(2) + temp0eb12/z(5)
      heb = heb - zz(2)*gamaeb(2)
      gamaeb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0eb13 = zz(1)*gamaeb(1)/(z(2)+z(4))
      f1eb(2) = f1eb(2) + temp0eb12/z(2) + temp0eb13/z(2) + temp0eb11/z(
     +  2)
      f2eb(1) = f2eb(1) + temp0eb13/z(4)
      heb = heb - zz(1)*gamaeb(1)
      gamaeb(1) = 0.D0
      ioniceb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0eb(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mpleb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijeb = (g0(i, j)+zpl*zmi*h)*f2eb(j)
          yji = ch*molal(j+3)/water
          g0eb(i, j) = g0eb(i, j) + yji*f1eb(i) + xij*f2eb(j)
          heb = heb + yji*zpl*zmi*f1eb(i) + xij*zpl*zmi*f2eb(j)
          yjieb = (g0(i, j)+zpl*zmi*h)*f1eb(i)
          temp0eb1 = molal(j+3)*yjieb/water
          molaleb(j+3) = molaleb(j+3) + ch*yjieb/water
          cheb = mpl*xijeb + temp0eb1
          watereb = watereb - ch*temp0eb1/water
          mpleb = mpleb + ch*xijeb
          ioniceb = ioniceb - (zpl+zmi)**2*0.25d0*cheb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molaleb(i) = molaleb(i) + mpleb/water
        watereb = watereb - molal(i)*mpleb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0eb0 = agama*heb/(sion+1.d0)
      sioneb = (1.D0-sion/(sion+1.d0))*temp0eb0
      IF (.NOT.ionic .EQ. 0.0) ioniceb = ioniceb + sioneb/(2.0*SQRT(
     +    ionic))
      g05eb = g0eb(3, 4)
      g0eb(3, 4) = 0.D0
      g09eb = g0eb(3, 3)
      g0eb(3, 3) = 0.D0
      g04eb = g0eb(3, 2)
      g0eb(3, 2) = 0.D0
      g06eb = g0eb(3, 1)
      g0eb(3, 1) = 0.D0
      g03eb = g0eb(2, 4)
      g0eb(2, 4) = 0.D0
      g12eb = g0eb(2, 3)
      g0eb(2, 3) = 0.D0
      g02eb = g0eb(2, 2)
      g0eb(2, 2) = 0.D0
      g01eb = g0eb(2, 1)
      g0eb(2, 1) = 0.D0
      g10eb = g0eb(1, 4)
      g0eb(1, 4) = 0.D0
      g08eb = g0eb(1, 3)
      g0eb(1, 3) = 0.D0
      g07eb = g0eb(1, 2)
      g0eb(1, 2) = 0.D0
      g11eb = g0eb(1, 1)
      CALL KMFUL3_EB(ionic, ioniceb, temp, g01, g01eb, g02, g02eb, g03, 
     +               g03eb, g04, g04eb, g05, g05eb, g06, g06eb, g07, 
     +               g07eb, g08, g08eb, g09, g09eb, g10, g10eb, g11, 
     +               g11eb, g12, g12eb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1eb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1eb = ioniceb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ioniceb = 0.D0
      ELSE
        temp0eb = 0.5d0*x1eb/water
        ioniceb = temp0eb
        watereb = watereb - ionic*temp0eb/water
      END IF
      DO i=7,1,-1
        molaleb(i) = molaleb(i) + z(i)**2*ioniceb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_EB(ionic, ioniceb, temp, g01, g01eb, g02, g02eb
     +                     , g03, g03eb, g04, g04eb, g05, g05eb, g06, 
     +                     g06eb, g07, g07eb, g08, g08eb, g09, g09eb, 
     +                     g10, g10eb, g11, g11eb, g12, g12eb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ioniceb, sioneb, cf2eb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01eb, g02eb, g03eb, g04eb, g05eb, g06eb, g07eb, 
     +                 g08eb, g09eb, g10eb, g11eb, g12eb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0eb
      INTRINSIC ABS
      DOUBLE PRECISION temp0eb0
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01eb = g01eb + g12eb
      g08eb = g08eb + g09eb + g12eb
      g11eb = g11eb - g09eb - g12eb
      g06eb = g06eb + g09eb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2eb = -(z10*g10eb) - z07*g07eb - z05*g05eb - z03*g03eb - z01*
     +    g01eb - z02*g02eb - z04*g04eb - z06*g06eb - z08*g08eb - z11*
     +    g11eb
        g11eb = cf1*g11eb
        g10eb = cf1*g10eb
        g08eb = cf1*g08eb
        g07eb = cf1*g07eb
        g06eb = cf1*g06eb
        g05eb = cf1*g05eb
        g04eb = cf1*g04eb
        g03eb = cf1*g03eb
        g02eb = cf1*g02eb
        g01eb = cf1*g01eb
        temp0eb = (0.125d0-ti*0.005d0)*cf2eb
        temp0eb0 = -(0.41d0*temp0eb/(sion+1.d0))
        ioniceb = ioniceb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0eb
        sioneb = (1.D0-sion/(sion+1.d0))*temp0eb0
      ELSE
        sioneb = 0.D0
      END IF
      CALL MKBI_EB(q11, ionic, ioniceb, sion, sioneb, z11, g11, g11eb)
      CALL MKBI_EB(q10, ionic, ioniceb, sion, sioneb, z10, g10, g10eb)
      CALL MKBI_EB(q8, ionic, ioniceb, sion, sioneb, z08, g08, g08eb)
      CALL MKBI_EB(q7, ionic, ioniceb, sion, sioneb, z07, g07, g07eb)
      CALL MKBI_EB(q6, ionic, ioniceb, sion, sioneb, z06, g06, g06eb)
      CALL MKBI_EB(q5, ionic, ioniceb, sion, sioneb, z05, g05, g05eb)
      CALL MKBI_EB(q4, ionic, ioniceb, sion, sioneb, z04, g04, g04eb)
      CALL MKBI_EB(q3, ionic, ioniceb, sion, sioneb, z03, g03, g03eb)
      CALL MKBI_EB(q2, ionic, ioniceb, sion, sioneb, z02, g02, g02eb)
      CALL MKBI_EB(q1, ionic, ioniceb, sion, sioneb, z01, g01, g01eb)
      IF (.NOT.ionic .EQ. 0.0) ioniceb = ioniceb + sioneb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_EB(q, ionic, ioniceb, sion, sioneb, zip, bi, bieb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ioniceb, sioneb, bieb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION ceb, xxeb
      INTRINSIC EXP
      DOUBLE PRECISION tempeb0
      DOUBLE PRECISION tempeb
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxeb = zip*bieb
      bieb = zip*bieb/(bi*LOG(10.0))
      tempeb = -(0.5107d0*xxeb/(c*sion+1.d0))
      tempeb0 = -(sion*tempeb/(c*sion+1.d0))
      sioneb = sioneb + c*tempeb0 + tempeb
      ceb = sion*tempeb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ioniceb = ioniceb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*ceb
      ELSE
        ioniceb = ioniceb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bieb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*ceb
      END IF
      END


