      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION x, y, so4i, hso4i, bb, cc, dd
      DOUBLE PRECISION so4ierb, hso4ierb, bberb, ccerb, dderb
      DOUBLE PRECISION gas(3), aerliq(nions+ngasaq+2)
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3), waerp(ncomp)
      DOUBLE PRECISION aerliqperb(nions+ngasaq+2), gasperb(3), waerperb(
     +                 ncomp)
      DOUBLE PRECISION wi(ncomp)
      INTEGER i
      DOUBLE PRECISION ak1
      DOUBLE PRECISION ak1erb
      DOUBLE PRECISION bet
      DOUBLE PRECISION beterb
      DOUBLE PRECISION gam
      DOUBLE PRECISION gamerb
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0erb
      DOUBLE PRECISION temp1erb
      INTRINSIC MAX
      DOUBLE PRECISION x4
      DOUBLE PRECISION x1erb
      DOUBLE PRECISION x3
      DOUBLE PRECISION temp2erb
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2erb
      DOUBLE PRECISION x3erb
      DOUBLE PRECISION x4erb
      INTRINSIC MIN
      INTRINSIC SQRT
      COMMON /gas_erb/ gnh3erb, ghno3erb
      COMMON /ions_erb/ molalerb, gamaerb, gasaqerb, watererb
      INTEGER npflag, ncase
C
C *** SOLVE EQUATIONS **************************************************
C
C      waer = waerp
C
      w(2) = waer(2)
      w(3) = waer(3)
      w(4) = waer(4)
C
      frst = .true.
      calain = .true.
C
C *** CALCULATE WATER CONTENT ******************************************
C
C      CALL CALCB1A         ! GET DRY SALT CONTENT, AND USE FOR WATER.
C
C *** SETUP PARAMETERS ************************************************
C
C Equivalent NH4HSO4
      x = 2.d0*w(2) - w(3)
C Equivalent (NH4)2SO4
      y = w(3) - w(2)
C
C *** CALCULATE COMPOSITION *******************************************
C
      IF (x .LE. y) THEN
C LC is the MIN(x,y)
CX        ! NH4HSO4 >= (NH4)2S04
        clc = 2.d0*w(2) - w(3)
        cnh4hs4 = zero
CY-X
        cnh42s4 = 2.d0*w(3) - 3.d0*w(2)
        CALL PUSHCONTROL1B(0)
      ELSE
CY        ! NH4HSO4 <  (NH4)2S04
        clc = w(3) - w(2)
CX-Y
        cnh4hs4 = 3.d0*w(2) - 2.d0*w(3)
        cnh42s4 = zero
        CALL PUSHCONTROL1B(1)
      END IF
C
      molalr(13) = clc
      molalr(9) = cnh4hs4
      molalr(4) = cnh42s4
      water = molalr(13)/m0(13) + molalr(9)/m0(9) + molalr(4)/m0(4)
C
C NH4I
      molal(3) = w(3)
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. calain)
        CALL PUSHREAL8(ak1)
C        
        ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
        bet = w(2)
        gam = molal(3)
        CALL PUSHREAL8(bb)
C
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        x4 = 0.5*(-bb+SQRT(dd))
        IF (x4 .GT. w(2)) THEN
          x1 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = x4
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHREAL8(molal(5))
          molal(5) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(5))
          molal(5) = x1
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(2) - molal(5) .GT. w(2)) THEN
          x2 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = w(2) - molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = x2
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ak1*molal(6)/molal(5) .GT. w(2)) THEN
          x3 = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          x3 = ak1*molal(6)/molal(5)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x3 .LT. tiny) THEN
          CALL PUSHREAL8(molal(1))
          molal(1) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(1))
          molal(1) = x3
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR        ! Water content   - now calculated here
C
C CORRECT FOR HSO4 DISSOCIATION  as from B4
        so4i = molal(5) - molal(1)
C         SO4I  = MAX(MOLAL(5)-MOLAL(1),ZERO)      ! FROM HSO4 DISSOCIATION 
        hso4i = molal(6) + molal(1)
        IF (so4i .LT. hso4i) THEN
C [LC] = [SO4] 
          molalr(13) = so4i
          IF (hso4i - so4i .LT. zero) THEN
            molalr(9) = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            molalr(9) = hso4i - so4i
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
C [LC] = [HSO4]
          molalr(13) = hso4i
          IF (so4i - hso4i .LT. zero) THEN
            molalr(4) = zero
            CALL PUSHCONTROL2B(3)
          ELSE
            molalr(4) = so4i - hso4i
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCE4R')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      CALL PUSHREAL8(molal(7))
C
C There is always water, so NO3(aer) is NO3-
      molal(7) = waer(4)
      CALL PUSHREAL8(molal(1))
C Add H+ to balance out
      molal(1) = molal(1) + waer(4)
      CALL PUSHREAL8ARRAY(molal, nions)
C HNO3, NH3 dissolved
      CALL CALCNAP()
C
C *** CALCULATE TOTAL AMOUNT OF SPECIES WITH GAS PHASE ****************
C
C      WTP(1) = WAER(1)                ! Total gas+aerosol phase
C      WTP(2) = WAER(2)
C      WTP(3) = WAER(3) + GNH3 
C      WTP(4) = WAER(4) + GHNO3
C      WTP(5) = WAER(5) + GHCL
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C Gaseous aerosol species
      aerliqperb(nions+ngasaq+2) = 0.D0
      watererb = 1.0d3*aerliqperb(nions+1)/18.0d0
      aerliqperb(nions+1) = 0.D0
      gasaqerb = 0.D0
      DO i=ngasaq,1,-1
        gasaqerb(i) = gasaqerb(i) + aerliqperb(nions+1+i)
        aerliqperb(nions+1+i) = 0.D0
      ENDDO
      molalerb = 0.D0
      DO i=nions,1,-1
        molalerb(i) = molalerb(i) + aerliqperb(i)
        aerliqperb(i) = 0.D0
      ENDDO
      gasperb(3) = 0.D0
      ghno3erb = gasperb(2)
      gasperb(2) = 0.D0
      gnh3erb = gasperb(1)
      gasperb(1) = 0.D0
      CALL CALCNH3P_ERB()
      CALL POPREAL8ARRAY(molal, nions)
      CALL CALCNAP_ERB()
      waererb = 0.D0
      CALL POPREAL8(molal(1))
      waererb(4) = waererb(4) + molalerb(7) + molalerb(1)
      CALL POPREAL8(molal(7))
      molalerb(7) = 0.D0
      werb = 0.D0
      molalrerb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_ERB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) watererb = 0.D0
        DO j=npair,1,-1
          molalrerb(j) = molalrerb(j) + watererb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            hso4ierb = molalrerb(9)
            so4ierb = -molalrerb(9)
            molalrerb(9) = 0.D0
          ELSE
            molalrerb(9) = 0.D0
            hso4ierb = 0.D0
            so4ierb = 0.D0
          END IF
          so4ierb = so4ierb + molalrerb(13)
          molalrerb(13) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            so4ierb = molalrerb(4)
            hso4ierb = -molalrerb(4)
            molalrerb(4) = 0.D0
          ELSE
            molalrerb(4) = 0.D0
            hso4ierb = 0.D0
            so4ierb = 0.D0
          END IF
          hso4ierb = hso4ierb + molalrerb(13)
          molalrerb(13) = 0.D0
        END IF
        molalerb(6) = molalerb(6) + hso4ierb
        molalerb(1) = molalerb(1) + hso4ierb
        molalerb(5) = molalerb(5) + so4ierb
        molalerb(1) = molalerb(1) - so4ierb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(1))
          molalerb(1) = 0.D0
          x3erb = 0.D0
        ELSE
          CALL POPREAL8(molal(1))
          x3erb = molalerb(1)
          molalerb(1) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          werb(2) = werb(2) + x3erb
          ak1 = xk1*(gama(8)/gama(7))**2.*(water/gama(7))
          ak1erb = 0.D0
        ELSE
          temp2erb = x3erb/molal(5)
          ak1erb = molal(6)*temp2erb
          molalerb(6) = molalerb(6) + ak1*temp2erb
          molalerb(5) = molalerb(5) - ak1*molal(6)*temp2erb/molal(5)
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalerb(6) = 0.D0
          x2erb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          x2erb = molalerb(6)
          molalerb(6) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          werb(2) = werb(2) + x2erb
        ELSE
          werb(2) = werb(2) + x2erb
          molalerb(5) = molalerb(5) - x2erb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          molalerb(5) = 0.D0
          x1erb = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          x1erb = molalerb(5)
          molalerb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          werb(2) = werb(2) + x1erb
          x4erb = 0.D0
        ELSE
          x4erb = x1erb
        END IF
        bet = w(2)
        gam = molal(3)
        bb = bet + ak1 - gam
        cc = -(ak1*bet)
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          dderb = 0.0
        ELSE
          dderb = 0.5*x4erb/(2.0*SQRT(dd))
        END IF
        bberb = 2*bb*dderb - 0.5*x4erb
        ccerb = -(4.d0*dderb)
        ak1erb = ak1erb + bberb - bet*ccerb
        beterb = bberb - ak1*ccerb
        CALL POPREAL8(bb)
        gamerb = -bberb
        molalerb(3) = molalerb(3) + gamerb
        werb(2) = werb(2) + beterb
        CALL POPREAL8(ak1)
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0erb = 2.*temp0*temp1*xk1*ak1erb/gama(7)
        temp1erb = temp0**2.*xk1*ak1erb/gama(7)
        gamaerb(8) = gamaerb(8) + temp0erb
        gamaerb(7) = gamaerb(7) - temp1*temp1erb - temp0*temp0erb
        watererb = temp1erb
      ENDDO
      werb(3) = werb(3) + molalerb(3)
      molalrerb(13) = molalrerb(13) + watererb/m0(13)
      molalrerb(9) = molalrerb(9) + watererb/m0(9)
      molalrerb(4) = molalrerb(4) + watererb/m0(4)
      cnh42s4erb = molalrerb(4)
      molalrerb(4) = 0.D0
      cnh4hs4erb = molalrerb(9)
      molalrerb(9) = 0.D0
      clcerb = molalrerb(13)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        werb(3) = werb(3) + 2.d0*cnh42s4erb
        werb(2) = werb(2) + 2.d0*clcerb - 3.d0*cnh42s4erb
        werb(3) = werb(3) - clcerb
      ELSE
        werb(2) = werb(2) + 3.d0*cnh4hs4erb
        werb(3) = werb(3) + clcerb - 2.d0*cnh4hs4erb
        werb(2) = werb(2) - clcerb
      END IF
      waererb(4) = waererb(4) + werb(4)
      werb(4) = 0.D0
      waererb(3) = waererb(3) + werb(3)
      werb(3) = 0.D0
      waererb(2) = waererb(2) + werb(2)
      waerperb = 0.D0
      waerperb = waererb
C
C *** adjoint development **********************************************
C
C      ncase = 15
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerperb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END

C  Differentiation of calcnap in reverse (adjoint) mode:
C   gradient     of useful results: molal gama gasaq water ghno3
C   with respect to varying inputs: molal gama water
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNAP
C *** CALCULATES NITRATES SPECIATION
C
C     NITRIC ACID IN THE LIQUID PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE HSO4-SO4 EQUILIBRIUM. THE NITRIC
C     ACID DISSOLVED IS CALCULATED FROM THE HNO3(G) -> HNO3(AQ) AND
C     HNO3(AQ) -> (H+) + (CL-) EQUILIBRIA, USING (H+) FROM THE SULFATES.
C
C     THIS IS THE VERSION USED BY THE INVERSE PROBLEM SOVER
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNAP_ERB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNAP *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalerb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaerb(npair), gasaqerb(ngasaq)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watererb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
