      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION alfa, delt
      DOUBLE PRECISION alfaerb, delterb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0erb
      DOUBLE PRECISION temp1erb
      COMMON /gas_erb/ gnh3erb, ghno3erb
      COMMON /ions_erb/ molalerb, gamaerb, gasaqerb, watererb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .GT. tiny) THEN
C
C *** CALCULATE HNO3 SPECIATION IN THE GAS PHASE ************************
C
        CALL CALCNIAQ(molal(7), molal(1), delt)
        alfa = xk4*r*temp*(water/gama(10))**2.0
        CALL PUSHREAL8(molal(1))
        molal(1) = molal(1) - delt
        CALL PUSHREAL8(molal(7))
        molal(7) = molal(7) - delt
C      write (*,*) ALFA, MOLAL(1), MOLAL(7), GHNO3, DELT
C 
        temp1erb = molal(7)*ghno3erb/alfa
        temp1 = molal(1)/alfa
        molalerb(1) = molalerb(1) + temp1erb
        alfaerb = -(temp1*temp1erb)
        molalerb(7) = molalerb(7) + temp1*ghno3erb
        CALL POPREAL8(molal(7))
        delterb = gasaqerb(3) - molalerb(1) - molalerb(7)
        CALL POPREAL8(molal(1))
        temp0 = water/gama(10)
        temp0erb = 2.0*temp0*xk4*r*temp*alfaerb/gama(10)
        watererb = watererb + temp0erb
        gamaerb(10) = gamaerb(10) - temp0*temp0erb
        CALL CALCNIAQ_ERB(molal(7), molalerb(7), molal(1), molalerb(1), 
     +                    delt, delterb)
      END IF
      END

