CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0erb(6, 4), sionerb, herb, cherb, f1erb(3), 
     +                 f2erb(4)
      DOUBLE PRECISION mpl, xij, yji, check
      DOUBLE PRECISION mplerb, xijerb, yjierb
      CHARACTER*40 errinf
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01erb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02erb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03erb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04erb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05erb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06erb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07erb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08erb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09erb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10erb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11erb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12erb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0erb
      INTRINSIC MAX
      DOUBLE PRECISION temp0erb9
      DOUBLE PRECISION temp0erb8
      DOUBLE PRECISION temp0erb7
      DOUBLE PRECISION temp0erb6
      DOUBLE PRECISION x1erb
      DOUBLE PRECISION temp0erb5
      DOUBLE PRECISION temp0erb4
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION temp0erb3
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0erb2
      DOUBLE PRECISION temp0erb1
      DOUBLE PRECISION temp0erb0
      DOUBLE PRECISION x2erb
      DOUBLE PRECISION temp0erb13
      INTRINSIC MIN
      DOUBLE PRECISION temp0erb12
      DOUBLE PRECISION temp0erb11
      DOUBLE PRECISION temp0erb10
      INTRINSIC SQRT
      DOUBLE PRECISION y1
      COMMON /gas_erb/ gnh3erb, ghno3erb
      COMMON /ions_erb/ molalerb, gamaerb, gasaqerb, watererb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 200.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamaerb(i) = 10.d0**gama(i)*LOG(10.d0)*gamaerb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamaerb(i) = 0.D0
          x2erb = 0.D0
        ELSE
          x2erb = gamaerb(i)
          gamaerb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamaerb(i) = gamaerb(i) + x2erb
      ENDDO
      CALL POPREAL8(gama(13))
      gamaerb(4) = gamaerb(4) + 0.2d0*3.d0*gamaerb(13)
      gamaerb(9) = gamaerb(9) + 0.2d0*2.d0*gamaerb(13)
      gamaerb(13) = 0.D0
      f1erb = 0.D0
      f2erb = 0.D0
      CALL POPREAL8(gama(12))
      temp0erb2 = zz(12)*gamaerb(12)/(z(2)+z(6))
      f1erb(2) = f1erb(2) + temp0erb2/z(2)
      f2erb(3) = f2erb(3) + temp0erb2/z(6)
      herb = -(zz(12)*gamaerb(12))
      gamaerb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0erb3 = zz(11)*gamaerb(11)/(z(1)+z(4))
      f2erb(1) = f2erb(1) + temp0erb3/z(4)
      herb = herb - zz(11)*gamaerb(11)
      gamaerb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0erb4 = zz(10)*gamaerb(10)/(z(1)+z(7))
      f1erb(1) = f1erb(1) + temp0erb4/z(1) + temp0erb3/z(1)
      f2erb(4) = f2erb(4) + temp0erb4/z(7)
      herb = herb - zz(10)*gamaerb(10)
      gamaerb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0erb5 = zz(9)*gamaerb(9)/(z(3)+z(6))
      f1erb(3) = f1erb(3) + temp0erb5/z(3)
      herb = herb - zz(9)*gamaerb(9)
      gamaerb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0erb6 = zz(8)*gamaerb(8)/(z(1)+z(6))
      f2erb(3) = f2erb(3) + temp0erb6/z(6) + temp0erb5/z(6)
      herb = herb - zz(8)*gamaerb(8)
      gamaerb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0erb7 = zz(7)*gamaerb(7)/(z(1)+z(5))
      f1erb(1) = f1erb(1) + temp0erb7/z(1) + temp0erb6/z(1)
      f2erb(2) = f2erb(2) + temp0erb7/z(5)
      herb = herb - zz(7)*gamaerb(7)
      gamaerb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0erb8 = zz(6)*gamaerb(6)/(z(3)+z(4))
      f2erb(1) = f2erb(1) + temp0erb8/z(4)
      herb = herb - zz(6)*gamaerb(6)
      gamaerb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0erb9 = zz(5)*gamaerb(5)/(z(3)+z(7))
      f2erb(4) = f2erb(4) + temp0erb9/z(7)
      herb = herb - zz(5)*gamaerb(5)
      gamaerb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0erb10 = zz(4)*gamaerb(4)/(z(3)+z(5))
      f1erb(3) = f1erb(3) + temp0erb9/z(3) + temp0erb10/z(3) + temp0erb8
     +  /z(3)
      f2erb(2) = f2erb(2) + temp0erb10/z(5)
      herb = herb - zz(4)*gamaerb(4)
      gamaerb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0erb11 = zz(3)*gamaerb(3)/(z(2)+z(7))
      f2erb(4) = f2erb(4) + temp0erb11/z(7)
      herb = herb - zz(3)*gamaerb(3)
      gamaerb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0erb12 = zz(2)*gamaerb(2)/(z(2)+z(5))
      f2erb(2) = f2erb(2) + temp0erb12/z(5)
      herb = herb - zz(2)*gamaerb(2)
      gamaerb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0erb13 = zz(1)*gamaerb(1)/(z(2)+z(4))
      f1erb(2) = f1erb(2) + temp0erb12/z(2) + temp0erb13/z(2) + 
     +  temp0erb11/z(2)
      f2erb(1) = f2erb(1) + temp0erb13/z(4)
      herb = herb - zz(1)*gamaerb(1)
      gamaerb(1) = 0.D0
      ionicerb = 0.D0
      g0erb = 0.D0
      DO i=3,1,-1
        mplerb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijerb = (g0(i, j)+zpl*zmi*h)*f2erb(j)
          yji = ch*molal(j+3)/water
          g0erb(i, j) = g0erb(i, j) + yji*f1erb(i) + xij*f2erb(j)
          herb = herb + yji*zpl*zmi*f1erb(i) + xij*zpl*zmi*f2erb(j)
          yjierb = (g0(i, j)+zpl*zmi*h)*f1erb(i)
          temp0erb1 = molal(j+3)*yjierb/water
          molalerb(j+3) = molalerb(j+3) + ch*yjierb/water
          cherb = mpl*xijerb + temp0erb1
          watererb = watererb - ch*temp0erb1/water
          mplerb = mplerb + ch*xijerb
          ionicerb = ionicerb - (zpl+zmi)**2*0.25d0*cherb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalerb(i) = molalerb(i) + mplerb/water
        watererb = watererb - molal(i)*mplerb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0erb0 = agama*herb/(sion+1.d0)
      sionerb = (1.D0-sion/(sion+1.d0))*temp0erb0
      IF (.NOT.ionic .EQ. 0.0) ionicerb = ionicerb + sionerb/(2.0*SQRT(
     +    ionic))
      g05erb = g0erb(3, 4)
      g0erb(3, 4) = 0.D0
      g09erb = g0erb(3, 3)
      g0erb(3, 3) = 0.D0
      g04erb = g0erb(3, 2)
      g0erb(3, 2) = 0.D0
      g06erb = g0erb(3, 1)
      g0erb(3, 1) = 0.D0
      g03erb = g0erb(2, 4)
      g0erb(2, 4) = 0.D0
      g12erb = g0erb(2, 3)
      g0erb(2, 3) = 0.D0
      g02erb = g0erb(2, 2)
      g0erb(2, 2) = 0.D0
      g01erb = g0erb(2, 1)
      g0erb(2, 1) = 0.D0
      g10erb = g0erb(1, 4)
      g0erb(1, 4) = 0.D0
      g08erb = g0erb(1, 3)
      g0erb(1, 3) = 0.D0
      g07erb = g0erb(1, 2)
      g0erb(1, 2) = 0.D0
      g11erb = g0erb(1, 1)
      CALL KMFUL3_ERB(ionic, ionicerb, temp, g01, g01erb, g02, g02erb, 
     +                g03, g03erb, g04, g04erb, g05, g05erb, g06, g06erb
     +                , g07, g07erb, g08, g08erb, g09, g09erb, g10, 
     +                g10erb, g11, g11erb, g12, g12erb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1erb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1erb = ionicerb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicerb = 0.D0
      ELSE
        temp0erb = 0.5d0*x1erb/water
        ionicerb = temp0erb
        watererb = watererb - ionic*temp0erb/water
      END IF
      DO i=7,1,-1
        molalerb(i) = molalerb(i) + z(i)**2*ionicerb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_ERB(ionic, ionicerb, temp, g01, g01erb, g02, 
     +                      g02erb, g03, g03erb, g04, g04erb, g05, 
     +                      g05erb, g06, g06erb, g07, g07erb, g08, 
     +                      g08erb, g09, g09erb, g10, g10erb, g11, 
     +                      g11erb, g12, g12erb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicerb, sionerb, cf2erb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01erb, g02erb, g03erb, g04erb, g05erb, g06erb, 
     +                 g07erb, g08erb, g09erb, g10erb, g11erb, g12erb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0erb
      INTRINSIC ABS
      DOUBLE PRECISION temp0erb0
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01erb = g01erb + g12erb
      g08erb = g08erb + g09erb + g12erb
      g11erb = g11erb - g09erb - g12erb
      g06erb = g06erb + g09erb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2erb = -(z10*g10erb) - z07*g07erb - z05*g05erb - z03*g03erb - 
     +    z01*g01erb - z02*g02erb - z04*g04erb - z06*g06erb - z08*g08erb
     +    - z11*g11erb
        g11erb = cf1*g11erb
        g10erb = cf1*g10erb
        g08erb = cf1*g08erb
        g07erb = cf1*g07erb
        g06erb = cf1*g06erb
        g05erb = cf1*g05erb
        g04erb = cf1*g04erb
        g03erb = cf1*g03erb
        g02erb = cf1*g02erb
        g01erb = cf1*g01erb
        temp0erb = (0.125d0-ti*0.005d0)*cf2erb
        temp0erb0 = -(0.41d0*temp0erb/(sion+1.d0))
        ionicerb = ionicerb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0erb
        sionerb = (1.D0-sion/(sion+1.d0))*temp0erb0
      ELSE
        sionerb = 0.D0
      END IF
      CALL MKBI_ERB(q11, ionic, ionicerb, sion, sionerb, z11, g11, 
     +              g11erb)
      CALL MKBI_ERB(q10, ionic, ionicerb, sion, sionerb, z10, g10, 
     +              g10erb)
      CALL MKBI_ERB(q8, ionic, ionicerb, sion, sionerb, z08, g08, g08erb
     +             )
      CALL MKBI_ERB(q7, ionic, ionicerb, sion, sionerb, z07, g07, g07erb
     +             )
      CALL MKBI_ERB(q6, ionic, ionicerb, sion, sionerb, z06, g06, g06erb
     +             )
      CALL MKBI_ERB(q5, ionic, ionicerb, sion, sionerb, z05, g05, g05erb
     +             )
      CALL MKBI_ERB(q4, ionic, ionicerb, sion, sionerb, z04, g04, g04erb
     +             )
      CALL MKBI_ERB(q3, ionic, ionicerb, sion, sionerb, z03, g03, g03erb
     +             )
      CALL MKBI_ERB(q2, ionic, ionicerb, sion, sionerb, z02, g02, g02erb
     +             )
      CALL MKBI_ERB(q1, ionic, ionicerb, sion, sionerb, z01, g01, g01erb
     +             )
      IF (.NOT.ionic .EQ. 0.0) ionicerb = ionicerb + sionerb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_ERB(q, ionic, ionicerb, sion, sionerb, zip, bi, 
     +                    bierb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicerb, sionerb, bierb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cerb, xxerb
      INTRINSIC EXP
      DOUBLE PRECISION temperb0
      DOUBLE PRECISION temperb
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxerb = zip*bierb
      bierb = zip*bierb/(bi*LOG(10.0))
      temperb = -(0.5107d0*xxerb/(c*sion+1.d0))
      temperb0 = -(sion*temperb/(c*sion+1.d0))
      sionerb = sionerb + c*temperb0 + temperb
      cerb = sion*temperb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicerb = ionicerb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cerb
      ELSE
        ionicerb = ionicerb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bierb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cerb
      END IF
      END

