     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION lamda, kapa, psi, parm
      DOUBLE PRECISION lamdafb, kapafb, psifb, parmfb
      DOUBLE PRECISION bb, cc
      DOUBLE PRECISION bbfb, ccfb
      DOUBLE PRECISION wp(ncomp), gas(3), aerliq(7)
      DOUBLE PRECISION wpfb(ncomp), gasfb(3), aerliqfb(7)
      INTEGER i
