C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS **************************************************
C
C NH4HSO4 INITIALLY IN SOLUTION
      lamda = w(3)
C H2SO4 IN SOLUTION
      psi = w(2) - w(3)
      i = 1
      ad_count = 0
C      NSWEEP = 50
      DO WHILE (i .LE. nsweep .AND. calain)
C         IF (I.GT.1) CALL CALCACT3 
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        kapa = 0.5*(-bb+SQRT(bb*bb-4.0*cc))
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = psi + kapa
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = lamda
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = kapa
        IF (lamda + psi - kapa .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = lamda + psi - kapa
          CALL PUSHCONTROL1B(1)
