C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicfb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterfb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION ghno3fb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0fb(6, 4), sionfb, hfb, chfb, f1fb(3), f2fb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplfb, xijfb, yjifb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01fb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02fb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03fb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04fb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05fb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06fb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07fb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08fb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09fb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10fb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11fb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12fb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1fb
      DOUBLE PRECISION temp0fb13
      DOUBLE PRECISION temp0fb12
      DOUBLE PRECISION temp0fb11
      DOUBLE PRECISION temp0fb10
      DOUBLE PRECISION x2fb
      DOUBLE PRECISION temp0fb
      INTRINSIC MIN
      DOUBLE PRECISION temp0fb9
      DOUBLE PRECISION temp0fb8
      DOUBLE PRECISION temp0fb7
      DOUBLE PRECISION temp0fb6
      INTEGER ii2
      INTEGER ii1
      DOUBLE PRECISION temp0fb5
      INTRINSIC SQRT
      DOUBLE PRECISION temp0fb4
      DOUBLE PRECISION temp0fb3
      DOUBLE PRECISION temp0fb2
      DOUBLE PRECISION temp0fb1
      DOUBLE PRECISION temp0fb0
      DOUBLE PRECISION y1
      COMMON /gas_fb/ ghno3fb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      COMMON /inpt_fb/ wfb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamafb(i) = 10.d0**gama(i)*LOG(10.d0)*gamafb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamafb(i) = 0.D0
          x2fb = 0.D0
        ELSE
          x2fb = gamafb(i)
          gamafb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamafb(i) = gamafb(i) + x2fb
      ENDDO
      CALL POPREAL8(gama(13))
      gamafb(4) = gamafb(4) + 0.2d0*3.d0*gamafb(13)
      gamafb(9) = gamafb(9) + 0.2d0*2.d0*gamafb(13)
      gamafb(13) = 0.D0
      DO ii1=1,3
        f1fb(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2fb(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0fb2 = zz(12)*gamafb(12)/(z(2)+z(6))
      f1fb(2) = f1fb(2) + temp0fb2/z(2)
      f2fb(3) = f2fb(3) + temp0fb2/z(6)
      hfb = -(zz(12)*gamafb(12))
      gamafb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0fb3 = zz(11)*gamafb(11)/(z(1)+z(4))
      f2fb(1) = f2fb(1) + temp0fb3/z(4)
      hfb = hfb - zz(11)*gamafb(11)
      gamafb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0fb4 = zz(10)*gamafb(10)/(z(1)+z(7))
      f1fb(1) = f1fb(1) + temp0fb4/z(1) + temp0fb3/z(1)
      f2fb(4) = f2fb(4) + temp0fb4/z(7)
      hfb = hfb - zz(10)*gamafb(10)
      gamafb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0fb5 = zz(9)*gamafb(9)/(z(3)+z(6))
      f1fb(3) = f1fb(3) + temp0fb5/z(3)
      hfb = hfb - zz(9)*gamafb(9)
      gamafb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0fb6 = zz(8)*gamafb(8)/(z(1)+z(6))
      f2fb(3) = f2fb(3) + temp0fb6/z(6) + temp0fb5/z(6)
      hfb = hfb - zz(8)*gamafb(8)
      gamafb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0fb7 = zz(7)*gamafb(7)/(z(1)+z(5))
      f1fb(1) = f1fb(1) + temp0fb7/z(1) + temp0fb6/z(1)
      f2fb(2) = f2fb(2) + temp0fb7/z(5)
      hfb = hfb - zz(7)*gamafb(7)
      gamafb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0fb8 = zz(6)*gamafb(6)/(z(3)+z(4))
      f2fb(1) = f2fb(1) + temp0fb8/z(4)
      hfb = hfb - zz(6)*gamafb(6)
      gamafb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0fb9 = zz(5)*gamafb(5)/(z(3)+z(7))
      f2fb(4) = f2fb(4) + temp0fb9/z(7)
      hfb = hfb - zz(5)*gamafb(5)
      gamafb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0fb10 = zz(4)*gamafb(4)/(z(3)+z(5))
      f1fb(3) = f1fb(3) + temp0fb9/z(3) + temp0fb10/z(3) + temp0fb8/z(3)
      f2fb(2) = f2fb(2) + temp0fb10/z(5)
      hfb = hfb - zz(4)*gamafb(4)
      gamafb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0fb11 = zz(3)*gamafb(3)/(z(2)+z(7))
      f2fb(4) = f2fb(4) + temp0fb11/z(7)
      hfb = hfb - zz(3)*gamafb(3)
      gamafb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0fb12 = zz(2)*gamafb(2)/(z(2)+z(5))
      f2fb(2) = f2fb(2) + temp0fb12/z(5)
      hfb = hfb - zz(2)*gamafb(2)
      gamafb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0fb13 = zz(1)*gamafb(1)/(z(2)+z(4))
      f1fb(2) = f1fb(2) + temp0fb12/z(2) + temp0fb13/z(2) + temp0fb11/z(
     +  2)
      f2fb(1) = f2fb(1) + temp0fb13/z(4)
      hfb = hfb - zz(1)*gamafb(1)
      gamafb(1) = 0.D0
      ionicfb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0fb(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mplfb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijfb = (g0(i, j)+zpl*zmi*h)*f2fb(j)
          yji = ch*molal(j+3)/water
          g0fb(i, j) = g0fb(i, j) + yji*f1fb(i) + xij*f2fb(j)
          hfb = hfb + yji*zpl*zmi*f1fb(i) + xij*zpl*zmi*f2fb(j)
          yjifb = (g0(i, j)+zpl*zmi*h)*f1fb(i)
          temp0fb1 = molal(j+3)*yjifb/water
          molalfb(j+3) = molalfb(j+3) + ch*yjifb/water
          chfb = mpl*xijfb + temp0fb1
          waterfb = waterfb - ch*temp0fb1/water
          mplfb = mplfb + ch*xijfb
          ionicfb = ionicfb - (zpl+zmi)**2*0.25d0*chfb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalfb(i) = molalfb(i) + mplfb/water
        waterfb = waterfb - molal(i)*mplfb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0fb0 = agama*hfb/(sion+1.d0)
      sionfb = (1.D0-sion/(sion+1.d0))*temp0fb0
      IF (.NOT.ionic .EQ. 0.0) ionicfb = ionicfb + sionfb/(2.0*SQRT(
     +    ionic))
      g05fb = g0fb(3, 4)
      g0fb(3, 4) = 0.D0
      g09fb = g0fb(3, 3)
      g0fb(3, 3) = 0.D0
      g04fb = g0fb(3, 2)
      g0fb(3, 2) = 0.D0
      g06fb = g0fb(3, 1)
      g0fb(3, 1) = 0.D0
      g03fb = g0fb(2, 4)
      g0fb(2, 4) = 0.D0
      g12fb = g0fb(2, 3)
      g0fb(2, 3) = 0.D0
      g02fb = g0fb(2, 2)
      g0fb(2, 2) = 0.D0
      g01fb = g0fb(2, 1)
      g0fb(2, 1) = 0.D0
      g10fb = g0fb(1, 4)
      g0fb(1, 4) = 0.D0
      g08fb = g0fb(1, 3)
      g0fb(1, 3) = 0.D0
      g07fb = g0fb(1, 2)
      g0fb(1, 2) = 0.D0
      g11fb = g0fb(1, 1)
      CALL KMFUL3_FB(ionic, ionicfb, temp, g01, g01fb, g02, g02fb, g03, 
     +               g03fb, g04, g04fb, g05, g05fb, g06, g06fb, g07, 
     +               g07fb, g08, g08fb, g09, g09fb, g10, g10fb, g11, 
     +               g11fb, g12, g12fb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1fb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1fb = ionicfb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicfb = 0.D0
      ELSE
        temp0fb = 0.5d0*x1fb/water
        ionicfb = temp0fb
        waterfb = waterfb - ionic*temp0fb/water
      END IF
      DO i=7,1,-1
        molalfb(i) = molalfb(i) + z(i)**2*ionicfb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_FB(ionic, ionicfb, temp, g01, g01fb, g02, g02fb
     +                     , g03, g03fb, g04, g04fb, g05, g05fb, g06, 
     +                     g06fb, g07, g07fb, g08, g08fb, g09, g09fb, 
     +                     g10, g10fb, g11, g11fb, g12, g12fb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicfb, sionfb, cf2fb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01fb, g02fb, g03fb, g04fb, g05fb, g06fb, g07fb, 
     +                 g08fb, g09fb, g10fb, g11fb, g12fb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      INTRINSIC ABS
      DOUBLE PRECISION abs1
      DOUBLE PRECISION temp0fb
      INTRINSIC SQRT
      DOUBLE PRECISION temp0fb0
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01fb = g01fb + g12fb
      g08fb = g08fb + g09fb + g12fb
      g11fb = g11fb - g09fb - g12fb
      g06fb = g06fb + g09fb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2fb = -(z10*g10fb) - z07*g07fb - z05*g05fb - z03*g03fb - z01*
     +    g01fb - z02*g02fb - z04*g04fb - z06*g06fb - z08*g08fb - z11*
     +    g11fb
        g11fb = cf1*g11fb
        g10fb = cf1*g10fb
        g08fb = cf1*g08fb
        g07fb = cf1*g07fb
        g06fb = cf1*g06fb
        g05fb = cf1*g05fb
        g04fb = cf1*g04fb
        g03fb = cf1*g03fb
        g02fb = cf1*g02fb
        g01fb = cf1*g01fb
        temp0fb = (0.125d0-ti*0.005d0)*cf2fb
        temp0fb0 = -(0.41d0*temp0fb/(sion+1.d0))
        ionicfb = ionicfb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0fb
        sionfb = (1.D0-sion/(sion+1.d0))*temp0fb0
      ELSE
        sionfb = 0.D0
      END IF
      CALL MKBI_FB(q11, ionic, ionicfb, sion, sionfb, z11, g11, g11fb)
      CALL MKBI_FB(q10, ionic, ionicfb, sion, sionfb, z10, g10, g10fb)
      CALL MKBI_FB(q8, ionic, ionicfb, sion, sionfb, z08, g08, g08fb)
      CALL MKBI_FB(q7, ionic, ionicfb, sion, sionfb, z07, g07, g07fb)
      CALL MKBI_FB(q6, ionic, ionicfb, sion, sionfb, z06, g06, g06fb)
      CALL MKBI_FB(q5, ionic, ionicfb, sion, sionfb, z05, g05, g05fb)
      CALL MKBI_FB(q4, ionic, ionicfb, sion, sionfb, z04, g04, g04fb)
      CALL MKBI_FB(q3, ionic, ionicfb, sion, sionfb, z03, g03, g03fb)
      CALL MKBI_FB(q2, ionic, ionicfb, sion, sionfb, z02, g02, g02fb)
      CALL MKBI_FB(q1, ionic, ionicfb, sion, sionfb, z01, g01, g01fb)
      IF (.NOT.ionic .EQ. 0.0) ionicfb = ionicfb + sionfb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_FB(q, ionic, ionicfb, sion, sionfb, zip, bi, bifb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicfb, sionfb, bifb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cfb, xxfb
      INTRINSIC EXP
      DOUBLE PRECISION tempfb
      DOUBLE PRECISION tempfb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxfb = zip*bifb
      bifb = zip*bifb/(bi*LOG(10.0))
      tempfb = -(0.5107d0*xxfb/(c*sion+1.d0))
      tempfb0 = -(sion*tempfb/(c*sion+1.d0))
      sionfb = sionfb + c*tempfb0 + tempfb
      cfb = sion*tempfb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicfb = ionicfb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cfb
      ELSE
        ionicfb = ionicfb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bifb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cfb
      END IF
      END


