      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION lamda, kapa, psi, parm
      DOUBLE PRECISION lamdafrb, kapafrb, psifrb, parmfrb
      DOUBLE PRECISION bb, cc
      DOUBLE PRECISION bbfrb, ccfrb
      DOUBLE PRECISION gas(3), aerliq(nions+ngasaq+2)
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3), waerp(ncomp)
      DOUBLE PRECISION aerliqpfrb(nions+ngasaq+2), gaspfrb(3), waerpfrb(
     +                 ncomp)
      DOUBLE PRECISION wi
      DIMENSION wi(ncomp)
      INTEGER i
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp0frb
      DOUBLE PRECISION temp1frb
      DOUBLE PRECISION temp2frb
      INTRINSIC SQRT
      COMMON /gas_frb/ gnh3frb, ghno3frb
      COMMON /ions_frb/ molalfrb, gamafrb, gasaqfrb, waterfrb
      INTEGER npflag, ncase
C
C      waer = waerp
C
      w(2) = waer(2)
      w(3) = waer(3)
      w(4) = waer(4)
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS **************************************************
C
C NH4HSO4 INITIALLY IN SOLUTION
      lamda = w(3)
C H2SO4 IN SOLUTION
      psi = w(2) - w(3)
C     
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. calain)
C         IF (I.GT.1) CALL CALCACT3 
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.d0
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        kapa = 0.5*(-bb+SQRT(bb*bb-4.0*cc))
        CALL PUSHREAL8(molal(1))
C
C *** SPECIATION & WATER CONTENT ***************************************
C
C HI
        molal(1) = psi + kapa
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = lamda
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = kapa
        IF (lamda + psi - kapa .LT. tiny) THEN
          CALL PUSHREAL8(molal(6))
          molal(6) = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molal(6))
          molal(6) = lamda + psi - kapa
          CALL PUSHCONTROL1B(1)
        END IF
C
C         CALL CALCMR                                       ! Water content
C
C NH4HSO4
        molalr(9) = molal(3)
        IF (molal(5) + molal(6) - molal(3) .LT. zero) THEN
          molalr(7) = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          molalr(7) = molal(5) + molal(6) - molal(3)
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
C         IF (.NOT.CALAIN) GOTO 30
        i = i + 1
        CALL PUSHREAL8ARRAY(gama, npair)
C*** slc.11.2009 Moved to beginning of loop     
        CALL CALCACT3()
        ad_count = ad_count + 1
      ENDDO
      IF (CALAIN .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCF2R')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      CALL PUSHREAL8(molal(7))
C
C *** Add the NO3 to the solution now and calculate partitioning.
C
C There is always water, so NO3(aer) is NO3-
      molal(7) = waer(4)
      CALL PUSHREAL8(molal(1))
C Add H+ to balance out
      molal(1) = molal(1) + waer(4)
      CALL PUSHREAL8ARRAY(molal, nions)
C
C HNO3, NH3 dissolved
      CALL CALCNAP()
C
C *** CALCULATE TOTAL AMOUNT OF SPECIES WITH GAS PHASE ****************
C
C      WTP(1) = WAER(1)                ! Total gas+aerosol phase
C      WTP(2) = WAER(2)
C      WTP(3) = WAER(3) + GNH3 
C      WTP(4) = WAER(4) + GHNO3
C      WTP(5) = WAER(5) + GHCL
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C Gaseous aerosol species
      aerliqpfrb(nions+ngasaq+2) = 0.D0
      waterfrb = 1.0d3*aerliqpfrb(nions+1)/18.0d0
      aerliqpfrb(nions+1) = 0.D0
      gasaqfrb = 0.D0
      DO i=ngasaq,1,-1
        gasaqfrb(i) = gasaqfrb(i) + aerliqpfrb(nions+1+i)
        aerliqpfrb(nions+1+i) = 0.D0
      ENDDO
      molalfrb = 0.D0
      DO i=nions,1,-1
        molalfrb(i) = molalfrb(i) + aerliqpfrb(i)
        aerliqpfrb(i) = 0.D0
      ENDDO
      gaspfrb(3) = 0.D0
      ghno3frb = gaspfrb(2)
      gaspfrb(2) = 0.D0
      gnh3frb = gaspfrb(1)
      gaspfrb(1) = 0.D0
      CALL CALCNH3P_FRB()
      CALL POPREAL8ARRAY(molal, nions)
      CALL CALCNAP_FRB()
      waerfrb = 0.D0
      CALL POPREAL8(molal(1))
      waerfrb(4) = waerfrb(4) + molalfrb(7) + molalfrb(1)
      CALL POPREAL8(molal(7))
      molalfrb(7) = 0.D0
      molalrfrb = 0.D0
      psifrb = 0.D0
      lamdafrb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_FRB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterfrb = 0.D0
        DO j=npair,1,-1
          molalrfrb(j) = molalrfrb(j) + waterfrb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          molalrfrb(7) = 0.D0
        ELSE
          molalfrb(5) = molalfrb(5) + molalrfrb(7)
          molalfrb(6) = molalfrb(6) + molalrfrb(7)
          molalfrb(3) = molalfrb(3) - molalrfrb(7)
          molalrfrb(7) = 0.D0
        END IF
        molalfrb(3) = molalfrb(3) + molalrfrb(9)
        molalrfrb(9) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(6))
          molalfrb(6) = 0.D0
          kapafrb = 0.D0
        ELSE
          CALL POPREAL8(molal(6))
          lamdafrb = lamdafrb + molalfrb(6)
          psifrb = psifrb + molalfrb(6)
          kapafrb = -molalfrb(6)
          molalfrb(6) = 0.D0
        END IF
        CALL POPREAL8(molal(5))
        kapafrb = kapafrb + molalfrb(5)
        molalfrb(5) = 0.D0
        CALL POPREAL8(molal(3))
        lamdafrb = lamdafrb + molalfrb(3)
        molalfrb(3) = 0.D0
        CALL POPREAL8(molal(1))
        kapafrb = kapafrb + molalfrb(1)
        parm = water*xk1/gama(7)*(gama(8)/gama(7))**2.d0
        bb = psi + parm
        cc = -(parm*(lamda+psi))
        IF (bb**2 - 4.0*cc .EQ. 0.0) THEN
          temp2frb = 0.0
        ELSE
          temp2frb = 0.5*kapafrb/(2.0*SQRT(bb**2-4.0*cc))
        END IF
        bbfrb = 2*bb*temp2frb - 0.5*kapafrb
        ccfrb = -(4.0*temp2frb)
        psifrb = psifrb + bbfrb - parm*ccfrb + molalfrb(1)
        molalfrb(1) = 0.D0
        parmfrb = bbfrb - (lamda+psi)*ccfrb
        lamdafrb = lamdafrb - parm*ccfrb
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0frb = 2.d0*temp0*temp1*xk1*parmfrb/gama(7)
        temp1frb = temp0**2.d0*xk1*parmfrb/gama(7)
        gamafrb(8) = gamafrb(8) + temp0frb
        gamafrb(7) = gamafrb(7) - temp1*temp1frb - temp0*temp0frb
        waterfrb = temp1frb
      ENDDO
      wfrb = 0.D0
      wfrb(2) = wfrb(2) + psifrb
      wfrb(3) = wfrb(3) + lamdafrb - psifrb
      waerfrb(4) = waerfrb(4) + wfrb(4)
      wfrb(4) = 0.D0
      waerfrb(3) = waerfrb(3) + wfrb(3)
      wfrb(3) = 0.D0
      waerfrb(2) = waerfrb(2) + wfrb(2)
      waerpfrb = 0.D0
      waerpfrb = waerfrb
C
C *** adjoint development **********************************************
C
C      ncase = 16
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpfrb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END

C
C  Differentiation of calcnap in reverse (adjoint) mode:
C   gradient     of useful results: molal gama gasaq water ghno3
C   with respect to varying inputs: molal gama water
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNAP
C *** CALCULATES NITRATES SPECIATION
C
C     NITRIC ACID IN THE LIQUID PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE HSO4-SO4 EQUILIBRIUM. THE NITRIC
C     ACID DISSOLVED IS CALCULATED FROM THE HNO3(G) -> HNO3(AQ) AND
C     HNO3(AQ) -> (H+) + (CL-) EQUILIBRIA, USING (H+) FROM THE SULFATES.
C
C     THIS IS THE VERSION USED BY THE INVERSE PROBLEM SOVER
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNAP_FRB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNAP *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
