      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1frb0
      DOUBLE PRECISION temp0frb
      DOUBLE PRECISION temp1frb
      INTEGER ii1
      COMMON /gas_frb/ gnh3frb, ghno3frb
      COMMON /ions_frb/ molalfrb, gamafrb, gasaqfrb, waterfrb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamafrb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 GAS PHASE CONCENTRATION *****************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
C 
        temp1frb = gnh3frb/(molal(1)*a1)
        temp1frb0 = -(molal(3)*temp1frb/(molal(1)*a1))
        molalfrb(3) = molalfrb(3) + temp1frb
        molalfrb(1) = molalfrb(1) + a1*temp1frb0
        a1frb = molal(1)*temp1frb0
        DO ii1=1,npair
          gamafrb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0frb = 2.0*temp0*xk2*r*temp*a1frb/(xkw*gama(5))
        gamafrb(10) = gamafrb(10) + temp0frb
        gamafrb(5) = gamafrb(5) - temp0*temp0frb
      END IF
      END

