CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION no3i, hi, delt
      DOUBLE PRECISION no3ifrb, hifrb, deltfrb
      DOUBLE PRECISION om1, om2, bb, cc, dd, del1, del2
      DOUBLE PRECISION om1frb, om2frb, bbfrb, ccfrb, ddfrb, del1frb, 
     +                 del2frb
      DOUBLE PRECISION a42
      DOUBLE PRECISION a42frb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0frb
      DOUBLE PRECISION temp1frb
      INTRINSIC SQRT
      COMMON /gas_frb/ gnh3frb, ghno3frb
      COMMON /ions_frb/ molalfrb, gamafrb, gasaqfrb, waterfrb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HNO3) ASSUMED 1
      a42 = xk42*water/gama(10)**2.
C
C *** FIND ROOT
C
      om1 = no3i
      om2 = hi
      bb = -(om1+om2+a42)
      cc = om1*om2
      dd = SQRT(bb*bb - 4.d0*cc)
C
      del1 = 0.5d0*(-bb-dd)
      del2 = 0.5d0*(-bb+dd)
C
C *** GET APPROPRIATE ROOT.
C
      IF ((del1 .LT. zero .OR. del1 .GT. hi) .OR. del1 .GT. no3i) THEN
C
        IF ((del2 .LT. zero .OR. del2 .GT. no3i) .OR. del2 .GT. hi) THEN
          del2frb = 0.D0
        ELSE
          del2frb = deltfrb
        END IF
        del1frb = 0.D0
      ELSE
        del1frb = deltfrb
        del2frb = 0.D0
      END IF
      ddfrb = 0.5d0*del2frb - 0.5d0*del1frb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1frb = 0.0
      ELSE
        temp1frb = ddfrb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbfrb = 2*bb*temp1frb - 0.5d0*del1frb - 0.5d0*del2frb
      ccfrb = -(4.d0*temp1frb)
      om1frb = om2*ccfrb - bbfrb
      om2frb = om1*ccfrb - bbfrb
      a42frb = -bbfrb
      hifrb = hifrb + om2frb
      no3ifrb = no3ifrb + om1frb
      temp0 = gama(10)**2.
      temp0frb = xk42*a42frb/temp0
      waterfrb = waterfrb + temp0frb
      gamafrb(10) = gamafrb(10) - water*2.*gama(10)*temp0frb/temp0
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_FRB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
