      gamafrb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0frb13 = zz(1)*gamafrb(1)/(z(2)+z(4))
      f1frb(2) = f1frb(2) + temp0frb12/z(2) + temp0frb13/z(2) + 
     +  temp0frb11/z(2)
      f2frb(1) = f2frb(1) + temp0frb13/z(4)
      hfrb = hfrb - zz(1)*gamafrb(1)
      gamafrb(1) = 0.D0
      ionicfrb = 0.D0
      g0frb = 0.D0
      DO i=3,1,-1
        mplfrb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
