C
C=======================================================================
C
      SUBROUTINE KMFUL3_FRB(ionic, ionicfrb, temp, g01, g01frb, g02, 
     +                      g02frb, g03, g03frb, g04, g04frb, g05, 
     +                      g05frb, g06, g06frb, g07, g07frb, g08, 
     +                      g08frb, g09, g09frb, g10, g10frb, g11, 
     +                      g11frb, g12, g12frb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicfrb, sionfrb, cf2frb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01frb, g02frb, g03frb, g04frb, g05frb, g06frb, 
     +                 g07frb, g08frb, g09frb, g10frb, g11frb, g12frb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      INTRINSIC ABS
