C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01frb = g01frb + g12frb
      g08frb = g08frb + g09frb + g12frb
      g11frb = g11frb - g09frb - g12frb
      g06frb = g06frb + g09frb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2frb = -(z10*g10frb) - z07*g07frb - z05*g05frb - z03*g03frb - 
     +    z01*g01frb - z02*g02frb - z04*g04frb - z06*g06frb - z08*g08frb
     +    - z11*g11frb
        g11frb = cf1*g11frb
        g10frb = cf1*g10frb
        g08frb = cf1*g08frb
        g07frb = cf1*g07frb
        g06frb = cf1*g06frb
        g05frb = cf1*g05frb
        g04frb = cf1*g04frb
        g03frb = cf1*g03frb
        g02frb = cf1*g02frb
        g01frb = cf1*g01frb
        temp0frb = (0.125d0-ti*0.005d0)*cf2frb
        temp0frb0 = -(0.41d0*temp0frb/(sion+1.d0))
        ionicfrb = ionicfrb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0frb
        sionfrb = (1.D0-sion/(sion+1.d0))*temp0frb0
