      CALL MKBI_FRB(q11, ionic, ionicfrb, sion, sionfrb, z11, g11, 
     +              g11frb)
      CALL MKBI_FRB(q10, ionic, ionicfrb, sion, sionfrb, z10, g10, 
     +              g10frb)
      CALL MKBI_FRB(q8, ionic, ionicfrb, sion, sionfrb, z08, g08, g08frb
     +             )
      CALL MKBI_FRB(q7, ionic, ionicfrb, sion, sionfrb, z07, g07, g07frb
     +             )
      CALL MKBI_FRB(q6, ionic, ionicfrb, sion, sionfrb, z06, g06, g06frb
     +             )
      CALL MKBI_FRB(q5, ionic, ionicfrb, sion, sionfrb, z05, g05, g05frb
     +             )
      CALL MKBI_FRB(q4, ionic, ionicfrb, sion, sionfrb, z04, g04, g04frb
     +             )
      CALL MKBI_FRB(q3, ionic, ionicfrb, sion, sionfrb, z03, g03, g03frb
     +             )
      CALL MKBI_FRB(q2, ionic, ionicfrb, sion, sionfrb, z02, g02, g02frb
     +             )
      CALL MKBI_FRB(q1, ionic, ionicfrb, sion, sionfrb, z01, g01, g01frb
     +             )
      IF (.NOT.ionic .EQ. 0.0) ionicfrb = ionicfrb + sionfrb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_FRB(q, ionic, ionicfrb, sion, sionfrb, zip, bi, 
     +                    bifrb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicfrb, sionfrb, bifrb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cfrb, xxfrb
      INTRINSIC EXP
      DOUBLE PRECISION tempfrb
      DOUBLE PRECISION tempfrb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxfrb = zip*bifrb
      bifrb = zip*bifrb/(bi*LOG(10.0))
      tempfrb = -(0.5107d0*xxfrb/(c*sion+1.d0))
      tempfrb0 = -(sion*tempfrb/(c*sion+1.d0))
      sionfrb = sionfrb + c*tempfrb0 + tempfrb
      cfrb = sion*tempfrb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicfrb = ionicfrb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cfrb
      ELSE
        ionicfrb = ionicfrb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bifrb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cfrb
      END IF
      END

