C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2gb
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2gb
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4gb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5gb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6gb
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrd
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      LOGICAL tst
      DOUBLE PRECISION lamda
      DOUBLE PRECISION wp(5), x1
      DOUBLE PRECISION wpgb(5)
      DOUBLE PRECISION aerliq(12), gas(3)
      DOUBLE PRECISION aerliqgb(12), gasgb(3)
      CHARACTER*40  ERRINF
      INTEGER errstki(25)
      CHARACTER*40 errmsgi(25)
      DOUBLE PRECISION feps
      INTEGER i
      DOUBLE PRECISION xt
      DOUBLE PRECISION xtd
      DOUBLE PRECISION y1
      DOUBLE PRECISION y1gb
      DOUBLE PRECISION y1d
      DOUBLE PRECISION y1dgb
      DOUBLE PRECISION x2
      DOUBLE PRECISION x2gb
      DOUBLE PRECISION y2
      DOUBLE PRECISION delta
      DOUBLE PRECISION deltagb
      INTEGER branch
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION abs1
      INTEGER ii1
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      COMMON /inpt_gb/ wgb
C
C *** SETUP PARAMETERS ************************************************
C
      feps = 1.d-5
C      w = wp
      IF (w(2) - 0.5d0*w(1) .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        chi2 = zero
      ELSE
        chi2 = w(2) - 0.5d0*w(1)
        CALL PUSHCONTROL1B(1)
      END IF
      IF (w(3) - 2.d0*chi2 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        chi4 = zero
      ELSE
        chi4 = w(3) - 2.d0*chi2
        CALL PUSHCONTROL1B(1)
      END IF
      chi5 = w(4)
      chi6 = w(5)
C 
      psi2 = chi2
C
C *** NEWTON-RAPHSON DETERMINATION OF ROOT **********************
C
      xt = x1
      xtd = 1.d0
      CALL PUSHREAL8ARRAY(gamagnrd, npair)
      CALL PUSHREAL8ARRAY(molalgnrd, nions)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
CCCC$AD NOCHECKPOINT
      CALL FUNCG5AB_GNRD(xt, xtd, y1, y1d)
      x2 = xt - y1/(y1d*1.d0)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
      CALL FUNCG5AB(x2, y2)
C      WRITE(*,*) 'x2 ',x2,' y2 ',y2
      IF (y2 .GE. 0.) THEN
        abs1 = y2
      ELSE
        abs1 = -y2
      END IF
C      CALL FUNCG5AB(XT,Y2)
C
      IF (abs1 .GT. feps) THEN
        DO ii1=1,nions
          molalgb(ii1) = 0.D0
        ENDDO
        DO ii1=1,npair
          gamagb(ii1) = 0.D0
        ENDDO
        watergb = 0.D0
        gnh3gb = 0.D0
        ghno3gb = 0.D0
        ghclgb = 0.D0
        WRITE(ERRINF, '(A,E12.5,A)') 'CALCG5 (',(Y1),')'
        CALL PUSHERR (0104, ERRINF)    ! WARNING ERROR: NO CONVERGENCE
        RETURN
      ELSE
C
        IF (molal(1) .GT. tiny .AND. molal(5) .GT. tiny) THEN
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        ghclgb = gasgb(3)
        gasgb(3) = 0.D0
        ghno3gb = gasgb(2)
        gasgb(2) = 0.D0
        gnh3gb = gasgb(1)
        gasgb(1) = 0.D0
        aerliqgb(nions+ngasaq+2) = 0.D0
        watergb = 1.0d3*aerliqgb(nions+1)/18.0d0
        aerliqgb(nions+1) = 0.D0
        DO i=ngasaq,1,-1
          aerliqgb(nions+1+i) = 0.D0
        ENDDO
        DO ii1=1,nions
          molalgb(ii1) = 0.D0
        ENDDO
        DO i=nions,1,-1
          molalgb(i) = molalgb(i) + aerliqgb(i)
          aerliqgb(i) = 0.D0
        ENDDO
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          DO ii1=1,npair
            gamagb(ii1) = 0.D0
          ENDDO
        ELSE
          deltagb = molalgb(6)
          molalgb(6) = 0.D0
          deltagb = deltagb - molalgb(1) - molalgb(5)
          CALL CALCHS4_GB(molal(1), molalgb(1), molal(5), molalgb(5), 
     +                    zero, delta, deltagb)
        END IF
      END IF
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL FUNCG5AB_GB(x2, x2gb, y2)
      y1gb = -(x2gb/y1d)
      y1dgb = y1*x2gb/y1d**2
C      WRITE(*,*) 'y1gb ',y1gb,'y1dgb ',y1dgb
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL POPREAL8ARRAY(molalgnrd, nions)
      CALL POPREAL8ARRAY(gamagnrd, npair)
      CALL FUNCG5AB_GNRD_GB(xt, xtd, y1, y1gb, y1d, y1dgb)
      chi2gb = psi2gb
      wgb(5) = wgb(5) + chi6gb
      wgb(4) = wgb(4) + chi5gb
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wgb(3) = wgb(3) + chi4gb
        chi2gb = chi2gb - 2.d0*chi4gb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wgb(2) = wgb(2) + chi2gb
        wgb(1) = wgb(1) - 0.5d0*chi2gb
      END IF
      DO ii1=1,5
        wpgb(ii1) = 0.D0
      ENDDO
      wpgb = wgb
C      PAUSE
      END

C  Differentiation of funcg5ab in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water gnh3 ghno3
C                ghcl
C   with respect to varying inputs: w molal molalr gama water gnh3
C                ghno3 ghcl chi4 chi5 chi6 psi2 x
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE FUNCG5A
C *** CASE G5
C
C     THE MAIN CHARACTERISTICS OF THIS REGIME ARE:
C     1. SULFATE POOR (SULRAT > 2.0) ; SODIUM POOR (SODRAT < 2.0)
C     2. THERE IS BOTH A LIQUID & SOLID PHASE
C     3. SOLIDS POSSIBLE : (NH4)2SO4, NH4CL, NA2SO4
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
