      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      LOGICAL tst
      INTEGER so4flg
      DOUBLE PRECISION lamda, fg5ab
      INTEGER i
      DOUBLE PRECISION akk
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbgb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccgb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddgb
      DOUBLE PRECISION smin
      DOUBLE PRECISION smingb
      DOUBLE PRECISION hi
