      INTEGER j
      INTEGER branch
      DOUBLE PRECISION x
      DOUBLE PRECISION xgb
      DOUBLE PRECISION temp3
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp4gb
      INTRINSIC MAX
      DOUBLE PRECISION temp2gb
      DOUBLE PRECISION temp5gb
      DOUBLE PRECISION temp0gb
      DOUBLE PRECISION temp3gb
      DOUBLE PRECISION temp5gb0
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1gb
      DOUBLE PRECISION temp4
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      COMMON /inpt_gb/ wgb
C
C *** SETUP PARAMETERS ************************************************
C
      psi6 = x
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
C      WRITE(*,*) 'NSWEEP ',NSWEEP,'WATER',WATER
      DO i=1,2
C
C      IF (I.GT.1) CALL CALCACT3P
C      WRITE(*,*) 'GAMA ', GAMA
C
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        a5 = xk4*r*temp*(water/gama(10))**2.0
        a6 = xk3*r*temp*(water/gama(11))**2.0
C        WRITE(*,*) 'a6/a5', a6/a5
C
C  CALCULATE DISSOCIATION QUANTITIES
C
        IF (chi5 .GE. tiny) THEN
          CALL PUSHREAL8(psi5)
          psi5 = psi6*chi5/(a6/a5*(chi6-psi6)+psi6)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(psi5)
          psi5 = tiny
          CALL PUSHCONTROL1B(1)
        END IF
C
CCC      IF(CHI4.GT.TINY) THEN
        IF (w(2) .GT. tiny) THEN
          CALL PUSHREAL8(bb)
C Accounts for NH3 evaporation
          bb = -(chi4+psi6+psi5+1.d0/a4)
          cc = chi4*(psi5+psi6) - 2.d0*psi2/a4
          IF (bb*bb - 4.d0*cc .LT. zero) THEN
            CALL PUSHREAL8(dd)
            dd = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(dd)
            dd = bb*bb - 4.d0*cc
            CALL PUSHCONTROL1B(1)
          END IF
          psi4 = 0.5d0*(-bb-SQRT(dd))
          CALL PUSHCONTROL1B(0)
        ELSE
          psi4 = tiny
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molal(2))
C
C *** CALCULATE SPECIATION ********************************************
C
C NAI
        molal(2) = w(1)
        CALL PUSHREAL8(molal(4))
C      MOLAL (3) = 2.0*PSI2 + PSI4                     ! NH4I
C CLI
        molal(4) = psi6
        IF (w(2) - 0.5d0*w(1) .GT. zero) THEN
          CALL PUSHREAL8(molal(3))
          molal(3) = 2.d0*w(2) - w(1) + psi4
          CALL PUSHREAL8(molal(5))
C SO4I
          molal(5) = w(2)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHREAL8(molal(3))
          molal(3) = psi4
          CALL PUSHREAL8(molal(5))
C SO4I
          molal(5) = 0.5d0*w(1)
          CALL PUSHCONTROL1B(0)
        END IF
        CALL PUSHREAL8(molal(6))
        molal(6) = zero
        CALL PUSHREAL8(molal(7))
C NO3I
        molal(7) = psi5
        CALL PUSHREAL8(smin)
C
C         SMIN      = 2.d0*MOLAL(5)+MOLAL(7)+MOLAL(4)-MOLAL(2)-MOLAL(3)
        smin = psi5 + psi6 - psi4
        CALL CALCPH(smin, hi, ohi)
        CALL PUSHREAL8(molal(1))
        molal(1) = hi
        IF (chi4 - psi4 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi5 - psi5 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi6 - psi6 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
C
C Solid (NH4)2SO4
C Solid NH4NO3
C Solid NH4Cl
C
C      CALL CALCMR                                     ! Water content
C
C      WRITE(*,*) 'MOLAL ',MOLAL
C NA2SO4
        molalr(2) = 0.5*w(1)
        IF (w(2) - 0.5d0*w(1) .GT. zero) THEN
C Total SO4
C (NH4)2SO4
          molalr(4) = w(2) - 0.5d0*w(1)
          IF (psi4 .LT. zero) THEN
            frnh4 = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            frnh4 = psi4
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
C Total SO4
C (NH4)2SO4
          molalr(4) = zero
          IF (2.d0*w(2) - w(1) + psi4 .LT. zero) THEN
            frnh4 = zero
            CALL PUSHCONTROL2B(3)
          ELSE
            frnh4 = 2.d0*w(2) - w(1) + psi4
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        IF (psi5 .LT. frnh4) THEN
          molalr(5) = psi5
          IF (frnh4 - psi5 .LT. zero) THEN
            frnh4 = zero
            CALL PUSHCONTROL2B(2)
          ELSE
            frnh4 = frnh4 - psi5
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
          molalr(5) = frnh4
          frnh4 = zero
          CALL PUSHCONTROL2B(0)
        END IF
        IF (psi6 .GT. frnh4) THEN
          molalr(6) = frnh4
          CALL PUSHCONTROL1B(0)
        ELSE
          molalr(6) = psi6
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C         WRITE(*,*) 'After CALCMR_AB: WATER ',WATER
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P()
      ENDDO
      DO ii1=1,ncomp
        wgb(ii1) = 0.D0
      ENDDO
      DO ii1=1,npair
        molalrgb(ii1) = 0.D0
      ENDDO
      chi4gb = 0.D0
      chi5gb = 0.D0
      chi6gb = 0.D0
      psi2gb = 0.D0
      psi6gb = 0.D0
      DO i=2,1,-1
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3P_GB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) watergb = 0.D0
        DO j=npair,1,-1
          molalrgb(j) = molalrgb(j) + watergb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          frnh4gb = molalrgb(6)
          molalrgb(6) = 0.D0
        ELSE
          psi6gb = psi6gb + molalrgb(6)
          molalrgb(6) = 0.D0
          frnh4gb = 0.D0
        END IF
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          frnh4gb = molalrgb(5)
          molalrgb(5) = 0.D0
          psi5gb = 0.D0
        ELSE
          IF (branch .EQ. 1) THEN
            psi5gb = -frnh4gb
          ELSE
            psi5gb = 0.D0
            frnh4gb = 0.D0
          END IF
          psi5gb = psi5gb + molalrgb(5)
          molalrgb(5) = 0.D0
        END IF
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            psi4gb = frnh4gb
          ELSE
            psi4gb = 0.D0
          END IF
          wgb(2) = wgb(2) + molalrgb(4)
          wgb(1) = wgb(1) - 0.5d0*molalrgb(4)
          molalrgb(4) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            wgb(2) = wgb(2) + 2.d0*frnh4gb
            wgb(1) = wgb(1) - frnh4gb
            psi4gb = frnh4gb
          ELSE
            psi4gb = 0.D0
          END IF
          molalrgb(4) = 0.D0
        END IF
        wgb(1) = wgb(1) + 0.5*molalrgb(2)
        molalrgb(2) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi6gb = chi6gb + ghclgb
          psi6gb = psi6gb - ghclgb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi5gb = chi5gb + ghno3gb
          psi5gb = psi5gb - ghno3gb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi4gb = chi4gb + gnh3gb
          psi4gb = psi4gb - gnh3gb
        END IF
        CALL POPREAL8(molal(1))
        higb = molalgb(1)
        molalgb(1) = 0.D0
        CALL CALCPH_GB(smin, smingb, hi, higb, ohi)
        CALL POPREAL8(smin)
        psi5gb = psi5gb + molalgb(7) + smingb
        psi6gb = psi6gb + smingb
        psi4gb = psi4gb - smingb
        CALL POPREAL8(molal(7))
        molalgb(7) = 0.D0
        CALL POPREAL8(molal(6))
        molalgb(6) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          wgb(1) = wgb(1) + 0.5d0*molalgb(5)
          molalgb(5) = 0.D0
          CALL POPREAL8(molal(3))
          psi4gb = psi4gb + molalgb(3)
          molalgb(3) = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          wgb(2) = wgb(2) + molalgb(5)
          molalgb(5) = 0.D0
          CALL POPREAL8(molal(3))
          wgb(2) = wgb(2) + 2.d0*molalgb(3)
          wgb(1) = wgb(1) - molalgb(3)
          psi4gb = psi4gb + molalgb(3)
          molalgb(3) = 0.D0
        END IF
        CALL POPREAL8(molal(4))
        psi6gb = psi6gb + molalgb(4)
        molalgb(4) = 0.D0
        CALL POPREAL8(molal(2))
        wgb(1) = wgb(1) + molalgb(2)
        molalgb(2) = 0.D0
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          bbgb = -(0.5d0*psi4gb)
          IF (dd .EQ. 0.0) THEN
            ddgb = 0.0
          ELSE
            ddgb = -(0.5d0*psi4gb/(2.0*SQRT(dd)))
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(dd)
            ccgb = 0.D0
          ELSE
            CALL POPREAL8(dd)
            bbgb = bbgb + 2*bb*ddgb
            ccgb = -(4.d0*ddgb)
          END IF
          temp5gb0 = -(2.d0*ccgb/a4)
          chi4gb = chi4gb + (psi5+psi6)*ccgb - bbgb
          psi5gb = psi5gb + chi4*ccgb - bbgb
          psi6gb = psi6gb + chi4*ccgb - bbgb
          psi2gb = psi2gb + temp5gb0
          a4gb = bbgb/a4**2 - psi2*temp5gb0/a4
          CALL POPREAL8(bb)
        ELSE
          a4gb = 0.D0
        END IF
        a5 = xk4*r*temp*(water/gama(10))**2.0
        a6 = xk3*r*temp*(water/gama(11))**2.0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(psi5)
          temp3 = a6/a5
          temp4 = (chi6-psi6)*temp3 + psi6
          temp5gb = psi5gb/temp4
          temp4gb = -(psi6*chi5*temp5gb/temp4)
          temp3gb = (chi6-psi6)*temp4gb/a5
          psi6gb = psi6gb + (1.D0-temp3)*temp4gb + chi5*temp5gb
          chi5gb = chi5gb + psi6*temp5gb
          chi6gb = chi6gb + temp3*temp4gb
          a6gb = temp3gb
          a5gb = -(temp3*temp3gb)
        ELSE
          CALL POPREAL8(psi5)
          a5gb = 0.D0
          a6gb = 0.D0
        END IF
        temp0 = gama(10)/gama(5)
        temp0gb = 2.0*temp0*xk2*r*temp*a4gb/(xkw*gama(5))
        temp1 = water/gama(10)
        temp1gb = 2.0*temp1*xk4*r*temp*a5gb/gama(10)
        temp2 = water/gama(11)
        temp2gb = 2.0*temp2*xk3*r*temp*a6gb/gama(11)
        watergb = watergb + temp1gb + temp2gb
        gamagb(11) = gamagb(11) - temp2*temp2gb
        gamagb(10) = gamagb(10) + temp0gb - temp1*temp1gb
        gamagb(5) = gamagb(5) - temp0*temp0gb
        gnh3gb = 0.D0
        ghno3gb = 0.D0
        ghclgb = 0.D0
      ENDDO
      xgb = psi6gb
      END

C
C  Differentiation of calchs4 in reverse (adjoint) mode:
C   gradient     of useful results: water hi so4i delta
C   with respect to varying inputs: gama water hi so4i
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHS4
C *** THIS SUBROUTINE CALCULATES THE HSO4 GENERATED FROM (H,SO4).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHS4_GB(hi, higb, so4i, so4igb, hso4i, delta, 
     +                      deltagb)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHS4 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wgb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watergb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2gb
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4gb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5gb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6gb
      DOUBLE PRECISION a8
      DOUBLE PRECISION a8gb
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrd
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION higb, so4igb, deltagb, bbgb, ccgb, ddgb, sqddgb, 
     +                 delta1gb, delta2gb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0gb
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1gb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      COMMON /inpt_gb/ wgb
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .LE. 1d1*tiny) THEN
        DO ii1=1,npair
          gamagb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2gb = deltagb
            delta1gb = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2gb = deltagb
            delta1gb = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1gb = deltagb
            ELSE
              delta1gb = 0.D0
            END IF
            delta2gb = 0.D0
          END IF
          bbgb = -(0.5*delta1gb) - 0.5*delta2gb
          sqddgb = 0.5*delta1gb - 0.5*delta2gb
          IF (dd .EQ. 0.0) THEN
            ddgb = 0.0
          ELSE
            ddgb = sqddgb/(2.0*SQRT(dd))
          END IF
        ELSE
          ddgb = 0.D0
          bbgb = 0.D0
        END IF
        bbgb = bbgb + 2*bb*ddgb
        ccgb = -(4.d0*ddgb)
        higb = higb + so4i*ccgb - bbgb
        so4igb = so4igb + hi*ccgb - bbgb
        a8gb = -bbgb - hso4i*ccgb
        DO ii1=1,npair
          gamagb(ii1) = 0.D0
        ENDDO
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1gb = 2.*temp1*temp0*xk1*a8gb/gama(7)
        temp0gb = temp1**2.*xk1*a8gb/gama(7)
        gamagb(8) = gamagb(8) + temp1gb
        gamagb(7) = gamagb(7) - temp0*temp0gb - temp1*temp1gb
        watergb = watergb + temp0gb
      END IF
      END

