      SUBROUTINE FUNCG5AB_GNRD_GB(x, xgnrd, fg5ab, fg5abgb, fg5abgnrd, 
     +                            fg5abgnrdgb)
      IMPLICIT NONE
C
C *** END OF FUNCTION FUNCG5A *******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
