      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION molalrgnrd(npair)
      DOUBLE PRECISION molalrgnrdgb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watergb
      DOUBLE PRECISION watergnrd
      DOUBLE PRECISION watergnrdgb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION ghclgnrd
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2gb
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi4gb
      DOUBLE PRECISION psi4gnrd
      DOUBLE PRECISION psi4gnrdgb
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi5gb
      DOUBLE PRECISION psi5gnrd
      DOUBLE PRECISION psi5gnrdgb
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi6gnrd
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4gb
      DOUBLE PRECISION a4gnrd
      DOUBLE PRECISION a4gnrdgb
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION a5gb
      DOUBLE PRECISION a5gnrd
      DOUBLE PRECISION a5gnrdgb
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4gb
      DOUBLE PRECISION a6
      DOUBLE PRECISION a6gb
      DOUBLE PRECISION a6gnrd
      DOUBLE PRECISION a6gnrdgb
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5gb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6gb
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
C      DOUBLE PRECISION molalgnrd(nions)
C      DOUBLE PRECISION gamagnrd(npair)
C      DOUBLE PRECISION watergnrd
C      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      LOGICAL tst
      INTEGER so4flg
      DOUBLE PRECISION lamda, fg5ab
      DOUBLE PRECISION fg5abgb
      DOUBLE PRECISION fg5abgnrd
      DOUBLE PRECISION fg5abgnrdgb
      INTEGER i
      DOUBLE PRECISION akk
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbgb
      DOUBLE PRECISION bbgnrd
      DOUBLE PRECISION bbgnrdgb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccgb
      DOUBLE PRECISION ccgnrd
      DOUBLE PRECISION ccgnrdgb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddgb
      DOUBLE PRECISION ddgnrd
      DOUBLE PRECISION ddgnrdgb
      DOUBLE PRECISION smin
      DOUBLE PRECISION smingb
      DOUBLE PRECISION smingnrd
      DOUBLE PRECISION smingnrdgb
      DOUBLE PRECISION hi
      DOUBLE PRECISION higb
      DOUBLE PRECISION hignrd
      DOUBLE PRECISION hignrdgb
      DOUBLE PRECISION ohi
      DOUBLE PRECISION tots4
      DOUBLE PRECISION frnh4
      DOUBLE PRECISION frnh4gb
      DOUBLE PRECISION frnh4gnrd
      DOUBLE PRECISION frnh4gnrdgb
      INTEGER j
      DOUBLE PRECISION result1
      DOUBLE PRECISION result1gb
      DOUBLE PRECISION result1gnrd
      DOUBLE PRECISION result1gnrdgb
      DOUBLE PRECISION x
      DOUBLE PRECISION xgnrd
      INTRINSIC MAX
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      INTEGER branch
      DOUBLE PRECISION temp3
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp20gb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp9gb
      DOUBLE PRECISION temp18gb
      DOUBLE PRECISION temp22
      DOUBLE PRECISION temp4gb
      DOUBLE PRECISION temp21
      DOUBLE PRECISION temp20
      DOUBLE PRECISION temp13gb
      DOUBLE PRECISION temp23gb1
      DOUBLE PRECISION temp23gb0
      DOUBLE PRECISION temp9gb0
      DOUBLE PRECISION temp23gb
      DOUBLE PRECISION temp7gb
      DOUBLE PRECISION temp16gb
      INTRINSIC ABS
      DOUBLE PRECISION temp2gb
      DOUBLE PRECISION temp19
      DOUBLE PRECISION temp11gb
      DOUBLE PRECISION temp18
      DOUBLE PRECISION temp17
      DOUBLE PRECISION temp16
      DOUBLE PRECISION temp15
      DOUBLE PRECISION temp14
      DOUBLE PRECISION temp13
      DOUBLE PRECISION temp12
      DOUBLE PRECISION temp11
      DOUBLE PRECISION temp10
      DOUBLE PRECISION temp21gb
      DOUBLE PRECISION temp1gb0
      DOUBLE PRECISION temp19gb
      DOUBLE PRECISION temp5gb
      DOUBLE PRECISION temp14gb
      DOUBLE PRECISION temp15gb0
      DOUBLE PRECISION temp0gb
      DOUBLE PRECISION temp3gb1
      DOUBLE PRECISION temp3gb0
      DOUBLE PRECISION temp8gb
      DOUBLE PRECISION temp17gb3
      DOUBLE PRECISION temp17gb
      DOUBLE PRECISION temp17gb2
      DOUBLE PRECISION temp17gb1
      DOUBLE PRECISION temp17gb0
      DOUBLE PRECISION temp3gb
      INTEGER ii10
      DOUBLE PRECISION temp5gb1
      DOUBLE PRECISION temp5gb0
      DOUBLE PRECISION abs1
      DOUBLE PRECISION temp6gb
      DOUBLE PRECISION temp15gb
      DOUBLE PRECISION temp1gb
      DOUBLE PRECISION temp10gb
      DOUBLE PRECISION temp9
      DOUBLE PRECISION temp8
      DOUBLE PRECISION temp7
      DOUBLE PRECISION temp6
      DOUBLE PRECISION temp5
      DOUBLE PRECISION temp4
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      COMMON /inpt_gb/ wgb
C
C *** SETUP PARAMETERS ************************************************
C
      psi6gnrd = xgnrd
      psi6 = x
      DO ii1=1,nions
        molalgnrd(ii1) = 0.d0
      ENDDO
      DO ii1=1,npair
        molalrgnrd(ii1) = 0.d0
      ENDDO
      DO ii1=1,npair
        gamagnrd(ii1) = 0.d0
      ENDDO
      watergnrd = 0.d0
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
C      WRITE(*,*) 'NSWEEP ',NSWEEP,'WATER',WATER
      DO i=1,2
        CALL PUSHREAL8(a4gnrd)
C
C      IF (I.GT.1) CALL CALCACT3P
C      WRITE(*,*) 'GAMA ', GAMA
C
        a4gnrd = xk2*r*temp*2.0*gama(10)*(gamagnrd(10)*gama(5)-gama(10)*
     +    gamagnrd(5))/(xkw*gama(5)**3)
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        CALL PUSHREAL8(a5gnrd)
        a5gnrd = xk4*r*temp*2.0*water*(watergnrd*gama(10)-water*gamagnrd
     +    (10))/gama(10)**3
        a5 = xk4*r*temp*(water/gama(10))**2.0
        CALL PUSHREAL8(a6gnrd)
        a6gnrd = xk3*r*temp*2.0*water*(watergnrd*gama(11)-water*gamagnrd
     +    (11))/gama(11)**3
        CALL PUSHREAL8(a6)
        a6 = xk3*r*temp*(water/gama(11))**2.0
C
C  CALCULATE DISSOCIATION QUANTITIES
C
        IF (chi5 .GE. tiny) THEN
          CALL PUSHREAL8(psi5gnrd)
          psi5gnrd = (chi5*psi6gnrd*(a6/a5*(chi6-psi6)+psi6)-psi6*chi5*(
     +      (a6gnrd*a5-a6*a5gnrd)*(chi6-psi6)/a5**2-a6*psi6gnrd/a5+
     +      psi6gnrd))/(a6/a5*(chi6-psi6)+psi6)**2
          CALL PUSHREAL8(psi5)
          psi5 = psi6*chi5/(a6/a5*(chi6-psi6)+psi6)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(psi5)
          psi5 = tiny
          CALL PUSHREAL8(psi5gnrd)
          psi5gnrd = 0.d0
          CALL PUSHCONTROL1B(1)
        END IF
C
CCC      IF(CHI4.GT.TINY) THEN
        IF (w(2) .GT. tiny) THEN
          CALL PUSHREAL8(bbgnrd)
C Accounts for NH3 evaporation
          bbgnrd = -(psi6gnrd+psi5gnrd-a4gnrd/a4**2)
          CALL PUSHREAL8(bb)
          bb = -(chi4+psi6+psi5+1.d0/a4)
          ccgnrd = chi4*(psi5gnrd+psi6gnrd) + 2.d0*psi2*a4gnrd/a4**2
          cc = chi4*(psi5+psi6) - 2.d0*psi2/a4
          IF (bb*bb - 4.d0*cc .LT. zero) THEN
            CALL PUSHREAL8(dd)
            dd = zero
            CALL PUSHREAL8(ddgnrd)
            ddgnrd = 0.d0
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHREAL8(ddgnrd)
            ddgnrd = bbgnrd*bb + bb*bbgnrd - 4.d0*ccgnrd
            CALL PUSHREAL8(dd)
            dd = bb*bb - 4.d0*cc
            CALL PUSHCONTROL1B(0)
          END IF
          IF (dd .GE. 0.) THEN
            abs1 = dd
          ELSE
            abs1 = -dd
          END IF
          IF (abs1 .LT. tiny) THEN
            result1gnrd = 0.d0
            CALL PUSHCONTROL1B(0)
          ELSE
            result1gnrd = ddgnrd/(2.0*SQRT(dd))
            CALL PUSHCONTROL1B(1)
          END IF
          result1 = SQRT(dd)
          psi4gnrd = 0.5d0*(-bbgnrd-result1gnrd)
          psi4 = 0.5d0*(-bb-result1)
          CALL PUSHCONTROL1B(0)
        ELSE
          psi4 = tiny
          psi4gnrd = 0.d0
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molalgnrd(2))
C
C *** CALCULATE SPECIATION ********************************************
C
C NAI
        molalgnrd(2) = 0.d0
        CALL PUSHREAL8(molal(2))
        molal(2) = w(1)
        CALL PUSHREAL8(molalgnrd(4))
C      MOLAL (3) = 2.0*PSI2 + PSI4                     ! NH4I
C CLI
        molalgnrd(4) = psi6gnrd
        CALL PUSHREAL8(molal(4))
        molal(4) = psi6
        IF (w(2) - 0.5d0*w(1) .GT. zero) THEN
          CALL PUSHREAL8(molalgnrd(3))
          molalgnrd(3) = psi4gnrd
          CALL PUSHREAL8(molal(3))
          molal(3) = 2.d0*w(2) - w(1) + psi4
          CALL PUSHREAL8(molalgnrd(5))
C SO4I
          molalgnrd(5) = 0.d0
          CALL PUSHREAL8(molal(5))
          molal(5) = w(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(molalgnrd(3))
          molalgnrd(3) = psi4gnrd
          CALL PUSHREAL8(molal(3))
          molal(3) = psi4
          CALL PUSHREAL8(molalgnrd(5))
C SO4I
          molalgnrd(5) = 0.d0
          CALL PUSHREAL8(molal(5))
          molal(5) = 0.5d0*w(1)
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molalgnrd(6))
        molalgnrd(6) = 0.d0
        CALL PUSHREAL8(molal(6))
        molal(6) = zero
        CALL PUSHREAL8(molalgnrd(7))
C NO3I
        molalgnrd(7) = psi5gnrd
        CALL PUSHREAL8(molal(7))
        molal(7) = psi5
        CALL PUSHREAL8(smingnrd)
C
C         SMIN      = 2.d0*MOLAL(5)+MOLAL(7)+MOLAL(4)-MOLAL(2)-MOLAL(3)
        smingnrd = psi5gnrd + psi6gnrd - psi4gnrd
        CALL PUSHREAL8(smin)
        smin = psi5 + psi6 - psi4
        CALL CALCPH_GNRD(smin, smingnrd, hi, hignrd, ohi)
        CALL PUSHREAL8(molalgnrd(1))
        molalgnrd(1) = hignrd
        CALL PUSHREAL8(molal(1))
        molal(1) = hi
        IF (chi4 - psi4 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi5 - psi5 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi6 - psi6 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
          ghcl = tiny
          ghclgnrd = 0.d0
        ELSE
          ghclgnrd = -psi6gnrd
          ghcl = chi6 - psi6
          CALL PUSHCONTROL1B(1)
        END IF
C
C Solid (NH4)2SO4
C Solid NH4NO3
C Solid NH4Cl
C
C      CALL CALCMR                                     ! Water content
C
C      WRITE(*,*) 'MOLAL ',MOLAL
C NA2SO4
        molalrgnrd(2) = 0.d0
        molalr(2) = 0.5*w(1)
        IF (w(2) - 0.5d0*w(1) .GT. zero) THEN
C Total SO4
C (NH4)2SO4
          molalrgnrd(4) = 0.d0
          molalr(4) = w(2) - 0.5d0*w(1)
          IF (psi4 .LT. zero) THEN
            frnh4 = zero
            frnh4gnrd = 0.d0
            CALL PUSHCONTROL2B(0)
          ELSE
            frnh4gnrd = psi4gnrd
            frnh4 = psi4
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
C Total SO4
C (NH4)2SO4
          molalrgnrd(4) = 0.d0
          molalr(4) = zero
          IF (2.d0*w(2) - w(1) + psi4 .LT. zero) THEN
            frnh4 = zero
            frnh4gnrd = 0.d0
            CALL PUSHCONTROL2B(2)
          ELSE
            frnh4gnrd = psi4gnrd
            frnh4 = 2.d0*w(2) - w(1) + psi4
            CALL PUSHCONTROL2B(3)
          END IF
        END IF
        IF (psi5 .LT. frnh4) THEN
          molalrgnrd(5) = psi5gnrd
          molalr(5) = psi5
          IF (frnh4 - psi5 .LT. zero) THEN
            frnh4 = zero
            frnh4gnrd = 0.d0
            CALL PUSHCONTROL2B(0)
          ELSE
            frnh4gnrd = frnh4gnrd - psi5gnrd
            frnh4 = frnh4 - psi5
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
          molalrgnrd(5) = frnh4gnrd
          molalr(5) = frnh4
          frnh4 = zero
          frnh4gnrd = 0.d0
          CALL PUSHCONTROL2B(2)
        END IF
        IF (psi6 .GT. frnh4) THEN
          molalrgnrd(6) = frnh4gnrd
          molalr(6) = frnh4
          CALL PUSHCONTROL1B(0)
        ELSE
          molalrgnrd(6) = psi6gnrd
          molalr(6) = psi6
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        CALL PUSHREAL8(watergnrd)
        watergnrd = 0.d0
        DO j=1,npair
          watergnrd = watergnrd + molalrgnrd(j)/m0(j)
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          watergnrd = 0.d0
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gamagnrd, npair)
        CALL PUSHREAL8ARRAY(gama, npair)
C         WRITE(*,*) 'After CALCMR: WATER ',WATER
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P_GNRD()
      ENDDO
      temp23gb1 = fg5abgnrdgb/a6**2
      temp22 = ghcl**2
      temp19 = a6/temp22
      temp20gb = temp19*temp23gb1
      temp21gb = ghcl*temp20gb
      temp21 = molalgnrd(1)*molal(4) + molal(1)*molalgnrd(4)
      temp20 = temp21*ghcl - ghclgnrd*molal(1)*molal(4)
      temp19gb = temp20*temp23gb1/temp22
      temp18 = a6gnrd/ghcl
      temp18gb = -(molal(1)*molal(4)*temp23gb1/ghcl)
      temp23gb = fg5abgb/(ghcl*a6)
      temp23gb0 = -(molal(1)*molal(4)*temp23gb/(ghcl*a6))
      molalgb(1) = molalgb(1) + molal(4)*temp23gb
      molalgb(4) = molalgb(4) + molalgnrd(1)*temp21gb - ghclgnrd*molal(1
     +  )*temp20gb - temp18*molal(1)*temp23gb1 + molal(1)*temp23gb
      ghclgb = ghclgb + temp21*temp20gb - temp19*2*ghcl*temp19gb - 
     +  temp18*temp18gb + a6*temp23gb0
      a6gb = temp19gb - (temp20*temp19-molal(1)*molal(4)*temp18)*2*
     +  temp23gb1/a6 + ghcl*temp23gb0
      DO ii10=1,nions
        molalgnrdgb(ii10) = 0.D0
      ENDDO
      molalgnrdgb(1) = molalgnrdgb(1) + molal(4)*temp21gb
      molalgb(1) = molalgb(1) + molalgnrd(4)*temp21gb - ghclgnrd*molal(4
     +  )*temp20gb - temp18*molal(4)*temp23gb1
      molalgnrdgb(4) = molalgnrdgb(4) + molal(1)*temp21gb
      a6gnrdgb = temp18gb
      DO ii10=1,npair
        gamagnrdgb(ii10) = 0.D0
      ENDDO
      watergnrdgb = 0.D0
      DO ii10=1,npair
        molalrgnrdgb(ii10) = 0.D0
      ENDDO
      DO i=2,1,-1
        CALL POPREAL8ARRAY(gama, npair)
        CALL POPREAL8ARRAY(gamagnrd, npair)
        CALL CALCACT3P_GNRD_GB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          watergb = 0.D0
          watergnrdgb = 0.D0
        END IF
        DO j=npair,1,-1
          molalrgb(j) = molalrgb(j) + watergb/m0(j)
          molalrgnrdgb(j) = molalrgnrdgb(j) + watergnrdgb/m0(j)
        ENDDO
        CALL POPREAL8(watergnrd)
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          frnh4gb = molalrgb(6)
          molalrgb(6) = 0.D0
          frnh4gnrdgb = molalrgnrdgb(6)
          molalrgnrdgb(6) = 0.D0
        ELSE
          molalrgb(6) = 0.D0
          molalrgnrdgb(6) = 0.D0
          frnh4gb = 0.D0
          frnh4gnrdgb = 0.D0
        END IF
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          psi5gb = 0.D0
          psi5gnrdgb = 0.D0
          frnh4gb = 0.D0
          frnh4gnrdgb = 0.D0
        ELSE IF (branch .EQ. 1) THEN
          psi5gb = -frnh4gb
          psi5gnrdgb = -frnh4gnrdgb
        ELSE
          frnh4gb = molalrgb(5)
          molalrgb(5) = 0.D0
          frnh4gnrdgb = molalrgnrdgb(5)
          molalrgnrdgb(5) = 0.D0
          psi5gb = 0.D0
          psi5gnrdgb = 0.D0
          GOTO 100
        END IF
        psi5gb = psi5gb + molalrgb(5)
        molalrgb(5) = 0.D0
        psi5gnrdgb = psi5gnrdgb + molalrgnrdgb(5)
        molalrgnrdgb(5) = 0.D0
 100    CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            psi4gb = 0.D0
            psi4gnrdgb = 0.D0
          ELSE
            psi4gb = frnh4gb
            psi4gnrdgb = frnh4gnrdgb
          END IF
          wgb(2) = wgb(2) + molalrgb(4)
          wgb(1) = wgb(1) - 0.5d0*molalrgb(4)
          molalrgb(4) = 0.D0
          molalrgnrdgb(4) = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            psi4gb = 0.D0
            psi4gnrdgb = 0.D0
          ELSE
            wgb(2) = wgb(2) + 2.d0*frnh4gb
            wgb(1) = wgb(1) - frnh4gb
            psi4gb = frnh4gb
            psi4gnrdgb = frnh4gnrdgb
          END IF
          molalrgb(4) = 0.D0
          molalrgnrdgb(4) = 0.D0
        END IF
        wgb(1) = wgb(1) + 0.5*molalrgb(2)
        molalrgb(2) = 0.D0
        molalrgnrdgb(2) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) chi6gb = chi6gb + ghclgb
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi5gb = chi5gb + ghno3gb
          psi5gb = psi5gb - ghno3gb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi4gb = chi4gb + gnh3gb
          psi4gb = psi4gb - gnh3gb
        END IF
        CALL POPREAL8(molal(1))
        higb = molalgb(1)
        molalgb(1) = 0.D0
        CALL POPREAL8(molalgnrd(1))
        hignrdgb = molalgnrdgb(1)
        molalgnrdgb(1) = 0.D0
        CALL CALCPH_GNRD_GB(smin, smingb, smingnrd, smingnrdgb, hi, higb
     +                      , hignrd, hignrdgb, ohi)
        CALL POPREAL8(smin)
        psi5gb = psi5gb + molalgb(7) + smingb
        psi4gb = psi4gb - smingb
        CALL POPREAL8(smingnrd)
        psi5gnrdgb = psi5gnrdgb + molalgnrdgb(7) + smingnrdgb
        psi4gnrdgb = psi4gnrdgb - smingnrdgb
        CALL POPREAL8(molal(7))
        molalgb(7) = 0.D0
        CALL POPREAL8(molalgnrd(7))
        molalgnrdgb(7) = 0.D0
        CALL POPREAL8(molal(6))
        molalgb(6) = 0.D0
        CALL POPREAL8(molalgnrd(6))
        molalgnrdgb(6) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(molal(5))
          wgb(2) = wgb(2) + molalgb(5)
          molalgb(5) = 0.D0
          CALL POPREAL8(molalgnrd(5))
          molalgnrdgb(5) = 0.D0
          CALL POPREAL8(molal(3))
          wgb(2) = wgb(2) + 2.d0*molalgb(3)
          wgb(1) = wgb(1) - molalgb(3)
          psi4gb = psi4gb + molalgb(3)
          molalgb(3) = 0.D0
          CALL POPREAL8(molalgnrd(3))
          psi4gnrdgb = psi4gnrdgb + molalgnrdgb(3)
          molalgnrdgb(3) = 0.D0
        ELSE
          CALL POPREAL8(molal(5))
          wgb(1) = wgb(1) + 0.5d0*molalgb(5)
          molalgb(5) = 0.D0
          CALL POPREAL8(molalgnrd(5))
          molalgnrdgb(5) = 0.D0
          CALL POPREAL8(molal(3))
          psi4gb = psi4gb + molalgb(3)
          molalgb(3) = 0.D0
          CALL POPREAL8(molalgnrd(3))
          psi4gnrdgb = psi4gnrdgb + molalgnrdgb(3)
          molalgnrdgb(3) = 0.D0
        END IF
        CALL POPREAL8(molal(4))
        molalgb(4) = 0.D0
        CALL POPREAL8(molalgnrd(4))
        molalgnrdgb(4) = 0.D0
        CALL POPREAL8(molal(2))
        wgb(1) = wgb(1) + molalgb(2)
        molalgb(2) = 0.D0
        CALL POPREAL8(molalgnrd(2))
        molalgnrdgb(2) = 0.D0
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          bbgb = -(0.5d0*psi4gb)
          result1gb = -(0.5d0*psi4gb)
          bbgnrdgb = -(0.5d0*psi4gnrdgb)
          result1gnrdgb = -(0.5d0*psi4gnrdgb)
          IF (dd .EQ. 0.0) THEN
            ddgb = 0.0
          ELSE
            ddgb = result1gb/(2.0*SQRT(dd))
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            ddgnrdgb = 0.D0
          ELSE
            temp17 = SQRT(dd)
            temp17gb3 = result1gnrdgb/(2.0*temp17)
            ddgnrdgb = temp17gb3
            IF (.NOT.dd .EQ. 0.0) ddgb = ddgb - ddgnrd*temp17gb3/(2.0*
     +          temp17**2)
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(dd)
            bbgb = bbgb + 2*bbgnrd*ddgnrdgb + 2*bb*ddgb
            ccgb = -(4.d0*ddgb)
            CALL POPREAL8(ddgnrd)
            bbgnrdgb = bbgnrdgb + 2*bb*ddgnrdgb
            ccgnrdgb = -(4.d0*ddgnrdgb)
          ELSE
            CALL POPREAL8(ddgnrd)
            CALL POPREAL8(dd)
            ccgnrdgb = 0.D0
            ccgb = 0.D0
          END IF
          temp17gb2 = bbgnrdgb/a4**2
          temp17gb1 = 2.d0*ccgnrdgb/a4**2
          temp17gb0 = -(2.d0*ccgb/a4)
          chi4gb = chi4gb + (psi6gnrd+psi5gnrd)*ccgnrdgb - bbgb + (psi6+
     +      psi5)*ccgb
          psi5gb = psi5gb + chi4*ccgb - bbgb
          psi2gb = psi2gb + a4gnrd*temp17gb1 + temp17gb0
          a4gb = bbgb/a4**2 - a4gnrd*2*temp17gb2/a4 - psi2*a4gnrd*2*
     +      temp17gb1/a4 - psi2*temp17gb0/a4
          psi5gnrdgb = psi5gnrdgb + chi4*ccgnrdgb - bbgnrdgb
          a4gnrdgb = temp17gb2 + psi2*temp17gb1
          CALL POPREAL8(bb)
          CALL POPREAL8(bbgnrd)
        ELSE
          a4gb = 0.D0
          a4gnrdgb = 0.D0
        END IF
        a5 = xk4*r*temp*(water/gama(10))**2.0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          temp7 = a6/a5
          temp8 = psi6 + (chi6-psi6)*temp7
          temp15gb0 = psi5gnrdgb/temp8**2
          temp13 = a6/a5
          temp14 = psi6 + (chi6-psi6)*temp13
          temp14gb = psi6gnrd*temp15gb0
          temp13gb = (chi6-psi6)*chi5*temp14gb/a5
          temp12 = a5**2
          temp9 = (chi6-psi6)/temp12
          temp10 = a6gnrd*a5 - a6*a5gnrd
          temp11 = psi6gnrd + temp10*temp9 - psi6gnrd*a6/a5
          temp11gb = -(psi6*chi5*temp15gb0)
          temp10gb = temp9*temp11gb
          temp9gb = temp10*temp11gb/temp12
          temp9gb0 = -(psi6gnrd*temp11gb/a5)
          temp8gb = -((psi6gnrd*(chi5*temp14)-psi6*(chi5*temp11))*2*
     +      temp15gb0/temp8)
          temp7gb = (chi6-psi6)*temp8gb/a5
          CALL POPREAL8(psi5)
          temp15 = a6/a5
          temp16 = psi6 + (chi6-psi6)*temp15
          temp17gb = psi6*psi5gb/temp16
          temp16gb = -(chi5*temp17gb/temp16)
          temp15gb = (chi6-psi6)*temp16gb/a5
          chi5gb = chi5gb + temp14*temp14gb - psi6*temp11*temp15gb0 + 
     +      temp17gb
          chi6gb = chi6gb + chi5*temp13*temp14gb + temp9gb + temp7*
     +      temp8gb + temp15*temp16gb
          a6gb = a6gb + temp13gb - a5gnrd*temp10gb + temp9gb0 + temp7gb 
     +      + temp15gb
          a5gb = a6gnrd*temp10gb - temp13*temp13gb - temp9*2*a5*temp9gb 
     +      - a6*temp9gb0/a5 - temp7*temp7gb - temp15*temp15gb
          CALL POPREAL8(psi5gnrd)
          a6gnrdgb = a6gnrdgb + a5*temp10gb
          a5gnrdgb = -(a6*temp10gb)
        ELSE
          CALL POPREAL8(psi5gnrd)
          CALL POPREAL8(psi5)
          a5gb = 0.D0
          a5gnrdgb = 0.D0
        END IF
        temp1 = xkw*gama(5)**3
        temp0 = gama(10)/temp1
        temp1gb0 = xk2*2.0*r*temp*a4gnrdgb
        temp1gb = temp0*temp1gb0
        temp0gb = (gamagnrd(10)*gama(5)-gama(10)*gamagnrd(5))*temp1gb0/
     +    temp1
        temp2 = gama(10)/gama(5)
        temp2gb = 2.0*temp2*xk2*r*temp*a4gb/(xkw*gama(5))
        temp3 = gama(10)**3
        temp3gb1 = xk4*2.0*r*temp*a5gnrdgb
        temp3gb = water*temp3gb1/temp3
        temp3gb0 = (watergnrd*gama(10)-water*gamagnrd(10))*temp3gb1/
     +    temp3
        temp4 = water/gama(10)
        temp4gb = 2.0*temp4*xk4*r*temp*a5gb/gama(10)
        temp5 = gama(11)**3
        temp5gb1 = xk3*2.0*r*temp*a6gnrdgb
        temp5gb = water*temp5gb1/temp5
        temp5gb0 = (watergnrd*gama(11)-water*gamagnrd(11))*temp5gb1/
     +    temp5
        CALL POPREAL8(a6)
        temp6 = water/gama(11)
        temp6gb = 2.0*temp6*xk3*r*temp*a6gb/gama(11)
        watergb = watergb + temp5gb0 - gamagnrd(11)*temp5gb - gamagnrd(
     +    10)*temp3gb + temp3gb0 + temp4gb + temp6gb
        gamagb(11) = gamagb(11) + watergnrd*temp5gb - water*3*gama(11)**
     +    2*temp5gb0/temp5 - temp6*temp6gb
        CALL POPREAL8(a6gnrd)
        watergnrdgb = watergnrdgb + gama(10)*temp3gb + gama(11)*temp5gb
        gamagnrdgb(11) = gamagnrdgb(11) - water*temp5gb
        gamagb(10) = gamagb(10) + watergnrd*temp3gb - water*3*gama(10)**
     +    2*temp3gb0/temp3 + temp2gb - temp4*temp4gb
        CALL POPREAL8(a5gnrd)
        gamagnrdgb(10) = gamagnrdgb(10) + gama(5)*temp1gb - water*
     +    temp3gb
        gamagb(5) = gamagb(5) + gamagnrd(10)*temp1gb - xkw*temp0*3*gama(
     +    5)**2*temp0gb - temp2*temp2gb
        CALL POPREAL8(a4gnrd)
        gamagb(10) = gamagb(10) + temp0gb - gamagnrd(5)*temp1gb
        gamagnrdgb(5) = gamagnrdgb(5) - gama(10)*temp1gb
        gnh3gb = 0.D0
        ghno3gb = 0.D0
        ghclgb = 0.D0
        a6gb = 0.D0
        a6gnrdgb = 0.D0
      ENDDO
      END

C  Differentiation of calcph_gnrd in reverse (adjoint) mode:
C   gradient     of useful results: hi hignrd
C   with respect to varying inputs: water watergnrd gggnrd gg
C
C  Differentiation of calcph in forward (tangent) mode:
C   variations   of useful results: hi
C   with respect to varying inputs: water gg
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCPH
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCPH_GNRD_GB(gg, gggb, gggnrd, gggnrdgb, hi, higb, 
     +                          hignrd, hignrdgb, ohi)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCPH ******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wgb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION watergb
      DOUBLE PRECISION watergnrd
      DOUBLE PRECISION watergnrdgb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2gb
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4gb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5gb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6gb
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
C      DOUBLE PRECISION molalgnrd(nions)
C      DOUBLE PRECISION gamagnrd(npair)
C      DOUBLE PRECISION watergnrd
C      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION cn, gg, hi, ohi, bb, cc, dd
      DOUBLE PRECISION cngb, gggb, higb, ohigb, bbgb, ccgb, ddgb
      DOUBLE PRECISION cngnrd, gggnrd, hignrd, ohignrd, bbgnrd, ccgnrd, 
     +                 ddgnrd
      DOUBLE PRECISION cngnrdgb, gggnrdgb, hignrdgb, ohignrdgb, bbgnrdgb
     +                 , ccgnrdgb, ddgnrdgb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwgb
      DOUBLE PRECISION akwgnrd
      DOUBLE PRECISION akwgnrdgb
      DOUBLE PRECISION result1
      DOUBLE PRECISION result1gb
      DOUBLE PRECISION result1gnrd
      DOUBLE PRECISION result1gnrdgb
      DOUBLE PRECISION x2gnrd
      DOUBLE PRECISION x2gnrdgb
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x2gb
      DOUBLE PRECISION x1gnrd
      DOUBLE PRECISION x1gnrdgb
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1gb
      INTRINSIC SQRT
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      INTEGER branch
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC ABS
      DOUBLE PRECISION temp2gb
      DOUBLE PRECISION temp0gb0
      DOUBLE PRECISION temp0gb
      DOUBLE PRECISION temp3gb
      DOUBLE PRECISION abs3
      DOUBLE PRECISION abs2
      DOUBLE PRECISION abs1
      DOUBLE PRECISION temp1gb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      COMMON /inpt_gb/ wgb
C
      akwgnrd = xkw*rh*(watergnrd*water+water*watergnrd)
      akw = xkw*rh*water*water
      IF (akw .GE. 0.) THEN
        abs1 = akw
      ELSE
        abs1 = -akw
      END IF
      IF (abs1 .LT. tiny) THEN
        CALL PUSHCONTROL1B(0)
        cngnrd = 0.d0
      ELSE
        cngnrd = akwgnrd/(2.0*SQRT(akw))
        CALL PUSHCONTROL1B(1)
      END IF
      cn = SQRT(akw)
C
C *** GG = (negative charge) - (positive charge)
C
      IF (gg .GT. tiny) THEN
C H+ in excess
        bbgnrd = -gggnrd
        bb = -gg
        ccgnrd = -akwgnrd
        cc = -akw
        ddgnrd = bbgnrd*bb + bb*bbgnrd - 4.d0*ccgnrd
        dd = bb*bb - 4.d0*cc
        IF (dd .GE. 0.) THEN
          abs2 = dd
        ELSE
          abs2 = -dd
        END IF
        IF (abs2 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        result1 = SQRT(dd)
        x1 = 0.5d0*(-bb+result1)
        IF (x1 .LT. cn) THEN
          cngb = higb
          cngnrdgb = hignrdgb
          x1gb = 0.D0
          x1gnrdgb = 0.D0
        ELSE
          x1gb = higb
          x1gnrdgb = hignrdgb
          cngb = 0.D0
          cngnrdgb = 0.D0
        END IF
        result1gb = 0.5d0*x1gb
        bbgb = -(0.5d0*x1gb)
        result1gnrdgb = 0.5d0*x1gnrdgb
        bbgnrdgb = -(0.5d0*x1gnrdgb)
        IF (dd .EQ. 0.0) THEN
          ddgb = 0.0
        ELSE
          ddgb = result1gb/(2.0*SQRT(dd))
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          ddgnrdgb = 0.D0
        ELSE
          temp1 = SQRT(dd)
          temp1gb = result1gnrdgb/(2.0*temp1)
          ddgnrdgb = temp1gb
          IF (.NOT.dd .EQ. 0.0) ddgb = ddgb - ddgnrd*temp1gb/(2.0*temp1
     +        **2)
        END IF
        bbgb = bbgb + 2*bbgnrd*ddgnrdgb + 2*bb*ddgb
        ccgb = -(4.d0*ddgb)
        bbgnrdgb = bbgnrdgb + 2*bb*ddgnrdgb
        ccgnrdgb = -(4.d0*ddgnrdgb)
        akwgb = -ccgb
        akwgnrdgb = -ccgnrdgb
        gggb = -bbgb
        gggnrdgb = -bbgnrdgb
      ELSE
C OH- in excess
        bbgnrd = gggnrd
        bb = gg
        ccgnrd = -akwgnrd
        cc = -akw
        ddgnrd = bbgnrd*bb + bb*bbgnrd - 4.d0*ccgnrd
        dd = bb*bb - 4.d0*cc
        IF (dd .GE. 0.) THEN
          abs3 = dd
        ELSE
          abs3 = -dd
        END IF
        IF (abs3 .LT. tiny) THEN
          result1gnrd = 0.d0
          CALL PUSHCONTROL1B(0)
        ELSE
          result1gnrd = ddgnrd/(2.0*SQRT(dd))
          CALL PUSHCONTROL1B(1)
        END IF
        result1 = SQRT(dd)
        x2gnrd = 0.5d0*(result1gnrd-bbgnrd)
        x2 = 0.5d0*(-bb+result1)
        IF (x2 .LT. cn) THEN
          ohignrd = cngnrd
          ohi = cn
          CALL PUSHCONTROL1B(0)
        ELSE
          ohignrd = x2gnrd
          ohi = x2
          CALL PUSHCONTROL1B(1)
        END IF
        temp3gb = hignrdgb/ohi**2
        akwgb = higb/ohi - ohignrd*temp3gb
        ohigb = (akwgnrd-(akwgnrd*ohi-akw*ohignrd)*2/ohi)*temp3gb - akw*
     +    higb/ohi**2
        akwgnrdgb = ohi*temp3gb
        ohignrdgb = -(akw*temp3gb)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          cngb = ohigb
          cngnrdgb = ohignrdgb
          x2gb = 0.D0
          x2gnrdgb = 0.D0
        ELSE
          x2gb = ohigb
          x2gnrdgb = ohignrdgb
          cngb = 0.D0
          cngnrdgb = 0.D0
        END IF
        result1gb = 0.5d0*x2gb
        bbgb = -(0.5d0*x2gb)
        result1gnrdgb = 0.5d0*x2gnrdgb
        bbgnrdgb = -(0.5d0*x2gnrdgb)
        IF (dd .EQ. 0.0) THEN
          ddgb = 0.0
        ELSE
          ddgb = result1gb/(2.0*SQRT(dd))
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          ddgnrdgb = 0.D0
        ELSE
          temp2 = SQRT(dd)
          temp2gb = result1gnrdgb/(2.0*temp2)
          ddgnrdgb = temp2gb
          IF (.NOT.dd .EQ. 0.0) ddgb = ddgb - ddgnrd*temp2gb/(2.0*temp2
     +        **2)
        END IF
        bbgb = bbgb + 2*bbgnrd*ddgnrdgb + 2*bb*ddgb
        ccgb = -(4.d0*ddgb)
        bbgnrdgb = bbgnrdgb + 2*bb*ddgnrdgb
        ccgnrdgb = -(4.d0*ddgnrdgb)
        akwgb = akwgb - ccgb
        akwgnrdgb = akwgnrdgb - ccgnrdgb
        gggb = bbgb
        gggnrdgb = bbgnrdgb
      END IF
      IF (.NOT.akw .EQ. 0.0) akwgb = akwgb + cngb/(2.0*SQRT(akw))
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        temp0 = SQRT(akw)
        temp0gb0 = cngnrdgb/(2.0*temp0)
        akwgnrdgb = akwgnrdgb + temp0gb0
        IF (.NOT.akw .EQ. 0.0) akwgb = akwgb - akwgnrd*temp0gb0/(2.0*
     +      temp0**2)
      END IF
      temp0gb = xkw*rh*akwgnrdgb
      watergb = 2*watergnrd*temp0gb + xkw*rh*2*water*akwgb
      watergnrdgb = 2*water*temp0gb
      END

C  Differentiation of calcact3p_gnrd in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water molalgnrd
C                gamagnrd watergnrd
C   with respect to varying inputs: molal gama water molalgnrd
C                gamagnrd watergnrd
C
C  Differentiation of calcact3p in forward (tangent) mode:
C   variations   of useful results: gama
C   with respect to varying inputs: molal gama water
