      DOUBLE PRECISION g0gnrdgb(6, 4), siongnrdgb, hgnrdgb, chgnrdgb, 
     +                 f1gnrdgb(3), f2gnrdgb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplgb, xijgb, yjigb
      DOUBLE PRECISION mplgnrd, xijgnrd, yjignrd
      DOUBLE PRECISION mplgnrdgb, xijgnrdgb, yjignrdgb
      INTEGER i
