      DOUBLE PRECISION g10gnrdgb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11gb
      DOUBLE PRECISION g11gnrd
      DOUBLE PRECISION g11gnrdgb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12gb
      DOUBLE PRECISION g12gnrd
      DOUBLE PRECISION g12gnrdgb
      INTEGER j
      DOUBLE PRECISION x2gnrd
      DOUBLE PRECISION x2gnrdgb
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x2gb
      DOUBLE PRECISION x1gnrd
      DOUBLE PRECISION x1gnrdgb
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1gb
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      INTEGER branch
      DOUBLE PRECISION temp2gb13
      DOUBLE PRECISION temp2gb12
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp2gb11
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp2gb10
      INTRINSIC ABS
      DOUBLE PRECISION temp2gb
      DOUBLE PRECISION temp0gb1
      DOUBLE PRECISION temp0gb0
      DOUBLE PRECISION temp1gb4
      DOUBLE PRECISION temp1gb3
      DOUBLE PRECISION temp1gb2
      INTEGER ii20
      DOUBLE PRECISION temp1gb1
      DOUBLE PRECISION temp1gb0
      DOUBLE PRECISION temp2gb9
      DOUBLE PRECISION temp2gb8
      DOUBLE PRECISION temp2gb7
      DOUBLE PRECISION temp2gb6
