C      WRITE(*,*) 'NSWEEP ',NSWEEP,'WATER',WATER
      DO i=1,2
C
C      IF (I.GT.1) CALL CALCACT3P
C      WRITE(*,*) 'GAMA ', GAMA
C
        a1 = xk5*(water/gama(2))**3.0
        a2 = xk7*(water/gama(4))**3.0
