C
C  CALCULATE DISSOCIATION QUANTITIES
C
        IF (chi5 .GE. tiny) THEN
          psi5gnrd = (chi5*psi6gnrd*(a6/a5*(chi6-psi6)+psi6)-psi6*chi5*(
     +      (a6gnrd*a5-a6*a5gnrd)*(chi6-psi6)/a5**2-a6*psi6gnrd/a5+
     +      psi6gnrd))/(a6/a5*(chi6-psi6)+psi6)**2
          psi5 = psi6*chi5/(a6/a5*(chi6-psi6)+psi6)
        ELSE
          psi5 = tiny
          psi5gnrd = 0.D0
        END IF
C
CCC      IF(CHI4.GT.TINY) THEN
        IF (w(2) .GT. tiny) THEN
C Accounts for NH3 evaporation
          bbgnrd = -(psi6gnrd+psi5gnrd-a4gnrd/a4**2)
          bb = -(chi4+psi6+psi5+1.d0/a4)
          ccgnrd = chi4*(psi5gnrd+psi6gnrd) + 2.d0*psi2*a4gnrd/a4**2
          cc = chi4*(psi5+psi6) - 2.d0*psi2/a4
          IF (bb*bb - 4.d0*cc .LT. zero) THEN
            dd = zero
            ddgnrd = 0.D0
          ELSE
            ddgnrd = bbgnrd*bb + bb*bbgnrd - 4.d0*ccgnrd
            dd = bb*bb - 4.d0*cc
          END IF
          IF (abs(dd) .LT. tiny) THEN
            result1gnrd = 0.D0
          ELSE
            result1gnrd = ddgnrd/(2.0*SQRT(dd))
          END IF
          result1 = SQRT(dd)
          psi4gnrd = 0.5d0*(-bbgnrd-result1gnrd)
          psi4 = 0.5d0*(-bb-result1)
        ELSE
          psi4 = tiny
          psi4gnrd = 0.D0
        END IF
C
C *** CALCULATE SPECIATION ********************************************
C
C NAI
        molalgnrd(2) = 0.D0
        molal(2) = w(1)
C      MOLAL (3) = 2.0*PSI2 + PSI4                     ! NH4I
C CLI
        molalgnrd(4) = psi6gnrd
        molal(4) = psi6
        IF (w(2) - 0.5d0*w(1) .GT. zero) THEN
          molalgnrd(3) = psi4gnrd
          molal(3) = 2.d0*w(2) - w(1) + psi4
C SO4I
          molalgnrd(5) = 0.D0
          molal(5) = w(2)
        ELSE
          molalgnrd(3) = psi4gnrd
          molal(3) = psi4
C SO4I
          molalgnrd(5) = 0.D0
          molal(5) = 0.5d0*w(1)
        END IF
        molalgnrd(6) = 0.D0
        molal(6) = zero
C NO3I
        molalgnrd(7) = psi5gnrd
        molal(7) = psi5
C
C      SMIN      = 2.d0*MOLAL(5)+MOLAL(7)+MOLAL(4)-MOLAL(2)-MOLAL(3)
        smingnrd = psi5gnrd + psi6gnrd - psi4gnrd
        smin = psi5 + psi6 - psi4
        CALL CALCPH_GNRD(smin, smingnrd, hi, hignrd, ohi)
        molalgnrd(1) = hignrd
        molal(1) = hi
        IF (chi4 - psi4 .LT. tiny) THEN
          gnh3 = tiny
        ELSE
          gnh3 = chi4 - psi4
        END IF
        IF (chi5 - psi5 .LT. tiny) THEN
          ghno3 = tiny
        ELSE
          ghno3 = chi5 - psi5
        END IF
        IF (chi6 - psi6 .LT. tiny) THEN
          ghcl = tiny
          ghclgnrd = 0.D0
        ELSE
          ghclgnrd = -psi6gnrd
          ghcl = chi6 - psi6
        END IF
C
C Solid (NH4)2SO4
        cnh42s4 = zero
C Solid NH4NO3
        cnh4no3 = zero
C Solid NH4Cl
        cnh4cl = zero
C
C      CALL CALCMR                                     ! Water content
C
C      WRITE(*,*) 'MOLAL ',MOLAL
C NA2SO4
        molalrgnrd(2) = 0.D0
        molalr(2) = 0.5d0*w(1)
        IF (w(2) - 0.5d0*w(1) .GE. 0.) THEN
          abs1 = w(2) - 0.5d0*w(1)
        ELSE
          abs1 = -(w(2)-0.5d0*w(1))
        END IF
        IF (abs1 .GT. tiny) THEN
C            WRITE(*,*) 'W(2) - 0.5D0W(1) .GT. ZERO'
          molalrgnrd(4) = 0.D0
          molalr(4) = w(2) - 0.5d0*w(1)
          IF (psi4 .GE. 0.) THEN
            abs2 = psi4
          ELSE
            abs2 = -psi4
          END IF
          IF (abs2 .GT. tiny) THEN
C FRNH4,2 = PSI4
            IF (psi5 .LT. psi4) THEN
C 
              molalrgnrd(5) = psi5gnrd
              molalr(5) = psi5
              IF (psi4 - psi5 .GE. 0.) THEN
                abs3 = psi4 - psi5
              ELSE
                abs3 = -(psi4-psi5)
              END IF
              IF (abs3 .GT. tiny) THEN
                IF (psi6 .GT. psi4 - psi5) THEN
                  molalrgnrd(6) = psi4gnrd - psi5gnrd
                  molalr(6) = psi4 - psi5
                ELSE
                  molalrgnrd(6) = psi6gnrd
                  molalr(6) = psi6
                END IF
              ELSE IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            ELSE
C FRNH4,2 = ZERO
              molalrgnrd(5) = psi4gnrd
              molalr(5) = psi4
              IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            END IF
          ELSE
            IF (psi5 .GE. 0.) THEN
              abs4 = psi5
            ELSE
              abs4 = -psi5
            END IF
C               WRITE(*,*) 'MOLALR(4,5,6)',MOLALR(4),MOLALR(5),MOLALR(6)
C               PAUSE
            IF (abs4 .LT. tiny) THEN
              molalrgnrd(5) = psi5gnrd
              molalr(5) = psi5
              IF (-psi5 .GE. 0.) THEN
                abs5 = -psi5
              ELSE
                abs5 = psi5
              END IF
              IF (abs5 .GT. tiny) THEN
                IF (psi6 .GT. -psi5) THEN
                  molalrgnrd(6) = -psi5gnrd
                  molalr(6) = -psi5
                ELSE
                  molalrgnrd(6) = psi6gnrd
                  molalr(6) = psi6
                END IF
              ELSE IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            ELSE
              molalrgnrd(5) = 0.D0
              molalr(5) = zero
              IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            END IF
          END IF
        ELSE
C W(2) - 0.5D0W(1) .LT. ZERO
C            WRITE(*,*) 'W(2) - 0.5D0W(1) .LT. ZERO'
          molalrgnrd(4) = 0.D0
          molalr(4) = zero
          IF (2.d0*psi2 + psi4 .GE. 0.) THEN
            abs6 = 2.d0*psi2 + psi4
          ELSE
            abs6 = -(2.d0*psi2+psi4)
          END IF
          IF (abs6 .GT. tiny) THEN
            IF (psi5 .LT. 2.d0*w(2) - w(1) + psi4) THEN
              molalrgnrd(5) = psi5gnrd
              molalr(5) = psi5
              IF (2.d0*w(2) - w(1) + psi4 - psi5 .GE. 0.) THEN
                abs7 = 2.d0*w(2) - w(1) + psi4 - psi5
              ELSE
                abs7 = -(2.d0*w(2)-w(1)+psi4-psi5)
              END IF
              IF (abs7 .GT. tiny) THEN
                IF (psi6 .GT. 2.d0*w(2) - w(1) + psi4 - psi5) THEN
                  molalrgnrd(6) = psi4gnrd - psi5gnrd
                  molalr(6) = 2.d0*w(2) - w(1) + psi4 - psi5
                ELSE
                  molalrgnrd(6) = psi6gnrd
                  molalr(6) = psi6
                END IF
              ELSE IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            ELSE
              molalrgnrd(5) = psi4gnrd
              molalr(5) = 2.d0*w(2) - w(1) + psi4
              IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            END IF
          ELSE
            IF (psi5 .GE. 0.) THEN
              abs8 = psi5
            ELSE
              abs8 = -psi5
            END IF
            IF (abs8 .LT. tiny) THEN
              molalrgnrd(5) = psi5gnrd
              molalr(5) = psi5
              IF (-psi5 .GE. 0.) THEN
                abs9 = -psi5
              ELSE
                abs9 = psi5
              END IF
              IF (abs9 .LT. tiny) THEN
                IF (psi6 .GT. -psi5) THEN
                  molalrgnrd(6) = -psi5gnrd
                  molalr(6) = -psi5
                ELSE
                  molalrgnrd(6) = psi6gnrd
                  molalr(6) = psi6
                END IF
              ELSE IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            ELSE
              molalrgnrd(5) = 0.D0
              molalr(5) = zero
              IF (psi6 .GT. zero) THEN
                molalrgnrd(6) = 0.D0
                molalr(6) = zero
              ELSE
                molalrgnrd(6) = psi6gnrd
                molalr(6) = psi6
              END IF
            END IF
          END IF
        END IF
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        watergnrd = 0.D0
        DO j=1,npair
          watergnrd = watergnrd + molalrgnrd(j)/m0(j)
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          watergnrd = 0.D0
        ELSE
          water = water
        END IF
C         WRITE(*,*) 'After CALCMR: WATER ',WATER
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P_GNRD()
      ENDDO
C
C *** CALCULATE FUNCTION VALUE FOR OUTER LOOP ***************************
C
      fg5abgnrd = (((molalgnrd(1)*molal(4)+molal(1)*molalgnrd(4))*ghcl-
     +  molal(1)*molal(4)*ghclgnrd)*a6/ghcl**2-molal(1)*molal(4)*a6gnrd/
     +  ghcl)/a6**2
      fg5ab = molal(1)*molal(4)/ghcl/a6 - one
CCC         FUNCG5A = MOLAL(3)*MOLAL(4)/GHCL/GNH3/A6/A4 - ONE
C
      RETURN
      END

C
C  Differentiation of calcph in forward (tangent) mode:
C   variations   of useful results: hi
