C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION whb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterhb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1hb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4hb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5hb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6hb
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi7hb
      DOUBLE PRECISION chi8
      DOUBLE PRECISION chi8hb
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrd
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      DOUBLE PRECISION aerliq(12), gas(3), wp(5)
      DOUBLE PRECISION aerliqhb(12), gashb(3), wphb(5)
      CHARACTER*40  ERRINF
      INTEGER errstki(25)
      CHARACTER*40 errmsgi(25)
      DOUBLE PRECISION feps
      DOUBLE PRECISION frna
      DOUBLE PRECISION frnahb
      DOUBLE PRECISION xt
      DOUBLE PRECISION xtd
      DOUBLE PRECISION y1
      DOUBLE PRECISION y1hb
      DOUBLE PRECISION y1d
      DOUBLE PRECISION y1dhb
      DOUBLE PRECISION x2
      DOUBLE PRECISION x2hb
      DOUBLE PRECISION y2
      DOUBLE PRECISION delta
      DOUBLE PRECISION deltahb
      INTEGER i
      INTEGER branch
      DOUBLE PRECISION x1
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION abs1
      INTRINSIC MIN
      INTEGER ii1
      DOUBLE PRECISION max1
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
C
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               CHI9, CHI10, CHI11, CHI12, CHI13, CHI14, CHI15,
C     &               CHI16, CHI17, PSI1, PSI2, PSI3, PSI4, PSI5, PSI6,
C     &               PSI7, PSI8, PSI9, PSI10, PSI11, PSI12, PSI13,
C     &               PSI14, PSI15, PSI16, PSI17, A1, A2, A3, A4, A5, A6,
C     &               A7, A8, A9, A10, A11, A12, A13, A14, A15, A16, A17
C
C *** SETUP PARAMETERS ************************************************
C
      feps = 1.d-5
C      w = wp
C CNA2SO4
      chi1 = w(2)
C CNH42S4
C CNH4CL
      IF (w(1) - 2.d0*w(2) .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frna = zero
      ELSE
        frna = w(1) - 2.d0*w(2)
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frna .GT. w(4)) THEN
        chi8 = w(4)
        CALL PUSHCONTROL1B(0)
      ELSE
        chi8 = frna
        CALL PUSHCONTROL1B(1)
      END IF
C NH3(g)
      chi4 = w(3)
C      CHI5   = MAX (W(4)-CHI8, ZERO)               ! HNO3(g)
C      CHI7   = MIN (MAX(FRNA-CHI8, ZERO), W(5))    ! CNACL
C      CHI6   = MAX (W(5)-CHI7, ZERO)               ! HCL(g)
      IF (frna .LT. w(4)) THEN
        IF (w(4) - frna .LT. zero) THEN
          chi5 = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          chi5 = w(4) - frna
          CALL PUSHCONTROL1B(1)
        END IF
        IF (zero .GT. w(5)) THEN
          chi7 = w(5)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          chi7 = zero
        END IF
        IF (w(5) .LT. zero) THEN
          chi6 = zero
          CALL PUSHCONTROL3B(2)
        ELSE
          chi6 = w(5)
          CALL PUSHCONTROL3B(1)
        END IF
      ELSE
        chi5 = zero
        IF (frna - w(4) .LT. zero) THEN
          max1 = zero
        ELSE
          max1 = frna - w(4)
        END IF
        IF (max1 .LT. w(5)) THEN
          IF (frna - w(4) .LT. zero) THEN
            chi7 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            chi7 = frna - w(4)
            CALL PUSHCONTROL1B(1)
          END IF
          IF (w(5) - chi7 .LT. zero) THEN
            chi6 = zero
            CALL PUSHCONTROL3B(4)
          ELSE
            chi6 = w(5) - chi7
            CALL PUSHCONTROL3B(3)
          END IF
        ELSE
          chi7 = w(5)
          chi6 = zero
          CALL PUSHCONTROL3B(0)
        END IF
      END IF
C
C
C *** NEWTON-RAPHSON DETERMINATION OF ROOT **********************
C
      xt = x1
      xtd = 1.d0
      CALL PUSHREAL8ARRAY(gamahnrd, npair)
      CALL PUSHREAL8ARRAY(molalhnrd, nions)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
      CALL FUNCH6AB_HNRD(xt, xtd, y1, y1d)
      x2 = xt - y1/(y1d*1.d0)
      CALL PUSHINTEGER4(iclact)
      CALL PUSHREAL8(water)
      CALL PUSHREAL8ARRAY(gama, npair)
      CALL PUSHREAL8ARRAY(molalr, npair)
      CALL PUSHREAL8ARRAY(molal, nions)
      CALL FUNCH6AB(x2, y2)
      IF (y2 .GE. 0.) THEN
        abs1 = y2
      ELSE
        abs1 = -y2
      END IF
C
      IF (abs1 .GT. feps) THEN
        DO ii1=1,nions
          molalhb(ii1) = 0.D0
        ENDDO
        DO ii1=1,npair
          gamahb(ii1) = 0.D0
        ENDDO
        waterhb = 0.D0
        gnh3hb = 0.D0
        ghno3hb = 0.D0
        ghclhb = 0.D0
        WRITE(ERRINF, '(A,E12.5,A)') 'CALCH6 (',(Y1),')'
        CALL PUSHERR (0104, ERRINF)    ! WARNING ERROR: NO CONVERGENCE
        RETURN
      ELSE
C
C      CALL FUNCH6AB(XT,Y2)
C
        IF (molal(1) .GT. tiny .AND. molal(5) .GT. tiny) THEN
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        ghclhb = gashb(3)
        gashb(3) = 0.D0
        ghno3hb = gashb(2)
        gashb(2) = 0.D0
        gnh3hb = gashb(1)
        gashb(1) = 0.D0
        aerliqhb(nions+ngasaq+2) = 0.D0
        waterhb = 1.0d3*aerliqhb(nions+1)/18.0d0
        aerliqhb(nions+1) = 0.D0
        DO i=ngasaq,1,-1
          aerliqhb(nions+1+i) = 0.D0
        ENDDO
        DO ii1=1,nions
          molalhb(ii1) = 0.D0
        ENDDO
        DO i=nions,1,-1
          molalhb(i) = molalhb(i) + aerliqhb(i)
          aerliqhb(i) = 0.D0
        ENDDO
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          DO ii1=1,npair
            gamahb(ii1) = 0.D0
          ENDDO
        ELSE
          deltahb = molalhb(6)
          molalhb(6) = 0.D0
          deltahb = deltahb - molalhb(1) - molalhb(5)
          CALL CALCHS4_HB(molal(1), molalhb(1), molal(5), molalhb(5), 
     +                    zero, delta, deltahb)
        END IF
      END IF
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL FUNCH6AB_HB(x2, x2hb, y2)
      y1hb = -(x2hb/y1d)
      y1dhb = y1*x2hb/y1d**2
      CALL POPREAL8ARRAY(molal, nions)
      CALL POPREAL8ARRAY(molalr, npair)
      CALL POPREAL8ARRAY(gama, npair)
      CALL POPREAL8(water)
      CALL POPINTEGER4(iclact)
      CALL POPREAL8ARRAY(molalhnrd, nions)
      CALL POPREAL8ARRAY(gamahnrd, npair)
      CALL FUNCH6AB_HNRD_HB(xt, xtd, y1, y1hb, y1d, y1dhb)
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          DO ii1=1,ncomp
            whb(ii1) = 0.D0
          ENDDO
          whb(5) = whb(5) + chi7hb
          frnahb = 0.D0
          GOTO 100
        ELSE
          DO ii1=1,ncomp
            whb(ii1) = 0.D0
          ENDDO
          whb(5) = whb(5) + chi6hb
        END IF
      ELSE IF (branch .EQ. 2) THEN
        DO ii1=1,ncomp
          whb(ii1) = 0.D0
        ENDDO
      ELSE
        IF (branch .EQ. 3) THEN
          DO ii1=1,ncomp
            whb(ii1) = 0.D0
          ENDDO
          whb(5) = whb(5) + chi6hb
          chi7hb = chi7hb - chi6hb
        ELSE
          DO ii1=1,ncomp
            whb(ii1) = 0.D0
          ENDDO
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          frnahb = 0.D0
        ELSE
          frnahb = chi7hb
          whb(4) = whb(4) - chi7hb
        END IF
        GOTO 100
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) whb(5) = whb(5) + chi7hb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frnahb = 0.D0
      ELSE
        whb(4) = whb(4) + chi5hb
        frnahb = -chi5hb
      END IF
 100  whb(3) = whb(3) + chi4hb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        whb(4) = whb(4) + chi8hb
      ELSE
        frnahb = frnahb + chi8hb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        whb(1) = whb(1) + frnahb
        whb(2) = whb(2) - 2.d0*frnahb
      END IF
      whb(2) = whb(2) + chi1hb
      DO ii1=1,5
        wphb(ii1) = 0.D0
      ENDDO
      wphb = whb
      END

C  Differentiation of funch6ab in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water gnh3 ghno3
C                ghcl
C   with respect to varying inputs: molal molalr gama water gnh3
C                ghno3 ghcl chi1 chi4 chi5 chi6 chi7 chi8 x
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE FUNCH6AB
C *** CASE H6
C
C     THE MAIN CHARACTERISTICS OF THIS REGIME ARE:
C     1. SULFATE POOR (SULRAT > 2.0) ; SODIUM RICH (SODRAT >= 2.0)
C     2. THERE IS BOTH A LIQUID & SOLID PHASE
C     3. SOLIDS POSSIBLE : (NH4)2SO4, NH4CL, NA2SO4
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE FUNCH6AB_HB(x, xhb, fh6ab)
      IMPLICIT NONE
C
C *** END OF FUNCTION FUNCH6A *******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterhb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1hb
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi4hb
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi5hb
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi6hb
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi7hb
      DOUBLE PRECISION psi8
      DOUBLE PRECISION psi8hb
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1hb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4hb
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION a5hb
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4hb
      DOUBLE PRECISION a6
      DOUBLE PRECISION a6hb
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5hb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6hb
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi7hb
      DOUBLE PRECISION chi8
      DOUBLE PRECISION chi8hb
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrd
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      INTEGER j
      INTEGER i
      DOUBLE PRECISION a9
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbhb
      DOUBLE PRECISION cc
      DOUBLE PRECISION cchb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddhb
      DOUBLE PRECISION smin
      DOUBLE PRECISION sminhb
      DOUBLE PRECISION hi
      DOUBLE PRECISION hihb
      DOUBLE PRECISION ohi
      DOUBLE PRECISION frno3
      DOUBLE PRECISION frno3hb
      DOUBLE PRECISION frcl
      DOUBLE PRECISION frclhb
      DOUBLE PRECISION frnh4
      DOUBLE PRECISION frnh4hb
      INTEGER branch
      DOUBLE PRECISION fh6ab
      DOUBLE PRECISION x
      DOUBLE PRECISION xhb
      DOUBLE PRECISION temp3
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp5hb
      DOUBLE PRECISION temp0hb
      INTRINSIC MAX
      DOUBLE PRECISION temp3hb
      DOUBLE PRECISION temp1hb
      DOUBLE PRECISION temp4hb
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp5
      DOUBLE PRECISION temp4
      DOUBLE PRECISION temp2hb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
C
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               CHI9, CHI10, CHI11, CHI12, CHI13, CHI14, CHI15,
C     &               CHI16, CHI17, PSI1, PSI2, PSI3, PSI4, PSI5, PSI6,
C     &               PSI7, PSI8, PSI9, PSI10, PSI11, PSI12, PSI13,
C     &               PSI14, PSI15, PSI16, PSI17, A1, A2, A3, A4, A5, A6,
C     &               A7, A8, A9, A10, A11, A12, A13, A14, A15, A16, A17
C
C *** SETUP PARAMETERS ************************************************
C
      psi6 = x
      psi1 = chi1
      psi2 = zero
      psi3 = zero
      psi7 = chi7
      psi8 = chi8
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      DO i=1,2
C
        a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        a5 = xk4*r*temp*(water/gama(10))**2.0
        a6 = xk3*r*temp*(water/gama(11))**2.0
        CALL PUSHREAL8(psi5)
C
C  CALCULATE DISSOCIATION QUANTITIES
C
        psi5 = chi5*(psi6+psi7) - a6/a5*psi8*(chi6-psi6-psi3)
        CALL PUSHREAL8(psi5)
        psi5 = psi5/(a6/a5*(chi6-psi6-psi3)+psi6+psi7)
        IF (psi5 .LT. tiny) THEN
          psi5 = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          psi5 = psi5
        END IF
C
        IF (w(3) .GT. tiny .AND. water .GT. tiny) THEN
          CALL PUSHREAL8(bb)
C First try 3rd order soln
          bb = -(chi4+psi6+psi5+1.d0/a4)
          cc = chi4*(psi5+psi6)
          dd = bb*bb - 4.d0*cc
          psi4 = 0.5d0*(-bb-SQRT(dd))
          IF (psi4 .GT. chi4) THEN
            psi4 = chi4
            CALL PUSHCONTROL2B(2)
          ELSE
            CALL PUSHCONTROL2B(1)
            psi4 = psi4
          END IF
        ELSE
          psi4 = tiny
          CALL PUSHCONTROL2B(0)
        END IF
        CALL PUSHREAL8(molal(2))
C
C *** CALCULATE SPECIATION ********************************************
C
C NAI
        molal(2) = psi8 + psi7 + 2.d0*psi1
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = psi4
        CALL PUSHREAL8(molal(4))
C CLI
        molal(4) = psi6 + psi7
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = psi2 + psi1
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = zero
        CALL PUSHREAL8(molal(7))
C NO3I
        molal(7) = psi5 + psi8
        CALL PUSHREAL8(smin)
C
C      SMIN      = 2.d0*MOLAL(5)+MOLAL(7)+MOLAL(4)-MOLAL(2)-MOLAL(3)
        smin = 2.d0*psi2 + psi5 + psi6 - psi4
        CALL CALCPH(smin, hi, ohi)
        CALL PUSHREAL8(molal(1))
        molal(1) = hi
        IF (chi4 - psi4 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi5 - psi5 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (chi6 - psi6 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
C
C      CALL CALCMR                                    ! Water content
C
C *** NA-NH4-SO4-NO3-CL SYSTEM ; SULFATE POOR ; SODIUM RICH CASE
C *** RETREIVE DISSOLVED SALTS DIRECTLY FROM COMMON BLOCK /SOLUT/
C
C NACL 
        molalr(1) = psi7
C NA2SO4
        molalr(2) = psi1
C NANO3
        molalr(3) = psi8
C (NH4)2SO4
        molalr(4) = zero
        IF (psi5 .LT. zero) THEN
          frno3 = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          frno3 = psi5
          CALL PUSHCONTROL1B(1)
        END IF
        IF (psi6 .LT. zero) THEN
          CALL PUSHCONTROL1B(0)
          frcl = zero
        ELSE
          frcl = psi6
          CALL PUSHCONTROL1B(1)
        END IF
C         MOLALR(5) = MIN(MOLAL(3),FRNO3)                   ! NH4NO3
C         FRNH4     = MAX(MOLAL(3) - MOLALR(5), ZERO)       ! "FREE" NH3
C         MOLALR(6) = MIN(FRCL, FRNH4)                      ! NH4CL
        IF (psi4 .LT. frno3) THEN
          molalr(5) = psi4
          IF (frcl .GT. zero) THEN
            molalr(6) = zero
            CALL PUSHCONTROL2B(1)
          ELSE
            molalr(6) = frcl
            CALL PUSHCONTROL2B(0)
          END IF
        ELSE
          molalr(5) = frno3
          IF (psi4 - frno3 .LT. zero) THEN
            frnh4 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            frnh4 = psi4 - frno3
            CALL PUSHCONTROL1B(1)
          END IF
          IF (frcl .GT. frnh4) THEN
            molalr(6) = frnh4
            CALL PUSHCONTROL2B(3)
          ELSE
            molalr(6) = frcl
            CALL PUSHCONTROL2B(2)
          END IF
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P()
      ENDDO
      DO ii1=1,npair
        molalrhb(ii1) = 0.D0
      ENDDO
      chi4hb = 0.D0
      chi5hb = 0.D0
      chi6hb = 0.D0
      psi1hb = 0.D0
      psi6hb = 0.D0
      psi7hb = 0.D0
      psi8hb = 0.D0
      DO i=2,1,-1
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3P_HB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterhb = 0.D0
        DO j=npair,1,-1
          molalrhb(j) = molalrhb(j) + waterhb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            frclhb = molalrhb(6)
            molalrhb(6) = 0.D0
          ELSE
            molalrhb(6) = 0.D0
            frclhb = 0.D0
          END IF
          psi4hb = molalrhb(5)
          molalrhb(5) = 0.D0
          frno3hb = 0.D0
        ELSE
          IF (branch .EQ. 2) THEN
            frclhb = molalrhb(6)
            molalrhb(6) = 0.D0
            frnh4hb = 0.D0
          ELSE
            frnh4hb = molalrhb(6)
            molalrhb(6) = 0.D0
            frclhb = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            psi4hb = 0.D0
            frno3hb = 0.D0
          ELSE
            psi4hb = frnh4hb
            frno3hb = -frnh4hb
          END IF
          frno3hb = frno3hb + molalrhb(5)
          molalrhb(5) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) psi6hb = psi6hb + frclhb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          psi5hb = 0.D0
        ELSE
          psi5hb = frno3hb
        END IF
        molalrhb(4) = 0.D0
        psi8hb = psi8hb + molalrhb(3)
        molalrhb(3) = 0.D0
        psi1hb = psi1hb + molalrhb(2)
        molalrhb(2) = 0.D0
        psi7hb = psi7hb + molalrhb(1)
        molalrhb(1) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi6hb = chi6hb + ghclhb
          psi6hb = psi6hb - ghclhb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi5hb = chi5hb + ghno3hb
          psi5hb = psi5hb - ghno3hb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          chi4hb = chi4hb + gnh3hb
          psi4hb = psi4hb - gnh3hb
        END IF
        CALL POPREAL8(molal(1))
        hihb = molalhb(1)
        molalhb(1) = 0.D0
        CALL CALCPH_HB(smin, sminhb, hi, hihb, ohi)
        CALL POPREAL8(smin)
        psi5hb = psi5hb + molalhb(7) + sminhb
        CALL POPREAL8(molal(7))
        psi8hb = psi8hb + molalhb(7)
        molalhb(7) = 0.D0
        CALL POPREAL8(molal(6))
        molalhb(6) = 0.D0
        CALL POPREAL8(molal(5))
        psi1hb = psi1hb + molalhb(5)
        molalhb(5) = 0.D0
        psi6hb = psi6hb + molalhb(4) + sminhb
        CALL POPREAL8(molal(4))
        psi7hb = psi7hb + molalhb(4)
        molalhb(4) = 0.D0
        psi4hb = psi4hb + molalhb(3) - sminhb
        CALL POPREAL8(molal(3))
        molalhb(3) = 0.D0
        CALL POPREAL8(molal(2))
        psi8hb = psi8hb + molalhb(2)
        psi7hb = psi7hb + molalhb(2)
        psi1hb = psi1hb + 2.d0*molalhb(2)
        molalhb(2) = 0.D0
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          a4hb = 0.D0
        ELSE
          IF (branch .NE. 1) THEN
            chi4hb = chi4hb + psi4hb
            psi4hb = 0.D0
          END IF
          cc = chi4*(psi5+psi6)
          dd = bb*bb - 4.d0*cc
          IF (dd .EQ. 0.0) THEN
            ddhb = 0.0
          ELSE
            ddhb = -(0.5d0*psi4hb/(2.0*SQRT(dd)))
          END IF
          bbhb = 2*bb*ddhb - 0.5d0*psi4hb
          cchb = -(4.d0*ddhb)
          chi4hb = chi4hb + (psi5+psi6)*cchb - bbhb
          psi5hb = psi5hb + chi4*cchb - bbhb
          psi6hb = psi6hb + chi4*cchb - bbhb
          a4 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
          CALL POPREAL8(bb)
          a4hb = bbhb/a4**2
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) psi5hb = 0.D0
        temp0 = gama(10)/gama(5)
        temp0hb = 2.0*temp0*xk2*r*temp*a4hb/(xkw*gama(5))
        a5 = xk4*r*temp*(water/gama(10))**2.0
        a6 = xk3*r*temp*(water/gama(11))**2.0
        CALL POPREAL8(psi5)
        temp4 = a6/a5
        temp5 = (chi6-psi3-psi6)*temp4 + psi6 + psi7
        temp5hb = -(psi5*psi5hb/temp5**2)
        temp4hb = (chi6-psi3-psi6)*temp5hb/a5
        psi5hb = psi5hb/temp5
        psi7hb = psi7hb + chi5*psi5hb + temp5hb
        CALL POPREAL8(psi5)
        temp3 = (chi6-psi3-psi6)/a5
        a6hb = temp4hb - temp3*psi8*psi5hb
        temp3hb = -(a6*psi8*psi5hb/a5)
        chi6hb = chi6hb + temp3hb + temp4*temp5hb
        psi6hb = psi6hb + chi5*psi5hb - temp3hb + (1.D0-temp4)*temp5hb
        a5hb = -(temp3*temp3hb) - temp4*temp4hb
        chi5hb = chi5hb + (psi6+psi7)*psi5hb
        psi8hb = psi8hb - temp3*a6*psi5hb
        temp2 = water/gama(11)
        temp2hb = 2.0*temp2*xk3*r*temp*a6hb/gama(11)
        gamahb(11) = gamahb(11) - temp2*temp2hb
        temp1 = water/gama(10)
        temp1hb = 2.0*temp1*xk4*r*temp*a5hb/gama(10)
        waterhb = waterhb + temp1hb + temp2hb
        gamahb(10) = gamahb(10) + temp0hb - temp1*temp1hb
        gamahb(5) = gamahb(5) - temp0*temp0hb
        gnh3hb = 0.D0
        ghno3hb = 0.D0
        ghclhb = 0.D0
      ENDDO
      chi8hb = psi8hb
      chi7hb = psi7hb
      chi1hb = psi1hb
      xhb = psi6hb
      END

C
C  Differentiation of calchs4 in reverse (adjoint) mode:
C   gradient     of useful results: water hi so4i delta
C   with respect to varying inputs: gama water hi so4i
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHS4
C *** THIS SUBROUTINE CALCULATES THE HSO4 GENERATED FROM (H,SO4).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHS4_HB(hi, hihb, so4i, so4ihb, hso4i, delta, 
     +                      deltahb)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHS4 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterhb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1hb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4hb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION chi5hb
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION chi6hb
      DOUBLE PRECISION a8
      DOUBLE PRECISION a8hb
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi7hb
      DOUBLE PRECISION chi8
      DOUBLE PRECISION chi8hb
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrd
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION hihb, so4ihb, deltahb, bbhb, cchb, ddhb, sqddhb, 
     +                 delta1hb, delta2hb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0hb
      DOUBLE PRECISION temp1hb
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .LE. 1d1*tiny) THEN
        DO ii1=1,npair
          gamahb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2hb = deltahb
            delta1hb = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2hb = deltahb
            delta1hb = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1hb = deltahb
            ELSE
              delta1hb = 0.D0
            END IF
            delta2hb = 0.D0
          END IF
          bbhb = -(0.5*delta1hb) - 0.5*delta2hb
          sqddhb = 0.5*delta1hb - 0.5*delta2hb
          IF (dd .EQ. 0.0) THEN
            ddhb = 0.0
          ELSE
            ddhb = sqddhb/(2.0*SQRT(dd))
          END IF
        ELSE
          ddhb = 0.D0
          bbhb = 0.D0
        END IF
        bbhb = bbhb + 2*bb*ddhb
        cchb = -(4.d0*ddhb)
        hihb = hihb + so4i*cchb - bbhb
        so4ihb = so4ihb + hi*cchb - bbhb
        a8hb = -bbhb - hso4i*cchb
        DO ii1=1,npair
          gamahb(ii1) = 0.D0
        ENDDO
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1hb = 2.*temp1*temp0*xk1*a8hb/gama(7)
        temp0hb = temp1**2.*xk1*a8hb/gama(7)
        gamahb(8) = gamahb(8) + temp1hb
        gamahb(7) = gamahb(7) - temp0*temp0hb - temp1*temp1hb
        waterhb = waterhb + temp0hb
      END IF
      END

