C  CALCULATE DISSOCIATION QUANTITIES
C
        psi5hnrd = chi5*psi6hnrd - psi8*((a6hnrd*a5-a6*a5hnrd)*(chi6-
     +    psi6-psi3)/a5**2-a6*psi6hnrd/a5)
        psi5 = chi5*(psi6+psi7) - a6/a5*psi8*(chi6-psi6-psi3)
        psi5hnrd = (psi5hnrd*(a6/a5*(chi6-psi6-psi3)+psi6+psi7)-psi5*((
     +    a6hnrd*a5-a6*a5hnrd)*(chi6-psi6-psi3)/a5**2-a6*psi6hnrd/a5+
     +    psi6hnrd))/(a6/a5*(chi6-psi6-psi3)+psi6+psi7)**2
        psi5 = psi5/(a6/a5*(chi6-psi6-psi3)+psi6+psi7)
        IF (psi5 .LT. tiny) THEN
          psi5 = tiny
          psi5hnrd = 0.D0
        ELSE
          psi5 = psi5
        END IF
C
        IF (w(3) .GT. tiny .AND. water .GT. tiny) THEN
C First try 3rd order soln
          bbhnrd = -(psi6hnrd+psi5hnrd-a4hnrd/a4**2)
          bb = -(chi4+psi6+psi5+1.d0/a4)
          cchnrd = chi4*(psi5hnrd+psi6hnrd)
          cc = chi4*(psi5+psi6)
          ddhnrd = bbhnrd*bb + bb*bbhnrd - 4.d0*cchnrd
          dd = bb*bb - 4.d0*cc
          IF (abs(dd) .LT. tiny) THEN
            result1hnrd = 0.D0
          ELSE
            result1hnrd = ddhnrd/(2.0*SQRT(dd))
          END IF
          result1 = SQRT(dd)
          psi4hnrd = 0.5d0*(-bbhnrd-result1hnrd)
          psi4 = 0.5d0*(-bb-result1)
          IF (psi4 .GT. chi4) THEN
            psi4 = chi4
            psi4hnrd = 0.D0
          ELSE
            psi4 = psi4
          END IF
        ELSE
          psi4 = tiny
          psi4hnrd = 0.D0
        END IF
C
C *** CALCULATE SPECIATION ********************************************
C
C NAI
        molalhnrd(2) = 0.D0
        molal(2) = psi8 + psi7 + 2.d0*psi1
C NH4I
        molalhnrd(3) = psi4hnrd
        molal(3) = psi4
C CLI
        molalhnrd(4) = psi6hnrd
        molal(4) = psi6 + psi7
C SO4I
        molalhnrd(5) = 0.D0
        molal(5) = psi2 + psi1
C HSO4I
        molalhnrd(6) = 0.D0
        molal(6) = zero
C NO3I
        molalhnrd(7) = psi5hnrd
        molal(7) = psi5 + psi8
C
C      SMIN      = 2.d0*MOLAL(5)+MOLAL(7)+MOLAL(4)-MOLAL(2)-MOLAL(3)
        sminhnrd = psi5hnrd + psi6hnrd - psi4hnrd
        smin = 2.d0*psi2 + psi5 + psi6 - psi4
        CALL CALCPH_HNRD(smin, sminhnrd, hi, hihnrd, ohi)
        molalhnrd(1) = hihnrd
        molal(1) = hi
        IF (chi4 - psi4 .LT. tiny) THEN
          gnh3 = tiny
          gnh3hnrd = 0.D0
        ELSE
          gnh3hnrd = -psi4hnrd
          gnh3 = chi4 - psi4
        END IF
        IF (chi5 - psi5 .LT. tiny) THEN
          ghno3 = tiny
        ELSE
          ghno3 = chi5 - psi5
        END IF
        IF (chi6 - psi6 .LT. tiny) THEN
          ghcl = tiny
          ghclhnrd = 0.D0
        ELSE
          ghclhnrd = -psi6hnrd
          ghcl = chi6 - psi6
        END IF
C 
        cnh42s4 = zero
        cnh4no3 = zero
        IF (chi7 - psi7 .LT. zero) THEN
          cnacl = zero
        ELSE
          cnacl = chi7 - psi7
        END IF
        IF (chi8 - psi8 .LT. zero) THEN
          cnano3 = zero
        ELSE
          cnano3 = chi8 - psi8
        END IF
        IF (chi1 - psi1 .LT. zero) THEN
          cna2so4 = zero
        ELSE
          cna2so4 = chi1 - psi1
        END IF
C
C      CALL CALCMR                                    ! Water content
C
C *** NA-NH4-SO4-NO3-CL SYSTEM ; SULFATE POOR ; SODIUM RICH CASE
C *** RETREIVE DISSOLVED SALTS DIRECTLY FROM COMMON BLOCK /SOLUT/
C
C NACL 
        molalrhnrd(1) = 0.D0
        molalr(1) = psi7
C NA2SO4
        molalrhnrd(2) = 0.D0
        molalr(2) = psi1
C NANO3
        molalrhnrd(3) = 0.D0
        molalr(3) = psi8
C (NH4)2SO4
        molalrhnrd(4) = 0.D0
        molalr(4) = zero
        IF (psi5 .LT. zero) THEN
          frno3 = zero
          frno3hnrd = 0.D0
        ELSE
          frno3hnrd = psi5hnrd
          frno3 = psi5
        END IF
        IF (psi6 .LT. zero) THEN
          frcl = zero
          frclhnrd = 0.D0
        ELSE
          frclhnrd = psi6hnrd
          frcl = psi6
        END IF
C         MOLALR(5) = MIN(MOLAL(3),FRNO3)                   ! NH4NO3
C         FRNH4     = MAX(MOLAL(3) - MOLALR(5), ZERO)       ! "FREE" NH3
C         MOLALR(6) = MIN(FRCL, FRNH4)                      ! NH4CL
        IF (psi4 .LT. frno3) THEN
          molalrhnrd(5) = psi4hnrd
          molalr(5) = psi4
          frnh4 = zero
          IF (frcl .GT. zero) THEN
            molalrhnrd(6) = 0.D0
            molalr(6) = zero
          ELSE
            molalrhnrd(6) = frclhnrd
            molalr(6) = frcl
          END IF
        ELSE
          molalrhnrd(5) = frno3hnrd
          molalr(5) = frno3
          IF (psi4 - frno3 .LT. zero) THEN
            frnh4 = zero
            frnh4hnrd = 0.D0
          ELSE
            frnh4hnrd = psi4hnrd - frno3hnrd
            frnh4 = psi4 - frno3
          END IF
          IF (frcl .GT. frnh4) THEN
            molalrhnrd(6) = frnh4hnrd
            molalr(6) = frnh4
          ELSE
            molalrhnrd(6) = frclhnrd
            molalr(6) = frcl
          END IF
        END IF
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        waterhnrd = 0.D0
        DO j=1,npair
          waterhnrd = waterhnrd + molalrhnrd(j)/m0(j)
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          waterhnrd = 0.D0
        ELSE
          water = water
        END IF
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3P_HNRD()
      ENDDO
C
C *** CALCULATE FUNCTION VALUE FOR OUTER LOOP ***************************
C
      fh6abhnrd = (((((molalhnrd(3)*molal(4)+molal(3)*molalhnrd(4))*ghcl
     +  -molal(3)*molal(4)*ghclhnrd)*gnh3/ghcl**2-molal(3)*molal(4)*
     +  gnh3hnrd/ghcl)*a6/gnh3**2-molal(3)*molal(4)*a6hnrd/(ghcl*gnh3))*
     +  a4/a6**2-molal(3)*molal(4)*a4hnrd/(ghcl*gnh3*a6))/a4**2
      fh6ab = molal(3)*molal(4)/ghcl/gnh3/a6/a4 - one
C
      RETURN
      END
C
C
C

C
C  Differentiation of calcph in forward (tangent) mode:
C   variations   of useful results: hi
C   with respect to varying inputs: water gg
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCPH
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCPH_HNRD(gg, gghnrd, hi, hihnrd, ohi)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCPH ******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterhnrd
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION cn, gg, hi, ohi, bb, cc, dd
      DOUBLE PRECISION cnhnrd, gghnrd, hihnrd, ohihnrd, bbhnrd, cchnrd, 
     +                 ddhnrd
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwhnrd
      DOUBLE PRECISION result1
      DOUBLE PRECISION result1hnrd
      DOUBLE PRECISION x2hnrd
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1hnrd
      INTRINSIC SQRT
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      akwhnrd = xkw*rh*(waterhnrd*water+water*waterhnrd)
      akw = xkw*rh*water*water
      IF (abs(akw) .LT. tiny) THEN
        cnhnrd = 0.D0
      ELSE
        cnhnrd = akwhnrd/(2.0*SQRT(akw))
      END IF
      cn = SQRT(akw)
C
C *** GG = (negative charge) - (positive charge)
C
      IF (gg .GT. tiny) THEN
C H+ in excess
        bbhnrd = -gghnrd
        bb = -gg
        cchnrd = -akwhnrd
        cc = -akw
        ddhnrd = bbhnrd*bb + bb*bbhnrd - 4.d0*cchnrd
        dd = bb*bb - 4.d0*cc
        IF (abs(dd) .LT. tiny) THEN
          result1hnrd = 0.D0
        ELSE
          result1hnrd = ddhnrd/(2.0*SQRT(dd))
        END IF
        result1 = SQRT(dd)
        x1hnrd = 0.5d0*(result1hnrd-bbhnrd)
        x1 = 0.5d0*(-bb+result1)
        IF (x1 .LT. cn) THEN
          hihnrd = cnhnrd
          hi = cn
        ELSE
          hihnrd = x1hnrd
          hi = x1
        END IF
        ohi = akw/hi
      ELSE
C OH- in excess
        bbhnrd = gghnrd
        bb = gg
        cchnrd = -akwhnrd
        cc = -akw
        ddhnrd = bbhnrd*bb + bb*bbhnrd - 4.d0*cchnrd
        dd = bb*bb - 4.d0*cc
        IF (abs(dd) .LT. tiny) THEN
          result1hnrd = 0.D0
        ELSE
          result1hnrd = ddhnrd/(2.0*SQRT(dd))
        END IF
        result1 = SQRT(dd)
        x2hnrd = 0.5d0*(result1hnrd-bbhnrd)
        x2 = 0.5d0*(-bb+result1)
        IF (x2 .LT. cn) THEN
          ohihnrd = cnhnrd
          ohi = cn
        ELSE
          ohihnrd = x2hnrd
          ohi = x2
        END IF
        hihnrd = (akwhnrd*ohi-akw*ohihnrd)/ohi**2
        hi = akw/ohi
      END IF
C
      RETURN
      END

C  Differentiation of calcact3p in forward (tangent) mode:
C   variations   of useful results: gama
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3P_HNRD()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionichnrd
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterhnrd
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0hnrd(6, 4), sionhnrd, hhnrd, chhnrd, f1hnrd(3)
     +                 , f2hnrd(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mplhnrd, xijhnrd, yjihnrd
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01hnrd
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02hnrd
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03hnrd
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04hnrd
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05hnrd
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06hnrd
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07hnrd
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08hnrd
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09hnrd
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10hnrd
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11hnrd
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12hnrd
      INTEGER j
      DOUBLE PRECISION x2hnrd
      INTRINSIC MAX
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1hnrd
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      ionichnrd = 0.D0
      DO i=1,7
        ionichnrd = ionichnrd + z(i)**2*molalhnrd(i)
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        x1hnrd = 0.D0
      ELSE
        x1hnrd = (0.5d0*ionichnrd*water-0.5d0*ionic*waterhnrd)/water**2
        x1 = 0.5d0*ionic/water
      END IF
      IF (x1 .LT. tiny) THEN
        ionic = tiny
        ionichnrd = 0.D0
      ELSE
        ionichnrd = x1hnrd
        ionic = x1
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3_HNRD(ionic, ionichnrd, temp, g01, g01hnrd, g02, 
     +                 g02hnrd, g03, g03hnrd, g04, g04hnrd, g05, g05hnrd
     +                 , g06, g06hnrd, g07, g07hnrd, g08, g08hnrd, g09, 
     +                 g09hnrd, g10, g10hnrd, g11, g11hnrd, g12, g12hnrd
     +                )
      DO ii1=1,4
        DO ii2=1,6
          g0hnrd(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
C
      g0hnrd(1, 1) = g11hnrd
      g0(1, 1) = g11
      g0hnrd(1, 2) = g07hnrd
      g0(1, 2) = g07
      g0hnrd(1, 3) = g08hnrd
      g0(1, 3) = g08
      g0hnrd(1, 4) = g10hnrd
      g0(1, 4) = g10
      g0hnrd(2, 1) = g01hnrd
      g0(2, 1) = g01
      g0hnrd(2, 2) = g02hnrd
      g0(2, 2) = g02
      g0hnrd(2, 3) = g12hnrd
      g0(2, 3) = g12
      g0hnrd(2, 4) = g03hnrd
      g0(2, 4) = g03
      g0hnrd(3, 1) = g06hnrd
      g0(3, 1) = g06
      g0hnrd(3, 2) = g04hnrd
      g0(3, 2) = g04
      g0hnrd(3, 3) = g09hnrd
      g0(3, 3) = g09
      g0hnrd(3, 4) = g05hnrd
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      IF (abs(ionic) .LT. tiny) THEN
        sionhnrd = 0.D0
      ELSE
        sionhnrd = ionichnrd/(2.0*SQRT(ionic))
      END IF
      sion = SQRT(ionic)
      hhnrd = (agama*sionhnrd*(1.d0+sion)-agama*sion*sionhnrd)/(1.d0+
     +  sion)**2
      h = agama*sion/(1.d0+sion)
C
      DO i=1,3
        f1hnrd(i) = 0.D0
        f1(i) = 0.d0
        f2hnrd(i) = 0.D0
        f2(i) = 0.d0
      ENDDO
      f2hnrd(4) = 0.D0
      f2(4) = 0.d0
      DO ii1=1,3
        f1hnrd(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2hnrd(ii1) = 0.D0
      ENDDO
C
      DO i=1,3
        zpl = z(i)
        mplhnrd = (molalhnrd(i)*water-molal(i)*waterhnrd)/water**2
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          chhnrd = -(0.25d0*(zpl+zmi)**2*ionichnrd/ionic**2)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xijhnrd = chhnrd*mpl + ch*mplhnrd
          xij = ch*mpl
          yjihnrd = ((chhnrd*molal(j+3)+ch*molalhnrd(j+3))*water-ch*
     +      molal(j+3)*waterhnrd)/water**2
          yji = ch*molal(j+3)/water
          f1hnrd(i) = f1hnrd(i) + yjihnrd*(g0(i, j)+zpl*zmi*h) + yji*(
     +      g0hnrd(i, j)+zpl*zmi*hhnrd)
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2hnrd(j) = f2hnrd(j) + xijhnrd*(g0(i, j)+zpl*zmi*h) + xij*(
     +      g0hnrd(i, j)+zpl*zmi*hhnrd)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gamahnrd(1) = zz(1)*((f1hnrd(2)/z(2)+f2hnrd(1)/z(4))/(z(2)+z(4))-
     +  hhnrd)
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gamahnrd(2) = zz(2)*((f1hnrd(2)/z(2)+f2hnrd(2)/z(5))/(z(2)+z(5))-
     +  hhnrd)
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gamahnrd(3) = zz(3)*((f1hnrd(2)/z(2)+f2hnrd(4)/z(7))/(z(2)+z(7))-
     +  hhnrd)
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gamahnrd(4) = zz(4)*((f1hnrd(3)/z(3)+f2hnrd(2)/z(5))/(z(3)+z(5))-
     +  hhnrd)
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gamahnrd(5) = zz(5)*((f1hnrd(3)/z(3)+f2hnrd(4)/z(7))/(z(3)+z(7))-
     +  hhnrd)
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gamahnrd(6) = zz(6)*((f1hnrd(3)/z(3)+f2hnrd(1)/z(4))/(z(3)+z(4))-
     +  hhnrd)
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gamahnrd(7) = zz(7)*((f1hnrd(1)/z(1)+f2hnrd(2)/z(5))/(z(1)+z(5))-
     +  hhnrd)
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gamahnrd(8) = zz(8)*((f1hnrd(1)/z(1)+f2hnrd(3)/z(6))/(z(1)+z(6))-
     +  hhnrd)
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gamahnrd(9) = zz(9)*((f1hnrd(3)/z(3)+f2hnrd(3)/z(6))/(z(3)+z(6))-
     +  hhnrd)
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gamahnrd(10) = zz(10)*((f1hnrd(1)/z(1)+f2hnrd(4)/z(7))/(z(1)+z(7))
     +  -hhnrd)
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gamahnrd(11) = zz(11)*((f1hnrd(1)/z(1)+f2hnrd(1)/z(4))/(z(1)+z(4))
     +  -hhnrd)
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gamahnrd(12) = zz(12)*((f1hnrd(2)/z(2)+f2hnrd(3)/z(6))/(z(2)+z(6))
     +  -hhnrd)
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
C LC ; SCAPE
      gamahnrd(13) = 0.2d0*(3.d0*gamahnrd(4)+2.d0*gamahnrd(9))
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          x2 = 5.0d0
          x2hnrd = 0.D0
        ELSE
          x2hnrd = gamahnrd(i)
          x2 = gama(i)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          gamahnrd(i) = 0.D0
          gama(i) = -5.0d0
        ELSE
          gamahnrd(i) = x2hnrd
          gama(i) = x2
        END IF
        gamahnrd(i) = 10.d0**gama(i)*LOG(10.d0)*gamahnrd(i)
        gama(i) = 10.d0**gama(i)
      ENDDO
C
C Increment ACTIVITY call counter
      iclact = iclact + 1
C
C *** END OF SUBROUTINE ACTIVITY ****************************************
C
      RETURN
      END

C  Differentiation of kmful3 in forward (tangent) mode:
C   variations   of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_HNRD(ionic, ionichnrd, temp, g01, g01hnrd, g02, 
     +                       g02hnrd, g03, g03hnrd, g04, g04hnrd, g05, 
     +                       g05hnrd, g06, g06hnrd, g07, g07hnrd, g08, 
     +                       g08hnrd, g09, g09hnrd, g10, g10hnrd, g11, 
     +                       g11hnrd, g12, g12hnrd)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionichnrd, sionhnrd, cf2hnrd
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01hnrd, g02hnrd, g03hnrd, g04hnrd, g05hnrd, 
     +                 g06hnrd, g07hnrd, g08hnrd, g09hnrd, g10hnrd, 
     +                 g11hnrd, g12hnrd
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTRINSIC ABS
      DOUBLE PRECISION abs1, tiny
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      tiny = 1.d-20
      IF (abs(ionic) .LT. tiny) THEN
        sionhnrd = 0.D0
      ELSE
        sionhnrd = ionichnrd/(2.0*SQRT(ionic))
      END IF
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
      CALL MKBI_HNRD(q1, ionic, ionichnrd, sion, sionhnrd, z01, g01, 
     +               g01hnrd)
      CALL MKBI_HNRD(q2, ionic, ionichnrd, sion, sionhnrd, z02, g02, 
     +               g02hnrd)
      CALL MKBI_HNRD(q3, ionic, ionichnrd, sion, sionhnrd, z03, g03, 
     +               g03hnrd)
      CALL MKBI_HNRD(q4, ionic, ionichnrd, sion, sionhnrd, z04, g04, 
     +               g04hnrd)
      CALL MKBI_HNRD(q5, ionic, ionichnrd, sion, sionhnrd, z05, g05, 
     +               g05hnrd)
      CALL MKBI_HNRD(q6, ionic, ionichnrd, sion, sionhnrd, z06, g06, 
     +               g06hnrd)
      CALL MKBI_HNRD(q7, ionic, ionichnrd, sion, sionhnrd, z07, g07, 
     +               g07hnrd)
      CALL MKBI_HNRD(q8, ionic, ionichnrd, sion, sionhnrd, z08, g08, 
     +               g08hnrd)
      CALL MKBI_HNRD(q10, ionic, ionichnrd, sion, sionhnrd, z10, g10, 
     +               g10hnrd)
      CALL MKBI_HNRD(q11, ionic, ionichnrd, sion, sionhnrd, z11, g11, 
     +               g11hnrd)
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.d0) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        cf2hnrd = (0.125d0-0.005d0*ti)*(0.039d0*0.92d0*ionic**(-0.8D0)*
     +    ionichnrd-(0.41d0*sionhnrd*(1.d0+sion)-0.41d0*sion*sionhnrd)/(
     +    1.d0+sion)**2)
        cf2 = (0.125d0-0.005d0*ti)*(0.039d0*ionic**0.92d0-0.41d0*sion/(
     +    1.d0+sion))
        g01hnrd = cf1*g01hnrd - z01*cf2hnrd
        g01 = cf1*g01 - cf2*z01
        g02hnrd = cf1*g02hnrd - z02*cf2hnrd
        g02 = cf1*g02 - cf2*z02
        g03hnrd = cf1*g03hnrd - z03*cf2hnrd
        g03 = cf1*g03 - cf2*z03
        g04hnrd = cf1*g04hnrd - z04*cf2hnrd
        g04 = cf1*g04 - cf2*z04
        g05hnrd = cf1*g05hnrd - z05*cf2hnrd
        g05 = cf1*g05 - cf2*z05
        g06hnrd = cf1*g06hnrd - z06*cf2hnrd
        g06 = cf1*g06 - cf2*z06
        g07hnrd = cf1*g07hnrd - z07*cf2hnrd
        g07 = cf1*g07 - cf2*z07
        g08hnrd = cf1*g08hnrd - z08*cf2hnrd
        g08 = cf1*g08 - cf2*z08
        g10hnrd = cf1*g10hnrd - z10*cf2hnrd
        g10 = cf1*g10 - cf2*z10
        g11hnrd = cf1*g11hnrd - z11*cf2hnrd
        g11 = cf1*g11 - cf2*z11
      END IF
C
      g09hnrd = g06hnrd + g08hnrd - g11hnrd
      g09 = g06 + g08 - g11
      g12hnrd = g01hnrd + g08hnrd - g11hnrd
      g12 = g01 + g08 - g11
C
C *** Return point ; End of subroutine
C
      RETURN
      END

C  Differentiation of mkbi in forward (tangent) mode:
C   variations   of useful results: bi
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_HNRD(q, ionic, ionichnrd, sion, sionhnrd, zip, bi
     +                     , bihnrd)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionichnrd, sionhnrd, bihnrd
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION chnrd, xxhnrd
      DOUBLE PRECISION arg1
      DOUBLE PRECISION arg1hnrd
      DOUBLE PRECISION pwx1
      DOUBLE PRECISION pwx1hnrd
      DOUBLE PRECISION pwr1
      DOUBLE PRECISION pwr1hnrd, tiny
      INTRINSIC EXP
      INTRINSIC LOG10
      tiny = 1.d-20
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      arg1hnrd = -(.023d0*((ionichnrd*ionic+ionic*ionichnrd)*ionic+ionic
     +  **2*ionichnrd))
      arg1 = -(.023d0*ionic*ionic*ionic)
      chnrd = .055d0*q*arg1hnrd*EXP(arg1)
      c = 1.d0 + .055d0*q*EXP(arg1)
      xxhnrd = -((0.5107d0*sionhnrd*(1.d0+c*sion)-0.5107d0*sion*(chnrd*
     +  sion+c*sionhnrd))/(1.d0+c*sion)**2)
      xx = -(0.5107d0*sion/(1.d0+c*sion))
      pwx1hnrd = .1d0*ionichnrd
      pwx1 = 1.d0 + .1d0*ionic
      IF (pwx1 .GT. 0.d0 .OR. (pwx1 .LT. 0.d0 .AND. 
     &    abs(q-INT(q)) .LT. tiny)) THEN
        pwr1hnrd = q*pwx1**(q-1)*pwx1hnrd
      ELSE IF (abs(pwx1) .LT. tiny .AND. abs(q-1.d0) .LT. tiny) THEN
        pwr1hnrd = pwx1hnrd
      ELSE
        pwr1hnrd = 0.d0
      END IF
      pwr1 = pwx1**q
      bihnrd = b*pwr1hnrd
      bi = 1.d0 + b*pwr1 - b
      bihnrd = zip*bihnrd/(bi*LOG(10.d0)) + zip*xxhnrd
      bi = zip*LOG10(bi) + zip*xx
C
      RETURN
      END

