      aerliqib(nions+1) = 0.D0
      DO i=ngasaq,1,-1
        aerliqib(nions+1+i) = 0.D0
      ENDDO
      DO ii1=1,nions
        molalib(ii1) = 0.D0
      ENDDO
      DO i=nions,1,-1
        molalib(i) = molalib(i) + aerliqib(i)
        aerliqib(i) = 0.D0
