      ELSE
        restib = 0.D0
      END IF
      wib(2) = wib(2) + 2.d0*restib
      wib(4) = wib(4) + restib
      wib(5) = wib(5) + restib
      DO ii1=1,5
        wpib(ii1) = 0.D0
      ENDDO
      wpib = wib
