      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION aerliq(12), gas(3), wp(5)
      DOUBLE PRECISION frso4
      DOUBLE PRECISION frso4ib
      DOUBLE PRECISION frnh4
      DOUBLE PRECISION frnh4ib
      INTEGER i
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbib
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccib
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddib
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION min1
      INTRINSIC MAX
      DOUBLE PRECISION temp1ib
      DOUBLE PRECISION temp2ib
      DOUBLE PRECISION min1ib
      INTRINSIC MIN
      DOUBLE PRECISION temp0ib
      INTEGER ii1
      INTRINSIC SQRT
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      COMMON /ions_ib/ molalib, gamaib, waterib
      COMMON /inpt_ib/ wib
C      COMMON /SOLUT/ CHI1, CHI2, CHI3, CHI4, CHI5, CHI6, CHI7, CHI8,
C     &               PSI1, PSI2, PSI3, PSI4, PSI5, PSI6, PSI7, PSI8,
C     &               A1,   A2,   A3,   A4,   A5,   A6,   A7,   A8
C
C *** FIND DRY COMPOSITION **********************************************
C
C      CALL CALCI1A
C
C *** CALCULATE NON VOLATILE SOLIDS ***********************************
C
      cna2so4 = 0.5d0*w(1)
      cnh4hs4 = zero
      cnahso4 = zero
      cnh42s4 = zero
      IF (w(2) - cna2so4 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frso4 = zero
      ELSE
        frso4 = w(2) - cna2so4
        CALL PUSHCONTROL1B(1)
      END IF
      IF (w(3)/3.d0 .GT. frso4/2.d0) THEN
        clc = frso4/2.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        clc = w(3)/3.d0
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frso4 - 2.d0*clc .LT. zero) THEN
        frso4 = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        frso4 = frso4 - 2.d0*clc
        CALL PUSHCONTROL1B(1)
      END IF
      IF (w(3) - 3.d0*clc .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frnh4 = zero
      ELSE
        frnh4 = w(3) - 3.d0*clc
        CALL PUSHCONTROL1B(1)
      END IF
C
      IF (frso4 .LE. tiny) THEN
        IF (clc - frnh4 .LT. zero) THEN
          clc = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          clc = clc - frnh4
          CALL PUSHCONTROL1B(1)
        END IF
        cnh42s4 = 2.d0*frnh4
C
        CALL PUSHCONTROL3B(0)
      ELSE IF (frnh4 .LE. tiny) THEN
        IF (frso4 .GT. clc) THEN
          min1 = clc
          CALL PUSHCONTROL1B(0)
        ELSE
          min1 = frso4
          CALL PUSHCONTROL1B(1)
        END IF
        cnh4hs4 = 3.d0*min1
        IF (clc - frso4 .LT. zero) THEN
          clc = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          clc = clc - frso4
          CALL PUSHCONTROL1B(1)
        END IF
        IF (cna2so4 .GT. tiny) THEN
          IF (frso4 - cnh4hs4/3.d0 .LT. zero) THEN
            frso4 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            frso4 = frso4 - cnh4hs4/3.d0
            CALL PUSHCONTROL1B(1)
          END IF
          cnahso4 = 2.d0*frso4
          IF (cna2so4 - frso4 .LT. zero) THEN
            cna2so4 = zero
            CALL PUSHCONTROL3B(4)
          ELSE
            cna2so4 = cna2so4 - frso4
            CALL PUSHCONTROL3B(3)
          END IF
        ELSE
          CALL PUSHCONTROL3B(1)
        END IF
      ELSE
        CALL PUSHCONTROL3B(2)
      END IF
C
C *** CALCULATE GAS SPECIES *********************************************
C
C
C *** SETUP PARAMETERS ************************************************
C
C Save from CALCI1 run
C
C ASSIGN INITIAL PSI's
      psi1 = cnh4hs4
      psi2 = clc
      psi3 = cnahso4
      psi4 = cna2so4
      psi5 = cnh42s4
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. calain)
C
        a6 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
C  CALCULATE DISSOCIATION QUANTITIES
C
C PSI6
        bb = psi2 + psi4 + psi5 + a6
        cc = -(a6*(psi2+psi3+psi1))
        dd = bb*bb - 4.d0*cc
        psi6 = 0.5d0*(-bb+SQRT(dd))
        CALL PUSHREAL8(molal(1))
C
C *** CALCULATE SPECIATION ********************************************
C
C HI
        molal(1) = psi6
        CALL PUSHREAL8(molal(2))
C NAI
        molal(2) = 2.d0*psi4 + psi3
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = 3.d0*psi2 + 2.d0*psi5 + psi1
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = psi2 + psi4 + psi5 + psi6
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = psi2 + psi3 + psi1 - psi6
C      CALL CALCMR                                         ! Water content
C (NH4)2SO4
        molalr(4) = psi5
C NA2SO4
        molalr(2) = psi4
C NH4HSO4
        molalr(9) = psi1
C NAHSO4
        molalr(12) = psi3
C LC
        molalr(13) = psi2
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3()
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      CALL PUSHINTEGER4(ad_count)
      DO ii1=1,npair
        molalrib(ii1) = 0.D0
      ENDDO
      psi1ib = 0.D0
      psi2ib = 0.D0
      psi3ib = 0.D0
      psi4ib = 0.D0
      psi5ib = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_IB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterib = 0.D0
        DO j=npair,1,-1
          molalrib(j) = molalrib(j) + waterib/m0(j)
        ENDDO
        CALL POPREAL8(water)
        psi2ib = psi2ib + molalib(6) + molalrib(13)
        molalrib(13) = 0.D0
        psi3ib = psi3ib + molalib(6) + molalrib(12)
        molalrib(12) = 0.D0
        psi1ib = psi1ib + molalib(6) + molalrib(9)
        molalrib(9) = 0.D0
        CALL POPREAL8(molal(6))
        psi6ib = -molalib(6)
        molalib(6) = 0.D0
        psi4ib = psi4ib + molalib(5) + molalrib(2)
        molalrib(2) = 0.D0
        psi5ib = psi5ib + molalib(5) + molalrib(4)
        molalrib(4) = 0.D0
        CALL POPREAL8(molal(5))
        psi2ib = psi2ib + molalib(5)
        psi6ib = psi6ib + molalib(5)
        molalib(5) = 0.D0
        CALL POPREAL8(molal(3))
        psi2ib = psi2ib + 3.d0*molalib(3)
        psi5ib = psi5ib + 2.d0*molalib(3)
        psi1ib = psi1ib + molalib(3)
        molalib(3) = 0.D0
        CALL POPREAL8(molal(2))
        psi4ib = psi4ib + 2.d0*molalib(2)
        psi3ib = psi3ib + molalib(2)
        molalib(2) = 0.D0
        CALL POPREAL8(molal(1))
        psi6ib = psi6ib + molalib(1)
        molalib(1) = 0.D0
        a6 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
        bb = psi2 + psi4 + psi5 + a6
        cc = -(a6*(psi2+psi3+psi1))
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddib = 0.0
        ELSE
          ddib = 0.5d0*psi6ib/(2.0*SQRT(dd))
        END IF
        bbib = 2*bb*ddib - 0.5d0*psi6ib
        ccib = -(4.d0*ddib)
        temp2ib = -(a6*ccib)
        a6ib = bbib - (psi2+psi3+psi1)*ccib
        psi2ib = psi2ib + bbib + temp2ib
        psi3ib = psi3ib + temp2ib
        psi1ib = psi1ib + temp2ib
        psi4ib = psi4ib + bbib
        psi5ib = psi5ib + bbib
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1ib = 2.*temp1*temp0*xk1*a6ib/gama(7)
        temp0ib = temp1**2.*xk1*a6ib/gama(7)
        gamaib(8) = gamaib(8) + temp1ib
        gamaib(7) = gamaib(7) - temp0*temp0ib - temp1*temp1ib
        waterib = temp0ib
      ENDDO
      cnh42s4ib = psi5ib
      cna2so4ib = psi4ib
      cnahso4ib = psi3ib
      clcib = psi2ib
      cnh4hs4ib = psi1ib
      wib(5) = wib(5) + ghclib
      wib(4) = wib(4) + ghno3ib
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          frnh4ib = 2.d0*cnh42s4ib
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            clcib = 0.D0
          ELSE
            frnh4ib = frnh4ib - clcib
          END IF
          frso4ib = 0.D0
          GOTO 110
        ELSE
          frso4ib = 0.D0
        END IF
      ELSE IF (branch .EQ. 2) THEN
        frso4ib = 0.D0
        GOTO 100
      ELSE
        IF (branch .EQ. 3) THEN
          frso4ib = -cna2so4ib
        ELSE
          cna2so4ib = 0.D0
          frso4ib = 0.D0
        END IF
        frso4ib = frso4ib + 2.d0*cnahso4ib
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          frso4ib = 0.D0
        ELSE
          cnh4hs4ib = cnh4hs4ib - frso4ib/3.d0
        END IF
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        clcib = 0.D0
      ELSE
        frso4ib = frso4ib - clcib
      END IF
      min1ib = 3.d0*cnh4hs4ib
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        clcib = clcib + min1ib
      ELSE
        frso4ib = frso4ib + min1ib
      END IF
 100  frnh4ib = 0.D0
 110  CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wib(3) = wib(3) + frnh4ib
        clcib = clcib - 3.d0*frnh4ib
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frso4ib = 0.D0
      ELSE
        clcib = clcib - 2.d0*frso4ib
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frso4ib = frso4ib + clcib/2.d0
      ELSE
        wib(3) = wib(3) + clcib/3.d0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wib(2) = wib(2) + frso4ib
        cna2so4ib = cna2so4ib - frso4ib
      END IF
      wib(1) = wib(1) + 0.5d0*cna2so4ib
      END

C
C  Differentiation of calcnh3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA IN THE GAS PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE AEROSOL EQUILIBRIUM. 
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE DIRECT PROBLEM
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3_IB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wib(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterib
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1ib
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1ib
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2ib
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION bb, cc, diak, psi
      DOUBLE PRECISION bbib, ccib, diakib, psiib
      INTEGER branch
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp1ib
      DOUBLE PRECISION x1
      DOUBLE PRECISION x1ib
      INTRINSIC MIN
      INTEGER ii1
      DOUBLE PRECISION temp0ib
      INTRINSIC SQRT
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      COMMON /ions_ib/ molalib, gamaib, waterib
      COMMON /inpt_ib/ wib
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamaib(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 SUBLIMATION *****************************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        chi1 = molal(3)
        chi2 = molal(1)
C
C a=1; b!=1; c!=1 
        bb = chi2 + one/a1
        cc = -(chi1/a1)
C Always > 0
        diak = SQRT(bb*bb - 4.d0*cc)
C One positive root
        psi = 0.5*(-bb+diak)
        IF (psi .GT. chi1) THEN
          x1 = chi1
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = psi
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        chi2ib = molalib(1)
        psiib = molalib(1)
        molalib(1) = 0.D0
        chi1ib = molalib(3)
        psiib = psiib + gnh3ib - molalib(3)
        molalib(3) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          x1ib = 0.D0
        ELSE
          x1ib = psiib
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi1ib = chi1ib + x1ib
          psiib = 0.D0
        ELSE
          psiib = x1ib
        END IF
        diakib = 0.5*psiib
        IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
          temp1ib = 0.0
        ELSE
          temp1ib = diakib/(2.0*SQRT(bb**2-4.d0*cc))
        END IF
        bbib = 2*bb*temp1ib - 0.5*psiib
        ccib = -(4.d0*temp1ib)
        chi1ib = chi1ib - ccib/a1
        a1ib = chi1*ccib/a1**2 - one*bbib/a1**2
        chi2ib = chi2ib + bbib
        molalib(1) = molalib(1) + chi2ib
        molalib(3) = molalib(3) + chi1ib
        DO ii1=1,npair
          gamaib(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0ib = 2.0*temp0*xk2*r*temp*a1ib/(xkw*gama(5))
        gamaib(10) = gamaib(10) + temp0ib
        gamaib(5) = gamaib(5) - temp0*temp0ib
C        WRITE(*,*) 'At end of CALCNH3_IB: molalib(1,3)',molalib(1),
C     +    molalib(3)
C        WRITE(*,*) 'gamaib(5,10)',gamaib(5), gamaib(10)
C        WRITE(*,*) 'gama(5,10)',gama(5),gama(10)
      END IF
      END

C  Differentiation of calcnha in reverse (adjoint) mode (forward sweep):
C   gradient     of useful results: molal gama water ghno3 ghcl
C   with respect to varying inputs: w molal gama water ghno3 ghcl
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNHA
C
C     THIS SUBROUTINE CALCULATES THE DISSOLUTION OF HCL, HNO3 AT
C     THE PRESENCE OF (H,SO4). HCL, HNO3 ARE CONSIDERED MINOR SPECIES,
C     THAT DO NOT SIGNIFICANTLY AFFECT THE EQUILIBRIUM POINT.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNHA_IFWD()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNHA *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION coh, chno3, chcl, water
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION m1, m2, m3, delcl, delno, omega
      CHARACTER*40 errinf
      DOUBLE PRECISION c1
      DOUBLE PRECISION c2
      DOUBLE PRECISION c3
      INTEGER islv
      INTRINSIC MAX
      INTRINSIC MIN
C
C *** SPECIAL CASE; WATER=ZERO ******************************************
C
      IF (water .LE. tiny) THEN
        IF (w(5) - molal(4) .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(4) - molal(7) .LT. tiny) THEN
          CALL PUSHCONTROL3B(1)
        ELSE
          CALL PUSHCONTROL3B(0)
        END IF
      ELSE IF (w(5) .LE. tiny .AND. w(4) .LE. tiny) THEN
        CALL PUSHCONTROL3B(2)
      ELSE IF (w(5) .LE. tiny) THEN
        CALL PUSHREAL8ARRAY(molal, nions)
C CALL HNO3 DISSOLUTION ROUTINE
        CALL CALCNA()
C         GOTO 60
C
C *** SPECIAL CASE; HNO3=ZERO *******************************************
C
        CALL PUSHCONTROL3B(3)
      ELSE IF (w(4) .LE. tiny) THEN
        CALL PUSHREAL8ARRAY(molal, nions)
C CALL HCL DISSOLUTION ROUTINE
        CALL CALCHA()
C         GOTO 60
C      ENDIF
        CALL PUSHCONTROL3B(4)
      ELSE
C
C *** CALCULATE EQUILIBRIUM CONSTANTS ***********************************
C
C HNO3
        a3 = xk4*r*temp*(water/gama(10))**2.0
C HCL
        a4 = xk3*r*temp*(water/gama(11))**2.0
C
C *** CALCULATE CUBIC EQUATION COEFFICIENTS *****************************
C
C
C H+
        omega = molal(1)
C HNO3
        chi3 = w(4)
C HCL
        chi4 = w(5)
C
        c1 = a3*chi3
        c2 = a4*chi4
        c3 = a3 - a4
C
        m1 = (c1+c2+(omega+a4)*c3)/c3
        m2 = ((omega+a4)*c2-a4*c3*chi4)/c3
        m3 = -(a4*c2*chi4/c3)
C
C *** CALCULATE ROOTS ***************************************************
C
        CALL POLY3(m1, m2, m3, delcl, islv)
C HCL DISSOLUTION
        IF (islv .NE. 0) THEN
C TINY AMOUNTS OF HCL ASSUMED WHEN NO ROOT 
          delcl = tiny
C            WRITE (ERRINF,'(1PE10.1)') TINY
C            CALL PUSHERR (0022, ERRINF)    ! WARNING ERROR: NO SOLUTION
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        IF (delcl .GT. chi4) THEN
          delcl = chi4
          CALL PUSHCONTROL1B(0)
        ELSE
          delcl = delcl
          CALL PUSHCONTROL1B(1)
        END IF
C
        delno = c1*delcl/(c2+c3*delcl)
        IF (delno .GT. chi3) THEN
          delno = chi3
          CALL PUSHCONTROL1B(0)
        ELSE
          delno = delno
          CALL PUSHCONTROL1B(1)
        END IF
C
        IF (((delcl .LT. zero .OR. delno .LT. zero) .OR. delcl .GT. chi4
     +      ) .OR. delno .GT. chi3) THEN
          CALL PUSHREAL8(delcl)
C TINY AMOUNTS OF HCL ASSUMED WHEN NO ROOT 
          delcl = tiny
          delno = tiny
C            WRITE (ERRINF,'(1PE10.1)') TINY
C            CALL PUSHERR (0022, ERRINF)    ! WARNING ERROR: NO SOLUTION
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
CCC
CCC *** COMPARE DELTA TO TOTAL H+ ; ESTIMATE EFFECT TO HSO4 ***************
CCC
CC      IF ((DELCL+DELNO)/MOLAL(1).GT.0.1d0) THEN
CC         WRITE (ERRINF,'(1PE10.3)') (DELCL+DELNO)/MOLAL(1)*100.0
CC         CALL PUSHERR (0021, ERRINF)   
CC      ENDIF
C
C *** EFFECT ON LIQUID PHASE ********************************************
C
C H+   CHANGE
        molal(1) = molal(1) + (delno+delcl)
C CL-  CHANGE
        molal(4) = molal(4) + delcl
C NO3- CHANGE
        molal(7) = molal(7) + delno
        IF (w(5) - molal(4) .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(4) - molal(7) .LT. tiny) THEN
          CALL PUSHREAL8(omega)
          CALL PUSHREAL8(delcl)
          CALL PUSHCONTROL3B(5)
        ELSE
          CALL PUSHREAL8(omega)
          CALL PUSHREAL8(delcl)
          CALL PUSHCONTROL3B(6)
        END IF
      END IF
      END

C  Differentiation of calcnha in reverse (adjoint) mode (backward sweep):
C   gradient     of useful results: molal gama water ghno3 ghcl
C   with respect to varying inputs: w molal gama water ghno3 ghcl
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNHA
C
C     THIS SUBROUTINE CALCULATES THE DISSOLUTION OF HCL, HNO3 AT
C     THE PRESENCE OF (H,SO4). HCL, HNO3 ARE CONSIDERED MINOR SPECIES,
C     THAT DO NOT SIGNIFICANTLY AFFECT THE EQUILIBRIUM POINT.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNHA_IBWD()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNHA *****************************************
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wib(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterib
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas/ gnh3, ghno3, ghcl
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION a3ib
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4ib
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3ib
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4ib
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION m1, m2, m3, delcl, delno, omega
      DOUBLE PRECISION m1ib, m2ib, m3ib, delclib, delnoib, omegaib
      CHARACTER*40 errinf
      DOUBLE PRECISION c1
      DOUBLE PRECISION c1ib
      DOUBLE PRECISION c2
      DOUBLE PRECISION c2ib
      DOUBLE PRECISION c3
      DOUBLE PRECISION c3ib
      INTEGER islv
      INTEGER branch
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp3ib
      INTRINSIC MAX
      DOUBLE PRECISION temp2ib1
      DOUBLE PRECISION temp1ib
      DOUBLE PRECISION temp2ib0
      DOUBLE PRECISION temp3ib0
      DOUBLE PRECISION temp2ib
      INTRINSIC MIN
      INTEGER ii1
      DOUBLE PRECISION temp0ib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      COMMON /ions_ib/ molalib, gamaib, waterib
      COMMON /inpt_ib/ wib
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 3) THEN
        IF (branch .EQ. 0) THEN
          DO ii1=1,ncomp
            wib(ii1) = 0.D0
          ENDDO
          wib(4) = wib(4) + ghno3ib
          molalib(7) = molalib(7) - ghno3ib
        ELSE IF (branch .EQ. 1) THEN
          DO ii1=1,ncomp
            wib(ii1) = 0.D0
          ENDDO
        ELSE
          DO ii1=1,ncomp
            wib(ii1) = 0.D0
          ENDDO
          GOTO 100
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          wib(5) = wib(5) + ghclib
          molalib(4) = molalib(4) - ghclib
        END IF
        ghno3ib = 0.D0
        ghclib = 0.D0
      ELSE
        IF (branch .LT. 5) THEN
          IF (branch .EQ. 3) THEN
            CALL POPREAL8ARRAY(molal, nions)
            CALL CALCNA_IB()
            ghno3ib = 0.D0
            GOTO 100
          ELSE
            CALL POPREAL8ARRAY(molal, nions)
            CALL CALCHA_IB()
          END IF
        ELSE
          IF (branch .EQ. 5) THEN
            CALL POPREAL8(delcl)
            CALL POPREAL8(omega)
            DO ii1=1,ncomp
              wib(ii1) = 0.D0
            ENDDO
          ELSE
            CALL POPREAL8(delcl)
            CALL POPREAL8(omega)
            DO ii1=1,ncomp
              wib(ii1) = 0.D0
            ENDDO
            wib(4) = wib(4) + ghno3ib
            molalib(7) = molalib(7) - ghno3ib
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            wib(5) = wib(5) + ghclib
            molalib(4) = molalib(4) - ghclib
          END IF
          delnoib = molalib(1) + molalib(7)
          delclib = molalib(1) + molalib(4)
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            CALL POPREAL8(delcl)
            delnoib = 0.D0
            delclib = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            c1 = a3*chi3
            c2 = a4*chi4
            c3 = a3 - a4
            chi3ib = delnoib
            delnoib = 0.D0
          ELSE
            c1 = a3*chi3
            c2 = a4*chi4
            c3 = a3 - a4
            chi3ib = 0.D0
          END IF
          temp3ib = delnoib/(c2+c3*delcl)
          temp3ib0 = -(c1*delcl*temp3ib/(c2+c3*delcl))
          c1ib = delcl*temp3ib
          delclib = delclib + c3*temp3ib0 + c1*temp3ib
          c2ib = temp3ib0
          c3ib = delcl*temp3ib0
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            chi4ib = delclib
            delclib = 0.D0
          ELSE
            chi4ib = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) delclib = 0.D0
          m1 = (c1+c2+(omega+a4)*c3)/c3
          m2 = ((omega+a4)*c2-a4*c3*chi4)/c3
          m3 = -(a4*c2*chi4/c3)
          CALL POLY3_IB(m1, m1ib, m2, m2ib, m3, m3ib, delcl, delclib, 
     +                  islv)
C          WRITE(*,*) 'm1ib',m1ib,'m2ib',m2ib,'m3ib',m3ib
C          WRITE(*,*) 'delcl(b)',delcl, delclib
C          WRITE(*,*) 'islv',islv
          temp2 = chi4/c3
          temp2ib = -(a4*c2*m3ib/c3)
          temp2ib0 = m2ib/c3
          temp2ib1 = m1ib/c3
          c2ib = c2ib + (omega+a4)*temp2ib0 + temp2ib1 - temp2*a4*m3ib
          chi4ib = chi4ib + a4*c2ib - a4*c3*temp2ib0 + temp2ib
          c3ib = c3ib + (-(((omega+a4)*c2-a4*c3*chi4)/c3)-chi4*a4)*
     +      temp2ib0 + (omega-(c1+c2+(omega+a4)*c3)/c3+a4)*temp2ib1 - 
     +      temp2*temp2ib
          a4ib = (c2-chi4*c3)*temp2ib0 - c3ib + chi4*c2ib + c3*temp2ib1 
     +      - temp2*c2*m3ib
          omegaib = c3*temp2ib1 + c2*temp2ib0
          c1ib = c1ib + temp2ib1
          a3ib = chi3*c1ib + c3ib
          chi3ib = chi3ib + a3*c1ib
          wib(5) = wib(5) + chi4ib
          wib(4) = wib(4) + chi3ib
          molalib(1) = molalib(1) + omegaib
          temp1 = water/gama(11)
          temp1ib = 2.0*temp1*xk3*r*temp*a4ib/gama(11)
          gamaib(11) = gamaib(11) - temp1*temp1ib
          temp0 = water/gama(10)
          temp0ib = 2.0*temp0*xk4*r*temp*a3ib/gama(10)
          waterib = waterib + temp0ib + temp1ib
          gamaib(10) = gamaib(10) - temp0*temp0ib
C          WRITE(*,*) 'GAMA IB at end of CALCNHA_IBWD', gamaib(10)
C          WRITE(*,*) 'wib(4,5)',wib(4),wib(5)
C          WRITE(*,*) 'w ',w, 'rh',rh
C          PAUSE 
          ghno3ib = 0.D0
        END IF
        ghclib = 0.D0
      END IF
 100  CONTINUE
      END

C  Differentiation of calcha in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water ghcl
C   with respect to varying inputs: w molal gama water
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHA
C *** CALCULATES CHLORIDES SPECIATION
C
C     HYDROCHLORIC ACID IN THE LIQUID PHASE IS ASSUMED A MINOR SPECIES,  
C     AND DOES NOT SIGNIFICANTLY PERTURB THE HSO4-SO4 EQUILIBRIUM. THE 
C     HYDROCHLORIC ACID DISSOLVED IS CALCULATED FROM THE 
C     HCL(G) <-> (H+) + (CL-) 
C     EQUILIBRIUM, USING THE (H+) FROM THE SULFATES.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHA_IB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHA ******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wib(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterib
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION kapa, x, delt, alfa, diak
      DOUBLE PRECISION kapaib, xib, deltib, alfaib, diakib
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1ib1
      DOUBLE PRECISION temp1ib0
      INTRINSIC MAX
      DOUBLE PRECISION temp1ib
      INTEGER ii1
      DOUBLE PRECISION temp0ib
      INTRINSIC SQRT
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      COMMON /ions_ib/ molalib, gamaib, waterib
      COMMON /inpt_ib/ wib
CC      CHARACTER*40 errinf
C
C *** CALCULATE HCL DISSOLUTION *****************************************
C
      x = w(5)
      delt = 0.0d0
      IF (water .GT. tiny) THEN
        kapa = molal(1)
        alfa = xk3*r*temp*(water/gama(11))**2.0
        diak = SQRT((kapa+alfa)**2.0 + 4.0*alfa*x)
        delt = 0.5*(-(kapa+alfa)+diak)
CC         IF (DELT/KAPA.GT.0.1d0) THEN
CC            WRITE (ERRINF,'(1PE10.3)') DELT/KAPA*100.0
CC            CALL PUSHERR (0033, ERRINF)    
CC         ENDIF
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      IF (x - delt .LT. 0.0d0) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      deltib = molalib(4) + molalib(1)
      molalib(4) = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        xib = 0.D0
      ELSE
        xib = ghclib
        deltib = deltib - ghclib
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        temp1ib = 0.5*deltib
        diakib = temp1ib
        IF ((kapa+alfa)**2.0 + 4.0*(alfa*x) .EQ. 0.0) THEN
          temp1ib1 = 0.0
        ELSE
          temp1ib1 = diakib/(2.0*SQRT((kapa+alfa)**2.0+4.0*(alfa*x)))
        END IF
        temp1ib0 = 2.0*(kapa+alfa)*temp1ib1
        alfaib = temp1ib0 + 4.0*x*temp1ib1 - temp1ib
        kapaib = temp1ib0 - temp1ib
        xib = xib + 4.0*alfa*temp1ib1
        temp0 = water/gama(11)
        temp0ib = 2.0*temp0*xk3*r*temp*alfaib/gama(11)
        waterib = waterib + temp0ib
        gamaib(11) = gamaib(11) - temp0*temp0ib
        molalib(1) = molalib(1) + kapaib
      END IF
      DO ii1=1,ncomp
        wib(ii1) = 0.D0
      ENDDO
      wib(5) = wib(5) + xib
      END

C  Differentiation of calcna in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water ghno3
C   with respect to varying inputs: w molal gama water
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNA
C *** CALCULATES NITRATES SPECIATION
