      DOUBLE PRECISION frso4
      DOUBLE PRECISION frso4irb
      DOUBLE PRECISION frnh4
      DOUBLE PRECISION frnh4irb
      INTEGER j
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbirb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccirb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddirb
      INTEGER i
      DOUBLE PRECISION delt
      DOUBLE PRECISION deltirb
      DOUBLE PRECISION arg1
      DOUBLE PRECISION arg1irb
      INTEGER branch, npflag, ncase
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp3
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp4irb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp5irb
      DOUBLE PRECISION min1
      DOUBLE PRECISION min1irb
      INTRINSIC MAX
      DOUBLE PRECISION temp2irb0
      DOUBLE PRECISION temp0irb
      DOUBLE PRECISION temp1irb
      DOUBLE PRECISION temp2irb
      INTRINSIC MIN
      INTRINSIC SQRT
      DOUBLE PRECISION temp3irb
      DOUBLE PRECISION temp5
      DOUBLE PRECISION temp4
      COMMON /gas_irb/ gnh3irb
      COMMON /ions_irb/ molalirb, gamairb, waterirb
C         
C      waer = waerp
      w = waer
C
C *** FIND DRY COMPOSITION ********************************************
C
C      CALL CALCI1A
C
C *** CALCULATE NON VOLATILE SOLIDS ***********************************
C
      cna2so4 = 0.5d0*w(1)
      cnh4hs4 = zero
      cnahso4 = zero
      cnh42s4 = zero
      IF (w(2) - cna2so4 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frso4 = zero
      ELSE
        frso4 = w(2) - cna2so4
        CALL PUSHCONTROL1B(1)
      END IF
      IF (w(3)/3.d0 .GT. frso4/2.d0) THEN
        clc = frso4/2.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        clc = w(3)/3.d0
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frso4 - 2.d0*clc .LT. zero) THEN
        frso4 = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        frso4 = frso4 - 2.d0*clc
        CALL PUSHCONTROL1B(1)
      END IF
      IF (w(3) - 3.d0*clc .LT. zero) THEN
        frnh4 = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        frnh4 = w(3) - 3.d0*clc
        CALL PUSHCONTROL1B(1)
      END IF
C
      IF (frso4 .LE. tiny) THEN
        IF (clc - frnh4 .LT. zero) THEN
          clc = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          clc = clc - frnh4
          CALL PUSHCONTROL1B(1)
        END IF
        cnh42s4 = 2.d0*frnh4
C
        CALL PUSHCONTROL3B(0)
      ELSE IF (frnh4 .LE. tiny) THEN
        IF (frso4 .GT. clc) THEN
          min1 = clc
          CALL PUSHCONTROL1B(0)
        ELSE
          min1 = frso4
          CALL PUSHCONTROL1B(1)
        END IF
        cnh4hs4 = 3.d0*min1
        IF (clc - frso4 .LT. zero) THEN
          clc = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          clc = clc - frso4
          CALL PUSHCONTROL1B(1)
        END IF
        IF (cna2so4 .GT. tiny) THEN
          IF (frso4 - cnh4hs4/3.d0 .LT. zero) THEN
            frso4 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            frso4 = frso4 - cnh4hs4/3.d0
            CALL PUSHCONTROL1B(1)
          END IF
          cnahso4 = 2.d0*frso4
          IF (cna2so4 - frso4 .LT. zero) THEN
            cna2so4 = zero
            CALL PUSHCONTROL3B(4)
          ELSE
            cna2so4 = cna2so4 - frso4
            CALL PUSHCONTROL3B(3)
          END IF
        ELSE
          CALL PUSHCONTROL3B(1)
        END IF
      ELSE
        CALL PUSHCONTROL3B(2)
      END IF
C
C *** CALCULATE GAS SPECIES *********************************************
C
C
C *** SETUP PARAMETERS ************************************************
C
C Save from CALCI1 run
C
C ASSIGN INITIAL PSI's
      psi1 = cnh4hs4
      psi2 = clc
      psi3 = cnahso4
      psi4 = cna2so4
      psi5 = cnh42s4
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      j = 1
      ad_count = 0
      DO WHILE (j .LE. nsweep .AND. calain)
C
        a6 = xk1*water/gama(7)*(gama(8)/gama(7))**2.d0
C
C  CALCULATE DISSOCIATION QUANTITIES
C
C PSI6
        bb = psi2 + psi4 + psi5 + a6
        cc = -(a6*(psi2+psi3+psi1))
        dd = bb*bb - 4.d0*cc
        psi6 = 0.5d0*(-bb+SQRT(dd))
        CALL PUSHREAL8(molal(1))
C
C *** CALCULATE SPECIATION ********************************************
C
C HI
        molal(1) = psi6
        CALL PUSHREAL8(molal(2))
C NAI
        molal(2) = 2.d0*psi4 + psi3
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = 3.d0*psi2 + 2.d0*psi5 + psi1
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = psi2 + psi4 + psi5 + psi6
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = psi2 + psi3 + psi1 - psi6
C      CALL CALCMR                                         ! Water content
C (NH4)2SO4
        molalr(4) = psi5
C NA2SO4
        molalr(2) = psi4
C NH4HSO4
        molalr(9) = psi1
C NAHSO4
        molalr(12) = psi3
C LC
        molalr(13) = psi2
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO i=1,npair
          water = water + molalr(i)/m0(i)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3()
        j = j + 1
        ad_count = ad_count + 1
      ENDDO
      CALL PUSHINTEGER4(ad_count)
C      CALL CALCNHP                ! HNO3, NH3, HCL in gas phase
C
C     Inserting subroutine here (slc.3.2012 - for adjoint development)
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        waerirb = 0.D0
        molalirb = 0.D0
        gamairb = 0.D0
        waterirb = 0.D0
      ELSE
C
C *** CALCULATE EQUILIBRIUM CONSTANTS ***********************************
C
        a3 = xk3*r*temp*(water/gama(11))**2.0
        a4 = xk4*r*temp*(water/gama(10))**2.0
        CALL PUSHREAL8(molal(1))
C H+ increases because NO3, Cl are added.
        molal(1) = molal(1) + waer(4) + waer(5)
C
C *** CALCULATE CONCENTRATIONS ******************************************
C *** ASSUME THAT 'DELT' FROM HNO3 >> 'DELT' FROM HCL
C
        arg1 = molal(1) + molal(7) + molal(4)
        CALL CALCNIAQ(waer(4), arg1, delt)
        CALL PUSHREAL8(molal(1))
        molal(1) = molal(1) - delt
        CALL PUSHREAL8(molal(7))
C NO3- = Waer(4) minus any turned into (HNO3aq)
        molal(7) = waer(4) - delt
C
        arg1 = molal(1) + molal(7) + molal(4)
        CALL CALCCLAQ(waer(5), arg1, delt)
        CALL PUSHREAL8(molal(1))
        molal(1) = molal(1) - delt
        CALL PUSHREAL8(molal(4))
C Cl- = Waer(4) minus any turned into (HNO3aq)
        molal(4) = waer(5) - delt
C
C
C
C *** CALCULATE TOTAL AMOUNT OF SPECIES WITH GAS PHASE ****************
C
C      WTP(1) = WAER(1)                C Total gas+aerosol phase
C      WTP(2) = WAER(2)
C      WTP(3) = WAER(3) + GNH3 
C      WTP(4) = WAER(4) + GHNO3
C      WTP(5) = WAER(5) + GHCL
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C Gaseous aerosol species
        aerliqpirb(nions+ngasaq+2) = 0.D0
        waterirb = 1.0d3*aerliqpirb(nions+1)/18.0d0
        aerliqpirb(nions+1) = 0.D0
        gasaqirb = 0.D0
        DO i=ngasaq,1,-1
          gasaqirb(i) = gasaqirb(i) + aerliqpirb(nions+1+i)
          aerliqpirb(nions+1+i) = 0.D0
        ENDDO
        molalirb = 0.D0
        DO i=nions,1,-1
          molalirb(i) = molalirb(i) + aerliqpirb(i)
          aerliqpirb(i) = 0.D0
        ENDDO
        ghclirb = gaspirb(3)
        gaspirb(3) = 0.D0
        ghno3irb = gaspirb(2)
        gaspirb(2) = 0.D0
        gnh3irb = gaspirb(1)
        gaspirb(1) = 0.D0
        CALL CALCNH3P_IRB()
        temp5irb = molal(4)*ghclirb/a3
        temp5 = molal(1)/a3
        molalirb(1) = molalirb(1) + temp5irb
        a3irb = -(temp5*temp5irb)
        molalirb(4) = molalirb(4) + temp5*ghclirb
        temp4irb = molal(7)*ghno3irb/a4
        temp4 = molal(1)/a4
        molalirb(1) = molalirb(1) + temp4irb
        a4irb = -(temp4*temp4irb)
        molalirb(7) = molalirb(7) + temp4*ghno3irb
        deltirb = gasaqirb(2) - molalirb(4)
        gasaqirb(2) = 0.D0
        waerirb = 0.D0
        CALL POPREAL8(molal(4))
        waerirb(5) = waerirb(5) + molalirb(4)
        molalirb(4) = 0.D0
        CALL POPREAL8(molal(1))
        deltirb = deltirb - molalirb(1)
        CALL CALCCLAQ_IRB(waer(5), waerirb(5), arg1, arg1irb, delt, 
     +                    deltirb)
        molalirb(1) = molalirb(1) + arg1irb
        molalirb(7) = molalirb(7) + arg1irb
        molalirb(4) = molalirb(4) + arg1irb
        deltirb = gasaqirb(3) - molalirb(7)
        CALL POPREAL8(molal(7))
        waerirb(4) = waerirb(4) + molalirb(7)
        molalirb(7) = 0.D0
        CALL POPREAL8(molal(1))
        deltirb = deltirb - molalirb(1)
        arg1 = molal(1) + molal(7) + molal(4)
        CALL CALCNIAQ_IRB(waer(4), waerirb(4), arg1, arg1irb, delt, 
     +                    deltirb)
        molalirb(1) = molalirb(1) + arg1irb
        molalirb(7) = molalirb(7) + arg1irb
        molalirb(4) = molalirb(4) + arg1irb
        CALL POPREAL8(molal(1))
        waerirb(4) = waerirb(4) + molalirb(1)
        waerirb(5) = waerirb(5) + molalirb(1)
        temp3 = water/gama(10)
        temp3irb = 2.0*temp3*xk4*r*temp*a4irb/gama(10)
        gamairb(10) = gamairb(10) - temp3*temp3irb
        temp2 = water/gama(11)
        temp2irb0 = 2.0*temp2*xk3*r*temp*a3irb/gama(11)
        waterirb = waterirb + temp2irb0 + temp3irb
        gamairb(11) = gamairb(11) - temp2*temp2irb0
      END IF
      molalrirb = 0.D0
      psi1irb = 0.D0
      psi2irb = 0.D0
      psi3irb = 0.D0
      psi4irb = 0.D0
      psi5irb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_IRB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterirb = 0.D0
        DO i=npair,1,-1
          molalrirb(i) = molalrirb(i) + waterirb/m0(i)
        ENDDO
        CALL POPREAL8(water)
        psi2irb = psi2irb + molalirb(6) + molalrirb(13)
        molalrirb(13) = 0.D0
        psi3irb = psi3irb + molalirb(6) + molalrirb(12)
        molalrirb(12) = 0.D0
        psi1irb = psi1irb + molalirb(6) + molalrirb(9)
        molalrirb(9) = 0.D0
        CALL POPREAL8(molal(6))
        psi6irb = -molalirb(6)
        molalirb(6) = 0.D0
        psi4irb = psi4irb + molalirb(5) + molalrirb(2)
        molalrirb(2) = 0.D0
        psi5irb = psi5irb + molalirb(5) + molalrirb(4)
        molalrirb(4) = 0.D0
        CALL POPREAL8(molal(5))
        psi2irb = psi2irb + molalirb(5)
        psi6irb = psi6irb + molalirb(5)
        molalirb(5) = 0.D0
        CALL POPREAL8(molal(3))
        psi2irb = psi2irb + 3.d0*molalirb(3)
        psi5irb = psi5irb + 2.d0*molalirb(3)
        psi1irb = psi1irb + molalirb(3)
        molalirb(3) = 0.D0
        CALL POPREAL8(molal(2))
        psi4irb = psi4irb + 2.d0*molalirb(2)
        psi3irb = psi3irb + molalirb(2)
        molalirb(2) = 0.D0
        CALL POPREAL8(molal(1))
        psi6irb = psi6irb + molalirb(1)
        molalirb(1) = 0.D0
        a6 = xk1*water/gama(7)*(gama(8)/gama(7))**2.d0
        bb = psi2 + psi4 + psi5 + a6
        cc = -(a6*(psi2+psi3+psi1))
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddirb = 0.0
        ELSE
          ddirb = 0.5d0*psi6irb/(2.0*SQRT(dd))
        END IF
        bbirb = 2*bb*ddirb - 0.5d0*psi6irb
        ccirb = -(4.d0*ddirb)
        temp2irb = -(a6*ccirb)
        a6irb = bbirb - (psi2+psi3+psi1)*ccirb
        psi2irb = psi2irb + bbirb + temp2irb
        psi3irb = psi3irb + temp2irb
        psi1irb = psi1irb + temp2irb
        psi4irb = psi4irb + bbirb
        psi5irb = psi5irb + bbirb
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0irb = 2.d0*temp0*temp1*xk1*a6irb/gama(7)
        temp1irb = temp0**2.d0*xk1*a6irb/gama(7)
        gamairb(8) = gamairb(8) + temp0irb
        gamairb(7) = gamairb(7) - temp1*temp1irb - temp0*temp0irb
        waterirb = temp1irb
      ENDDO
      cnh42s4irb = psi5irb
      cna2so4irb = psi4irb
      cnahso4irb = psi3irb
      clcirb = psi2irb
      cnh4hs4irb = psi1irb
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          frnh4irb = 2.d0*cnh42s4irb
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            clcirb = 0.D0
          ELSE
            frnh4irb = frnh4irb - clcirb
          END IF
          frso4irb = 0.D0
          GOTO 110
        ELSE
          frso4irb = 0.D0
        END IF
      ELSE IF (branch .EQ. 2) THEN
        frso4irb = 0.D0
        GOTO 100
      ELSE
        IF (branch .EQ. 3) THEN
          frso4irb = -cna2so4irb
        ELSE
          cna2so4irb = 0.D0
          frso4irb = 0.D0
        END IF
        frso4irb = frso4irb + 2.d0*cnahso4irb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          frso4irb = 0.D0
        ELSE
          cnh4hs4irb = cnh4hs4irb - frso4irb/3.d0
        END IF
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        clcirb = 0.D0
      ELSE
        frso4irb = frso4irb - clcirb
      END IF
      min1irb = 3.d0*cnh4hs4irb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        clcirb = clcirb + min1irb
      ELSE
        frso4irb = frso4irb + min1irb
      END IF
 100  frnh4irb = 0.D0
 110  CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        wirb = 0.D0
      ELSE
        wirb = 0.D0
        wirb(3) = wirb(3) + frnh4irb
        clcirb = clcirb - 3.d0*frnh4irb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frso4irb = 0.D0
      ELSE
        clcirb = clcirb - 2.d0*frso4irb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frso4irb = frso4irb + clcirb/2.d0
      ELSE
        wirb(3) = wirb(3) + clcirb/3.d0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wirb(2) = wirb(2) + frso4irb
        cna2so4irb = cna2so4irb - frso4irb
      END IF
      wirb(1) = wirb(1) + 0.5d0*cna2so4irb
      waerirb = waerirb + wirb
      waerpirb = 0.D0
      waerpirb = waerirb
C
C *** adjoint development **********************************************
C
C      ncase = 19
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpirb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END


C  Differentiation of calcnh3p in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3P
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE INVERSE PROBLEM SOLVER
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3P_IRB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3P ****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalirb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamairb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterirb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3irb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1irb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION wb(ncomp)
      COMMON /inpt_b/ wb
C
C *** Case A adjoint ***************************************************
C
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION waterab
      COMMON /ions_ab/ molalab, gamaab, waterab
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt_ab/ wab
      DOUBLE PRECISION gnh3ab
      COMMON /gas_ab/ gnh3ab
CC
CC *** Case B adjoint ***************************************************
CC
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION waterbb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
      DOUBLE PRECISION gnh3bb
      COMMON /gas_bb/ gnh3bb
CC
CC *** Case C adjoint ***************************************************
CC
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION watercb
      COMMON /ions_cb/ molalcb, gamacb, watercb
      DOUBLE PRECISION gnh3cb
      COMMON /gas_cb/ gnh3cb
CC
CC *** Case D adjoint ***************************************************
CC
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2db
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas_db/ gnh3db, ghno3db
