CC *** Case E adjoint ***************************************************
CC
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION watereb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt_eb/ web
      DOUBLE PRECISION ghno3eb
      COMMON /gas_eb/ ghno3eb
CC
CC *** Case F adjoint ***************************************************
CC
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION waterfb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt_fb/ wfb
      DOUBLE PRECISION ghno3fb
      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0irb(6, 4), sionirb, hirb, chirb, f1irb(3), 
     +                 f2irb(4)
      DOUBLE PRECISION mpl, xij, yji, check
      DOUBLE PRECISION mplirb, xijirb, yjiirb
      CHARACTER*40 errinf
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01irb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02irb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03irb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04irb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05irb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06irb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07irb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08irb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09irb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10irb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11irb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12irb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0irb13
      DOUBLE PRECISION temp0irb12
      DOUBLE PRECISION temp0irb11
      DOUBLE PRECISION temp0irb10
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0irb9
      DOUBLE PRECISION temp0irb8
      DOUBLE PRECISION temp0irb7
      DOUBLE PRECISION temp0irb6
      DOUBLE PRECISION temp0irb5
      DOUBLE PRECISION temp0irb4
      DOUBLE PRECISION temp0irb3
      DOUBLE PRECISION temp0irb
      DOUBLE PRECISION temp0irb2
      DOUBLE PRECISION temp0irb1
      DOUBLE PRECISION temp0irb0
      DOUBLE PRECISION x1irb
      INTRINSIC MIN
      INTRINSIC SQRT
      DOUBLE PRECISION x2irb
      DOUBLE PRECISION y1
      COMMON /gas_irb/ gnh3irb
      COMMON /ions_irb/ molalirb, gamairb, waterirb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 200.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamairb(i) = 10.d0**gama(i)*LOG(10.d0)*gamairb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamairb(i) = 0.D0
          x2irb = 0.D0
        ELSE
          x2irb = gamairb(i)
          gamairb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamairb(i) = gamairb(i) + x2irb
      ENDDO
      CALL POPREAL8(gama(13))
      gamairb(4) = gamairb(4) + 0.2d0*3.d0*gamairb(13)
      gamairb(9) = gamairb(9) + 0.2d0*2.d0*gamairb(13)
      gamairb(13) = 0.D0
      f1irb = 0.D0
      f2irb = 0.D0
      CALL POPREAL8(gama(12))
      temp0irb2 = zz(12)*gamairb(12)/(z(2)+z(6))
      f1irb(2) = f1irb(2) + temp0irb2/z(2)
      f2irb(3) = f2irb(3) + temp0irb2/z(6)
      hirb = -(zz(12)*gamairb(12))
      gamairb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0irb3 = zz(11)*gamairb(11)/(z(1)+z(4))
      f2irb(1) = f2irb(1) + temp0irb3/z(4)
      hirb = hirb - zz(11)*gamairb(11)
      gamairb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0irb4 = zz(10)*gamairb(10)/(z(1)+z(7))
      f1irb(1) = f1irb(1) + temp0irb4/z(1) + temp0irb3/z(1)
      f2irb(4) = f2irb(4) + temp0irb4/z(7)
      hirb = hirb - zz(10)*gamairb(10)
      gamairb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0irb5 = zz(9)*gamairb(9)/(z(3)+z(6))
      f1irb(3) = f1irb(3) + temp0irb5/z(3)
      hirb = hirb - zz(9)*gamairb(9)
      gamairb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0irb6 = zz(8)*gamairb(8)/(z(1)+z(6))
      f2irb(3) = f2irb(3) + temp0irb6/z(6) + temp0irb5/z(6)
      hirb = hirb - zz(8)*gamairb(8)
      gamairb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0irb7 = zz(7)*gamairb(7)/(z(1)+z(5))
      f1irb(1) = f1irb(1) + temp0irb7/z(1) + temp0irb6/z(1)
      f2irb(2) = f2irb(2) + temp0irb7/z(5)
      hirb = hirb - zz(7)*gamairb(7)
      gamairb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0irb8 = zz(6)*gamairb(6)/(z(3)+z(4))
      f2irb(1) = f2irb(1) + temp0irb8/z(4)
      hirb = hirb - zz(6)*gamairb(6)
      gamairb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0irb9 = zz(5)*gamairb(5)/(z(3)+z(7))
      f2irb(4) = f2irb(4) + temp0irb9/z(7)
      hirb = hirb - zz(5)*gamairb(5)
      gamairb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0irb10 = zz(4)*gamairb(4)/(z(3)+z(5))
      f1irb(3) = f1irb(3) + temp0irb9/z(3) + temp0irb10/z(3) + temp0irb8
     +  /z(3)
      f2irb(2) = f2irb(2) + temp0irb10/z(5)
      hirb = hirb - zz(4)*gamairb(4)
      gamairb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0irb11 = zz(3)*gamairb(3)/(z(2)+z(7))
      f2irb(4) = f2irb(4) + temp0irb11/z(7)
      hirb = hirb - zz(3)*gamairb(3)
      gamairb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0irb12 = zz(2)*gamairb(2)/(z(2)+z(5))
      f2irb(2) = f2irb(2) + temp0irb12/z(5)
      hirb = hirb - zz(2)*gamairb(2)
      gamairb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0irb13 = zz(1)*gamairb(1)/(z(2)+z(4))
      f1irb(2) = f1irb(2) + temp0irb12/z(2) + temp0irb13/z(2) + 
     +  temp0irb11/z(2)
      f2irb(1) = f2irb(1) + temp0irb13/z(4)
      hirb = hirb - zz(1)*gamairb(1)
      gamairb(1) = 0.D0
      ionicirb = 0.D0
      g0irb = 0.D0
      DO i=3,1,-1
        mplirb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijirb = (g0(i, j)+zpl*zmi*h)*f2irb(j)
          yji = ch*molal(j+3)/water
          g0irb(i, j) = g0irb(i, j) + yji*f1irb(i) + xij*f2irb(j)
          hirb = hirb + yji*zpl*zmi*f1irb(i) + xij*zpl*zmi*f2irb(j)
          yjiirb = (g0(i, j)+zpl*zmi*h)*f1irb(i)
          temp0irb1 = molal(j+3)*yjiirb/water
          molalirb(j+3) = molalirb(j+3) + ch*yjiirb/water
          chirb = mpl*xijirb + temp0irb1
          waterirb = waterirb - ch*temp0irb1/water
          mplirb = mplirb + ch*xijirb
          ionicirb = ionicirb - (zpl+zmi)**2*0.25d0*chirb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalirb(i) = molalirb(i) + mplirb/water
        waterirb = waterirb - molal(i)*mplirb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0irb0 = agama*hirb/(sion+1.d0)
      sionirb = (1.D0-sion/(sion+1.d0))*temp0irb0
      IF (.NOT.ionic .EQ. 0.0) ionicirb = ionicirb + sionirb/(2.0*SQRT(
     +    ionic))
      g05irb = g0irb(3, 4)
      g0irb(3, 4) = 0.D0
      g09irb = g0irb(3, 3)
      g0irb(3, 3) = 0.D0
      g04irb = g0irb(3, 2)
      g0irb(3, 2) = 0.D0
      g06irb = g0irb(3, 1)
      g0irb(3, 1) = 0.D0
      g03irb = g0irb(2, 4)
      g0irb(2, 4) = 0.D0
      g12irb = g0irb(2, 3)
      g0irb(2, 3) = 0.D0
      g02irb = g0irb(2, 2)
      g0irb(2, 2) = 0.D0
      g01irb = g0irb(2, 1)
      g0irb(2, 1) = 0.D0
      g10irb = g0irb(1, 4)
      g0irb(1, 4) = 0.D0
      g08irb = g0irb(1, 3)
      g0irb(1, 3) = 0.D0
      g07irb = g0irb(1, 2)
      g0irb(1, 2) = 0.D0
      g11irb = g0irb(1, 1)
      CALL KMFUL3_IRB(ionic, ionicirb, temp, g01, g01irb, g02, g02irb, 
     +                g03, g03irb, g04, g04irb, g05, g05irb, g06, g06irb
     +                , g07, g07irb, g08, g08irb, g09, g09irb, g10, 
     +                g10irb, g11, g11irb, g12, g12irb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1irb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1irb = ionicirb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicirb = 0.D0
      ELSE
        temp0irb = 0.5d0*x1irb/water
        ionicirb = temp0irb
        waterirb = waterirb - ionic*temp0irb/water
      END IF
      DO i=7,1,-1
        molalirb(i) = molalirb(i) + z(i)**2*ionicirb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_IRB(ionic, ionicirb, temp, g01, g01irb, g02, 
     +                      g02irb, g03, g03irb, g04, g04irb, g05, 
     +                      g05irb, g06, g06irb, g07, g07irb, g08, 
     +                      g08irb, g09, g09irb, g10, g10irb, g11, 
     +                      g11irb, g12, g12irb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicirb, sionirb, cf2irb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01irb, g02irb, g03irb, g04irb, g05irb, g06irb, 
     +                 g07irb, g08irb, g09irb, g10irb, g11irb, g12irb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      INTRINSIC ABS
      DOUBLE PRECISION temp0irb
      DOUBLE PRECISION temp0irb0
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01irb = g01irb + g12irb
      g08irb = g08irb + g09irb + g12irb
      g11irb = g11irb - g09irb - g12irb
      g06irb = g06irb + g09irb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2irb = -(z10*g10irb) - z07*g07irb - z05*g05irb - z03*g03irb - 
     +    z01*g01irb - z02*g02irb - z04*g04irb - z06*g06irb - z08*g08irb
     +    - z11*g11irb
        g11irb = cf1*g11irb
        g10irb = cf1*g10irb
        g08irb = cf1*g08irb
        g07irb = cf1*g07irb
        g06irb = cf1*g06irb
        g05irb = cf1*g05irb
        g04irb = cf1*g04irb
        g03irb = cf1*g03irb
        g02irb = cf1*g02irb
        g01irb = cf1*g01irb
        temp0irb = (0.125d0-ti*0.005d0)*cf2irb
        temp0irb0 = -(0.41d0*temp0irb/(sion+1.d0))
        ionicirb = ionicirb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0irb
        sionirb = (1.D0-sion/(sion+1.d0))*temp0irb0
      ELSE
        sionirb = 0.D0
      END IF
      CALL MKBI_IRB(q11, ionic, ionicirb, sion, sionirb, z11, g11, 
     +              g11irb)
      CALL MKBI_IRB(q10, ionic, ionicirb, sion, sionirb, z10, g10, 
     +              g10irb)
      CALL MKBI_IRB(q8, ionic, ionicirb, sion, sionirb, z08, g08, g08irb
     +             )
      CALL MKBI_IRB(q7, ionic, ionicirb, sion, sionirb, z07, g07, g07irb
     +             )
      CALL MKBI_IRB(q6, ionic, ionicirb, sion, sionirb, z06, g06, g06irb
     +             )
      CALL MKBI_IRB(q5, ionic, ionicirb, sion, sionirb, z05, g05, g05irb
     +             )
      CALL MKBI_IRB(q4, ionic, ionicirb, sion, sionirb, z04, g04, g04irb
     +             )
      CALL MKBI_IRB(q3, ionic, ionicirb, sion, sionirb, z03, g03, g03irb
     +             )
      CALL MKBI_IRB(q2, ionic, ionicirb, sion, sionirb, z02, g02, g02irb
     +             )
      CALL MKBI_IRB(q1, ionic, ionicirb, sion, sionirb, z01, g01, g01irb
     +             )
      IF (.NOT.ionic .EQ. 0.0) ionicirb = ionicirb + sionirb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_IRB(q, ionic, ionicirb, sion, sionirb, zip, bi, 
     +                    biirb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicirb, sionirb, biirb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cirb, xxirb
      INTRINSIC EXP
      DOUBLE PRECISION tempirb
      DOUBLE PRECISION tempirb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxirb = zip*biirb
      biirb = zip*biirb/(bi*LOG(10.0))
      tempirb = -(0.5107d0*xxirb/(c*sion+1.d0))
      tempirb0 = -(sion*tempirb/(c*sion+1.d0))
      sionirb = sionirb + c*tempirb0 + tempirb
      cirb = sion*tempirb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicirb = ionicirb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cirb
      ELSE
        ionicirb = ionicirb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*biirb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cirb
      END IF
      END


