C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION molalrjb(npair)
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterjb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi1jb
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi2jb
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1jb
      DOUBLE PRECISION a3
      DOUBLE PRECISION a3jb
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2jb
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      DOUBLE PRECISION lamda, kapa
      DOUBLE PRECISION lamdajb, kapajb
      INTEGER i
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbjb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccjb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddjb
      INTEGER j
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp2jb
      DOUBLE PRECISION temp0jb
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1jb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
C
C *** SETUP PARAMETERS ************************************************
C
C Outer loop activity calculation flag
      frst = .true.
      calain = .true.
      IF (w(2) - w(3) - w(1) .LT. tiny) THEN
        CALL PUSHCONTROL1B(0)
        lamda = tiny
      ELSE
        lamda = w(2) - w(3) - w(1)
        CALL PUSHCONTROL1B(1)
      END IF
C NA TOTAL as NaHSO4
      chi1 = w(1)
C NH4 TOTAL as NH4HSO4
      chi2 = w(3)
      psi1 = chi1
C ALL NH4HSO4 DELIQUESCED
      psi2 = chi2
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. calain)
C
        a3 = xk1*water/gama(7)*(gama(8)/gama(7))**2.0
C
C  CALCULATE DISSOCIATION QUANTITIES
C
C KAPA
        bb = a3 + lamda
        cc = -(a3*(lamda+psi1+psi2))
        dd = bb*bb - 4.d0*cc
        kapa = 0.5d0*(-bb+SQRT(dd))
        CALL PUSHREAL8(molal(1))
C
C *** CALCULATE SPECIATION ********************************************
C
C HI
        molal(1) = lamda + kapa
        CALL PUSHREAL8(molal(2))
C NAI
        molal(2) = psi1
        CALL PUSHREAL8(molal(3))
C NH4I
        molal(3) = psi2
        CALL PUSHREAL8(molal(4))
C CLI
        molal(4) = zero
        CALL PUSHREAL8(molal(5))
C SO4I
        molal(5) = kapa
        CALL PUSHREAL8(molal(6))
C HSO4I
        molal(6) = lamda + psi1 + psi2 - kapa
        CALL PUSHREAL8(molal(7))
C NO3I
        molal(7) = zero
C
C
C      CALL CALCMR                              ! Water content
C
C NH4HSO4
        molalr(9) = molal(3)
C NAHSO4
        molalr(12) = molal(2)
C H2SO4
        molalr(7) = molal(5) + molal(6) - molal(3) - molal(2)
        IF (molalr(7) .LT. zero) THEN
          molalr(7) = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          molalr(7) = molalr(7)
        END IF
        CALL PUSHREAL8(water)
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
        water = zero
        DO j=1,npair
          water = water + molalr(j)/m0(j)
        ENDDO
        IF (water .LT. tiny) THEN
          water = tiny
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          water = water
        END IF
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3()
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      CALL PUSHINTEGER4(ad_count)
      DO ii1=1,npair
        molalrjb(ii1) = 0.D0
      ENDDO
      psi1jb = 0.D0
      psi2jb = 0.D0
      lamdajb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_JB()
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) waterjb = 0.D0
        DO j=npair,1,-1
          molalrjb(j) = molalrjb(j) + waterjb/m0(j)
        ENDDO
        CALL POPREAL8(water)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) molalrjb(7) = 0.D0
        molaljb(5) = molaljb(5) + molalrjb(7)
        molaljb(6) = molaljb(6) + molalrjb(7)
        molaljb(3) = molaljb(3) - molalrjb(7)
        molaljb(2) = molaljb(2) - molalrjb(7)
        molalrjb(7) = 0.D0
        molaljb(2) = molaljb(2) + molalrjb(12)
        molalrjb(12) = 0.D0
        molaljb(3) = molaljb(3) + molalrjb(9)
        molalrjb(9) = 0.D0
        CALL POPREAL8(molal(7))
        molaljb(7) = 0.D0
        CALL POPREAL8(molal(6))
        lamdajb = lamdajb + molaljb(6)
        psi1jb = psi1jb + molaljb(6)
        psi2jb = psi2jb + molaljb(6)
        kapajb = -molaljb(6)
        molaljb(6) = 0.D0
        CALL POPREAL8(molal(5))
        kapajb = kapajb + molaljb(5)
        molaljb(5) = 0.D0
        CALL POPREAL8(molal(4))
        molaljb(4) = 0.D0
        CALL POPREAL8(molal(3))
        psi2jb = psi2jb + molaljb(3)
        molaljb(3) = 0.D0
        CALL POPREAL8(molal(2))
        psi1jb = psi1jb + molaljb(2)
        molaljb(2) = 0.D0
        CALL POPREAL8(molal(1))
        kapajb = kapajb + molaljb(1)
        a3 = xk1*water/gama(7)*(gama(8)/gama(7))**2.0
        bb = a3 + lamda
        cc = -(a3*(lamda+psi1+psi2))
        dd = bb*bb - 4.d0*cc
        IF (dd .EQ. 0.0) THEN
          ddjb = 0.0
        ELSE
          ddjb = 0.5d0*kapajb/(2.0*SQRT(dd))
        END IF
        bbjb = 2*bb*ddjb - 0.5d0*kapajb
        ccjb = -(4.d0*ddjb)
        temp2jb = -(a3*ccjb)
        lamdajb = lamdajb + temp2jb + bbjb + molaljb(1)
        molaljb(1) = 0.D0
        a3jb = bbjb - (lamda+psi1+psi2)*ccjb
        psi1jb = psi1jb + temp2jb
        psi2jb = psi2jb + temp2jb
        temp0 = water/gama(7)
        temp1 = gama(8)/gama(7)
        temp1jb = 2.0*temp1*temp0*xk1*a3jb/gama(7)
        temp0jb = temp1**2.0*xk1*a3jb/gama(7)
        gamajb(8) = gamajb(8) + temp1jb
        gamajb(7) = gamajb(7) - temp0*temp0jb - temp1*temp1jb
        waterjb = temp0jb
      ENDDO
      chi2jb = psi2jb
      chi1jb = psi1jb
      wjb(3) = wjb(3) + chi2jb
      wjb(1) = wjb(1) + chi1jb
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        wjb(2) = wjb(2) + lamdajb
        wjb(3) = wjb(3) - lamdajb
        wjb(1) = wjb(1) - lamdajb
      END IF
      END
C
C  Differentiation of calcnh3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gnh3
C   with respect to varying inputs: molal gama
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNH3
C *** CALCULATES AMMONIA IN GAS PHASE
C
C     AMMONIA IN THE GAS PHASE IS ASSUMED A MINOR SPECIES, THAT 
C     DOES NOT SIGNIFICANTLY PERTURB THE AEROSOL EQUILIBRIUM. 
C     AMMONIA GAS IS CALCULATED FROM THE NH3(g) + (H+)(l) <==> (NH4+)(l)
C     EQUILIBRIUM, USING (H+), (NH4+) FROM THE AEROSOL SOLUTION.
C
C     THIS IS THE VERSION USED BY THE DIRECT PROBLEM
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNH3_JB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNH3 *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wjb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterjb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a1jb
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION chi1jb
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION chi2jb
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION bb, cc, diak, psi
      DOUBLE PRECISION bbjb, ccjb, diakjb, psijb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION x1jb
      INTRINSIC MAX
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0jb
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1jb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
C
C *** IS THERE A LIQUID PHASE? ******************************************
C
      IF (water .LE. tiny) THEN
        DO ii1=1,npair
          gamajb(ii1) = 0.D0
        ENDDO
      ELSE
C
C *** CALCULATE NH3 SUBLIMATION *****************************************
C
        a1 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.0
        chi1 = molal(3)
        chi2 = molal(1)
C
C a=1; b!=1; c!=1 
        bb = chi2 + one/a1
        cc = -(chi1/a1)
C Always > 0
        diak = SQRT(bb*bb - 4.d0*cc)
C One positive root
        psi = 0.5*(-bb+diak)
        IF (psi .GT. chi1) THEN
          x1 = chi1
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = psi
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        chi2jb = molaljb(1)
        psijb = molaljb(1)
        molaljb(1) = 0.D0
        chi1jb = molaljb(3)
        psijb = psijb + gnh3jb - molaljb(3)
        molaljb(3) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          x1jb = 0.D0
        ELSE
          x1jb = psijb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi1jb = chi1jb + x1jb
          psijb = 0.D0
        ELSE
          psijb = x1jb
        END IF
        diakjb = 0.5*psijb
        IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
          temp1jb = 0.0
        ELSE
          temp1jb = diakjb/(2.0*SQRT(bb**2-4.d0*cc))
        END IF
        bbjb = 2*bb*temp1jb - 0.5*psijb
        ccjb = -(4.d0*temp1jb)
        chi1jb = chi1jb - ccjb/a1
        a1jb = chi1*ccjb/a1**2 - one*bbjb/a1**2
        chi2jb = chi2jb + bbjb
        molaljb(1) = molaljb(1) + chi2jb
        molaljb(3) = molaljb(3) + chi1jb
        DO ii1=1,npair
          gamajb(ii1) = 0.D0
        ENDDO
        temp0 = gama(10)/gama(5)
        temp0jb = 2.0*temp0*xk2*r*temp*a1jb/(xkw*gama(5))
        gamajb(10) = gamajb(10) + temp0jb
        gamajb(5) = gamajb(5) - temp0*temp0jb
      END IF
      END

C  Differentiation of calcnha in reverse (adjoint) mode (forward sweep):
C   gradient     of useful results: molal gama water ghno3 ghcl
C   with respect to varying inputs: w molal gama water
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNHA
C
C     THIS SUBROUTINE CALCULATES THE DISSOLUTION OF HCL, HNO3 AT
C     THE PRESENCE OF (H,SO4). HCL, HNO3 ARE CONSIDERED MINOR SPECIES,
C     THAT DO NOT SIGNIFICANTLY AFFECT THE EQUILIBRIUM POINT.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNHA_JFWD()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNHA *****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION coh, chno3, chcl, water
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION m1, m2, m3, delcl, delno, omega
      CHARACTER*40 errinf
      DOUBLE PRECISION c1
      DOUBLE PRECISION c2
      DOUBLE PRECISION c3
      INTEGER islv
      INTRINSIC MAX
      INTRINSIC MIN
C
C *** SPECIAL CASE; WATER=ZERO ******************************************
C
      IF (water .LE. tiny) THEN
        IF (w(5) - molal(4) .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(4) - molal(7) .LT. tiny) THEN
          CALL PUSHCONTROL3B(1)
        ELSE
          CALL PUSHCONTROL3B(0)
        END IF
      ELSE IF (w(5) .LE. tiny .AND. w(4) .LE. tiny) THEN
        CALL PUSHCONTROL3B(2)
      ELSE IF (w(5) .LE. tiny) THEN
        CALL PUSHREAL8ARRAY(molal, nions)
C CALL HNO3 DISSOLUTION ROUTINE
        CALL CALCNA()
C         GOTO 60
C
C *** SPECIAL CASE; HNO3=ZERO *******************************************
C
        CALL PUSHCONTROL3B(3)
      ELSE IF (w(4) .LE. tiny) THEN
        CALL PUSHREAL8ARRAY(molal, nions)
C CALL HCL DISSOLUTION ROUTINE
        CALL CALCHA()
C         GOTO 60
C      ENDIF
        CALL PUSHCONTROL3B(4)
      ELSE
C
C *** CALCULATE EQUILIBRIUM CONSTANTS ***********************************
C
C HNO3
        a3 = xk4*r*temp*(water/gama(10))**2.0
C HCL
        a4 = xk3*r*temp*(water/gama(11))**2.0
C
C *** CALCULATE CUBIC EQUATION COEFFICIENTS *****************************
C
C
C H+
        omega = molal(1)
C HNO3
        chi3 = w(4)
C HCL
        chi4 = w(5)
C
        c1 = a3*chi3
        c2 = a4*chi4
        c3 = a3 - a4
C
        m1 = (c1+c2+(omega+a4)*c3)/c3
        m2 = ((omega+a4)*c2-a4*c3*chi4)/c3
        m3 = -(a4*c2*chi4/c3)
C
C *** CALCULATE ROOTS ***************************************************
C
        CALL POLY3(m1, m2, m3, delcl, islv)
C HCL DISSOLUTION
        IF (islv .NE. 0) THEN
C TINY AMOUNTS OF HCL ASSUMED WHEN NO ROOT 
          delcl = tiny
C            WRITE (ERRINF,'(1PE10.1)') TINY
C            CALL PUSHERR (0022, ERRINF)    ! WARNING ERROR: NO SOLUTION
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        IF (delcl .GT. chi4) THEN
          delcl = chi4
          CALL PUSHCONTROL1B(0)
        ELSE
          delcl = delcl
          CALL PUSHCONTROL1B(1)
        END IF
C
        delno = c1*delcl/(c2+c3*delcl)
        IF (delno .GT. chi3) THEN
          delno = chi3
          CALL PUSHCONTROL1B(0)
        ELSE
          delno = delno
          CALL PUSHCONTROL1B(1)
        END IF
C
        IF (((delcl .LT. zero .OR. delno .LT. zero) .OR. delcl .GT. chi4
     +      ) .OR. delno .GT. chi3) THEN
          CALL PUSHREAL8(delcl)
C TINY AMOUNTS OF HCL ASSUMED WHEN NO ROOT 
          delcl = tiny
          delno = tiny
C            WRITE (ERRINF,'(1PE10.1)') TINY
C            CALL PUSHERR (0022, ERRINF)    ! WARNING ERROR: NO SOLUTION
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
CCC
CCC *** COMPARE DELTA TO TOTAL H+ ; ESTIMATE EFFECT TO HSO4 ***************
CCC
CC      IF ((DELCL+DELNO)/MOLAL(1).GT.0.1d0) THEN
CC         WRITE (ERRINF,'(1PE10.3)') (DELCL+DELNO)/MOLAL(1)*100.0
CC         CALL PUSHERR (0021, ERRINF)   
CC      ENDIF
C
C *** EFFECT ON LIQUID PHASE ********************************************
C
C H+   CHANGE
        molal(1) = molal(1) + (delno+delcl)
C CL-  CHANGE
        molal(4) = molal(4) + delcl
C NO3- CHANGE
        molal(7) = molal(7) + delno
        IF (w(5) - molal(4) .LT. tiny) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (w(4) - molal(7) .LT. tiny) THEN
          CALL PUSHREAL8(omega)
          CALL PUSHREAL8(delcl)
          CALL PUSHCONTROL3B(5)
        ELSE
          CALL PUSHREAL8(omega)
          CALL PUSHREAL8(delcl)
          CALL PUSHCONTROL3B(6)
        END IF
      END IF
      END

C  Differentiation of calcnha in reverse (adjoint) mode (backward sweep):
C   gradient     of useful results: molal gama water ghno3 ghcl
C   with respect to varying inputs: w molal gama water
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCNHA
C
C     THIS SUBROUTINE CALCULATES THE DISSOLUTION OF HCL, HNO3 AT
C     THE PRESENCE OF (H,SO4). HCL, HNO3 ARE CONSIDERED MINOR SPECIES,
C     THAT DO NOT SIGNIFICANTLY AFFECT THE EQUILIBRIUM POINT.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCNHA_JBWD()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCNHA *****************************************
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wjb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterjb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas/ gnh3, ghno3, ghcl
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION a3jb
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION a4jb
      DOUBLE PRECISION chi3
      DOUBLE PRECISION chi3jb
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION chi4jb
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION m1, m2, m3, delcl, delno, omega
      DOUBLE PRECISION m1jb, m2jb, m3jb, delcljb, delnojb, omegajb
      CHARACTER*40 errinf
      DOUBLE PRECISION c1
      DOUBLE PRECISION c1jb
      DOUBLE PRECISION c2
      DOUBLE PRECISION c2jb
      DOUBLE PRECISION c3
      DOUBLE PRECISION c3jb
      INTEGER islv
      INTEGER branch
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp2jb
      DOUBLE PRECISION temp0jb
      DOUBLE PRECISION temp2jb1
      DOUBLE PRECISION temp2jb0
      DOUBLE PRECISION temp3jb
      DOUBLE PRECISION temp3jb0
      INTRINSIC MIN
      INTEGER ii1
      DOUBLE PRECISION temp1jb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 3) THEN
        IF (branch .EQ. 0) THEN
          DO ii1=1,ncomp
            wjb(ii1) = 0.D0
          ENDDO
          wjb(4) = wjb(4) + ghno3jb
          molaljb(7) = molaljb(7) - ghno3jb
        ELSE IF (branch .EQ. 1) THEN
          DO ii1=1,ncomp
            wjb(ii1) = 0.D0
          ENDDO
        ELSE
          DO ii1=1,ncomp
            wjb(ii1) = 0.D0
          ENDDO
          GOTO 100
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          wjb(5) = wjb(5) + ghcljb
          molaljb(4) = molaljb(4) - ghcljb
        END IF
      ELSE IF (branch .LT. 5) THEN
        IF (branch .EQ. 3) THEN
          CALL POPREAL8ARRAY(molal, nions)
          CALL CALCNA_JB()
        ELSE
          CALL POPREAL8ARRAY(molal, nions)
          CALL CALCHA_JB()
        END IF
      ELSE
        IF (branch .EQ. 5) THEN
          CALL POPREAL8(delcl)
          CALL POPREAL8(omega)
          DO ii1=1,ncomp
            wjb(ii1) = 0.D0
          ENDDO
        ELSE
          CALL POPREAL8(delcl)
          CALL POPREAL8(omega)
          DO ii1=1,ncomp
            wjb(ii1) = 0.D0
          ENDDO
          wjb(4) = wjb(4) + ghno3jb
          molaljb(7) = molaljb(7) - ghno3jb
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          wjb(5) = wjb(5) + ghcljb
          molaljb(4) = molaljb(4) - ghcljb
        END IF
        delnojb = molaljb(1) + molaljb(7)
        delcljb = molaljb(1) + molaljb(4)
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPREAL8(delcl)
          delnojb = 0.D0
          delcljb = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          c1 = a3*chi3
          c2 = a4*chi4
          c3 = a3 - a4
          chi3jb = delnojb
          delnojb = 0.D0
        ELSE
          c1 = a3*chi3
          c2 = a4*chi4
          c3 = a3 - a4
          chi3jb = 0.D0
        END IF
        temp3jb = delnojb/(c2+c3*delcl)
        temp3jb0 = -(c1*delcl*temp3jb/(c2+c3*delcl))
        c1jb = delcl*temp3jb
        delcljb = delcljb + c3*temp3jb0 + c1*temp3jb
        c2jb = temp3jb0
        c3jb = delcl*temp3jb0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          chi4jb = delcljb
          delcljb = 0.D0
        ELSE
          chi4jb = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) delcljb = 0.D0
        m1 = (c1+c2+(omega+a4)*c3)/c3
        m2 = ((omega+a4)*c2-a4*c3*chi4)/c3
        m3 = -(a4*c2*chi4/c3)
        CALL POLY3_JB(m1, m1jb, m2, m2jb, m3, m3jb, delcl, delcljb, islv
     +               )
        temp2 = chi4/c3
        temp2jb = -(a4*c2*m3jb/c3)
        temp2jb0 = m2jb/c3
        temp2jb1 = m1jb/c3
        c2jb = c2jb + (omega+a4)*temp2jb0 + temp2jb1 - temp2*a4*m3jb
        chi4jb = chi4jb + a4*c2jb - a4*c3*temp2jb0 + temp2jb
        c3jb = c3jb + (-(((omega+a4)*c2-a4*c3*chi4)/c3)-chi4*a4)*
     +    temp2jb0 + (omega-(c1+c2+(omega+a4)*c3)/c3+a4)*temp2jb1 - 
     +    temp2*temp2jb
        a4jb = (c2-chi4*c3)*temp2jb0 - c3jb + chi4*c2jb + c3*temp2jb1 - 
     +    temp2*c2*m3jb
        omegajb = c3*temp2jb1 + c2*temp2jb0
        c1jb = c1jb + temp2jb1
        a3jb = chi3*c1jb + c3jb
        chi3jb = chi3jb + a3*c1jb
        wjb(5) = wjb(5) + chi4jb
        wjb(4) = wjb(4) + chi3jb
        molaljb(1) = molaljb(1) + omegajb
        temp1 = water/gama(11)
        temp1jb = 2.0*temp1*xk3*r*temp*a4jb/gama(11)
        gamajb(11) = gamajb(11) - temp1*temp1jb
        temp0 = water/gama(10)
        temp0jb = 2.0*temp0*xk4*r*temp*a3jb/gama(10)
        waterjb = waterjb + temp0jb + temp1jb
        gamajb(10) = gamajb(10) - temp0*temp0jb
      END IF
 100  CONTINUE
      END

C  Differentiation of calcha in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water ghcl
C   with respect to varying inputs: w molal gama water
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCHA
C *** CALCULATES CHLORIDES SPECIATION
C
C     HYDROCHLORIC ACID IN THE LIQUID PHASE IS ASSUMED A MINOR SPECIES,  
C     AND DOES NOT SIGNIFICANTLY PERTURB THE HSO4-SO4 EQUILIBRIUM. THE 
C     HYDROCHLORIC ACID DISSOLVED IS CALCULATED FROM THE 
C     HCL(G) <-> (H+) + (CL-) 
C     EQUILIBRIUM, USING THE (H+) FROM THE SULFATES.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCHA_JB()
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCHA ******************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wjb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterjb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION kapa, x, delt, alfa, diak
      DOUBLE PRECISION kapajb, xjb, deltjb, alfajb, diakjb
      INTEGER branch
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp1jb1
      DOUBLE PRECISION temp0jb
      DOUBLE PRECISION temp1jb0
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1jb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
CC      CHARACTER*40 errinf
C
C *** CALCULATE HCL DISSOLUTION *****************************************
C
      x = w(5)
      delt = 0.0d0
      IF (water .GT. tiny) THEN
        kapa = molal(1)
        alfa = xk3*r*temp*(water/gama(11))**2.0
        diak = SQRT((kapa+alfa)**2.0 + 4.0*alfa*x)
        delt = 0.5*(-(kapa+alfa)+diak)
CC         IF (DELT/KAPA.GT.0.1d0) THEN
CC            WRITE (ERRINF,'(1PE10.3)') DELT/KAPA*100.0
CC            CALL PUSHERR (0033, ERRINF)    
CC         ENDIF
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      IF (x - delt .LT. 0.0d0) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      deltjb = molaljb(4) + molaljb(1)
      molaljb(4) = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        xjb = 0.D0
      ELSE
        xjb = ghcljb
        deltjb = deltjb - ghcljb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        temp1jb = 0.5*deltjb
        diakjb = temp1jb
        IF ((kapa+alfa)**2.0 + 4.0*(alfa*x) .EQ. 0.0) THEN
          temp1jb1 = 0.0
        ELSE
          temp1jb1 = diakjb/(2.0*SQRT((kapa+alfa)**2.0+4.0*(alfa*x)))
        END IF
        temp1jb0 = 2.0*(kapa+alfa)*temp1jb1
        alfajb = temp1jb0 + 4.0*x*temp1jb1 - temp1jb
        kapajb = temp1jb0 - temp1jb
        xjb = xjb + 4.0*alfa*temp1jb1
        temp0 = water/gama(11)
        temp0jb = 2.0*temp0*xk3*r*temp*alfajb/gama(11)
        waterjb = waterjb + temp0jb
        gamajb(11) = gamajb(11) - temp0*temp0jb
        molaljb(1) = molaljb(1) + kapajb
      END IF
      DO ii1=1,ncomp
        wjb(ii1) = 0.D0
      ENDDO
      wjb(5) = wjb(5) + xjb
      END

