      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION alfa, delt, kapa, diak
      DOUBLE PRECISION alfajb, deltjb, kapajb, diakjb
      DOUBLE PRECISION x
      DOUBLE PRECISION xjb
      INTEGER branch
      DOUBLE PRECISION temp0
      INTRINSIC MAX
      DOUBLE PRECISION temp1jb1
      DOUBLE PRECISION temp0jb
      DOUBLE PRECISION temp1jb0
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp1jb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
CC      CHARACTER*40 errinf
C
C *** CALCULATE HNO3 DISSOLUTION ****************************************
C
      x = w(4)
      delt = 0.0d0
      IF (water .GT. tiny) THEN
        kapa = molal(1)
        alfa = xk4*r*temp*(water/gama(10))**2.0
        diak = SQRT((kapa+alfa)**2.0 + 4.0*alfa*x)
        delt = 0.5*(-(kapa+alfa)+diak)
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      IF (x - delt .LT. 0.0d0) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      deltjb = molaljb(7) + molaljb(1)
      molaljb(7) = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        xjb = 0.D0
      ELSE
        xjb = ghno3jb
        deltjb = deltjb - ghno3jb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        temp1jb = 0.5*deltjb
        diakjb = temp1jb
        IF ((kapa+alfa)**2.0 + 4.0*(alfa*x) .EQ. 0.0) THEN
          temp1jb1 = 0.0
        ELSE
          temp1jb1 = diakjb/(2.0*SQRT((kapa+alfa)**2.0+4.0*(alfa*x)))
        END IF
        temp1jb0 = 2.0*(kapa+alfa)*temp1jb1
        alfajb = temp1jb0 + 4.0*x*temp1jb1 - temp1jb
        kapajb = temp1jb0 - temp1jb
        xjb = xjb + 4.0*alfa*temp1jb1
        temp0 = water/gama(10)
        temp0jb = 2.0*temp0*xk4*r*temp*alfajb/gama(10)
        waterjb = waterjb + temp0jb
        gamajb(10) = gamajb(10) - temp0*temp0jb
        molaljb(1) = molaljb(1) + kapajb
      END IF
      DO ii1=1,ncomp
        wjb(ii1) = 0.D0
      ENDDO
      wjb(4) = wjb(4) + xjb
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_JB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      DOUBLE PRECISION wjb(ncomp)
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION ionicjb
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterjb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
C      
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0jb(6, 4), sionjb, hjb, chjb, f1jb(3), f2jb(4)
      DOUBLE PRECISION mpl, xij, yji
      DOUBLE PRECISION mpljb, xijjb, yjijb
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01jb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02jb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03jb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04jb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05jb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06jb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07jb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08jb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09jb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10jb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11jb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12jb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION x1jb
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0jb9
      DOUBLE PRECISION temp0jb8
      DOUBLE PRECISION temp0jb7
      DOUBLE PRECISION temp0jb6
      DOUBLE PRECISION x2jb
      DOUBLE PRECISION temp0jb5
      DOUBLE PRECISION temp0jb4
      DOUBLE PRECISION temp0jb3
      DOUBLE PRECISION temp0jb2
      DOUBLE PRECISION temp0jb1
      DOUBLE PRECISION temp0jb0
      DOUBLE PRECISION temp0jb
      DOUBLE PRECISION temp0jb13
      DOUBLE PRECISION temp0jb12
      DOUBLE PRECISION temp0jb11
      DOUBLE PRECISION temp0jb10
      INTRINSIC MIN
      INTEGER ii2
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION y2
      DOUBLE PRECISION y1
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      COMMON /inpt_jb/ wjb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 100.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamajb(i) = 10.d0**gama(i)*LOG(10.d0)*gamajb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamajb(i) = 0.D0
          x2jb = 0.D0
        ELSE
          x2jb = gamajb(i)
          gamajb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamajb(i) = gamajb(i) + x2jb
      ENDDO
      CALL POPREAL8(gama(13))
      gamajb(4) = gamajb(4) + 0.2d0*3.d0*gamajb(13)
      gamajb(9) = gamajb(9) + 0.2d0*2.d0*gamajb(13)
      gamajb(13) = 0.D0
      DO ii1=1,3
        f1jb(ii1) = 0.D0
      ENDDO
      DO ii1=1,4
        f2jb(ii1) = 0.D0
      ENDDO
      CALL POPREAL8(gama(12))
      temp0jb2 = zz(12)*gamajb(12)/(z(2)+z(6))
      f1jb(2) = f1jb(2) + temp0jb2/z(2)
      f2jb(3) = f2jb(3) + temp0jb2/z(6)
      hjb = -(zz(12)*gamajb(12))
      gamajb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0jb3 = zz(11)*gamajb(11)/(z(1)+z(4))
      f2jb(1) = f2jb(1) + temp0jb3/z(4)
      hjb = hjb - zz(11)*gamajb(11)
      gamajb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0jb4 = zz(10)*gamajb(10)/(z(1)+z(7))
      f1jb(1) = f1jb(1) + temp0jb4/z(1) + temp0jb3/z(1)
      f2jb(4) = f2jb(4) + temp0jb4/z(7)
      hjb = hjb - zz(10)*gamajb(10)
      gamajb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0jb5 = zz(9)*gamajb(9)/(z(3)+z(6))
      f1jb(3) = f1jb(3) + temp0jb5/z(3)
      hjb = hjb - zz(9)*gamajb(9)
      gamajb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0jb6 = zz(8)*gamajb(8)/(z(1)+z(6))
      f2jb(3) = f2jb(3) + temp0jb6/z(6) + temp0jb5/z(6)
      hjb = hjb - zz(8)*gamajb(8)
      gamajb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0jb7 = zz(7)*gamajb(7)/(z(1)+z(5))
      f1jb(1) = f1jb(1) + temp0jb7/z(1) + temp0jb6/z(1)
      f2jb(2) = f2jb(2) + temp0jb7/z(5)
      hjb = hjb - zz(7)*gamajb(7)
      gamajb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0jb8 = zz(6)*gamajb(6)/(z(3)+z(4))
      f2jb(1) = f2jb(1) + temp0jb8/z(4)
      hjb = hjb - zz(6)*gamajb(6)
      gamajb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0jb9 = zz(5)*gamajb(5)/(z(3)+z(7))
      f2jb(4) = f2jb(4) + temp0jb9/z(7)
      hjb = hjb - zz(5)*gamajb(5)
      gamajb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0jb10 = zz(4)*gamajb(4)/(z(3)+z(5))
      f1jb(3) = f1jb(3) + temp0jb9/z(3) + temp0jb10/z(3) + temp0jb8/z(3)
      f2jb(2) = f2jb(2) + temp0jb10/z(5)
      hjb = hjb - zz(4)*gamajb(4)
      gamajb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0jb11 = zz(3)*gamajb(3)/(z(2)+z(7))
      f2jb(4) = f2jb(4) + temp0jb11/z(7)
      hjb = hjb - zz(3)*gamajb(3)
      gamajb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0jb12 = zz(2)*gamajb(2)/(z(2)+z(5))
      f2jb(2) = f2jb(2) + temp0jb12/z(5)
      hjb = hjb - zz(2)*gamajb(2)
      gamajb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0jb13 = zz(1)*gamajb(1)/(z(2)+z(4))
      f1jb(2) = f1jb(2) + temp0jb12/z(2) + temp0jb13/z(2) + temp0jb11/z(
     +  2)
      f2jb(1) = f2jb(1) + temp0jb13/z(4)
      hjb = hjb - zz(1)*gamajb(1)
      gamajb(1) = 0.D0
      ionicjb = 0.D0
      DO ii1=1,4
        DO ii2=1,6
          g0jb(ii2, ii1) = 0.D0
        ENDDO
      ENDDO
      DO i=3,1,-1
        mpljb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijjb = (g0(i, j)+zpl*zmi*h)*f2jb(j)
          yji = ch*molal(j+3)/water
          g0jb(i, j) = g0jb(i, j) + yji*f1jb(i) + xij*f2jb(j)
          hjb = hjb + yji*zpl*zmi*f1jb(i) + xij*zpl*zmi*f2jb(j)
          yjijb = (g0(i, j)+zpl*zmi*h)*f1jb(i)
          temp0jb1 = molal(j+3)*yjijb/water
          molaljb(j+3) = molaljb(j+3) + ch*yjijb/water
          chjb = mpl*xijjb + temp0jb1
          waterjb = waterjb - ch*temp0jb1/water
          mpljb = mpljb + ch*xijjb
          ionicjb = ionicjb - (zpl+zmi)**2*0.25d0*chjb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molaljb(i) = molaljb(i) + mpljb/water
        waterjb = waterjb - molal(i)*mpljb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0jb0 = agama*hjb/(sion+1.d0)
      sionjb = (1.D0-sion/(sion+1.d0))*temp0jb0
      IF (.NOT.ionic .EQ. 0.0) ionicjb = ionicjb + sionjb/(2.0*SQRT(
     +    ionic))
      g05jb = g0jb(3, 4)
      g0jb(3, 4) = 0.D0
      g09jb = g0jb(3, 3)
      g0jb(3, 3) = 0.D0
      g04jb = g0jb(3, 2)
      g0jb(3, 2) = 0.D0
      g06jb = g0jb(3, 1)
      g0jb(3, 1) = 0.D0
      g03jb = g0jb(2, 4)
      g0jb(2, 4) = 0.D0
      g12jb = g0jb(2, 3)
      g0jb(2, 3) = 0.D0
      g02jb = g0jb(2, 2)
      g0jb(2, 2) = 0.D0
      g01jb = g0jb(2, 1)
      g0jb(2, 1) = 0.D0
      g10jb = g0jb(1, 4)
      g0jb(1, 4) = 0.D0
      g08jb = g0jb(1, 3)
      g0jb(1, 3) = 0.D0
      g07jb = g0jb(1, 2)
      g0jb(1, 2) = 0.D0
      g11jb = g0jb(1, 1)
      CALL KMFUL3_JB(ionic, ionicjb, temp, g01, g01jb, g02, g02jb, g03, 
     +               g03jb, g04, g04jb, g05, g05jb, g06, g06jb, g07, 
     +               g07jb, g08, g08jb, g09, g09jb, g10, g10jb, g11, 
     +               g11jb, g12, g12jb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1jb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1jb = ionicjb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicjb = 0.D0
      ELSE
        temp0jb = 0.5d0*x1jb/water
        ionicjb = temp0jb
        waterjb = waterjb - ionic*temp0jb/water
      END IF
      DO i=7,1,-1
        molaljb(i) = molaljb(i) + z(i)**2*ionicjb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_JB(ionic, ionicjb, temp, g01, g01jb, g02, g02jb
     +                     , g03, g03jb, g04, g04jb, g05, g05jb, g06, 
     +                     g06jb, g07, g07jb, g08, g08jb, g09, g09jb, 
     +                     g10, g10jb, g11, g11jb, g12, g12jb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicjb, sionjb, cf2jb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01jb, g02jb, g03jb, g04jb, g05jb, g06jb, g07jb, 
     +                 g08jb, g09jb, g10jb, g11jb, g12jb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      INTRINSIC ABS
      DOUBLE PRECISION temp0jb0
      DOUBLE PRECISION temp0jb
      DOUBLE PRECISION abs1
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs1 = tc
      ELSE
        abs1 = -tc
      END IF
      IF (abs1 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01jb = g01jb + g12jb
      g08jb = g08jb + g09jb + g12jb
      g11jb = g11jb - g09jb - g12jb
      g06jb = g06jb + g09jb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2jb = -(z10*g10jb) - z07*g07jb - z05*g05jb - z03*g03jb - z01*
     +    g01jb - z02*g02jb - z04*g04jb - z06*g06jb - z08*g08jb - z11*
     +    g11jb
        g11jb = cf1*g11jb
        g10jb = cf1*g10jb
        g08jb = cf1*g08jb
        g07jb = cf1*g07jb
        g06jb = cf1*g06jb
        g05jb = cf1*g05jb
        g04jb = cf1*g04jb
        g03jb = cf1*g03jb
        g02jb = cf1*g02jb
        g01jb = cf1*g01jb
        temp0jb = (0.125d0-ti*0.005d0)*cf2jb
        temp0jb0 = -(0.41d0*temp0jb/(sion+1.d0))
        ionicjb = ionicjb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0jb
        sionjb = (1.D0-sion/(sion+1.d0))*temp0jb0
      ELSE
        sionjb = 0.D0
      END IF
      CALL MKBI_JB(q11, ionic, ionicjb, sion, sionjb, z11, g11, g11jb)
      CALL MKBI_JB(q10, ionic, ionicjb, sion, sionjb, z10, g10, g10jb)
      CALL MKBI_JB(q8, ionic, ionicjb, sion, sionjb, z08, g08, g08jb)
      CALL MKBI_JB(q7, ionic, ionicjb, sion, sionjb, z07, g07, g07jb)
      CALL MKBI_JB(q6, ionic, ionicjb, sion, sionjb, z06, g06, g06jb)
      CALL MKBI_JB(q5, ionic, ionicjb, sion, sionjb, z05, g05, g05jb)
      CALL MKBI_JB(q4, ionic, ionicjb, sion, sionjb, z04, g04, g04jb)
      CALL MKBI_JB(q3, ionic, ionicjb, sion, sionjb, z03, g03, g03jb)
      CALL MKBI_JB(q2, ionic, ionicjb, sion, sionjb, z02, g02, g02jb)
      CALL MKBI_JB(q1, ionic, ionicjb, sion, sionjb, z01, g01, g01jb)
      IF (.NOT.ionic .EQ. 0.0) ionicjb = ionicjb + sionjb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_JB(q, ionic, ionicjb, sion, sionjb, zip, bi, bijb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicjb, sionjb, bijb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cjb, xxjb
      INTRINSIC EXP
      DOUBLE PRECISION tempjb0
      DOUBLE PRECISION tempjb
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxjb = zip*bijb
      bijb = zip*bijb/(bi*LOG(10.0))
      tempjb = -(0.5107d0*xxjb/(c*sion+1.d0))
      tempjb0 = -(sion*tempjb/(c*sion+1.d0))
      sionjb = sionjb + c*tempjb0 + tempjb
      cjb = sion*tempjb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicjb = ionicjb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cjb
      ELSE
        ionicjb = ionicjb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bijb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cjb
      END IF
      END

C  Differentiation of poly3 in reverse (adjoint) mode:
C   gradient     of useful results: root
C   with respect to varying inputs: a1 a2 a3
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE POLY3
C *** FINDS THE REAL ROOTS OF THE THIRD ORDER ALGEBRAIC EQUATION:
C     X**3 + A1*X**2 + A2*X + A3 = 0.0
C     THE EQUATION IS SOLVED ANALYTICALLY.
C
C     PARAMETERS A1, A2, A3 ARE SPECIFIED BY THE USER. THE MINIMUM
C     NONEGATIVE ROOT IS RETURNED IN VARIABLE 'ROOT'. IF NO ROOT IS 
C     FOUND (WHICH IS GREATER THAN ZERO), ROOT HAS THE VALUE 1D30.
C     AND THE FLAG ISLV HAS A VALUE GREATER THAN ZERO.
C
C     SOLUTION FORMULA IS FOUND IN PAGE 32 OF:
C     MATHEMATICAL HANDBOOK OF FORMULAS AND TABLES
C     SCHAUM'S OUTLINE SERIES
C     MURRAY SPIEGER, McGRAW-HILL, NEW YORK, 1968
C     (GREEK TRANSLATION: BY SOTIRIOS PERSIDES, ESPI, ATHENS, 1976)
C
C     A SPECIAL CASE IS CONSIDERED SEPERATELY ; WHEN A3 = 0, THEN
C     ONE ROOT IS X=0.0, AND THE OTHER TWO FROM THE SOLUTION OF THE
C     QUADRATIC EQUATION X**2 + A1*X + A2 = 0.0
C     THIS SPECIAL CASE IS CONSIDERED BECAUSE THE ANALYTICAL FORMULA 
C     DOES NOT YIELD ACCURATE RESULTS (DUE TO NUMERICAL ROUNDOFF ERRORS)
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE POLY3_JB(a1, a1jb, a2, a2jb, a3, a3jb, root, rootjb, 
     +                    islv)
      IMPLICIT NONE
      DOUBLE PRECISION thet1
      DOUBLE PRECISION thet2
      DOUBLE PRECISION zero
      DOUBLE PRECISION expon
      DOUBLE PRECISION eps
      DOUBLE PRECISION pi
C
      PARAMETER (expon=1.d0/3.d0, zero=0.d0, thet1=120.d0/180.d0, thet2=
     +   240.d0/180.d0, pi=3.14159265358932, eps=1.d-50)
C      DOUBLE PRECISION X(3)
      DOUBLE PRECISION x(3), a1, a2, a3, root
      DOUBLE PRECISION xjb(3), a1jb, a2jb, a3jb, rootjb
      INTEGER ix
      DOUBLE PRECISION d
      DOUBLE PRECISION djb
      DOUBLE PRECISION sqd
      DOUBLE PRECISION sqdjb
      DOUBLE PRECISION q
      DOUBLE PRECISION qjb
      DOUBLE PRECISION u
      DOUBLE PRECISION ujb
      DOUBLE PRECISION thet
      DOUBLE PRECISION thetjb
      DOUBLE PRECISION coef
      DOUBLE PRECISION coefjb
      DOUBLE PRECISION ssig
      DOUBLE PRECISION s
      DOUBLE PRECISION sjb
      DOUBLE PRECISION tsig
      DOUBLE PRECISION t
      DOUBLE PRECISION tjb
      INTEGER i
      INTEGER branch
      INTEGER islv
      DOUBLE PRECISION temp0
      INTRINSIC COS
      DOUBLE PRECISION tempjb0
      DOUBLE PRECISION tempjb
      INTRINSIC SIGN
      INTRINSIC ABS
      DOUBLE PRECISION abs3jb
      DOUBLE PRECISION abs4jb
      INTRINSIC ACOS
      DOUBLE PRECISION abs4
      DOUBLE PRECISION abs3
      DOUBLE PRECISION abs2
      DOUBLE PRECISION abs1
      INTRINSIC MIN
      INTEGER ii1
      INTRINSIC SQRT
      DOUBLE PRECISION temp
      DOUBLE PRECISION abs2jb
      IF (a3 .GE. 0.) THEN
        abs1 = a3
      ELSE
        abs1 = -a3
      END IF
C
C *** SPECIAL CASE : QUADRATIC*X EQUATION *****************************
C
      IF (abs1 .LE. eps) THEN
        ix = 1
        x(1) = zero
        d = a1*a1 - 4.d0*a2
        IF (d .GE. zero) THEN
          ix = 3
          sqd = SQRT(d)
          x(2) = 0.5*(-a1+sqd)
          x(3) = 0.5*(-a1-sqd)
          CALL PUSHCONTROL3B(0)
        ELSE
          CALL PUSHCONTROL3B(1)
        END IF
      ELSE
C
C *** NORMAL CASE : CUBIC EQUATION ************************************
C
C DEFINE PARAMETERS Q, U, S, T, D 
C
        q = (3.d0*a2-a1*a1)/9.d0
        u = (9.d0*a1*a2-27.d0*a3-2.d0*a1*a1*a1)/54.d0
        d = q*q*q + u*u
C
C *** CALCULATE ROOTS *************************************************
C
C  D < 0, THREE REAL ROOTS
C
        IF (d .LT. -eps) THEN
C D < -EPS  : D < ZERO
          ix = 3
          thet = expon*ACOS(u/SQRT(-(q*q*q)))
          coef = 2.d0*SQRT(-q)
          x(1) = coef*COS(thet) - expon*a1
          x(2) = coef*COS(thet+thet1*pi) - expon*a1
          x(3) = coef*COS(thet+thet2*pi) - expon*a1
C
C  D = 0, THREE REAL (ONE DOUBLE) ROOTS
C
          CALL PUSHCONTROL3B(2)
        ELSE IF (d .LE. eps) THEN
C -EPS <= D <= EPS  : D = ZERO
          ix = 2
          ssig = SIGN(1.d0, u)
          IF (u .GE. 0.) THEN
            abs2 = u
            CALL PUSHCONTROL1B(0)
          ELSE
            abs2 = -u
            CALL PUSHCONTROL1B(1)
          END IF
          s = ssig*abs2**expon
          x(1) = 2.d0*s - expon*a1
          x(2) = -s - expon*a1
C
C  D > 0, ONE REAL ROOT
C
          CALL PUSHCONTROL3B(3)
        ELSE
C D > EPS  : D > ZERO
          ix = 1
          sqd = SQRT(d)
C TRANSFER SIGN TO SSIG
          ssig = SIGN(1.d0, u + sqd)
          tsig = SIGN(1.d0, u - sqd)
          IF (u + sqd .GE. 0.) THEN
            abs3 = u + sqd
            CALL PUSHCONTROL1B(0)
          ELSE
            abs3 = -(u+sqd)
            CALL PUSHCONTROL1B(1)
          END IF
C EXPONENTIATE ABS() 
          s = ssig*abs3**expon
          IF (u - sqd .GE. 0.) THEN
            abs4 = u - sqd
            CALL PUSHCONTROL1B(0)
          ELSE
            abs4 = -(u-sqd)
            CALL PUSHCONTROL1B(1)
          END IF
          t = tsig*abs4**expon
          x(1) = s + t - expon*a1
          CALL PUSHCONTROL3B(4)
        END IF
      END IF
C
C *** SELECT APPROPRIATE ROOT *****************************************
C
      root = 1.d30
      DO i=1,ix
        IF (x(i) .GT. zero) THEN
          IF (root .GT. x(i)) THEN
            root = x(i)
            CALL PUSHCONTROL2B(1)
          ELSE
            CALL PUSHCONTROL2B(2)
            root = root
          END IF
        ELSE
          CALL PUSHCONTROL2B(0)
        END IF
      ENDDO
      DO ii1=1,3
        xjb(ii1) = 0.D0
      ENDDO
      DO i=ix,1,-1
        CALL POPCONTROL2B(branch)
        IF (branch .NE. 0) THEN
          IF (branch .EQ. 1) THEN
            xjb(i) = xjb(i) + rootjb
            rootjb = 0.D0
          END IF
        END IF
      ENDDO
      CALL POPCONTROL3B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          a1jb = -(0.5*xjb(3))
          sqdjb = -(0.5*xjb(3))
          xjb(3) = 0.D0
          sqdjb = sqdjb + 0.5*xjb(2)
          a1jb = a1jb - 0.5*xjb(2)
          IF (d .EQ. 0.0) THEN
            djb = 0.0
          ELSE
            djb = sqdjb/(2.0*SQRT(d))
          END IF
        ELSE
          a1jb = 0.D0
          djb = 0.D0
        END IF
        a1jb = a1jb + 2*a1*djb
        a2jb = -(4.d0*djb)
        a3jb = 0.D0
      ELSE
        IF (branch .EQ. 2) THEN
          coefjb = COS(thet2*pi+thet)*xjb(3)
          thetjb = -(coef*SIN(thet2*pi+thet)*xjb(3))
          a1jb = -(expon*xjb(3))
          xjb(3) = 0.D0
          coefjb = coefjb + COS(thet1*pi+thet)*xjb(2)
          thetjb = thetjb - coef*SIN(thet1*pi+thet)*xjb(2)
          a1jb = a1jb - expon*xjb(2)
          xjb(2) = 0.D0
          coefjb = coefjb + COS(thet)*xjb(1)
          thetjb = thetjb - coef*SIN(thet)*xjb(1)
          a1jb = a1jb - expon*xjb(1)
          IF (-q .EQ. 0.0) THEN
            qjb = 0.0
          ELSE
            qjb = -(2.d0*coefjb/(2.0*SQRT(-q)))
          END IF
          temp0 = -(q**3)
          temp = SQRT(temp0)
          tempjb0 = -(expon*thetjb/(SQRT(1.0-(u/temp)**2)*temp))
          ujb = tempjb0
          IF (.NOT.temp0 .EQ. 0.0) qjb = qjb + u*3*q**2*tempjb0/(2.0*
     +        temp**2)
          djb = 0.D0
        ELSE
          IF (branch .EQ. 3) THEN
            sjb = -xjb(2)
            a1jb = -(expon*xjb(2))
            xjb(2) = 0.D0
            sjb = sjb + 2.d0*xjb(1)
            a1jb = a1jb - expon*xjb(1)
            IF (abs2 .LE. 0.0 .AND. (expon .EQ. 0.0 .OR. expon .NE. INT(
     +          expon))) THEN
              abs2jb = 0.0
            ELSE
              abs2jb = ssig*expon*abs2**(expon-1)*sjb
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              ujb = abs2jb
            ELSE
              ujb = -abs2jb
            END IF
            djb = 0.D0
          ELSE
            sjb = xjb(1)
            tjb = xjb(1)
            a1jb = -(expon*xjb(1))
            IF (abs4 .LE. 0.0 .AND. (expon .EQ. 0.0 .OR. expon .NE. INT(
     +          expon))) THEN
              abs4jb = 0.0
            ELSE
              abs4jb = tsig*expon*abs4**(expon-1)*tjb
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              ujb = abs4jb
              sqdjb = -abs4jb
            ELSE
              sqdjb = abs4jb
              ujb = -abs4jb
            END IF
            IF (abs3 .LE. 0.0 .AND. (expon .EQ. 0.0 .OR. expon .NE. INT(
     +          expon))) THEN
              abs3jb = 0.0
            ELSE
              abs3jb = ssig*expon*abs3**(expon-1)*sjb
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              ujb = ujb + abs3jb
              sqdjb = sqdjb + abs3jb
            ELSE
              ujb = ujb - abs3jb
              sqdjb = sqdjb - abs3jb
            END IF
            IF (d .EQ. 0.0) THEN
              djb = 0.0
            ELSE
              djb = sqdjb/(2.0*SQRT(d))
            END IF
          END IF
          qjb = 0.D0
        END IF
        qjb = qjb + 3*q**2*djb
        ujb = ujb + 2*u*djb
        tempjb = ujb/54.d0
        a1jb = a1jb + (9.d0*a2-2.d0*3*a1**2)*tempjb - 2*a1*qjb/9.d0
        a2jb = 3.d0*qjb/9.d0 + 9.d0*a1*tempjb
        a3jb = -(27.d0*tempjb)
      END IF
      END

