      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION cli, hi, om1, om2, bb, cc, dd, delt
      DOUBLE PRECISION clijrb, hijrb, om1jrb, om2jrb, bbjrb, ccjrb, 
     +                 ddjrb, deltjrb
      DOUBLE PRECISION a32
      DOUBLE PRECISION a32jrb
      DOUBLE PRECISION del1
      DOUBLE PRECISION del1jrb
      DOUBLE PRECISION del2
      DOUBLE PRECISION del2jrb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0jrb
      DOUBLE PRECISION temp1jrb
      INTRINSIC SQRT
      COMMON /gas_jrb/ gnh3jrb
      COMMON /ions_jrb/ molaljrb, gamajrb, waterjrb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HCL) ASSUMED 1
      a32 = xk32*water/gama(11)**2.
C
C *** FIND ROOT
C
      om1 = cli
      om2 = hi
      bb = -(om1+om2+a32)
      cc = om1*om2
      dd = SQRT(bb*bb - 4.d0*cc)
C
      del1 = 0.5d0*(-bb-dd)
      del2 = 0.5d0*(-bb+dd)
C
C *** GET APPROPRIATE ROOT.
C
      IF (del1 .LT. zero) THEN
        IF ((del2 .LT. zero .OR. del2 .GT. cli) .OR. del2 .GT. hi) THEN
          del2jrb = 0.D0
        ELSE
          del2jrb = deltjrb
        END IF
        del1jrb = 0.D0
      ELSE
        del1jrb = deltjrb
        del2jrb = 0.D0
      END IF
      ddjrb = 0.5d0*del2jrb - 0.5d0*del1jrb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1jrb = 0.0
      ELSE
        temp1jrb = ddjrb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbjrb = 2*bb*temp1jrb - 0.5d0*del1jrb - 0.5d0*del2jrb
      ccjrb = -(4.d0*temp1jrb)
      om1jrb = om2*ccjrb - bbjrb
      om2jrb = om1*ccjrb - bbjrb
      a32jrb = -bbjrb
      hijrb = om2jrb
      clijrb = clijrb + om1jrb
      temp0 = gama(11)**2.
      temp0jrb = xk32*a32jrb/temp0
      waterjrb = waterjrb + temp0jrb
      gamajrb(11) = gamajrb(11) - water*2.*gama(11)*temp0jrb/temp0
      END

