      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION no3i, hi, delt
      DOUBLE PRECISION no3ijrb, hijrb, deltjrb
      DOUBLE PRECISION om1, om2, bb, cc, dd, del1, del2
      DOUBLE PRECISION om1jrb, om2jrb, bbjrb, ccjrb, ddjrb, del1jrb, 
     +                 del2jrb
      DOUBLE PRECISION a42
      DOUBLE PRECISION a42jrb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0jrb
      DOUBLE PRECISION temp1jrb
      INTRINSIC SQRT
      COMMON /gas_jrb/ gnh3jrb
      COMMON /ions_jrb/ molaljrb, gamajrb, waterjrb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HNO3) ASSUMED 1
      a42 = xk42*water/gama(10)**2.
C
C *** FIND ROOT
C
      om1 = no3i
      om2 = hi
      bb = -(om1+om2+a42)
      cc = om1*om2
      dd = SQRT(bb*bb - 4.d0*cc)
C
      del1 = 0.5d0*(-bb-dd)
      del2 = 0.5d0*(-bb+dd)
C
C *** GET APPROPRIATE ROOT.
C
      IF ((del1 .LT. zero .OR. del1 .GT. hi) .OR. del1 .GT. no3i) THEN
C
        IF ((del2 .LT. zero .OR. del2 .GT. no3i) .OR. del2 .GT. hi) THEN
          del2jrb = 0.D0
        ELSE
          del2jrb = deltjrb
        END IF
        del1jrb = 0.D0
      ELSE
        del1jrb = deltjrb
        del2jrb = 0.D0
      END IF
      ddjrb = 0.5d0*del2jrb - 0.5d0*del1jrb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1jrb = 0.0
      ELSE
        temp1jrb = ddjrb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbjrb = 2*bb*temp1jrb - 0.5d0*del1jrb - 0.5d0*del2jrb
      ccjrb = -(4.d0*temp1jrb)
      om1jrb = om2*ccjrb - bbjrb
      om2jrb = om1*ccjrb - bbjrb
      a42jrb = -bbjrb
      hijrb = om2jrb
      no3ijrb = no3ijrb + om1jrb
      temp0 = gama(10)**2.
      temp0jrb = xk42*a42jrb/temp0
      waterjrb = waterjrb + temp0jrb
      gamajrb(10) = gamajrb(10) - water*2.*gama(10)*temp0jrb/temp0
      END

