      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0jrb
      DOUBLE PRECISION x1jrb
      INTRINSIC MAX
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION x2jrb
      DOUBLE PRECISION temp0jrb9
      DOUBLE PRECISION temp0jrb8
      DOUBLE PRECISION temp0jrb7
      DOUBLE PRECISION temp0jrb6
      DOUBLE PRECISION temp0jrb5
      DOUBLE PRECISION temp0jrb4
