      DOUBLE PRECISION temp0jrb2
      DOUBLE PRECISION temp0jrb1
      DOUBLE PRECISION temp0jrb0
      DOUBLE PRECISION temp0jrb13
      DOUBLE PRECISION temp0jrb12
      DOUBLE PRECISION temp0jrb11
      DOUBLE PRECISION temp0jrb10
      INTRINSIC MIN
      INTRINSIC SQRT
      DOUBLE PRECISION y1
      COMMON /gas_jrb/ gnh3jrb
      COMMON /ions_jrb/ molaljrb, gamajrb, waterjrb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 200.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamajrb(i) = 10.d0**gama(i)*LOG(10.d0)*gamajrb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamajrb(i) = 0.D0
          x2jrb = 0.D0
        ELSE
          x2jrb = gamajrb(i)
          gamajrb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamajrb(i) = gamajrb(i) + x2jrb
      ENDDO
      CALL POPREAL8(gama(13))
      gamajrb(4) = gamajrb(4) + 0.2d0*3.d0*gamajrb(13)
      gamajrb(9) = gamajrb(9) + 0.2d0*2.d0*gamajrb(13)
      gamajrb(13) = 0.D0
      f1jrb = 0.D0
      f2jrb = 0.D0
      CALL POPREAL8(gama(12))
      temp0jrb2 = zz(12)*gamajrb(12)/(z(2)+z(6))
      f1jrb(2) = f1jrb(2) + temp0jrb2/z(2)
      f2jrb(3) = f2jrb(3) + temp0jrb2/z(6)
      hjrb = -(zz(12)*gamajrb(12))
      gamajrb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0jrb3 = zz(11)*gamajrb(11)/(z(1)+z(4))
      f2jrb(1) = f2jrb(1) + temp0jrb3/z(4)
      hjrb = hjrb - zz(11)*gamajrb(11)
      gamajrb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0jrb4 = zz(10)*gamajrb(10)/(z(1)+z(7))
      f1jrb(1) = f1jrb(1) + temp0jrb4/z(1) + temp0jrb3/z(1)
      f2jrb(4) = f2jrb(4) + temp0jrb4/z(7)
      hjrb = hjrb - zz(10)*gamajrb(10)
      gamajrb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0jrb5 = zz(9)*gamajrb(9)/(z(3)+z(6))
      f1jrb(3) = f1jrb(3) + temp0jrb5/z(3)
      hjrb = hjrb - zz(9)*gamajrb(9)
      gamajrb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0jrb6 = zz(8)*gamajrb(8)/(z(1)+z(6))
      f2jrb(3) = f2jrb(3) + temp0jrb6/z(6) + temp0jrb5/z(6)
      hjrb = hjrb - zz(8)*gamajrb(8)
      gamajrb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0jrb7 = zz(7)*gamajrb(7)/(z(1)+z(5))
      f1jrb(1) = f1jrb(1) + temp0jrb7/z(1) + temp0jrb6/z(1)
      f2jrb(2) = f2jrb(2) + temp0jrb7/z(5)
      hjrb = hjrb - zz(7)*gamajrb(7)
      gamajrb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0jrb8 = zz(6)*gamajrb(6)/(z(3)+z(4))
      f2jrb(1) = f2jrb(1) + temp0jrb8/z(4)
      hjrb = hjrb - zz(6)*gamajrb(6)
      gamajrb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0jrb9 = zz(5)*gamajrb(5)/(z(3)+z(7))
      f2jrb(4) = f2jrb(4) + temp0jrb9/z(7)
      hjrb = hjrb - zz(5)*gamajrb(5)
      gamajrb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0jrb10 = zz(4)*gamajrb(4)/(z(3)+z(5))
      f1jrb(3) = f1jrb(3) + temp0jrb9/z(3) + temp0jrb10/z(3) + temp0jrb8
     +  /z(3)
      f2jrb(2) = f2jrb(2) + temp0jrb10/z(5)
      hjrb = hjrb - zz(4)*gamajrb(4)
      gamajrb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0jrb11 = zz(3)*gamajrb(3)/(z(2)+z(7))
      f2jrb(4) = f2jrb(4) + temp0jrb11/z(7)
      hjrb = hjrb - zz(3)*gamajrb(3)
      gamajrb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0jrb12 = zz(2)*gamajrb(2)/(z(2)+z(5))
      f2jrb(2) = f2jrb(2) + temp0jrb12/z(5)
      hjrb = hjrb - zz(2)*gamajrb(2)
      gamajrb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0jrb13 = zz(1)*gamajrb(1)/(z(2)+z(4))
      f1jrb(2) = f1jrb(2) + temp0jrb12/z(2) + temp0jrb13/z(2) + 
     +  temp0jrb11/z(2)
      f2jrb(1) = f2jrb(1) + temp0jrb13/z(4)
      hjrb = hjrb - zz(1)*gamajrb(1)
      gamajrb(1) = 0.D0
      ionicjrb = 0.D0
      g0jrb = 0.D0
      DO i=3,1,-1
        mpljrb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijjrb = (g0(i, j)+zpl*zmi*h)*f2jrb(j)
          yji = ch*molal(j+3)/water
          g0jrb(i, j) = g0jrb(i, j) + yji*f1jrb(i) + xij*f2jrb(j)
          hjrb = hjrb + yji*zpl*zmi*f1jrb(i) + xij*zpl*zmi*f2jrb(j)
          yjijrb = (g0(i, j)+zpl*zmi*h)*f1jrb(i)
          temp0jrb1 = molal(j+3)*yjijrb/water
          molaljrb(j+3) = molaljrb(j+3) + ch*yjijrb/water
          chjrb = mpl*xijjrb + temp0jrb1
          waterjrb = waterjrb - ch*temp0jrb1/water
          mpljrb = mpljrb + ch*xijjrb
          ionicjrb = ionicjrb - (zpl+zmi)**2*0.25d0*chjrb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molaljrb(i) = molaljrb(i) + mpljrb/water
        waterjrb = waterjrb - molal(i)*mpljrb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0jrb0 = agama*hjrb/(sion+1.d0)
      sionjrb = (1.D0-sion/(sion+1.d0))*temp0jrb0
      IF (.NOT.ionic .EQ. 0.0) ionicjrb = ionicjrb + sionjrb/(2.0*SQRT(
     +    ionic))
      g05jrb = g0jrb(3, 4)
      g0jrb(3, 4) = 0.D0
      g09jrb = g0jrb(3, 3)
      g0jrb(3, 3) = 0.D0
      g04jrb = g0jrb(3, 2)
      g0jrb(3, 2) = 0.D0
      g06jrb = g0jrb(3, 1)
      g0jrb(3, 1) = 0.D0
      g03jrb = g0jrb(2, 4)
      g0jrb(2, 4) = 0.D0
      g12jrb = g0jrb(2, 3)
      g0jrb(2, 3) = 0.D0
      g02jrb = g0jrb(2, 2)
      g0jrb(2, 2) = 0.D0
      g01jrb = g0jrb(2, 1)
      g0jrb(2, 1) = 0.D0
      g10jrb = g0jrb(1, 4)
      g0jrb(1, 4) = 0.D0
      g08jrb = g0jrb(1, 3)
      g0jrb(1, 3) = 0.D0
      g07jrb = g0jrb(1, 2)
      g0jrb(1, 2) = 0.D0
      g11jrb = g0jrb(1, 1)
      CALL KMFUL3_JRB(ionic, ionicjrb, temp, g01, g01jrb, g02, g02jrb, 
     +                g03, g03jrb, g04, g04jrb, g05, g05jrb, g06, g06jrb
     +                , g07, g07jrb, g08, g08jrb, g09, g09jrb, g10, 
     +                g10jrb, g11, g11jrb, g12, g12jrb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1jrb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1jrb = ionicjrb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicjrb = 0.D0
      ELSE
        temp0jrb = 0.5d0*x1jrb/water
        ionicjrb = temp0jrb
        waterjrb = waterjrb - ionic*temp0jrb/water
      END IF
      DO i=7,1,-1
        molaljrb(i) = molaljrb(i) + z(i)**2*ionicjrb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_JRB(ionic, ionicjrb, temp, g01, g01jrb, g02, 
     +                      g02jrb, g03, g03jrb, g04, g04jrb, g05, 
     +                      g05jrb, g06, g06jrb, g07, g07jrb, g08, 
     +                      g08jrb, g09, g09jrb, g10, g10jrb, g11, 
     +                      g11jrb, g12, g12jrb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicjrb, sionjrb, cf2jrb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01jrb, g02jrb, g03jrb, g04jrb, g05jrb, g06jrb, 
     +                 g07jrb, g08jrb, g09jrb, g10jrb, g11jrb, g12jrb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0jrb
      INTRINSIC ABS
      DOUBLE PRECISION temp0jrb0
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01jrb = g01jrb + g12jrb
      g08jrb = g08jrb + g09jrb + g12jrb
      g11jrb = g11jrb - g09jrb - g12jrb
      g06jrb = g06jrb + g09jrb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2jrb = -(z10*g10jrb) - z07*g07jrb - z05*g05jrb - z03*g03jrb - 
     +    z01*g01jrb - z02*g02jrb - z04*g04jrb - z06*g06jrb - z08*g08jrb
     +    - z11*g11jrb
        g11jrb = cf1*g11jrb
        g10jrb = cf1*g10jrb
        g08jrb = cf1*g08jrb
        g07jrb = cf1*g07jrb
        g06jrb = cf1*g06jrb
        g05jrb = cf1*g05jrb
        g04jrb = cf1*g04jrb
        g03jrb = cf1*g03jrb
        g02jrb = cf1*g02jrb
        g01jrb = cf1*g01jrb
        temp0jrb = (0.125d0-ti*0.005d0)*cf2jrb
        temp0jrb0 = -(0.41d0*temp0jrb/(sion+1.d0))
        ionicjrb = ionicjrb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0jrb
        sionjrb = (1.D0-sion/(sion+1.d0))*temp0jrb0
      ELSE
        sionjrb = 0.D0
      END IF
      CALL MKBI_JRB(q11, ionic, ionicjrb, sion, sionjrb, z11, g11, 
     +              g11jrb)
      CALL MKBI_JRB(q10, ionic, ionicjrb, sion, sionjrb, z10, g10, 
     +              g10jrb)
      CALL MKBI_JRB(q8, ionic, ionicjrb, sion, sionjrb, z08, g08, g08jrb
     +             )
      CALL MKBI_JRB(q7, ionic, ionicjrb, sion, sionjrb, z07, g07, g07jrb
     +             )
      CALL MKBI_JRB(q6, ionic, ionicjrb, sion, sionjrb, z06, g06, g06jrb
     +             )
      CALL MKBI_JRB(q5, ionic, ionicjrb, sion, sionjrb, z05, g05, g05jrb
     +             )
      CALL MKBI_JRB(q4, ionic, ionicjrb, sion, sionjrb, z04, g04, g04jrb
     +             )
      CALL MKBI_JRB(q3, ionic, ionicjrb, sion, sionjrb, z03, g03, g03jrb
     +             )
      CALL MKBI_JRB(q2, ionic, ionicjrb, sion, sionjrb, z02, g02, g02jrb
     +             )
      CALL MKBI_JRB(q1, ionic, ionicjrb, sion, sionjrb, z01, g01, g01jrb
     +             )
      IF (.NOT.ionic .EQ. 0.0) ionicjrb = ionicjrb + sionjrb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_JRB(q, ionic, ionicjrb, sion, sionjrb, zip, bi, 
     +                    bijrb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicjrb, sionjrb, bijrb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cjrb, xxjrb
      INTRINSIC EXP
      DOUBLE PRECISION tempjrb
      INTRINSIC LOG10
      DOUBLE PRECISION tempjrb0
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxjrb = zip*bijrb
      bijrb = zip*bijrb/(bi*LOG(10.0))
      tempjrb = -(0.5107d0*xxjrb/(c*sion+1.d0))
      tempjrb0 = -(sion*tempjrb/(c*sion+1.d0))
      sionjrb = sionjrb + c*tempjrb0 + tempjrb
      cjrb = sion*tempjrb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicjrb = ionicjrb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cjrb
      ELSE
        ionicjrb = ionicjrb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bijrb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cjrb
      END IF
      END

