      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION aml5, gg, del
      DOUBLE PRECISION aml5nb, ggnb, delnb
      DOUBLE PRECISION nh4i, no3i, so4i, hso4i, hi, ohi, nh3aq, no3aq
      DOUBLE PRECISION nh4inb, no3inb, so4inb, hso4inb, hinb, ohinb, 
     +                 nh3aqnb, no3aqnb
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3), waerp(ncomp)
      DOUBLE PRECISION aerliqpnb(nions+ngasaq+2), gaspnb(3), waerpnb(
     +                 ncomp)
      DOUBLE PRECISION wtp(ncomp)
      LOGICAL tst
      INTEGER i
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwnb
      DOUBLE PRECISION arg0
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp2nb
      INTRINSIC MAX
      DOUBLE PRECISION temp2nb1
      DOUBLE PRECISION temp2nb0
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0nb
      DOUBLE PRECISION arg0nb
      DOUBLE PRECISION temp1nb
      DOUBLE PRECISION x1nb
      INTRINSIC MIN
      COMMON /ions_nb/ molalnb, gamanb, waternb
      INTEGER npflag, ncase
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C      waer = waerp
C
C *** SETUP PARAMETERS ************************************************
C
C Outer loop activity calculation flag
      calaou = .true.
      frst = .true.
      calain = .true.
      tst = .true.
      IF (waer(2) .GT. 0.5d0*waer(3)) THEN
        molalr(4) = 0.5d0*waer(3)
        CALL PUSHCONTROL1B(0)
      ELSE
        molalr(4) = waer(2)
        CALL PUSHCONTROL1B(1)
      END IF
      IF (waer(3) - 2.d0*molalr(4) .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        aml5 = zero
      ELSE
        aml5 = waer(3) - 2.d0*molalr(4)
        CALL PUSHCONTROL1B(1)
      END IF
      IF (aml5 .GT. waer(4)) THEN
        x1 = waer(4)
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = aml5
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. zero) THEN
        molalr(5) = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        molalr(5) = x1
        CALL PUSHCONTROL1B(1)
      END IF
      water = molalr(4)/m0(4) + molalr(5)/m0(5)
      IF (water .LT. tiny) THEN
        water = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
        water = water
      END IF
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. tst)
C
        IF (i .GT. 1) THEN
          CALL PUSHREAL8ARRAY(gama, npair)
          CALL CALCACT3()
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(akw)
C
CC         A21   = XK21*WATER*R*TEMP
        akw = xkw*rh*water*water
        CALL PUSHREAL8(nh4i)
C
C ION CONCENTRATIONS
C
        nh4i = waer(3)
        CALL PUSHREAL8(no3i)
        no3i = waer(4)
        so4i = waer(2)
        hso4i = zero
        CALL PUSHREAL8(gg)
C
        gg = 2.d0*so4i + no3i - nh4i
        CALL PUSHREAL8(ohi)
        CALL PUSHREAL8(hi)
        CALL CALCPH(gg, hi, ohi)
C
C AMMONIA ASSOCIATION EQUILIBRIUM
C
        gg = 2.d0*so4i + no3i - nh4i
        IF (hi .LT. ohi) THEN
          arg0 = -gg
          CALL PUSHREAL8(nh4i)
          CALL CALCAMAQ2(arg0, nh4i, ohi, nh3aq)
          hi = akw/ohi
          CALL PUSHCONTROL1B(0)
        ELSE
          hi = zero
          CALL PUSHREAL8(hi)
          CALL PUSHREAL8(no3i)
          CALL CALCNIAQ2(gg, no3i, hi, no3aq)
C HNO3
C
C CONCENTRATION ADJUSTMENTS ; HSO4 minor species.
C
          CALL CALCHS4(hi, so4i, zero, del)
          CALL PUSHREAL8(so4i)
          so4i = so4i - del
          CALL PUSHREAL8(hi)
          hi = hi - del
          hso4i = del
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molal(1))
C
C *** SAVE CONCENTRATIONS IN MOLAL ARRAY ******************************
C
        molal(1) = hi
        CALL PUSHREAL8(molal(3))
        molal(3) = nh4i
        CALL PUSHREAL8(molal(5))
        molal(5) = so4i
        CALL PUSHREAL8(molal(6))
        molal(6) = hso4i
        CALL PUSHREAL8(molal(7))
        molal(7) = no3i
C
C
C
C   NH3AQ/A21 
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP ******************
C
        IF ((frst .AND. calaou) .OR. (.NOT.frst .AND. calain)) THEN
          tst = .true.
        ELSE
          tst = .false.
        END IF
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      IF (TST .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCN3')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
      cohnb = aerliqpnb(nions+ngasaq+2)
      aerliqpnb(nions+ngasaq+2) = 0.D0
      waternb = 1.0d3*aerliqpnb(nions+1)/18.0d0
      aerliqpnb(nions+1) = 0.D0
      gasaqnb = 0.D0
      DO i=ngasaq,1,-1
        gasaqnb(i) = gasaqnb(i) + aerliqpnb(nions+1+i)
        aerliqpnb(nions+1+i) = 0.D0
      ENDDO
      molalnb = 0.D0
      DO i=nions,1,-1
        molalnb(i) = molalnb(i) + aerliqpnb(i)
        aerliqpnb(i) = 0.D0
      ENDDO
      gaspnb(3) = 0.D0
      ghno3nb = gaspnb(2)
      gaspnb(2) = 0.D0
      gnh3nb = gaspnb(1)
      gaspnb(1) = 0.D0
      waernb = 0.D0
      gamanb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        a3 = xk4*r*temp*(water/gama(10))**2.0
        temp2nb1 = ghno3nb/a3
        no3inb = molalnb(7) + hi*temp2nb1
        molalnb(7) = 0.D0
        hso4inb = molalnb(6)
        molalnb(6) = 0.D0
        so4inb = molalnb(5)
        molalnb(5) = 0.D0
        a2 = xk2*r*temp/xkw/rh*(gama(8)/gama(9))**2.
        temp2nb = gnh3nb/(hi*a2)
        temp2nb0 = -(nh4i*temp2nb/(hi*a2))
        nh4inb = molalnb(3) + temp2nb
        a2nb = hi*temp2nb0
        a3nb = -(hi*no3i*temp2nb1/a3)
        no3aqnb = gasaqnb(3)
        gasaqnb(3) = 0.D0
        nh3aqnb = gasaqnb(1)
        gasaqnb(1) = 0.D0
        ohinb = cohnb
        CALL POPREAL8(molal(7))
        CALL POPREAL8(molal(6))
        CALL POPREAL8(molal(5))
        CALL POPREAL8(molal(3))
        molalnb(3) = 0.D0
        hinb = no3i*temp2nb1 + molalnb(1) + a2*temp2nb0
        CALL POPREAL8(molal(1))
        molalnb(1) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          akwnb = hinb/ohi
          ohinb = ohinb - akw*hinb/ohi**2
          CALL POPREAL8(nh4i)
          CALL CALCAMAQ2_NB(arg0, arg0nb, nh4i, nh4inb, ohi, ohinb, 
     +                      nh3aq, nh3aqnb)
          ggnb = -arg0nb
        ELSE
          akw = xkw*rh*water*water
          akwnb = ohinb/hi
          hinb = hinb - akw*ohinb/hi**2
          delnb = hso4inb - so4inb - hinb
          CALL POPREAL8(hi)
          CALL POPREAL8(so4i)
          CALL CALCHS4_NB(hi, hinb, so4i, so4inb, zero, del, delnb)
          CALL POPREAL8(no3i)
          CALL POPREAL8(hi)
          CALL CALCNIAQ2_NB(gg, ggnb, no3i, no3inb, hi, hinb, no3aq, 
     +                      no3aqnb)
        END IF
        temp1 = water/gama(10)
        temp1nb = 2.0*temp1*xk4*r*temp*a3nb/gama(10)
        so4inb = so4inb + 2.d0*ggnb
        no3inb = no3inb + ggnb
        nh4inb = nh4inb - ggnb
        CALL POPREAL8(hi)
        CALL POPREAL8(ohi)
        CALL POPREAL8(gg)
        waernb(2) = waernb(2) + so4inb
        CALL POPREAL8(no3i)
        waernb(4) = waernb(4) + no3inb
        CALL POPREAL8(nh4i)
        waernb(3) = waernb(3) + nh4inb
        CALL POPREAL8(akw)
        waternb = waternb + temp1nb + xkw*rh*2*water*akwnb
        gamanb(10) = gamanb(10) - temp1*temp1nb
        temp0 = gama(8)/gama(9)
        temp0nb = 2.*temp0*xk2*r*temp*a2nb/(xkw*rh*gama(9))
        gamanb(8) = gamanb(8) + temp0nb
        gamanb(9) = gamanb(9) - temp0*temp0nb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8ARRAY(gama, npair)
          CALL CALCACT3_NB()
        END IF
        cohnb = 0.D0
        gnh3nb = 0.D0
        ghno3nb = 0.D0
      ENDDO
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) waternb = 0.D0
      molalrnb = 0.D0
      molalrnb(4) = molalrnb(4) + waternb/m0(4)
      molalrnb(5) = molalrnb(5) + waternb/m0(5)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        molalrnb(5) = 0.D0
        x1nb = 0.D0
      ELSE
        x1nb = molalrnb(5)
        molalrnb(5) = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waernb(4) = waernb(4) + x1nb
        aml5nb = 0.D0
      ELSE
        aml5nb = x1nb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waernb(3) = waernb(3) + aml5nb
        molalrnb(4) = molalrnb(4) - 2.d0*aml5nb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waernb(3) = waernb(3) + 0.5d0*molalrnb(4)
      ELSE
        waernb(2) = waernb(2) + molalrnb(4)
      END IF
      waerpnb = 0.D0
      waerpnb = waernb
C
C *** adjoint development **********************************************
C
C      ncase = 14
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpnb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END


