      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION ggno3, no3i, hi, no3aq
      DOUBLE PRECISION ggno3nb, no3inb, hinb, no3aqnb
      DOUBLE PRECISION om1, om2, bb, cc, dd, alf1, alf2, alf3, del1
      DOUBLE PRECISION bbnb, ccnb, alf1nb, alf2nb, del1nb
      DOUBLE PRECISION a42
      DOUBLE PRECISION a42nb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwnb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0nb
      DOUBLE PRECISION temp1nb
      INTRINSIC SQRT
      COMMON /ions_nb/ molalnb, gamanb, waternb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HNO3) ASSUMED 1
      a42 = xk42*water/gama(10)**2.
      akw = xkw*rh*water*water
C
C *** FIND ROOT
C
      alf1 = no3i - ggno3
      alf2 = ggno3
      alf3 = hi
C
      bb = alf3 + alf1 + a42
      cc = alf3*alf1 - a42*alf2
      del1 = 0.5*(-bb+SQRT(bb*bb-4.d0*cc))
C
C *** CORRECT CONCENTRATIONS
C
      hi = alf3 + del1
C If solution is neutral.
      IF (hi .LE. tiny) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      alf2nb = no3aqnb
      del1nb = -no3aqnb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        IF (akw .EQ. 0.0) THEN
          akwnb = 0.0
        ELSE
          akwnb = hinb/(2.0*SQRT(akw))
        END IF
        hinb = 0.D0
      ELSE
        akwnb = 0.D0
      END IF
      del1nb = del1nb + no3inb + hinb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1nb = 0.0
      ELSE
        temp1nb = 0.5*del1nb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbnb = 2*bb*temp1nb - 0.5*del1nb
      ccnb = -(4.d0*temp1nb)
      alf1nb = alf3*ccnb + bbnb + no3inb
      a42nb = bbnb - alf2*ccnb
      alf2nb = alf2nb - a42*ccnb
      ggno3nb = alf2nb - alf1nb
      no3inb = alf1nb
      temp0 = gama(10)**2.
      temp0nb = xk42*a42nb/temp0
      waternb = waternb + temp0nb + xkw*rh*2*water*akwnb
      gamanb(10) = gamanb(10) - water*2.*gama(10)*temp0nb/temp0
      END

