CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION hinb, so4inb, deltanb, bbnb, ccnb, ddnb, sqddnb, 
     +                 delta1nb, delta2nb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0nb
      DOUBLE PRECISION temp1nb
      INTRINSIC SQRT
      COMMON /ions_nb/ molalnb, gamanb, waternb
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .GT. 1d1*tiny) THEN
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2nb = deltanb
            delta1nb = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2nb = deltanb
            delta1nb = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1nb = deltanb
            ELSE
              delta1nb = 0.D0
            END IF
            delta2nb = 0.D0
          END IF
          bbnb = -(0.5*delta1nb) - 0.5*delta2nb
          sqddnb = 0.5*delta1nb - 0.5*delta2nb
          IF (dd .EQ. 0.0) THEN
            ddnb = 0.0
          ELSE
            ddnb = sqddnb/(2.0*SQRT(dd))
          END IF
        ELSE
          ddnb = 0.D0
          bbnb = 0.D0
        END IF
        bbnb = bbnb + 2*bb*ddnb
        ccnb = -(4.d0*ddnb)
        hinb = hinb + so4i*ccnb - bbnb
        so4inb = so4inb + hi*ccnb - bbnb
        a8nb = -bbnb - hso4i*ccnb
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0nb = 2.*temp0*temp1*xk1*a8nb/gama(7)
        temp1nb = temp0**2.*xk1*a8nb/gama(7)
        gamanb(8) = gamanb(8) + temp0nb
        gamanb(7) = gamanb(7) - temp1*temp1nb - temp0*temp0nb
        waternb = waternb + temp1nb
      END IF
      END

C  Differentiation of calcact3 in reverse (adjoint) mode:
C   gradient     of useful results: molal gama water
C   with respect to varying inputs: molal gama water
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCACT3
C *** CALCULATES MULTI-COMPONENT ACTIVITY COEFFICIENTS FROM BROMLEYS
C     METHOD FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C     THE BINARY ACTIVITY COEFFICIENTS ARE CALCULATED BY
C     KUSIK-MEISNER RELATION (SUBROUTINE KMTAB or SUBROUTINE KMFUL3).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE CALCACT3_NB()
      IMPLICIT NONE
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
