C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
