      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamanb(i) = 10.d0**gama(i)*LOG(10.d0)*gamanb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamanb(i) = 0.D0
          x2nb = 0.D0
        ELSE
          x2nb = gamanb(i)
          gamanb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamanb(i) = gamanb(i) + x2nb
      ENDDO
      CALL POPREAL8(gama(13))
      gamanb(4) = gamanb(4) + 0.2d0*3.d0*gamanb(13)
      gamanb(9) = gamanb(9) + 0.2d0*2.d0*gamanb(13)
      gamanb(13) = 0.D0
      f1nb = 0.D0
      f2nb = 0.D0
      CALL POPREAL8(gama(12))
      temp0nb2 = zz(12)*gamanb(12)/(z(2)+z(6))
