      CALL POPREAL8(gama(10))
      temp0nb4 = zz(10)*gamanb(10)/(z(1)+z(7))
      f1nb(1) = f1nb(1) + temp0nb4/z(1) + temp0nb3/z(1)
      f2nb(4) = f2nb(4) + temp0nb4/z(7)
      hnb = hnb - zz(10)*gamanb(10)
      gamanb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0nb5 = zz(9)*gamanb(9)/(z(3)+z(6))
      f1nb(3) = f1nb(3) + temp0nb5/z(3)
      hnb = hnb - zz(9)*gamanb(9)
      gamanb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0nb6 = zz(8)*gamanb(8)/(z(1)+z(6))
      f2nb(3) = f2nb(3) + temp0nb6/z(6) + temp0nb5/z(6)
      hnb = hnb - zz(8)*gamanb(8)
      gamanb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0nb7 = zz(7)*gamanb(7)/(z(1)+z(5))
      f1nb(1) = f1nb(1) + temp0nb7/z(1) + temp0nb6/z(1)
