      hnb = hnb - zz(7)*gamanb(7)
      gamanb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0nb8 = zz(6)*gamanb(6)/(z(3)+z(4))
      f2nb(1) = f2nb(1) + temp0nb8/z(4)
      hnb = hnb - zz(6)*gamanb(6)
      gamanb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0nb9 = zz(5)*gamanb(5)/(z(3)+z(7))
      f2nb(4) = f2nb(4) + temp0nb9/z(7)
      hnb = hnb - zz(5)*gamanb(5)
      gamanb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0nb10 = zz(4)*gamanb(4)/(z(3)+z(5))
      f1nb(3) = f1nb(3) + temp0nb9/z(3) + temp0nb10/z(3) + temp0nb8/z(3)
      f2nb(2) = f2nb(2) + temp0nb10/z(5)
      hnb = hnb - zz(4)*gamanb(4)
      gamanb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0nb11 = zz(3)*gamanb(3)/(z(2)+z(7))
      f2nb(4) = f2nb(4) + temp0nb11/z(7)
      hnb = hnb - zz(3)*gamanb(3)
      gamanb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0nb12 = zz(2)*gamanb(2)/(z(2)+z(5))
      f2nb(2) = f2nb(2) + temp0nb12/z(5)
      hnb = hnb - zz(2)*gamanb(2)
      gamanb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0nb13 = zz(1)*gamanb(1)/(z(2)+z(4))
      f1nb(2) = f1nb(2) + temp0nb12/z(2) + temp0nb13/z(2) + temp0nb11/z(
     +  2)
      f2nb(1) = f2nb(1) + temp0nb13/z(4)
      hnb = hnb - zz(1)*gamanb(1)
      gamanb(1) = 0.D0
      ionicnb = 0.D0
      g0nb = 0.D0
      DO i=3,1,-1
        mplnb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijnb = (g0(i, j)+zpl*zmi*h)*f2nb(j)
          yji = ch*molal(j+3)/water
          g0nb(i, j) = g0nb(i, j) + yji*f1nb(i) + xij*f2nb(j)
          hnb = hnb + yji*zpl*zmi*f1nb(i) + xij*zpl*zmi*f2nb(j)
          yjinb = (g0(i, j)+zpl*zmi*h)*f1nb(i)
          temp0nb1 = molal(j+3)*yjinb/water
          molalnb(j+3) = molalnb(j+3) + ch*yjinb/water
          chnb = mpl*xijnb + temp0nb1
          waternb = waternb - ch*temp0nb1/water
          mplnb = mplnb + ch*xijnb
          ionicnb = ionicnb - (zpl+zmi)**2*0.25d0*chnb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalnb(i) = molalnb(i) + mplnb/water
        waternb = waternb - molal(i)*mplnb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0nb0 = agama*hnb/(sion+1.d0)
      sionnb = (1.D0-sion/(sion+1.d0))*temp0nb0
      IF (.NOT.ionic .EQ. 0.0) ionicnb = ionicnb + sionnb/(2.0*SQRT(
     +    ionic))
      g05nb = g0nb(3, 4)
      g0nb(3, 4) = 0.D0
      g09nb = g0nb(3, 3)
      g0nb(3, 3) = 0.D0
      g04nb = g0nb(3, 2)
      g0nb(3, 2) = 0.D0
      g06nb = g0nb(3, 1)
      g0nb(3, 1) = 0.D0
      g03nb = g0nb(2, 4)
      g0nb(2, 4) = 0.D0
      g12nb = g0nb(2, 3)
      g0nb(2, 3) = 0.D0
      g02nb = g0nb(2, 2)
      g0nb(2, 2) = 0.D0
      g01nb = g0nb(2, 1)
      g0nb(2, 1) = 0.D0
      g10nb = g0nb(1, 4)
      g0nb(1, 4) = 0.D0
      g08nb = g0nb(1, 3)
      g0nb(1, 3) = 0.D0
      g07nb = g0nb(1, 2)
      g0nb(1, 2) = 0.D0
      g11nb = g0nb(1, 1)
      CALL KMFUL3_NB(ionic, ionicnb, temp, g01, g01nb, g02, g02nb, g03, 
     +               g03nb, g04, g04nb, g05, g05nb, g06, g06nb, g07, 
     +               g07nb, g08, g08nb, g09, g09nb, g10, g10nb, g11, 
     +               g11nb, g12, g12nb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1nb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1nb = ionicnb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicnb = 0.D0
      ELSE
        temp0nb = 0.5d0*x1nb/water
        ionicnb = temp0nb
        waternb = waternb - ionic*temp0nb/water
      END IF
      DO i=7,1,-1
        molalnb(i) = molalnb(i) + z(i)**2*ionicnb
      ENDDO
      END

C  Differentiation of kmful3 in reverse (adjoint) mode:
C   gradient     of useful results: g01 g02 g03 g04 g05 g06 g07
C                g08 g09 g10 g11 g12 ionic
C   with respect to varying inputs: ionic
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_NB(ionic, ionicnb, temp, g01, g01nb, g02, g02nb
     +                     , g03, g03nb, g04, g04nb, g05, g05nb, g06, 
     +                     g06nb, g07, g07nb, g08, g08nb, g09, g09nb, 
     +                     g10, g10nb, g11, g11nb, g12, g12nb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicnb, sionnb, cf2nb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01nb, g02nb, g03nb, g04nb, g05nb, g06nb, g07nb, 
     +                 g08nb, g09nb, g10nb, g11nb, g12nb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0nb0
      INTRINSIC ABS
      DOUBLE PRECISION temp0nb
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01nb = g01nb + g12nb
      g08nb = g08nb + g09nb + g12nb
      g11nb = g11nb - g09nb - g12nb
      g06nb = g06nb + g09nb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2nb = -(z10*g10nb) - z07*g07nb - z05*g05nb - z03*g03nb - z01*
     +    g01nb - z02*g02nb - z04*g04nb - z06*g06nb - z08*g08nb - z11*
     +    g11nb
        g11nb = cf1*g11nb
        g10nb = cf1*g10nb
        g08nb = cf1*g08nb
        g07nb = cf1*g07nb
        g06nb = cf1*g06nb
        g05nb = cf1*g05nb
        g04nb = cf1*g04nb
        g03nb = cf1*g03nb
        g02nb = cf1*g02nb
        g01nb = cf1*g01nb
        temp0nb = (0.125d0-ti*0.005d0)*cf2nb
        temp0nb0 = -(0.41d0*temp0nb/(sion+1.d0))
        ionicnb = ionicnb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0nb
        sionnb = (1.D0-sion/(sion+1.d0))*temp0nb0
      ELSE
        sionnb = 0.D0
      END IF
      CALL MKBI_NB(q11, ionic, ionicnb, sion, sionnb, z11, g11, g11nb)
      CALL MKBI_NB(q10, ionic, ionicnb, sion, sionnb, z10, g10, g10nb)
      CALL MKBI_NB(q8, ionic, ionicnb, sion, sionnb, z08, g08, g08nb)
      CALL MKBI_NB(q7, ionic, ionicnb, sion, sionnb, z07, g07, g07nb)
      CALL MKBI_NB(q6, ionic, ionicnb, sion, sionnb, z06, g06, g06nb)
      CALL MKBI_NB(q5, ionic, ionicnb, sion, sionnb, z05, g05, g05nb)
      CALL MKBI_NB(q4, ionic, ionicnb, sion, sionnb, z04, g04, g04nb)
      CALL MKBI_NB(q3, ionic, ionicnb, sion, sionnb, z03, g03, g03nb)
      CALL MKBI_NB(q2, ionic, ionicnb, sion, sionnb, z02, g02, g02nb)
      CALL MKBI_NB(q1, ionic, ionicnb, sion, sionnb, z01, g01, g01nb)
      IF (.NOT.ionic .EQ. 0.0) ionicnb = ionicnb + sionnb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_NB(q, ionic, ionicnb, sion, sionnb, zip, bi, binb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicnb, sionnb, binb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cnb, xxnb
      INTRINSIC EXP
      DOUBLE PRECISION tempnb0
      INTRINSIC LOG10
      DOUBLE PRECISION tempnb
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxnb = zip*binb
      binb = zip*binb/(bi*LOG(10.0))
      tempnb = -(0.5107d0*xxnb/(c*sion+1.d0))
      tempnb0 = -(sion*tempnb/(c*sion+1.d0))
      sionnb = sionnb + c*tempnb0 + tempnb
      cnb = sion*tempnb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicnb = ionicnb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cnb
      ELSE
        ionicnb = ionicnb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*binb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cnb
      END IF
      END

