      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION nh4i, nai, no3i, nh3aq, no3aq, claq
      DOUBLE PRECISION nh4iqb, naiqb, no3iqb, nh3aqqb, no3aqqb, claqqb
      DOUBLE PRECISION gas(3), aerliq(nions+ngasaq+2)
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3)
      DOUBLE PRECISION aerliqpqb(nions+ngasaq+2), gaspqb(3)
      DOUBLE PRECISION waerp(ncomp)
      DOUBLE PRECISION waerpqb(ncomp)
      LOGICAL tst
      DOUBLE PRECISION frso4
      DOUBLE PRECISION frso4qb
      DOUBLE PRECISION frnh3
      DOUBLE PRECISION frnh3qb
      INTEGER i
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwqb
      DOUBLE PRECISION so4i
      DOUBLE PRECISION so4iqb
      DOUBLE PRECISION cli
      DOUBLE PRECISION cliqb
      DOUBLE PRECISION gg
      DOUBLE PRECISION ggqb
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbqb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccqb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddqb
      DOUBLE PRECISION hi
      DOUBLE PRECISION hiqb
      DOUBLE PRECISION ohi
      DOUBLE PRECISION ohiqb
      DOUBLE PRECISION hso4i
      DOUBLE PRECISION hso4iqb
      DOUBLE PRECISION ggno3
      DOUBLE PRECISION ggno3qb
      DOUBLE PRECISION ggcl
      DOUBLE PRECISION ggclqb
      DOUBLE PRECISION del
      DOUBLE PRECISION delqb
      DOUBLE PRECISION arg0
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp2qb
      INTRINSIC MAX
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0qb
      DOUBLE PRECISION temp3qb2
      DOUBLE PRECISION temp3qb1
      DOUBLE PRECISION temp3qb0
      DOUBLE PRECISION arg0qb
      DOUBLE PRECISION temp3qb
      DOUBLE PRECISION temp1qb
      INTRINSIC MIN
      DOUBLE PRECISION x1qb
      INTRINSIC SQRT
      COMMON /ions_qb/ molalqb, gamaqb, waterqb
      INTEGER npflag, ncase
C
C *** SETUP PARAMETERS ************************************************
C
C      waer = waerp
C
      frst = .true.
      calaou = .true.
      tst = .true.
C
C *** CALCULATE INITIAL SOLUTION ***************************************
C
C      CALL CALCQ1A - code inserted below
C
C *** CALCULATE SOLIDS **************************************************
C
      cna2so4 = 0.5d0*waer(1)
      IF (waer(2) - cna2so4 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frso4 = zero
      ELSE
        frso4 = waer(2) - cna2so4
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frso4 .GT. 0.5d0*waer(3)) THEN
        x1 = 0.5d0*waer(3)
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = frso4
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        cnh42s4 = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        cnh42s4 = x1
        CALL PUSHCONTROL1B(1)
      END IF
      IF (waer(3) - 2.d0*cnh42s4 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frnh3 = zero
      ELSE
        frnh3 = waer(3) - 2.d0*cnh42s4
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frnh3 .GT. waer(4)) THEN
        cnh4no3 = waer(4)
        CALL PUSHCONTROL1B(0)
      ELSE
        cnh4no3 = frnh3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frnh3 - cnh4no3 .LT. zero) THEN
        frnh3 = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        frnh3 = frnh3 - cnh4no3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frnh3 .GT. waer(5)) THEN
        cnh4cl = waer(5)
        CALL PUSHCONTROL1B(0)
      ELSE
        cnh4cl = frnh3
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** OTHER PHASES ******************************************************
C
C
C
C SALTS DISSOLVED
      psi1 = cna2so4
      psi4 = cnh4cl
      psi5 = cnh4no3
      psi6 = cnh42s4
C
C      CALL CALCMR           ! WATER   -  code inserted here
C
C NA2SO4
      molalr(2) = psi1
C (NH4)2SO4
      molalr(4) = psi6
C NH4NO3
      molalr(5) = psi5
C NH4CL
      molalr(6) = psi4
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
      water = zero
      DO i=1,npair
        water = water + molalr(i)/m0(i)
      ENDDO
      IF (water .LT. tiny) THEN
        water = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
        water = water
      END IF
C
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. tst)
        CALL PUSHREAL8(akw)
C H2O       <==> H+
        akw = xkw*rh*water*water
C
C ION CONCENTRATIONS
C
        nai = waer(1)
        so4i = waer(2)
        CALL PUSHREAL8(nh4i)
        nh4i = waer(3)
        CALL PUSHREAL8(no3i)
        no3i = waer(4)
        CALL PUSHREAL8(cli)
        cli = waer(5)
        CALL PUSHREAL8(gg)
C
C SOLUTION ACIDIC OR BASIC?
C
        gg = 2.d0*so4i + no3i + cli - nai - nh4i
        IF (gg .GT. tiny) THEN
C H+ in excess
          bb = -gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          hi = 0.5d0*(-bb+SQRT(dd))
          CALL PUSHREAL8(ohi)
          ohi = akw/hi
          CALL PUSHCONTROL1B(0)
        ELSE
C OH- in excess
          bb = gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          CALL PUSHREAL8(ohi)
          ohi = 0.5d0*(-bb+SQRT(dd))
          hi = akw/ohi
          CALL PUSHCONTROL1B(1)
        END IF
C
C UNDISSOCIATED SPECIES EQUILIBRIA
C
        IF (hi .LT. ohi) THEN
          arg0 = -gg
          CALL PUSHREAL8(ohi)
          CALL PUSHREAL8(nh4i)
          CALL CALCAMAQ2(arg0, nh4i, ohi, nh3aq)
          hi = akw/ohi
          hso4i = zero
          CALL PUSHCONTROL1B(0)
        ELSE
          IF (2.d0*so4i + no3i - nai - nh4i .LT. zero) THEN
            CALL PUSHREAL8(ggno3)
            ggno3 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(ggno3)
            ggno3 = 2.d0*so4i + no3i - nai - nh4i
            CALL PUSHCONTROL1B(1)
          END IF
          IF (gg - ggno3 .LT. zero) THEN
            CALL PUSHREAL8(ggcl)
            ggcl = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(ggcl)
            ggcl = gg - ggno3
            CALL PUSHCONTROL1B(1)
          END IF
          IF (ggcl .GT. tiny) THEN
            CALL PUSHREAL8(cli)
            CALL CALCCLAQ2(ggcl, cli, hi, claq)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
C HCl
          IF (ggno3 .GT. tiny) THEN
            IF (ggcl .LE. tiny) THEN
              hi = zero
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHREAL8(hi)
            CALL PUSHREAL8(no3i)
            CALL CALCNIAQ2(ggno3, no3i, hi, no3aq)
C HNO3
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
C
C CONCENTRATION ADJUSTMENTS ; HSO4 minor species.
C
          CALL CALCHS4(hi, so4i, zero, del)
          CALL PUSHREAL8(so4i)
          so4i = so4i - del
          CALL PUSHREAL8(hi)
          hi = hi - del
          hso4i = del
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molal(1))
C
C *** SAVE CONCENTRATIONS IN MOLAL ARRAY ******************************
C
        molal(1) = hi
        CALL PUSHREAL8(molal(2))
        molal(2) = nai
        CALL PUSHREAL8(molal(3))
        molal(3) = nh4i
        CALL PUSHREAL8(molal(4))
        molal(4) = cli
        CALL PUSHREAL8(molal(5))
        molal(5) = so4i
        CALL PUSHREAL8(molal(6))
        molal(6) = hso4i
        CALL PUSHREAL8(molal(7))
        molal(7) = no3i
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3()
        IF ((frst .AND. calaou) .OR. (.NOT.frst .AND. calain)) THEN
          tst = .true.
        ELSE
          tst = .false.
        END IF
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      IF (TST .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCQ5')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
C 
C *** CALCULATE GAS / SOLID SPECIES (LIQUID IN MOLAL ALREADY) *********
C
C NH3  <==> NH4+
      a2 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.
C HNO3 <==> NO3-
      a3 = xk4*r*temp*(water/gama(10))**2.
C HCL  <==> CL-
      a4 = xk3*r*temp*(water/gama(11))**2.
C
C
C
C
C *** CALCULATE TOTAL AMOUNT OF SPECIES WITH GAS PHASE ****************
C
C      WTP(1) = WAER(1)                ! Total gas+aerosol phase
C      WTP(2) = WAER(2)
C      WTP(3) = WAER(3) + GNH3 
C      WTP(4) = WAER(4) + GHNO3
C      WTP(5) = WAER(5) + GHCL
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C Gaseous aerosol species
      aerliqpqb(nions+ngasaq+2) = 0.D0
      waterqb = 1.0d3*aerliqpqb(nions+1)/18.0d0
      aerliqpqb(nions+1) = 0.D0
      gasaqqb = 0.D0
      DO i=ngasaq,1,-1
        gasaqqb(i) = gasaqqb(i) + aerliqpqb(nions+1+i)
        aerliqpqb(nions+1+i) = 0.D0
      ENDDO
      molalqb = 0.D0
      DO i=nions,1,-1
        molalqb(i) = molalqb(i) + aerliqpqb(i)
        aerliqpqb(i) = 0.D0
      ENDDO
      ghclqb = gaspqb(3)
      gaspqb(3) = 0.D0
      ghno3qb = gaspqb(2)
      gaspqb(2) = 0.D0
      gnh3qb = gaspqb(1)
      gaspqb(1) = 0.D0
      no3aqqb = gasaqqb(3)
      gasaqqb(3) = 0.D0
      claqqb = gasaqqb(2)
      gasaqqb(2) = 0.D0
      nh3aqqb = gasaqqb(1)
      temp3qb = ghclqb/a4
      cliqb = hi*temp3qb
      a4qb = -(hi*cli*temp3qb/a4)
      temp3qb0 = ghno3qb/a3
      no3iqb = hi*temp3qb0
      a3qb = -(hi*no3i*temp3qb0/a3)
      temp3qb2 = gnh3qb/(hi*a2)
      temp3qb1 = -(nh4i*temp3qb2/(hi*a2))
      hiqb = no3i*temp3qb0 + a2*temp3qb1 + cli*temp3qb
      nh4iqb = temp3qb2
      a2qb = hi*temp3qb1
      gamaqb = 0.D0
      temp2 = water/gama(11)
      temp2qb = 2.*temp2*xk3*r*temp*a4qb/gama(11)
      gamaqb(11) = gamaqb(11) - temp2*temp2qb
      temp1 = water/gama(10)
      temp1qb = 2.*temp1*xk4*r*temp*a3qb/gama(10)
      waterqb = waterqb + temp1qb + temp2qb
      temp0 = gama(10)/gama(5)
      temp0qb = 2.*temp0*xk2*r*temp*a2qb/(xkw*gama(5))
      gamaqb(10) = gamaqb(10) + temp0qb - temp1*temp1qb
      gamaqb(5) = gamaqb(5) - temp0*temp0qb
      waerqb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_QB()
        CALL POPREAL8(molal(7))
        no3iqb = no3iqb + molalqb(7)
        molalqb(7) = 0.D0
        CALL POPREAL8(molal(6))
        hso4iqb = molalqb(6)
        molalqb(6) = 0.D0
        CALL POPREAL8(molal(5))
        so4iqb = molalqb(5)
        molalqb(5) = 0.D0
        CALL POPREAL8(molal(4))
        cliqb = cliqb + molalqb(4)
        molalqb(4) = 0.D0
        CALL POPREAL8(molal(3))
        nh4iqb = nh4iqb + molalqb(3)
        molalqb(3) = 0.D0
        nai = waer(1)
        CALL POPREAL8(molal(2))
        naiqb = molalqb(2)
        molalqb(2) = 0.D0
        CALL POPREAL8(molal(1))
        hiqb = hiqb + molalqb(1)
        molalqb(1) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          akwqb = hiqb/ohi
          ohiqb = -(akw*hiqb/ohi**2)
          CALL POPREAL8(nh4i)
          CALL POPREAL8(ohi)
          CALL CALCAMAQ2_QB(arg0, arg0qb, nh4i, nh4iqb, ohi, ohiqb, 
     +                      nh3aq, nh3aqqb)
          ggqb = -arg0qb
          nh3aqqb = 0.D0
          hiqb = 0.D0
        ELSE
          delqb = hso4iqb - so4iqb - hiqb
          CALL POPREAL8(hi)
          CALL POPREAL8(so4i)
          CALL CALCHS4_QB(hi, hiqb, so4i, so4iqb, zero, del, delqb)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(no3i)
            CALL POPREAL8(hi)
            CALL CALCNIAQ2_QB(ggno3, ggno3qb, no3i, no3iqb, hi, hiqb, 
     +                        no3aq, no3aqqb)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) hiqb = 0.D0
            no3aqqb = 0.D0
          ELSE
            ggno3qb = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(cli)
            CALL CALCCLAQ2_QB(ggcl, ggclqb, cli, cliqb, hi, hiqb, claq, 
     +                        claqqb)
            claqqb = 0.D0
            hiqb = 0.D0
          ELSE
            ggclqb = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(ggcl)
            gg = 2.d0*so4i + no3i + cli - nai - nh4i
            ggqb = 0.D0
          ELSE
            gg = 2.d0*so4i + no3i + cli - nai - nh4i
            CALL POPREAL8(ggcl)
            ggqb = ggclqb
            ggno3qb = ggno3qb - ggclqb
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(ggno3)
          ELSE
            CALL POPREAL8(ggno3)
            so4iqb = so4iqb + 2.d0*ggno3qb
            no3iqb = no3iqb + ggno3qb
            naiqb = naiqb - ggno3qb
            nh4iqb = nh4iqb - ggno3qb
          END IF
          akw = xkw*rh*water*water
          akwqb = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(ohi)
          bb = -gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          IF (dd .EQ. 0.0) THEN
            ddqb = 0.0
          ELSE
            ddqb = 0.5d0*hiqb/(2.0*SQRT(dd))
          END IF
          bbqb = 2*bb*ddqb - 0.5d0*hiqb
          ccqb = -(4.d0*ddqb)
          akwqb = akwqb - ccqb
          ggqb = ggqb - bbqb
        ELSE
          ohiqb = -(akw*hiqb/ohi**2)
          bb = gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          IF (dd .EQ. 0.0) THEN
            ddqb = 0.0
          ELSE
            ddqb = 0.5d0*ohiqb/(2.0*SQRT(dd))
          END IF
          ccqb = -(4.d0*ddqb)
          akwqb = akwqb + hiqb/ohi - ccqb
          CALL POPREAL8(ohi)
          bbqb = 2*bb*ddqb - 0.5d0*ohiqb
          ggqb = ggqb + bbqb
        END IF
        CALL POPREAL8(gg)
        so4iqb = so4iqb + 2.d0*ggqb
        no3iqb = no3iqb + ggqb
        cliqb = cliqb + ggqb
        naiqb = naiqb - ggqb
        nh4iqb = nh4iqb - ggqb
        CALL POPREAL8(cli)
        waerqb(5) = waerqb(5) + cliqb
        CALL POPREAL8(no3i)
        waerqb(4) = waerqb(4) + no3iqb
        CALL POPREAL8(nh4i)
        waerqb(3) = waerqb(3) + nh4iqb
        waerqb(2) = waerqb(2) + so4iqb
        waerqb(1) = waerqb(1) + naiqb
        CALL POPREAL8(akw)
        waterqb = waterqb + xkw*rh*2*water*akwqb
        hiqb = 0.D0
        no3iqb = 0.D0
        nh4iqb = 0.D0
        cliqb = 0.D0
      ENDDO
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) waterqb = 0.D0
      molalrqb = 0.D0
      DO i=npair,1,-1
        molalrqb(i) = molalrqb(i) + waterqb/m0(i)
      ENDDO
      psi4qb = molalrqb(6)
      molalrqb(6) = 0.D0
      psi5qb = molalrqb(5)
      molalrqb(5) = 0.D0
      psi6qb = molalrqb(4)
      molalrqb(4) = 0.D0
      psi1qb = molalrqb(2)
      cnh42s4qb = psi6qb
      cnh4no3qb = psi5qb
      cnh4clqb = psi4qb
      cna2so4qb = psi1qb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerqb(5) = waerqb(5) + cnh4clqb
        frnh3qb = 0.D0
      ELSE
        frnh3qb = cnh4clqb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frnh3qb = 0.D0
      ELSE
        cnh4no3qb = cnh4no3qb - frnh3qb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerqb(4) = waerqb(4) + cnh4no3qb
      ELSE
        frnh3qb = frnh3qb + cnh4no3qb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerqb(3) = waerqb(3) + frnh3qb
        cnh42s4qb = cnh42s4qb - 2.d0*frnh3qb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        x1qb = 0.D0
      ELSE
        x1qb = cnh42s4qb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerqb(3) = waerqb(3) + 0.5d0*x1qb
        frso4qb = 0.D0
      ELSE
        frso4qb = x1qb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerqb(2) = waerqb(2) + frso4qb
        cna2so4qb = cna2so4qb - frso4qb
      END IF
      waerqb(1) = waerqb(1) + 0.5d0*cna2so4qb
      waerpqb = 0.D0
      waerpqb = waerqb
C
C *** adjoint development **********************************************
C
C      ncase = 17
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerpqb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END

C
C  Differentiation of calcamaq2 in reverse (adjoint) mode:
C   gradient     of useful results: gama water ohi nh3aq nh4i
C   with respect to varying inputs: gama water ggnh3 nh4i
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCAMAQ2
C
C     THIS SUBROUTINE CALCULATES THE NH3(aq) GENERATED FROM (H,NH4+).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCAMAQ2_QB(ggnh3, ggnh3qb, nh4i, nh4iqb, ohi, ohiqb, 
     +                        nh3aq, nh3aqqb)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCAMAQ2 ****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalqb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamaqb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterqb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
C *** ERROR SYSTEM *****************************************************
C
      CHARACTER*40 errmsg
      INTEGER errstk, nofer
      LOGICAL stkofl, nonphys, tayser
      COMMON /eror/ stkofl, nofer, errstk(nerrmx), errmsg(nerrmx), 
     +tayser, nonphys
C
C *** GENERIC VARIABLES ************************************************
C
      CHARACTER*15 version
      DOUBLE PRECISION great, tiny, tiny2, zero, one
      COMMON /cgen/ great, tiny, tiny2, zero, one, version
C
C *** For differentiated routine ***************************************
C
      DOUBLE PRECISION psi1
      DOUBLE PRECISION psi2
      DOUBLE PRECISION psi3
      DOUBLE PRECISION psi4
      DOUBLE PRECISION psi5
      DOUBLE PRECISION psi6
      DOUBLE PRECISION psi7
      DOUBLE PRECISION psi8
      DOUBLE PRECISION a1
      DOUBLE PRECISION a2
      DOUBLE PRECISION chi1
      DOUBLE PRECISION a3
      DOUBLE PRECISION chi2
      DOUBLE PRECISION a4
      DOUBLE PRECISION chi3
      DOUBLE PRECISION a5
      DOUBLE PRECISION chi4
      DOUBLE PRECISION a6
      DOUBLE PRECISION chi5
      DOUBLE PRECISION a7
      DOUBLE PRECISION chi6
      DOUBLE PRECISION a8
      DOUBLE PRECISION chi7
      DOUBLE PRECISION chi8
      COMMON /solut/ chi1, chi2, chi3, chi4, chi5, chi6, chi7, chi8, 
     +psi1, psi2, psi3, psi4, psi5, psi6, psi7, psi8, a1, a2, a3, a4, a5
     +, a6, a7, a8
C
      DOUBLE PRECISION wb(ncomp)
      COMMON /inpt_b/ wb
C
C *** Case A adjoint ***************************************************
C
      DOUBLE PRECISION molalab(nions)
      DOUBLE PRECISION gamaab(npair)
      DOUBLE PRECISION waterab
      COMMON /ions_ab/ molalab, gamaab, waterab
      DOUBLE PRECISION wab(ncomp)
      COMMON /inpt_ab/ wab
      DOUBLE PRECISION gnh3ab
      COMMON /gas_ab/ gnh3ab
CC
CC *** Case B adjoint ***************************************************
CC
      DOUBLE PRECISION molalbb(nions)
      DOUBLE PRECISION gamabb(npair)
      DOUBLE PRECISION waterbb
      COMMON /ions_bb/ molalbb, gamabb, waterbb
      DOUBLE PRECISION gnh3bb
      COMMON /gas_bb/ gnh3bb
CC
CC *** Case C adjoint ***************************************************
CC
      DOUBLE PRECISION molalcb(nions)
      DOUBLE PRECISION gamacb(npair)
      DOUBLE PRECISION watercb
      COMMON /ions_cb/ molalcb, gamacb, watercb
      DOUBLE PRECISION gnh3cb
      COMMON /gas_cb/ gnh3cb
CC
CC *** Case D adjoint ***************************************************
CC
      DOUBLE PRECISION molaldnrd(nions)
      DOUBLE PRECISION gamadnrd(npair)
      DOUBLE PRECISION waterdnrd
      COMMON /ions_dnrd/ molaldnrd, gamadnrd, waterdnrd
C
      DOUBLE PRECISION chi3db
      DOUBLE PRECISION chi4db
      DOUBLE PRECISION psi1db
      DOUBLE PRECISION psi2db
      COMMON /solut_db/ chi3db, chi4db, psi1db, psi2db
      DOUBLE PRECISION molaldnrddb(nions)
      DOUBLE PRECISION gamadnrddb(npair)
      DOUBLE PRECISION waterdnrddb
      COMMON /ions_dnrd_db/ molaldnrddb, gamadnrddb, waterdnrddb
      DOUBLE PRECISION gnh3db, ghno3db
      COMMON /gas_db/ gnh3db, ghno3db
      DOUBLE PRECISION molaldb(nions)
      DOUBLE PRECISION molalrdb(npair)
      DOUBLE PRECISION gamadb(npair)
      DOUBLE PRECISION waterdb
      COMMON /ions_db/ molaldb, molalrdb, gamadb, waterdb
CC
CC *** Case E adjoint ***************************************************
CC
      DOUBLE PRECISION molaleb(nions)
      DOUBLE PRECISION gamaeb(npair)
      DOUBLE PRECISION watereb
      COMMON /ions_eb/ molaleb, gamaeb, watereb
      DOUBLE PRECISION web(ncomp)
      COMMON /inpt_eb/ web
      DOUBLE PRECISION ghno3eb
      COMMON /gas_eb/ ghno3eb
CC
CC *** Case F adjoint ***************************************************
CC
      DOUBLE PRECISION molalfb(nions)
      DOUBLE PRECISION gamafb(npair)
      DOUBLE PRECISION waterfb
      COMMON /ions_fb/ molalfb, gamafb, waterfb
      DOUBLE PRECISION wfb(ncomp)
      COMMON /inpt_fb/ wfb
      DOUBLE PRECISION ghno3fb
      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION nh4i, nh3aq, alf1, alf2, bb, cc, del, ohi
      DOUBLE PRECISION nh4iqb, nh3aqqb, alf1qb, alf2qb, bbqb, ccqb, 
     +                 delqb, ohiqb
      DOUBLE PRECISION a22
      DOUBLE PRECISION a22qb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwqb
      INTEGER branch
      DOUBLE PRECISION ggnh3
      DOUBLE PRECISION ggnh3qb
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0qb0
      DOUBLE PRECISION temp0qb
      DOUBLE PRECISION temp1qb
      INTRINSIC SQRT
      COMMON /ions_qb/ molalqb, gamaqb, waterqb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(NH3) ASSUMED 1
      a22 = xk22/xkw/water*(gama(8)/gama(9))**2.
      akw = xkw*rh*water*water
C
C *** FIND ROOT
C
      alf1 = nh4i - ggnh3
      alf2 = ggnh3
      bb = alf1 + a22*akw
      cc = -(a22*akw*alf2)
      del = 0.5d0*(-bb+SQRT(bb*bb-4.d0*cc))
      CALL PUSHREAL8(ohi)
C
C *** ADJUST CONCENTRATIONS
C
      ohi = del
C If solution is neutral.
      IF (ohi .LE. tiny) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      alf2qb = nh3aqqb
      delqb = -nh3aqqb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        IF (akw .EQ. 0.0) THEN
          akwqb = 0.0
        ELSE
          akwqb = ohiqb/(2.0*SQRT(akw))
        END IF
        ohiqb = 0.D0
      ELSE
        akwqb = 0.D0
      END IF
      CALL POPREAL8(ohi)
      delqb = delqb + nh4iqb + ohiqb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1qb = 0.0
      ELSE
        temp1qb = 0.5d0*delqb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbqb = 2*bb*temp1qb - 0.5d0*delqb
      alf1qb = bbqb + nh4iqb
      ccqb = -(4.d0*temp1qb)
      a22qb = akw*bbqb - alf2*akw*ccqb
      akwqb = akwqb + a22*bbqb - alf2*a22*ccqb
      alf2qb = alf2qb - a22*akw*ccqb
      ggnh3qb = alf2qb - alf1qb
      nh4iqb = alf1qb
      temp0 = gama(8)/gama(9)
      temp0qb = xk22*a22qb/(xkw*water)
      waterqb = waterqb + xkw*rh*2*water*akwqb - temp0**2.*temp0qb/water
      temp0qb0 = 2.*temp0*temp0qb/gama(9)
      gamaqb(8) = gamaqb(8) + temp0qb0
      gamaqb(9) = gamaqb(9) - temp0*temp0qb0
      END

