      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION ggno3, no3i, hi, no3aq
      DOUBLE PRECISION ggno3qb, no3iqb, hiqb, no3aqqb
      DOUBLE PRECISION om1, om2, bb, cc, dd, alf1, alf2, alf3, del1
      DOUBLE PRECISION bbqb, ccqb, alf1qb, alf2qb, alf3qb, del1qb
      DOUBLE PRECISION a42
      DOUBLE PRECISION a42qb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwqb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0qb
      DOUBLE PRECISION temp1qb
      INTRINSIC SQRT
      COMMON /ions_qb/ molalqb, gamaqb, waterqb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HNO3) ASSUMED 1
      a42 = xk42*water/gama(10)**2.
      akw = xkw*rh*water*water
C
C *** FIND ROOT
C
      alf1 = no3i - ggno3
      alf2 = ggno3
      alf3 = hi
C
      bb = alf3 + alf1 + a42
      cc = alf3*alf1 - a42*alf2
      del1 = 0.5*(-bb+SQRT(bb*bb-4.d0*cc))
C
C *** CORRECT CONCENTRATIONS
C
      hi = alf3 + del1
C If solution is neutral.
      IF (hi .LE. tiny) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      alf2qb = no3aqqb
      del1qb = -no3aqqb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        IF (akw .EQ. 0.0) THEN
          akwqb = 0.0
        ELSE
          akwqb = hiqb/(2.0*SQRT(akw))
        END IF
        hiqb = 0.D0
      ELSE
        akwqb = 0.D0
      END IF
      del1qb = del1qb + no3iqb + hiqb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1qb = 0.0
      ELSE
        temp1qb = 0.5*del1qb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbqb = 2*bb*temp1qb - 0.5*del1qb
      ccqb = -(4.d0*temp1qb)
      alf3qb = alf1*ccqb + bbqb + hiqb
      alf1qb = alf3*ccqb + bbqb + no3iqb
      a42qb = bbqb - alf2*ccqb
      alf2qb = alf2qb - a42*ccqb
      hiqb = alf3qb
      ggno3qb = alf2qb - alf1qb
      no3iqb = alf1qb
      temp0 = gama(10)**2.
      temp0qb = xk42*a42qb/temp0
      waterqb = waterqb + temp0qb + xkw*rh*2*water*akwqb
      gamaqb(10) = gamaqb(10) - water*2.*gama(10)*temp0qb/temp0
      END

