      SUBROUTINE KMFUL3_QB(ionic, ionicqb, temp, g01, g01qb, g02, g02qb
     +                     , g03, g03qb, g04, g04qb, g05, g05qb, g06, 
     +                     g06qb, g07, g07qb, g08, g08qb, g09, g09qb, 
