      CALL MKBI_QB(q8, ionic, ionicqb, sion, sionqb, z08, g08, g08qb)
      CALL MKBI_QB(q7, ionic, ionicqb, sion, sionqb, z07, g07, g07qb)
      CALL MKBI_QB(q6, ionic, ionicqb, sion, sionqb, z06, g06, g06qb)
      CALL MKBI_QB(q5, ionic, ionicqb, sion, sionqb, z05, g05, g05qb)
      CALL MKBI_QB(q4, ionic, ionicqb, sion, sionqb, z04, g04, g04qb)
      CALL MKBI_QB(q3, ionic, ionicqb, sion, sionqb, z03, g03, g03qb)
      CALL MKBI_QB(q2, ionic, ionicqb, sion, sionqb, z02, g02, g02qb)
      CALL MKBI_QB(q1, ionic, ionicqb, sion, sionqb, z01, g01, g01qb)
      IF (.NOT.ionic .EQ. 0.0) ionicqb = ionicqb + sionqb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_QB(q, ionic, ionicqb, sion, sionqb, zip, bi, biqb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicqb, sionqb, biqb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION cqb, xxqb
      INTRINSIC EXP
      DOUBLE PRECISION tempqb
      INTRINSIC LOG10
      DOUBLE PRECISION tempqb0
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxqb = zip*biqb
      biqb = zip*biqb/(bi*LOG(10.0))
      tempqb = -(0.5107d0*xxqb/(c*sion+1.d0))
      tempqb0 = -(sion*tempqb/(c*sion+1.d0))
      sionqb = sionqb + c*tempqb0 + tempqb
      cqb = sion*tempqb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicqb = ionicqb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*cqb
      ELSE
        ionicqb = ionicqb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*biqb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*cqb
      END IF
      END


