      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION nh4i, nai, no3i, nh3aq, no3aq, claq
      DOUBLE PRECISION nh4irb, nairb, no3irb, nh3aqrb, no3aqrb, claqrb
      DOUBLE PRECISION gas(3), aerliq(nions+ngasaq+2), wtp(ncomp)
      DOUBLE PRECISION aerliqp(nions+ngasaq+2), gasp(3), waerp(ncomp)
      DOUBLE PRECISION aerliqprb(nions+ngasaq+2), gasprb(3), waerprb(
     +                 ncomp)
      LOGICAL tst
      DOUBLE PRECISION frna
      DOUBLE PRECISION frnarb
      DOUBLE PRECISION frno3
      DOUBLE PRECISION frno3rb
      DOUBLE PRECISION frcl
      DOUBLE PRECISION frclrb
      DOUBLE PRECISION frnh3
      DOUBLE PRECISION frnh3rb
      INTEGER i
      DOUBLE PRECISION hso4i
      DOUBLE PRECISION hso4irb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwrb
      DOUBLE PRECISION so4i
      DOUBLE PRECISION so4irb
      DOUBLE PRECISION cli
      DOUBLE PRECISION clirb
      DOUBLE PRECISION gg
      DOUBLE PRECISION ggrb
      DOUBLE PRECISION bb
      DOUBLE PRECISION bbrb
      DOUBLE PRECISION cc
      DOUBLE PRECISION ccrb
      DOUBLE PRECISION dd
      DOUBLE PRECISION ddrb
      DOUBLE PRECISION hi
      DOUBLE PRECISION hirb
      DOUBLE PRECISION ohi
      DOUBLE PRECISION ohirb
      DOUBLE PRECISION ggno3
      DOUBLE PRECISION ggno3rb
      DOUBLE PRECISION ggcl
      DOUBLE PRECISION ggclrb
      DOUBLE PRECISION del
      DOUBLE PRECISION delrb
      DOUBLE PRECISION arg0
      INTEGER branch
      INTEGER ad_count
      INTEGER i0
      DOUBLE PRECISION temp2
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0rb
      DOUBLE PRECISION arg0rb
      INTRINSIC MAX
      DOUBLE PRECISION temp3rb
      DOUBLE PRECISION temp1rb
      INTRINSIC MIN
      DOUBLE PRECISION temp3rb2
      DOUBLE PRECISION temp3rb1
      DOUBLE PRECISION temp2rb
      DOUBLE PRECISION temp3rb0
      INTRINSIC SQRT
      COMMON /ions_rb/ molalrb, gamarb, waterrb
      INTEGER npflag, ncase
C
C      waer = waerp
C
      frst = .true.
      calaou = .true.
      tst = .true.
C
C *** SETUP PARAMETERS ************************************************
C
C      CALL CALCR1A     ! Code inserted below
C
C *** CALCULATE SOLIDS **************************************************
C
      cna2so4 = waer(2)
      IF (waer(1) - 2*cna2so4 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frna = zero
      ELSE
        frna = waer(1) - 2*cna2so4
        CALL PUSHCONTROL1B(1)
      END IF
C
      IF (frna .GT. waer(4)) THEN
        cnano3 = waer(4)
        CALL PUSHCONTROL1B(0)
      ELSE
        cnano3 = frna
        CALL PUSHCONTROL1B(1)
      END IF
      IF (waer(4) - cnano3 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frno3 = zero
      ELSE
        frno3 = waer(4) - cnano3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frna - cnano3 .LT. zero) THEN
        frna = zero
        CALL PUSHCONTROL1B(0)
      ELSE
        frna = frna - cnano3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frna .GT. waer(5)) THEN
        cnacl = waer(5)
        CALL PUSHCONTROL1B(0)
      ELSE
        cnacl = frna
        CALL PUSHCONTROL1B(1)
      END IF
      IF (waer(5) - cnacl .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frcl = zero
      ELSE
        frcl = waer(5) - cnacl
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frno3 .GT. waer(3)) THEN
        cnh4no3 = waer(3)
        CALL PUSHCONTROL1B(0)
      ELSE
        cnh4no3 = frno3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (waer(3) - cnh4no3 .LT. zero) THEN
        CALL PUSHCONTROL1B(0)
        frnh3 = zero
      ELSE
        frnh3 = waer(3) - cnh4no3
        CALL PUSHCONTROL1B(1)
      END IF
      IF (frcl .GT. frnh3) THEN
        cnh4cl = frnh3
        CALL PUSHCONTROL1B(0)
      ELSE
        cnh4cl = frcl
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** OTHER PHASES ******************************************************
C
C
C
C
      psi1 = cna2so4
      psi2 = cnano3
      psi3 = cnacl
      psi4 = cnh4cl
      psi5 = cnh4no3
C
C *** CALCULATE WATER **************************************************
C
C      CALL CALCMR    ! Code inserted below
C
C NACL 
      molalr(1) = psi3
C NA2SO4
      molalr(2) = psi1
C NANO3
      molalr(3) = psi2
C (NH4)2SO4
      molalr(4) = zero
C NH4NO3
      molalr(5) = psi5
C NH4CL
      molalr(6) = psi4
C
C *** CALCULATE WATER CONTENT ; ZSR CORRELATION ***********************
C
      water = zero
      DO i=1,npair
        water = water + molalr(i)/m0(i)
      ENDDO
      IF (water .LT. tiny) THEN
        water = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
        water = water
      END IF
C
C *** SETUP LIQUID CONCENTRATIONS **************************************
C
      hso4i = zero
C
C *** SOLVE EQUATIONS ; WITH ITERATIONS FOR ACTIVITY COEF. ************
C
      i = 1
      ad_count = 0
      DO WHILE (i .LE. nsweep .AND. tst)
        CALL PUSHREAL8(akw)
C H2O    <==> H+      
        akw = xkw*rh*water*water
C
        nai = waer(1)
        so4i = waer(2)
        CALL PUSHREAL8(nh4i)
        nh4i = waer(3)
        CALL PUSHREAL8(no3i)
        no3i = waer(4)
        CALL PUSHREAL8(cli)
        cli = waer(5)
        CALL PUSHREAL8(gg)
C
C SOLUTION ACIDIC OR BASIC?
C
        gg = 2.d0*waer(2) + no3i + cli - nai - nh4i
        IF (gg .GT. tiny) THEN
C H+ in excess
          bb = -gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          hi = 0.5d0*(-bb+SQRT(dd))
          CALL PUSHREAL8(ohi)
          ohi = akw/hi
          CALL PUSHCONTROL1B(0)
        ELSE
C OH- in excess
          bb = gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          CALL PUSHREAL8(ohi)
          ohi = 0.5d0*(-bb+SQRT(dd))
          hi = akw/ohi
          CALL PUSHCONTROL1B(1)
        END IF
C
C UNDISSOCIATED SPECIES EQUILIBRIA
C
        IF (hi .LT. ohi) THEN
          arg0 = -gg
          CALL PUSHREAL8(ohi)
          CALL PUSHREAL8(nh4i)
          CALL CALCAMAQ2(arg0, nh4i, ohi, nh3aq)
          hi = akw/ohi
          CALL PUSHCONTROL1B(0)
        ELSE
          IF (2.d0*so4i + no3i - nai - nh4i .LT. zero) THEN
            CALL PUSHREAL8(ggno3)
            ggno3 = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(ggno3)
            ggno3 = 2.d0*so4i + no3i - nai - nh4i
            CALL PUSHCONTROL1B(1)
          END IF
          IF (gg - ggno3 .LT. zero) THEN
            CALL PUSHREAL8(ggcl)
            ggcl = zero
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(ggcl)
            ggcl = gg - ggno3
            CALL PUSHCONTROL1B(1)
          END IF
          IF (ggcl .GT. tiny) THEN
            CALL PUSHREAL8(cli)
            CALL CALCCLAQ2(ggcl, cli, hi, claq)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
C HCl
          IF (ggno3 .GT. tiny) THEN
            IF (ggcl .LE. tiny) THEN
              hi = zero
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHREAL8(hi)
            CALL PUSHREAL8(no3i)
            CALL CALCNIAQ2(ggno3, no3i, hi, no3aq)
C HNO3
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
C
C CONCENTRATION ADJUSTMENTS ; HSO4 minor species.
C
          CALL CALCHS4(hi, so4i, zero, del)
          CALL PUSHREAL8(so4i)
          so4i = so4i - del
          CALL PUSHREAL8(hi)
          hi = hi - del
          hso4i = del
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(molal(1))
C
C *** SAVE CONCENTRATIONS IN MOLAL ARRAY ******************************
C
        molal(1) = hi
        CALL PUSHREAL8(molal(2))
        molal(2) = nai
        CALL PUSHREAL8(molal(3))
        molal(3) = nh4i
        CALL PUSHREAL8(molal(4))
        molal(4) = cli
        CALL PUSHREAL8(molal(5))
        molal(5) = so4i
        CALL PUSHREAL8(molal(6))
        molal(6) = hso4i
        CALL PUSHREAL8(molal(7))
        molal(7) = no3i
        CALL PUSHREAL8ARRAY(gama, npair)
C
C *** CALCULATE ACTIVITIES OR TERMINATE INTERNAL LOOP *****************
C
        CALL CALCACT3()
        IF ((frst .AND. calaou) .OR. (.NOT.frst .AND. calain)) THEN
          tst = .true.
        ELSE
          tst = .false.
        END IF
        i = i + 1
        ad_count = ad_count + 1
      ENDDO
      IF (TST .AND. (I .GT. (NSWEEP+1))) THEN
         CALL PUSHERR (0001, 'CALCR6')    ! WARNING ERROR: NO SOLUTION
      ENDIF
      CALL PUSHINTEGER4(ad_count)
C 
C *** CALCULATE GAS / SOLID SPECIES (LIQUID IN MOLAL ALREADY) *********
C
C NH3  <==> NH4+
      a2 = xk2/xkw*r*temp*(gama(10)/gama(5))**2.
C HNO3 <==> NO3-
      a3 = xk4*r*temp*(water/gama(10))**2.
C HCL  <==> CL-
      a4 = xk3*r*temp*(water/gama(11))**2.
C
C
C
C
C *** CALCULATE TOTAL AMOUNT OF SPECIES WITH GAS PHASE ****************
C
C      WTP(1) = WAER(1)                ! Total gas+aerosol phase
C      WTP(2) = WAER(2)
C      WTP(3) = WAER(3) + GNH3 
C      WTP(4) = WAER(4) + GHNO3
C      WTP(5) = WAER(5) + GHCL
C
C *** ADJOINT DEVELOPMENT *********************************************
C
C Gaseous aerosol species
      aerliqprb(nions+ngasaq+2) = 0.D0
      waterrb = 1.0d3*aerliqprb(nions+1)/18.0d0
      aerliqprb(nions+1) = 0.D0
      gasaqrb = 0.D0
      DO i=ngasaq,1,-1
        gasaqrb(i) = gasaqrb(i) + aerliqprb(nions+1+i)
        aerliqprb(nions+1+i) = 0.D0
      ENDDO
      molalrb = 0.D0
      DO i=nions,1,-1
        molalrb(i) = molalrb(i) + aerliqprb(i)
        aerliqprb(i) = 0.D0
      ENDDO
      ghclrb = gasprb(3)
      gasprb(3) = 0.D0
      ghno3rb = gasprb(2)
      gasprb(2) = 0.D0
      gnh3rb = gasprb(1)
      gasprb(1) = 0.D0
      no3aqrb = gasaqrb(3)
      gasaqrb(3) = 0.D0
      claqrb = gasaqrb(2)
      gasaqrb(2) = 0.D0
      nh3aqrb = gasaqrb(1)
      temp3rb = ghclrb/a4
      clirb = hi*temp3rb
      a4rb = -(hi*cli*temp3rb/a4)
      temp3rb0 = ghno3rb/a3
      no3irb = hi*temp3rb0
      a3rb = -(hi*no3i*temp3rb0/a3)
      temp3rb2 = gnh3rb/(hi*a2)
      temp3rb1 = -(nh4i*temp3rb2/(hi*a2))
      hirb = no3i*temp3rb0 + a2*temp3rb1 + cli*temp3rb
      nh4irb = temp3rb2
      a2rb = hi*temp3rb1
      gamarb = 0.D0
      temp2 = water/gama(11)
      temp2rb = 2.*temp2*xk3*r*temp*a4rb/gama(11)
      gamarb(11) = gamarb(11) - temp2*temp2rb
      temp1 = water/gama(10)
      temp1rb = 2.*temp1*xk4*r*temp*a3rb/gama(10)
      waterrb = waterrb + temp1rb + temp2rb
      temp0 = gama(10)/gama(5)
      temp0rb = 2.*temp0*xk2*r*temp*a2rb/(xkw*gama(5))
      gamarb(10) = gamarb(10) + temp0rb - temp1*temp1rb
      gamarb(5) = gamarb(5) - temp0*temp0rb
      waerrb = 0.D0
      hso4irb = 0.D0
      CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        CALL POPREAL8ARRAY(gama, npair)
        CALL CALCACT3_RB()
        CALL POPREAL8(molal(7))
        no3irb = no3irb + molalrb(7)
        molalrb(7) = 0.D0
        CALL POPREAL8(molal(6))
        hso4irb = hso4irb + molalrb(6)
        molalrb(6) = 0.D0
        CALL POPREAL8(molal(5))
        so4irb = molalrb(5)
        molalrb(5) = 0.D0
        CALL POPREAL8(molal(4))
        clirb = clirb + molalrb(4)
        molalrb(4) = 0.D0
        CALL POPREAL8(molal(3))
        nh4irb = nh4irb + molalrb(3)
        molalrb(3) = 0.D0
        nai = waer(1)
        CALL POPREAL8(molal(2))
        nairb = molalrb(2)
        molalrb(2) = 0.D0
        CALL POPREAL8(molal(1))
        hirb = hirb + molalrb(1)
        molalrb(1) = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          akwrb = hirb/ohi
          ohirb = -(akw*hirb/ohi**2)
          CALL POPREAL8(nh4i)
          CALL POPREAL8(ohi)
          CALL CALCAMAQ2_RB(arg0, arg0rb, nh4i, nh4irb, ohi, ohirb, 
     +                      nh3aq, nh3aqrb)
          ggrb = -arg0rb
          nh3aqrb = 0.D0
          hirb = 0.D0
        ELSE
          delrb = hso4irb - so4irb - hirb
          CALL POPREAL8(hi)
          CALL POPREAL8(so4i)
          CALL CALCHS4_RB(hi, hirb, so4i, so4irb, zero, del, delrb)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(no3i)
            CALL POPREAL8(hi)
            CALL CALCNIAQ2_RB(ggno3, ggno3rb, no3i, no3irb, hi, hirb, 
     +                        no3aq, no3aqrb)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) hirb = 0.D0
            no3aqrb = 0.D0
          ELSE
            ggno3rb = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(cli)
            CALL CALCCLAQ2_RB(ggcl, ggclrb, cli, clirb, hi, hirb, claq, 
     +                        claqrb)
            claqrb = 0.D0
            hirb = 0.D0
          ELSE
            ggclrb = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(ggcl)
            gg = 2.d0*waer(2) + no3i + cli - nai - nh4i
            ggrb = 0.D0
          ELSE
            gg = 2.d0*waer(2) + no3i + cli - nai - nh4i
            CALL POPREAL8(ggcl)
            ggrb = ggclrb
            ggno3rb = ggno3rb - ggclrb
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(ggno3)
          ELSE
            CALL POPREAL8(ggno3)
            so4irb = so4irb + 2.d0*ggno3rb
            no3irb = no3irb + ggno3rb
            nairb = nairb - ggno3rb
            nh4irb = nh4irb - ggno3rb
          END IF
          akw = xkw*rh*water*water
          hso4irb = 0.D0
          akwrb = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(ohi)
          bb = -gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          IF (dd .EQ. 0.0) THEN
            ddrb = 0.0
          ELSE
            ddrb = 0.5d0*hirb/(2.0*SQRT(dd))
          END IF
          bbrb = 2*bb*ddrb - 0.5d0*hirb
          ccrb = -(4.d0*ddrb)
          akwrb = akwrb - ccrb
          ggrb = ggrb - bbrb
        ELSE
          ohirb = -(akw*hirb/ohi**2)
          bb = gg
          cc = -akw
          dd = bb*bb - 4.d0*cc
          IF (dd .EQ. 0.0) THEN
            ddrb = 0.0
          ELSE
            ddrb = 0.5d0*ohirb/(2.0*SQRT(dd))
          END IF
          ccrb = -(4.d0*ddrb)
          akwrb = akwrb + hirb/ohi - ccrb
          CALL POPREAL8(ohi)
          bbrb = 2*bb*ddrb - 0.5d0*ohirb
          ggrb = ggrb + bbrb
        END IF
        CALL POPREAL8(gg)
        waerrb(2) = waerrb(2) + 2.d0*ggrb
        no3irb = no3irb + ggrb
        clirb = clirb + ggrb
        nairb = nairb - ggrb
        nh4irb = nh4irb - ggrb
        CALL POPREAL8(cli)
        waerrb(5) = waerrb(5) + clirb
        CALL POPREAL8(no3i)
        waerrb(4) = waerrb(4) + no3irb
        CALL POPREAL8(nh4i)
        waerrb(3) = waerrb(3) + nh4irb
        waerrb(2) = waerrb(2) + so4irb
        waerrb(1) = waerrb(1) + nairb
        CALL POPREAL8(akw)
        waterrb = waterrb + xkw*rh*2*water*akwrb
        hirb = 0.D0
        no3irb = 0.D0
        nh4irb = 0.D0
        clirb = 0.D0
      ENDDO
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) waterrb = 0.D0
      molalrrb = 0.D0
      DO i=npair,1,-1
        molalrrb(i) = molalrrb(i) + waterrb/m0(i)
      ENDDO
      psi4rb = molalrrb(6)
      molalrrb(6) = 0.D0
      psi5rb = molalrrb(5)
      molalrrb(5) = 0.D0
      molalrrb(4) = 0.D0
      psi2rb = molalrrb(3)
      molalrrb(3) = 0.D0
      psi1rb = molalrrb(2)
      molalrrb(2) = 0.D0
      psi3rb = molalrrb(1)
      cnh4no3rb = psi5rb
      cnh4clrb = psi4rb
      cnaclrb = psi3rb
      cnano3rb = psi2rb
      cna2so4rb = psi1rb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frnh3rb = cnh4clrb
        frclrb = 0.D0
      ELSE
        frclrb = cnh4clrb
        frnh3rb = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerrb(3) = waerrb(3) + frnh3rb
        cnh4no3rb = cnh4no3rb - frnh3rb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerrb(3) = waerrb(3) + cnh4no3rb
        frno3rb = 0.D0
      ELSE
        frno3rb = cnh4no3rb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerrb(5) = waerrb(5) + frclrb
        cnaclrb = cnaclrb - frclrb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerrb(5) = waerrb(5) + cnaclrb
        frnarb = 0.D0
      ELSE
        frnarb = cnaclrb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        frnarb = 0.D0
      ELSE
        cnano3rb = cnano3rb - frnarb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerrb(4) = waerrb(4) + frno3rb
        cnano3rb = cnano3rb - frno3rb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        waerrb(4) = waerrb(4) + cnano3rb
      ELSE
        frnarb = frnarb + cnano3rb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        waerrb(1) = waerrb(1) + frnarb
        cna2so4rb = cna2so4rb - 2*frnarb
      END IF
      waerrb(2) = waerrb(2) + cna2so4rb
      waerprb = 0.D0
      waerprb = waerrb
C
C *** adjoint development **********************************************
C
C      ncase = 18
      CALL ISERRINF (ERRSTK, ERRMSG, NOFER, STKOFL) ! Obtain error stack
C      WRITE(*,*) 'Writing error code'
      IF (NOFER.EQ.0) THEN ! No errors
          NONPHYS = .FALSE.
C          npflag = 0
C          WRITE(*,*) 'Setting NONPHYS to FALSE'
      ELSE
          NONPHYS = .TRUE.
C          npflag = 1
C          WRITE(*,*) 'Setting NONPHYS to TRUE'
C          PAUSE
C          WRITE(*,*) 'After pause'
      ENDIF
C      OPEN (199, FILE='adj_sens.csv',STATUS='UNKNOWN',
C     &             POSITION='APPEND')
C      WRITE(199,888) waer,rh,temp,waerprb,npflag,ncase
C      CLOSE (199, STATUS='KEEP')
C 888  FORMAT (12(1PE11.4,","),I2,",",I2)
C
C *** adjoint development **********************************************
C
      END

C  Differentiation of calcamaq2 in reverse (adjoint) mode:
C   gradient     of useful results: gama water ohi nh3aq nh4i
C   with respect to varying inputs: gama water ggnh3 nh4i
C
C
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE CALCAMAQ2
C
C     THIS SUBROUTINE CALCULATES THE NH3(aq) GENERATED FROM (H,NH4+).
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE CALCAMAQ2_RB(ggnh3, ggnh3rb, nh4i, nh4irb, ohi, ohirb, 
     +                        nh3aq, nh3aqrb)
      IMPLICIT NONE
C
C *** END OF SUBROUTINE CALCAMAQ2 ****************************************
C
C
C *** END OF INCLUDE FILE **********************************************
C
C=======================================================================
C
C *** ISORROPIA CODE
C *** INCLUDE FILE 'ISRPIA_B.INC'
C *** THIS FILE CONTAINS THE DECLARATIONS OF THE GLOBAL CONSTANTS
C     AND VARIABLES. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      INTEGER nslds
      INTEGER nzsr
      INTEGER npair
      INTEGER ncomp
      INTEGER nions
      INTEGER ngasaq
      INTEGER nerrmx
      PARAMETER (ncomp=5, nions=7, ngasaq=3, nslds=9, npair=13, nzsr=100
     +   , nerrmx=25)
C
C *** INPUT VARIABLES **************************************************
C
      INTEGER metstbl, iprob, nadj
      DOUBLE PRECISION w, waer, temp, rh
      COMMON /inpt/ w(ncomp), waer(ncomp), temp, rh, iprob, metstbl, 
     +nadj
C
C *** WATER ACTIVITIES OF PURE SALT SOLUTIONS **************************
C
      DOUBLE PRECISION awas, awss, awac, awsc, awan, awsn, awsb, awab
      DOUBLE PRECISION awsa, awlc
      COMMON /zsr/ awas(nzsr), awss(nzsr), awac(nzsr), awsc(nzsr), awan(
     +nzsr), awsn(nzsr), awsb(nzsr), awab(nzsr), awsa(nzsr), awlc(nzsr)
C
C *** DELIQUESCENCE RELATIVE HUMIDITIES ********************************
C
      INTEGER wftyp
      DOUBLE PRECISION drh2so4, drnh42s4, drnahso4, drnacl, drnano3
      DOUBLE PRECISION drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      COMMON /drh/ drh2so4, drnh42s4, drnahso4, drnacl, drnano3, 
     +drna2so4, drnh4hs4, drlc, drnh4no3, drnh4cl
C
      DOUBLE PRECISION drmlcab, drmlcas, drmasan, drmg1, drmg2
      DOUBLE PRECISION drmg3, drmh1, drmh2, drmi1, drmi2
      DOUBLE PRECISION drmi3, drmq1, drmr1, drmr2, drmr3
      DOUBLE PRECISION drmr4, drmr5, drmr6, drmr7, drmr8
      DOUBLE PRECISION drmr9, drmr10, drmr11, drmr12, drmr13
C
      COMMON /mdrh/ drmlcab, drmlcas, drmasan, drmg1, drmg2, drmg3, 
     +drmh1, drmh2, drmi1, drmi2, drmi3, drmq1, drmr1, drmr2, drmr3, 
     +drmr4, drmr5, drmr6, drmr7, drmr8, drmr9, drmr10, drmr11, drmr12, 
     +drmr13, wftyp
C
C *** VARIABLES FOR LIQUID AEROSOL PHASE *******************************
C
      DOUBLE PRECISION molal
      DOUBLE PRECISION molalrb(nions)
      DOUBLE PRECISION molalr
      DOUBLE PRECISION m0
      DOUBLE PRECISION ionic
      DOUBLE PRECISION gama, zz, z, gamou, gamin, gasaq, epsact
      DOUBLE PRECISION gamarb(npair)
      DOUBLE PRECISION coh, chno3, chcl, water
      DOUBLE PRECISION waterrb
      INTEGER iacalc
      LOGICAL calaou, calain, frst, dryf
      COMMON /ions/ molal(nions), molalr(npair), gama(npair), zz(npair)
     +, z(nions), gamou(npair), gamin(npair), m0(npair), gasaq(ngasaq), 
     +epsact, coh, chno3, chcl, water, ionic, iacalc, frst, calain, 
     +calaou, dryf
C
C *** VARIABLES FOR SOLID AEROSOL PHASE ********************************
C
      DOUBLE PRECISION ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4
      DOUBLE PRECISION cnano3, cnh4no3, cnh4cl, cnahso4, clc
      COMMON /salt/ ch2so4, cnh42s4, cnh4hs4, cnacl, cna2so4, cnano3, 
     +cnh4no3, cnh4cl, cnahso4, clc
C
C *** VARIABLES FOR GAS PHASE ******************************************
C
      DOUBLE PRECISION gnh3, ghno3, ghcl
      COMMON /gas/ gnh3, ghno3, ghcl
C
C *** EQUILIBRIUM CONSTANTS ********************************************
C
      DOUBLE PRECISION xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10
      DOUBLE PRECISION xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, 
     +                 xk32, xk41
      DOUBLE PRECISION xk42
C
      COMMON /equk/ xk1, xk2, xk3, xk4, xk5, xk6, xk7, xk8, xk9, xk10, 
     +xk11, xk12, xk13, xk14, xkw, xk21, xk22, xk31, xk32, xk41, xk42
C
C *** MOLECULAR WEIGHTS ************************************************
C
      DOUBLE PRECISION imw, r, wmw, smw
      COMMON /othr/ r, imw(nions), wmw(ncomp), smw(npair)
C
C *** SOLUTION/INFO VARIABLES ******************************************
C
      CHARACTER*15 scase
      DOUBLE PRECISION sulratw, sulrat, sodrat
      COMMON /case/ sulratw, sulrat, sodrat, scase
C
      DOUBLE PRECISION eps
      INTEGER maxit, nsweep, ndiv, iclact
      LOGICAL ginit
      COMMON /soln/ eps, maxit, nsweep, ndiv, iclact, ginit
C
