      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION ggno3, no3i, hi, no3aq
      DOUBLE PRECISION ggno3rb, no3irb, hirb, no3aqrb
      DOUBLE PRECISION om1, om2, bb, cc, dd, alf1, alf2, alf3, del1
      DOUBLE PRECISION bbrb, ccrb, alf1rb, alf2rb, alf3rb, del1rb
      DOUBLE PRECISION a42
      DOUBLE PRECISION a42rb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwrb
      INTEGER branch
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp0rb
      DOUBLE PRECISION temp1rb
      INTRINSIC SQRT
      COMMON /ions_rb/ molalrb, gamarb, waterrb
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(HNO3) ASSUMED 1
      a42 = xk42*water/gama(10)**2.
      akw = xkw*rh*water*water
C
C *** FIND ROOT
C
      alf1 = no3i - ggno3
      alf2 = ggno3
      alf3 = hi
C
      bb = alf3 + alf1 + a42
      cc = alf3*alf1 - a42*alf2
      del1 = 0.5*(-bb+SQRT(bb*bb-4.d0*cc))
C
C *** CORRECT CONCENTRATIONS
C
      hi = alf3 + del1
C If solution is neutral.
      IF (hi .LE. tiny) THEN
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      alf2rb = no3aqrb
      del1rb = -no3aqrb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        IF (akw .EQ. 0.0) THEN
          akwrb = 0.0
        ELSE
          akwrb = hirb/(2.0*SQRT(akw))
        END IF
        hirb = 0.D0
      ELSE
        akwrb = 0.D0
      END IF
      del1rb = del1rb + no3irb + hirb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1rb = 0.0
      ELSE
        temp1rb = 0.5*del1rb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbrb = 2*bb*temp1rb - 0.5*del1rb
      ccrb = -(4.d0*temp1rb)
      alf3rb = alf1*ccrb + bbrb + hirb
      alf1rb = alf3*ccrb + bbrb + no3irb
      a42rb = bbrb - alf2*ccrb
      alf2rb = alf2rb - a42*ccrb
      hirb = alf3rb
      ggno3rb = alf2rb - alf1rb
      no3irb = alf1rb
      temp0 = gama(10)**2.
      temp0rb = xk42*a42rb/temp0
      waterrb = waterrb + temp0rb + xkw*rh*2*water*akwrb
      gamarb(10) = gamarb(10) - water*2.*gama(10)*temp0rb/temp0
      END

