        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamarb(i) = 10.d0**gama(i)*LOG(10.d0)*gamarb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamarb(i) = 0.D0
          x2rb = 0.D0
        ELSE
          x2rb = gamarb(i)
          gamarb(i) = 0.D0
