      CALL POPREAL8(gama(6))
      temp0rb8 = zz(6)*gamarb(6)/(z(3)+z(4))
      f2rb(1) = f2rb(1) + temp0rb8/z(4)
      hrb = hrb - zz(6)*gamarb(6)
      gamarb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0rb9 = zz(5)*gamarb(5)/(z(3)+z(7))
      f2rb(4) = f2rb(4) + temp0rb9/z(7)
      hrb = hrb - zz(5)*gamarb(5)
      gamarb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0rb10 = zz(4)*gamarb(4)/(z(3)+z(5))
      f1rb(3) = f1rb(3) + temp0rb9/z(3) + temp0rb10/z(3) + temp0rb8/z(3)
      f2rb(2) = f2rb(2) + temp0rb10/z(5)
      hrb = hrb - zz(4)*gamarb(4)
