      CALL POPREAL8(gama(3))
      temp0rb11 = zz(3)*gamarb(3)/(z(2)+z(7))
      f2rb(4) = f2rb(4) + temp0rb11/z(7)
      hrb = hrb - zz(3)*gamarb(3)
      gamarb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0rb12 = zz(2)*gamarb(2)/(z(2)+z(5))
      f2rb(2) = f2rb(2) + temp0rb12/z(5)
      hrb = hrb - zz(2)*gamarb(2)
      gamarb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0rb13 = zz(1)*gamarb(1)/(z(2)+z(4))
