      g09rb = g0rb(3, 3)
      g0rb(3, 3) = 0.D0
      g04rb = g0rb(3, 2)
      g0rb(3, 2) = 0.D0
      g06rb = g0rb(3, 1)
      g0rb(3, 1) = 0.D0
      g03rb = g0rb(2, 4)
