C
C=======================================================================
C
      SUBROUTINE KMFUL3_RB(ionic, ionicrb, temp, g01, g01rb, g02, g02rb
     +                     , g03, g03rb, g04, g04rb, g05, g05rb, g06, 
     +                     g06rb, g07, g07rb, g08, g08rb, g09, g09rb, 
     +                     g10, g10rb, g11, g11rb, g12, g12rb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicrb, sionrb, cf2rb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01rb, g02rb, g03rb, g04rb, g05rb, g06rb, g07rb, 
     +                 g08rb, g09rb, g10rb, g11rb, g12rb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0rb
      INTRINSIC ABS
      DOUBLE PRECISION temp0rb0
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01rb = g01rb + g12rb
      g08rb = g08rb + g09rb + g12rb
      g11rb = g11rb - g09rb - g12rb
      g06rb = g06rb + g09rb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2rb = -(z10*g10rb) - z07*g07rb - z05*g05rb - z03*g03rb - z01*
     +    g01rb - z02*g02rb - z04*g04rb - z06*g06rb - z08*g08rb - z11*
     +    g11rb
        g11rb = cf1*g11rb
        g10rb = cf1*g10rb
        g08rb = cf1*g08rb
        g07rb = cf1*g07rb
        g06rb = cf1*g06rb
        g05rb = cf1*g05rb
        g04rb = cf1*g04rb
        g03rb = cf1*g03rb
        g02rb = cf1*g02rb
        g01rb = cf1*g01rb
        temp0rb = (0.125d0-ti*0.005d0)*cf2rb
        temp0rb0 = -(0.41d0*temp0rb/(sion+1.d0))
        ionicrb = ionicrb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0rb
        sionrb = (1.D0-sion/(sion+1.d0))*temp0rb0
      ELSE
        sionrb = 0.D0
