      CALL MKBI_RB(q11, ionic, ionicrb, sion, sionrb, z11, g11, g11rb)
      CALL MKBI_RB(q10, ionic, ionicrb, sion, sionrb, z10, g10, g10rb)
      CALL MKBI_RB(q8, ionic, ionicrb, sion, sionrb, z08, g08, g08rb)
      CALL MKBI_RB(q7, ionic, ionicrb, sion, sionrb, z07, g07, g07rb)
      CALL MKBI_RB(q6, ionic, ionicrb, sion, sionrb, z06, g06, g06rb)
      CALL MKBI_RB(q5, ionic, ionicrb, sion, sionrb, z05, g05, g05rb)
      CALL MKBI_RB(q4, ionic, ionicrb, sion, sionrb, z04, g04, g04rb)
      CALL MKBI_RB(q3, ionic, ionicrb, sion, sionrb, z03, g03, g03rb)
      CALL MKBI_RB(q2, ionic, ionicrb, sion, sionrb, z02, g02, g02rb)
      CALL MKBI_RB(q1, ionic, ionicrb, sion, sionrb, z01, g01, g01rb)
      IF (.NOT.ionic .EQ. 0.0) ionicrb = ionicrb + sionrb/(2.0*SQRT(
     +    ionic))
      END

C  Differentiation of mkbi in reverse (adjoint) mode:
C   gradient     of useful results: sion bi ionic
C   with respect to varying inputs: sion ionic
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_RB(q, ionic, ionicrb, sion, sionrb, zip, bi, birb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicrb, sionrb, birb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION crb, xxrb
      INTRINSIC EXP
      DOUBLE PRECISION temprb0
      DOUBLE PRECISION temprb
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxrb = zip*birb
      birb = zip*birb/(bi*LOG(10.0))
      temprb = -(0.5107d0*xxrb/(c*sion+1.d0))
      temprb0 = -(sion*temprb/(c*sion+1.d0))
      sionrb = sionrb + c*temprb0 + temprb
      crb = sion*temprb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicrb = ionicrb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*crb
      ELSE
        ionicrb = ionicrb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*birb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*crb
      END IF
      END


