      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION nh4i, ohi, om1, om2, bb, cc, dd, del1, del2
      DOUBLE PRECISION nh4isb, ohisb, om1sb, om2sb, bbsb, ccsb, ddsb, 
     +                 del1sb, del2sb
      DOUBLE PRECISION a22
      DOUBLE PRECISION a22sb
      DOUBLE PRECISION akw
      DOUBLE PRECISION akwsb
      DOUBLE PRECISION delt
      DOUBLE PRECISION deltsb
      DOUBLE PRECISION temp0sb0
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1sb
      DOUBLE PRECISION temp0sb
      INTRINSIC SQRT
      COMMON /ions_sb/ molalsb, gamasb, watersb
CC      CHARACTER*40 errinf
C
C *** EQUILIBRIUM CONSTANTS
C
C GAMA(NH3) ASSUMED 1
      a22 = xk22/xkw/water*(gama(8)/gama(9))**2.
      akw = xkw*rh*water*water
C
C *** FIND ROOT
C
      om1 = nh4i
      om2 = ohi
      bb = -(om1+om2+a22*akw)
      cc = om1*om2
      dd = SQRT(bb*bb - 4.d0*cc)
C
      del1 = 0.5d0*(-bb-dd)
      del2 = 0.5d0*(-bb+dd)
C
C *** GET APPROPRIATE ROOT.
C
      IF (del1 .LT. zero) THEN
        IF (del2 .GT. nh4i .OR. del2 .GT. ohi) THEN
          del2sb = 0.D0
        ELSE
          del2sb = deltsb
        END IF
        del1sb = 0.D0
      ELSE
        del1sb = deltsb
        del2sb = 0.D0
      END IF
      ddsb = 0.5d0*del2sb - 0.5d0*del1sb
      IF (bb**2 - 4.d0*cc .EQ. 0.0) THEN
        temp1sb = 0.0
      ELSE
        temp1sb = ddsb/(2.0*SQRT(bb**2-4.d0*cc))
      END IF
      bbsb = 2*bb*temp1sb - 0.5d0*del1sb - 0.5d0*del2sb
      ccsb = -(4.d0*temp1sb)
      om1sb = om2*ccsb - bbsb
      om2sb = om1*ccsb - bbsb
      a22sb = -(akw*bbsb)
      akwsb = -(a22*bbsb)
      ohisb = ohisb + om2sb
      nh4isb = nh4isb + om1sb
      temp0 = gama(8)/gama(9)
      temp0sb = xk22*a22sb/(xkw*water)
      watersb = watersb + xkw*rh*2*water*akwsb - temp0**2.*temp0sb/water
      temp0sb0 = 2.*temp0*temp0sb/gama(9)
      gamasb(8) = gamasb(8) + temp0sb0
      gamasb(9) = gamasb(9) - temp0*temp0sb0
      END

