      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
      DOUBLE PRECISION hi, so4i, hso4i, delta, bb, cc, dd, sqdd, delta1
     +                 , delta2
      DOUBLE PRECISION hisb, so4isb, deltasb, bbsb, ccsb, ddsb, sqddsb, 
     +                 delta1sb, delta2sb
      DOUBLE PRECISION temp1
      DOUBLE PRECISION temp0
      DOUBLE PRECISION temp1sb
      DOUBLE PRECISION temp0sb
      INTRINSIC SQRT
      COMMON /ions_sb/ molalsb, gamasb, watersb
CC      CHARACTER*40 errinf
C
C *** IF TOO LITTLE WATER, DONT SOLVE
C
      IF (water .GT. 1d1*tiny) THEN
C
C *** CALCULATE HSO4 SPECIATION *****************************************
C
        a8 = xk1*water/gama(7)*(gama(8)/gama(7))**2.
C
        bb = -(hi+so4i+a8)
        cc = hi*so4i - hso4i*a8
        dd = bb*bb - 4.d0*cc
C
        IF (dd .GE. zero) THEN
          IF (hso4i .LE. tiny) THEN
            delta2sb = deltasb
            delta1sb = 0.D0
          ELSE IF (hi*so4i .GE. a8*hso4i) THEN
            delta2sb = deltasb
            delta1sb = 0.D0
          ELSE
            IF (hi*so4i .LT. a8*hso4i) THEN
              delta1sb = deltasb
            ELSE
              delta1sb = 0.D0
            END IF
            delta2sb = 0.D0
          END IF
          bbsb = -(0.5*delta1sb) - 0.5*delta2sb
          sqddsb = 0.5*delta1sb - 0.5*delta2sb
          IF (dd .EQ. 0.0) THEN
            ddsb = 0.0
          ELSE
            ddsb = sqddsb/(2.0*SQRT(dd))
          END IF
        ELSE
          ddsb = 0.D0
          bbsb = 0.D0
        END IF
        bbsb = bbsb + 2*bb*ddsb
        ccsb = -(4.d0*ddsb)
        hisb = hisb + so4i*ccsb - bbsb
        so4isb = so4isb + hi*ccsb - bbsb
        a8sb = -bbsb - hso4i*ccsb
        temp1 = water/gama(7)
        temp0 = gama(8)/gama(7)
        temp0sb = 2.*temp0*temp1*xk1*a8sb/gama(7)
        temp1sb = temp0**2.*xk1*a8sb/gama(7)
        gamasb(8) = gamasb(8) + temp0sb
        gamasb(7) = gamasb(7) - temp1*temp1sb - temp0*temp0sb
        watersb = watersb + temp1sb
      END IF
      END

