      COMMON /gas_fb/ ghno3fb
CC
CC *** Case G adjoint ***************************************************
CC
      DOUBLE PRECISION molalgnrd(nions)
      DOUBLE PRECISION gamagnrd(npair)
      DOUBLE PRECISION watergnrd
      COMMON /ions_gnrd/ molalgnrd, gamagnrd, watergnrd
      DOUBLE PRECISION molalgnrdgb(nions)
      DOUBLE PRECISION gamagnrdgb(npair)
      DOUBLE PRECISION watergnrdgb
      COMMON /ions_gnrd_gb/ molalgnrdgb, gamagnrdgb, watergnrdgb
      DOUBLE PRECISION chi4gb, chi5gb, chi6gb, psi2gb
      COMMON /solut_gb/ chi4gb, chi5gb, chi6gb, psi2gb
      DOUBLE PRECISION gnh3gb, ghno3gb, ghclgb
      COMMON /gas_gb/ gnh3gb, ghno3gb, ghclgb
      DOUBLE PRECISION molalgb(nions)
      DOUBLE PRECISION molalrgb(npair)
      DOUBLE PRECISION gamagb(npair)
      DOUBLE PRECISION watergb
      COMMON /ions_gb/ molalgb, molalrgb, gamagb, watergb
      DOUBLE PRECISION wgb(5)
      COMMON /inpt_gb/ wgb
CC
CC *** Case H adjoint ***************************************************
CC
      DOUBLE PRECISION molalhnrd(nions)
      DOUBLE PRECISION gamahnrd(npair)
      DOUBLE PRECISION waterhnrd
      COMMON /ions_hnrd/ molalhnrd, gamahnrd, waterhnrd
      DOUBLE PRECISION molalhnrdhb(nions)
      DOUBLE PRECISION gamahnrdhb(npair)
      DOUBLE PRECISION waterhnrdhb
      COMMON /ions_hnrd_hb/ molalhnrdhb, gamahnrdhb, waterhnrdhb
      DOUBLE PRECISION chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      COMMON /solut_hb/ chi1hb, chi4hb, chi5hb, chi6hb, chi7hb, chi8hb
      DOUBLE PRECISION gnh3hb, ghno3hb, ghclhb
      COMMON /gas_hb/ gnh3hb, ghno3hb, ghclhb
      DOUBLE PRECISION molalhb(nions)
      DOUBLE PRECISION molalrhb(npair)
      DOUBLE PRECISION gamahb(npair)
      DOUBLE PRECISION waterhb
      COMMON /ions_hb/ molalhb, molalrhb, gamahb, waterhb
CC
CC *** Case I adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3ib, ghno3ib, ghclib
      COMMON /gas_ib/ gnh3ib, ghno3ib, ghclib
      DOUBLE PRECISION molalib(nions)
      DOUBLE PRECISION gamaib(npair)
      DOUBLE PRECISION waterib
      COMMON /ions_ib/ molalib, gamaib, waterib
      DOUBLE PRECISION wib(5)
      COMMON /inpt_ib/ wib
CC
CC *** Case J adjoint ***************************************************
CC
      DOUBLE PRECISION gnh3jb, ghno3jb, ghcljb
      COMMON /gas_jb/ gnh3jb, ghno3jb, ghcljb
      DOUBLE PRECISION molaljb(nions)
      DOUBLE PRECISION gamajb(npair)
      DOUBLE PRECISION waterjb
      COMMON /ions_jb/ molaljb, gamajb, waterjb
      DOUBLE PRECISION wjb(5)
      COMMON /inpt_jb/ wjb
C
      DOUBLE PRECISION g0(6, 4), zpl, zmi, agama, sion, h, ch, f1(3), f2
     +                 (4)
      DOUBLE PRECISION g0sb(6, 4), sionsb, hsb, chsb, f1sb(3), f2sb(4)
      DOUBLE PRECISION mpl, xij, yji, check
      DOUBLE PRECISION mplsb, xijsb, yjisb
      CHARACTER*40 errinf
      INTEGER i
      DOUBLE PRECISION g01
      DOUBLE PRECISION g01sb
      DOUBLE PRECISION g02
      DOUBLE PRECISION g02sb
      DOUBLE PRECISION g03
      DOUBLE PRECISION g03sb
      DOUBLE PRECISION g04
      DOUBLE PRECISION g04sb
      DOUBLE PRECISION g05
      DOUBLE PRECISION g05sb
      DOUBLE PRECISION g06
      DOUBLE PRECISION g06sb
      DOUBLE PRECISION g07
      DOUBLE PRECISION g07sb
      DOUBLE PRECISION g08
      DOUBLE PRECISION g08sb
      DOUBLE PRECISION g09
      DOUBLE PRECISION g09sb
      DOUBLE PRECISION g10
      DOUBLE PRECISION g10sb
      DOUBLE PRECISION g11
      DOUBLE PRECISION g11sb
      DOUBLE PRECISION g12
      DOUBLE PRECISION g12sb
      INTEGER j
      DOUBLE PRECISION errou
      DOUBLE PRECISION errin
C
C
C      G(I,J)= (F1(I)/Z(I) + F2(J)/Z(J+3)) / (Z(I)+Z(J+3)) - H
C
C *** SAVE ACTIVITIES IN OLD ARRAY *************************************
C
      INTEGER branch
      DOUBLE PRECISION temp0sb2
      DOUBLE PRECISION temp0sb1
      DOUBLE PRECISION temp0sb0
      INTRINSIC MAX
      DOUBLE PRECISION x1sb
      INTRINSIC ABS
      DOUBLE PRECISION x2
      DOUBLE PRECISION x1
      DOUBLE PRECISION temp0sb13
      DOUBLE PRECISION temp0sb12
      DOUBLE PRECISION temp0sb11
      DOUBLE PRECISION temp0sb10
      DOUBLE PRECISION x2sb
      DOUBLE PRECISION temp0sb
      INTRINSIC MIN
      INTRINSIC SQRT
      DOUBLE PRECISION temp0sb9
      DOUBLE PRECISION temp0sb8
      DOUBLE PRECISION temp0sb7
      DOUBLE PRECISION temp0sb6
      DOUBLE PRECISION temp0sb5
      DOUBLE PRECISION temp0sb4
      DOUBLE PRECISION y1
      DOUBLE PRECISION temp0sb3
      COMMON /ions_sb/ molalsb, gamasb, watersb
C
C
C *** CALCULATE IONIC ACTIVITY OF SOLUTION *****************************
C
      ionic = 0.d0
      DO i=1,7
        ionic = ionic + molal(i)*z(i)*z(i)
      ENDDO
      IF (0.5d0*ionic/water .GT. 100.d0) THEN
        x1 = 200.d0
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = 0.5d0*ionic/water
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. tiny) THEN
        CALL PUSHREAL8(ionic)
        ionic = tiny
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(ionic)
        ionic = x1
        CALL PUSHCONTROL1B(1)
      END IF
C
C *** CALCULATE BINARY ACTIVITY COEFFICIENTS ***************************
C
C  G0(1,1)=G11;G0(1,2)=G07;G0(1,3)=G08;G0(1,4)=G10;G0(2,1)=G01;G0(2,2)=G02
C  G0(2,3)=G12;G0(2,4)=G03;G0(3,1)=G06;G0(3,2)=G04;G0(3,3)=G09;G0(3,4)=G05
C
C
      CALL KMFUL3(ionic, temp, g01, g02, g03, g04, g05, g06, g07, g08, 
     +            g09, g10, g11, g12)
C
      g0(1, 1) = g11
      g0(1, 2) = g07
      g0(1, 3) = g08
      g0(1, 4) = g10
      g0(2, 1) = g01
      g0(2, 2) = g02
      g0(2, 3) = g12
      g0(2, 4) = g03
      g0(3, 1) = g06
      g0(3, 2) = g04
      g0(3, 3) = g09
      g0(3, 4) = g05
C
C *** CALCULATE MULTICOMPONENT ACTIVITY COEFFICIENTS *******************
C
C Debye Huckel const. at T
      agama = 0.511d0*(298.d0/temp)**1.5d0
      sion = SQRT(ionic)
      h = agama*sion/(1.d0+sion)
C
C
      DO i=1,3
        f1(i) = 0.d0
        f2(i) = 0.d0
      ENDDO
      f2(4) = 0.d0
C
      DO i=1,3
        CALL PUSHREAL8(zpl)
        zpl = z(i)
        CALL PUSHREAL8(mpl)
        mpl = molal(i)/water
        DO j=1,4
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          yji = ch*molal(j+3)/water
          f1(i) = f1(i) + yji*(g0(i, j)+zpl*zmi*h)
          f2(j) = f2(j) + xij*(g0(i, j)+zpl*zmi*h)
        ENDDO
      ENDDO
      CALL PUSHREAL8(gama(1))
C
C *** LOG10 OF ACTIVITY COEFFICIENTS ***********************************
C
C      GAMA(01) = G(2,1)*ZZ(01)                     ! NACL
C NACL
      gama(1) = ((f1(2)/z(2)+f2(1)/z(4))/(z(2)+z(4))-h)*zz(1)
      CALL PUSHREAL8(gama(2))
C      GAMA(02) = G(2,2)*ZZ(02)                     ! NA2SO4
C NA2SO4
      gama(2) = ((f1(2)/z(2)+f2(2)/z(5))/(z(2)+z(5))-h)*zz(2)
      CALL PUSHREAL8(gama(3))
C      GAMA(03) = G(2,4)*ZZ(03)                     ! NANO3
C NANO3
      gama(3) = ((f1(2)/z(2)+f2(4)/z(7))/(z(2)+z(7))-h)*zz(3)
      CALL PUSHREAL8(gama(4))
C      GAMA(04) = G(3,2)*ZZ(04)                     ! (NH4)2SO4
C (NH4)2SO4
      gama(4) = ((f1(3)/z(3)+f2(2)/z(5))/(z(3)+z(5))-h)*zz(4)
      CALL PUSHREAL8(gama(5))
C      GAMA(05) = G(3,4)*ZZ(05)                     ! NH4NO3
C NH4NO3
      gama(5) = ((f1(3)/z(3)+f2(4)/z(7))/(z(3)+z(7))-h)*zz(5)
      CALL PUSHREAL8(gama(6))
C      GAMA(06) = G(3,1)*ZZ(06)                     ! NH4CL
C NH4CL
      gama(6) = ((f1(3)/z(3)+f2(1)/z(4))/(z(3)+z(4))-h)*zz(6)
      CALL PUSHREAL8(gama(7))
C      GAMA(07) = G(1,2)*ZZ(07)                     ! 2H-SO4
C 2H-SO4
      gama(7) = ((f1(1)/z(1)+f2(2)/z(5))/(z(1)+z(5))-h)*zz(7)
      CALL PUSHREAL8(gama(8))
C      GAMA(08) = G(1,3)*ZZ(08)                     ! H-HSO4
C H-HSO4
      gama(8) = ((f1(1)/z(1)+f2(3)/z(6))/(z(1)+z(6))-h)*zz(8)
      CALL PUSHREAL8(gama(9))
C      GAMA(09) = G(3,3)*ZZ(09)                     ! NH4HSO4
C NH4HSO4
      gama(9) = ((f1(3)/z(3)+f2(3)/z(6))/(z(3)+z(6))-h)*zz(9)
      CALL PUSHREAL8(gama(10))
C      GAMA(10) = G(1,4)*ZZ(10)                     ! HNO3
C HNO3
      gama(10) = ((f1(1)/z(1)+f2(4)/z(7))/(z(1)+z(7))-h)*zz(10)
      CALL PUSHREAL8(gama(11))
C      GAMA(11) = G(1,1)*ZZ(11)                     ! HCL
C HCL
      gama(11) = ((f1(1)/z(1)+f2(1)/z(4))/(z(1)+z(4))-h)*zz(11)
      CALL PUSHREAL8(gama(12))
C      GAMA(12) = G(2,3)*ZZ(12)                     ! NAHSO4
C NAHSO4
      gama(12) = ((f1(2)/z(2)+f2(3)/z(6))/(z(2)+z(6))-h)*zz(12)
      CALL PUSHREAL8(gama(13))
C LC ; SCAPE
      gama(13) = 0.2d0*(3.d0*gama(4)+2.d0*gama(9))
C
C *** CONVERT LOG (GAMA) COEFFICIENTS TO GAMA **************************
C
      DO i=1,13
        IF (gama(i) .GT. 5.0d0) THEN
          CALL PUSHCONTROL1B(0)
          x2 = 5.0d0
        ELSE
          x2 = gama(i)
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. -5.0d0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      ENDDO
      DO i=13,1,-1
        gamasb(i) = 10.d0**gama(i)*LOG(10.d0)*gamasb(i)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          gamasb(i) = 0.D0
          x2sb = 0.D0
        ELSE
          x2sb = gamasb(i)
          gamasb(i) = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) gamasb(i) = gamasb(i) + x2sb
      ENDDO
      CALL POPREAL8(gama(13))
      gamasb(4) = gamasb(4) + 0.2d0*3.d0*gamasb(13)
      gamasb(9) = gamasb(9) + 0.2d0*2.d0*gamasb(13)
      gamasb(13) = 0.D0
      f1sb = 0.D0
      f2sb = 0.D0
      CALL POPREAL8(gama(12))
      temp0sb2 = zz(12)*gamasb(12)/(z(2)+z(6))
      f1sb(2) = f1sb(2) + temp0sb2/z(2)
      f2sb(3) = f2sb(3) + temp0sb2/z(6)
      hsb = -(zz(12)*gamasb(12))
      gamasb(12) = 0.D0
      CALL POPREAL8(gama(11))
      temp0sb3 = zz(11)*gamasb(11)/(z(1)+z(4))
      f2sb(1) = f2sb(1) + temp0sb3/z(4)
      hsb = hsb - zz(11)*gamasb(11)
      gamasb(11) = 0.D0
      CALL POPREAL8(gama(10))
      temp0sb4 = zz(10)*gamasb(10)/(z(1)+z(7))
      f1sb(1) = f1sb(1) + temp0sb4/z(1) + temp0sb3/z(1)
      f2sb(4) = f2sb(4) + temp0sb4/z(7)
      hsb = hsb - zz(10)*gamasb(10)
      gamasb(10) = 0.D0
      CALL POPREAL8(gama(9))
      temp0sb5 = zz(9)*gamasb(9)/(z(3)+z(6))
      f1sb(3) = f1sb(3) + temp0sb5/z(3)
      hsb = hsb - zz(9)*gamasb(9)
      gamasb(9) = 0.D0
      CALL POPREAL8(gama(8))
      temp0sb6 = zz(8)*gamasb(8)/(z(1)+z(6))
      f2sb(3) = f2sb(3) + temp0sb6/z(6) + temp0sb5/z(6)
      hsb = hsb - zz(8)*gamasb(8)
      gamasb(8) = 0.D0
      CALL POPREAL8(gama(7))
      temp0sb7 = zz(7)*gamasb(7)/(z(1)+z(5))
      f1sb(1) = f1sb(1) + temp0sb7/z(1) + temp0sb6/z(1)
      f2sb(2) = f2sb(2) + temp0sb7/z(5)
      hsb = hsb - zz(7)*gamasb(7)
      gamasb(7) = 0.D0
      CALL POPREAL8(gama(6))
      temp0sb8 = zz(6)*gamasb(6)/(z(3)+z(4))
      f2sb(1) = f2sb(1) + temp0sb8/z(4)
      hsb = hsb - zz(6)*gamasb(6)
      gamasb(6) = 0.D0
      CALL POPREAL8(gama(5))
      temp0sb9 = zz(5)*gamasb(5)/(z(3)+z(7))
      f2sb(4) = f2sb(4) + temp0sb9/z(7)
      hsb = hsb - zz(5)*gamasb(5)
      gamasb(5) = 0.D0
      CALL POPREAL8(gama(4))
      temp0sb10 = zz(4)*gamasb(4)/(z(3)+z(5))
      f1sb(3) = f1sb(3) + temp0sb9/z(3) + temp0sb10/z(3) + temp0sb8/z(3)
      f2sb(2) = f2sb(2) + temp0sb10/z(5)
      hsb = hsb - zz(4)*gamasb(4)
      gamasb(4) = 0.D0
      CALL POPREAL8(gama(3))
      temp0sb11 = zz(3)*gamasb(3)/(z(2)+z(7))
      f2sb(4) = f2sb(4) + temp0sb11/z(7)
      hsb = hsb - zz(3)*gamasb(3)
      gamasb(3) = 0.D0
      CALL POPREAL8(gama(2))
      temp0sb12 = zz(2)*gamasb(2)/(z(2)+z(5))
      f2sb(2) = f2sb(2) + temp0sb12/z(5)
      hsb = hsb - zz(2)*gamasb(2)
      gamasb(2) = 0.D0
      CALL POPREAL8(gama(1))
      temp0sb13 = zz(1)*gamasb(1)/(z(2)+z(4))
      f1sb(2) = f1sb(2) + temp0sb12/z(2) + temp0sb13/z(2) + temp0sb11/z(
     +  2)
      f2sb(1) = f2sb(1) + temp0sb13/z(4)
      hsb = hsb - zz(1)*gamasb(1)
      gamasb(1) = 0.D0
      ionicsb = 0.D0
      g0sb = 0.D0
      DO i=3,1,-1
        mplsb = 0.D0
        DO j=4,1,-1
          zmi = z(j+3)
          ch = 0.25d0*(zpl+zmi)*(zpl+zmi)/ionic
          xij = ch*mpl
          xijsb = (g0(i, j)+zpl*zmi*h)*f2sb(j)
          yji = ch*molal(j+3)/water
          g0sb(i, j) = g0sb(i, j) + yji*f1sb(i) + xij*f2sb(j)
          hsb = hsb + yji*zpl*zmi*f1sb(i) + xij*zpl*zmi*f2sb(j)
          yjisb = (g0(i, j)+zpl*zmi*h)*f1sb(i)
          temp0sb1 = molal(j+3)*yjisb/water
          molalsb(j+3) = molalsb(j+3) + ch*yjisb/water
          chsb = mpl*xijsb + temp0sb1
          watersb = watersb - ch*temp0sb1/water
          mplsb = mplsb + ch*xijsb
          ionicsb = ionicsb - (zpl+zmi)**2*0.25d0*chsb/ionic**2
        ENDDO
        CALL POPREAL8(mpl)
        molalsb(i) = molalsb(i) + mplsb/water
        watersb = watersb - molal(i)*mplsb/water**2
        CALL POPREAL8(zpl)
      ENDDO
      temp0sb0 = agama*hsb/(sion+1.d0)
      sionsb = (1.D0-sion/(sion+1.d0))*temp0sb0
      IF (.NOT.ionic .EQ. 0.0) ionicsb = ionicsb + sionsb/(2.0*SQRT(
     +    ionic))
      g05sb = g0sb(3, 4)
      g0sb(3, 4) = 0.D0
      g09sb = g0sb(3, 3)
      g0sb(3, 3) = 0.D0
      g04sb = g0sb(3, 2)
      g0sb(3, 2) = 0.D0
      g06sb = g0sb(3, 1)
      g0sb(3, 1) = 0.D0
      g03sb = g0sb(2, 4)
      g0sb(2, 4) = 0.D0
      g12sb = g0sb(2, 3)
      g0sb(2, 3) = 0.D0
      g02sb = g0sb(2, 2)
      g0sb(2, 2) = 0.D0
      g01sb = g0sb(2, 1)
      g0sb(2, 1) = 0.D0
      g10sb = g0sb(1, 4)
      g0sb(1, 4) = 0.D0
      g08sb = g0sb(1, 3)
      g0sb(1, 3) = 0.D0
      g07sb = g0sb(1, 2)
      g0sb(1, 2) = 0.D0
      g11sb = g0sb(1, 1)
      CALL KMFUL3_SB(ionic, ionicsb, temp, g01, g01sb, g02, g02sb, g03, 
     +               g03sb, g04, g04sb, g05, g05sb, g06, g06sb, g07, 
     +               g07sb, g08, g08sb, g09, g09sb, g10, g10sb, g11, 
     +               g11sb, g12, g12sb)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(ionic)
        x1sb = 0.D0
      ELSE
        CALL POPREAL8(ionic)
        x1sb = ionicsb
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ionicsb = 0.D0
      ELSE
        temp0sb = 0.5d0*x1sb/water
        ionicsb = temp0sb
        watersb = watersb - ionic*temp0sb/water
      END IF
      DO i=7,1,-1
        molalsb(i) = molalsb(i) + z(i)**2*ionicsb
      ENDDO
      END

C
C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE KMFUL3
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD
C     FOR AN AMMONIUM-SULFATE-NITRATE-CHLORIDE-SODIUM AEROSOL SYSTEM.
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C
C *** WRITTEN BY CHRISTOS FOUNTOUKIS & ATHANASIOS NENES
C
C=======================================================================
C
      SUBROUTINE KMFUL3_SB(ionic, ionicsb, temp, g01, g01sb, g02, g02sb
     +                     , g03, g03sb, g04, g04sb, g05, g05sb, g06, 
     +                     g06sb, g07, g07sb, g08, g08sb, g09, g09sb, 
     +                     g10, g10sb, g11, g11sb, g12, g12sb)
      IMPLICIT NONE
      DOUBLE PRECISION ionic, temp, sion, ti, tc, cf1, cf2
      DOUBLE PRECISION ionicsb, sionsb, cf2sb
      DOUBLE PRECISION g01, g02, g03, g04, g05, g06, g07, g08, g09, g10
     +                 , g11, g12
      DOUBLE PRECISION g01sb, g02sb, g03sb, g04sb, g05sb, g06sb, g07sb, 
     +                 g08sb, g09sb, g10sb, g11sb, g12sb
      DOUBLE PRECISION q1, q2, q3, q4, q5, q6, q7, q8, q10, q11
      DOUBLE PRECISION z01, z02, z03, z04, z05, z06, z07, z08, z10, z11
      INTEGER branch
      DOUBLE PRECISION temp0sb0
      INTRINSIC ABS
      DOUBLE PRECISION temp0sb
      DOUBLE PRECISION abs0
      INTRINSIC SQRT
      DATA z01, z02, z03, z04, z05, z06, z07, z08, z10, z11 /1.d0, 2.d0
     +     , 1.d0, 2.d0, 1.d0, 1.d0, 2.d0, 1.d0, 1.d0, 1.d0/
C
      sion = SQRT(ionic)
C
C *** Coefficients at 25 oC
C
      q1 = 2.230d0
      q2 = -0.19d0
      q3 = -0.39d0
      q4 = -0.25d0
      q5 = -1.15d0
      q6 = 0.820d0
      q7 = -.100d0
      q8 = 8.000d0
      q10 = 2.600d0
      q11 = 6.000d0
C
C
C *** Correct for T other than 298 K
C
      ti = temp - 273.d0
      tc = ti - 25.d0
      IF (tc .GE. 0.) THEN
        abs0 = tc
      ELSE
        abs0 = -tc
      END IF
      IF (abs0 .GT. 1.d0) THEN
        cf1 = 1.125d0 - 0.005d0*ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      g01sb = g01sb + g12sb
      g08sb = g08sb + g09sb + g12sb
      g11sb = g11sb - g09sb - g12sb
      g06sb = g06sb + g09sb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        cf2sb = -(z10*g10sb) - z07*g07sb - z05*g05sb - z03*g03sb - z01*
     +    g01sb - z02*g02sb - z04*g04sb - z06*g06sb - z08*g08sb - z11*
     +    g11sb
        g11sb = cf1*g11sb
        g10sb = cf1*g10sb
        g08sb = cf1*g08sb
        g07sb = cf1*g07sb
        g06sb = cf1*g06sb
        g05sb = cf1*g05sb
        g04sb = cf1*g04sb
        g03sb = cf1*g03sb
        g02sb = cf1*g02sb
        g01sb = cf1*g01sb
        temp0sb = (0.125d0-ti*0.005d0)*cf2sb
        temp0sb0 = -(0.41d0*temp0sb/(sion+1.d0))
        ionicsb = ionicsb + 0.039d0*0.92d0*ionic**(-0.8D0)*temp0sb
        sionsb = (1.D0-sion/(sion+1.d0))*temp0sb0
      ELSE
        sionsb = 0.D0
      END IF
      CALL MKBI_SB(q11, ionic, ionicsb, sion, sionsb, z11, g11, g11sb)
      CALL MKBI_SB(q10, ionic, ionicsb, sion, sionsb, z10, g10, g10sb)
      CALL MKBI_SB(q8, ionic, ionicsb, sion, sionsb, z08, g08, g08sb)
      CALL MKBI_SB(q7, ionic, ionicsb, sion, sionsb, z07, g07, g07sb)
      CALL MKBI_SB(q6, ionic, ionicsb, sion, sionsb, z06, g06, g06sb)
      CALL MKBI_SB(q5, ionic, ionicsb, sion, sionsb, z05, g05, g05sb)
      CALL MKBI_SB(q4, ionic, ionicsb, sion, sionsb, z04, g04, g04sb)
      CALL MKBI_SB(q3, ionic, ionicsb, sion, sionsb, z03, g03, g03sb)
      CALL MKBI_SB(q2, ionic, ionicsb, sion, sionsb, z02, g02, g02sb)
      CALL MKBI_SB(q1, ionic, ionicsb, sion, sionsb, z01, g01, g01sb)
      IF (.NOT.ionic .EQ. 0.0) ionicsb = ionicsb + sionsb/(2.0*SQRT(
     +    ionic))
      END

C=======================================================================
C
C *** ISORROPIA CODE
C *** SUBROUTINE MKBI
C *** CALCULATES BINARY ACTIVITY COEFFICIENTS BY KUSIK-MEISSNER METHOD. 
C
C *** COPYRIGHT 1996-2006, UNIVERSITY OF MIAMI, CARNEGIE MELLON UNIVERSITY,
C *** GEORGIA INSTITUTE OF TECHNOLOGY
C *** WRITTEN BY ATHANASIOS NENES
C *** UPDATED BY CHRISTOS FOUNTOUKIS
C
C=======================================================================
C
      SUBROUTINE MKBI_SB(q, ionic, ionicsb, sion, sionsb, zip, bi, bisb)
      IMPLICIT NONE
      DOUBLE PRECISION q, ionic, sion, zip, bi
      DOUBLE PRECISION ionicsb, sionsb, bisb
      DOUBLE PRECISION b, c, xx
      DOUBLE PRECISION csb, xxsb
      INTRINSIC EXP
      DOUBLE PRECISION tempsb
      DOUBLE PRECISION tempsb0
      INTRINSIC LOG10
C
      b = .75d0 - .065d0*q
C      C= 1.0
C      IF (IONIC.LT.6.0) C=1.+.055*Q*EXP(-.023*IONIC*IONIC*IONIC)
      c = 1. + .055d0*q*EXP(-(.023d0*ionic*ionic*ionic))
      bi = 1.d0 + b*(1.d0+.1d0*ionic)**q - b
C
      xxsb = zip*bisb
      bisb = zip*bisb/(bi*LOG(10.0))
      tempsb = -(0.5107d0*xxsb/(c*sion+1.d0))
      tempsb0 = -(sion*tempsb/(c*sion+1.d0))
      sionsb = sionsb + c*tempsb0 + tempsb
      csb = sion*tempsb0
      IF (.1d0*ionic + 1.d0 .LE. 0.0 .AND. (q .EQ. 0.0 .OR. q .NE. INT(q
     +    ))) THEN
        ionicsb = ionicsb - .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*
     +    ionic**2*csb
      ELSE
        ionicsb = ionicsb + q*(.1d0*ionic+1.d0)**(q-1)*b*.1d0*bisb - 
     +    .023d0*EXP(-(.023d0*ionic**3))*q*.055d0*3*ionic**2*csb
      END IF
      END

C

